import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Validates the successful registration of a new shopping mall customer.
 *
 * This test ensures that a customer can be registered with a unique email, a
 * password meeting complexity requirements (minimum 8 characters, containing
 * uppercase, lowercase, digit, and symbol), a valid legal full name, and a
 * properly formatted phone number. It confirms that the API creates a new
 * customer account, returns an authorized actor with correct information, and
 * provides valid JWT authentication tokens as part of the authorized session
 * payload.
 *
 * Steps:
 *
 * 1. Generate unique, valid registration data: email, password, name, phone
 * 2. Call the /auth/customer/join endpoint to register a customer
 * 3. Validate that the response is a properly typed authorized customer
 * 4. Confirm returned fields match input and basic post-join invariants;
 *
 *    - The returned JWT token property is present and has both access and refresh
 *         tokens
 *    - Email, name, and phone match
 *    - Email verification is initially false
 *    - Account creation and update timestamps are valid ISO-8601 datetimes
 */
export async function test_api_customer_registration_success(
  connection: api.IConnection,
) {
  // Step 1: Generate registration input with required complexity
  const email = `${RandomGenerator.alphaNumeric(10)}@example.com` as string &
    tags.Format<"email">;
  // Compose a strong password: at least 8 chars, uppercase, lowercase, digit, symbol
  const password = [
    RandomGenerator.pick([..."ABCDEFGHIJKLMNOPQRSTUVWXYZ"]),
    RandomGenerator.pick([..."abcdefghijklmnopqrstuvwxyz"]),
    RandomGenerator.pick([..."0123456789"]),
    RandomGenerator.pick([..."!@#$%^&*()_+-=[]{};:,.<>?"]),
    RandomGenerator.alphaNumeric(4), // ensure min length
  ].join("");
  const name = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 2,
    wordMax: 8,
  }); // Legal full name >=2 chars
  // starts with +82, 010, etc. - generate a valid phone string of 10+ chars
  const phone = RandomGenerator.mobile();

  const requestBody = {
    email,
    password: password as string & tags.MinLength<8> & tags.Format<"password">,
    name: name as string & tags.MinLength<2> & tags.MaxLength<64>,
    phone,
  } satisfies IShoppingMallCustomer.ICreate;

  // Step 2: Call customer join API
  const authorizedCustomer = await api.functional.auth.customer.join(
    connection,
    {
      body: requestBody,
    },
  );
  typia.assert(authorizedCustomer);

  // Step 3: Validate the customer registration response matches input
  TestValidator.equals(
    "registered email matches input",
    authorizedCustomer.email,
    email,
  );
  TestValidator.equals(
    "registered name matches input",
    authorizedCustomer.name,
    name,
  );
  TestValidator.equals(
    "registered phone matches input",
    authorizedCustomer.phone,
    phone,
  );
  TestValidator.equals(
    "email is not verified after registration",
    authorizedCustomer.is_email_verified,
    false,
  );

  // Step 4: Basic JWT structure in token property
  typia.assert<IAuthorizationToken>(authorizedCustomer.token);
  TestValidator.predicate(
    "access token present",
    typeof authorizedCustomer.token.access === "string" &&
      authorizedCustomer.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token present",
    typeof authorizedCustomer.token.refresh === "string" &&
      authorizedCustomer.token.refresh.length > 0,
  );

  // Step 5: Confirm id format (UUID) and date-time fields
  typia.assert<string & tags.Format<"uuid">>(authorizedCustomer.id);
  typia.assert<string & tags.Format<"date-time">>(
    authorizedCustomer.created_at,
  );
  typia.assert<string & tags.Format<"date-time">>(
    authorizedCustomer.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Test customer registration rejects duplicate emails.
 *
 * 1. Register a customer using a randomly generated email.
 * 2. Attempt a second registration with the exact same email but different data
 *    for other fields.
 * 3. Assert the second registration attempt returns an error, ensuring email
 *    uniqueness is enforced by the system.
 */
export async function test_api_customer_registration_duplicate_email(
  connection: api.IConnection,
) {
  // Step 1: Register first customer (occupy the email)
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string & tags.MinLength<8> & tags.Format<"password"> =
    typia.random<string & tags.MinLength<8> & tags.Format<"password">>();
  const name: string & tags.MinLength<2> & tags.MaxLength<64> =
    RandomGenerator.name();
  const phone: string & tags.Pattern<"^[0-9\\-+() ]{8,20}$"> =
    RandomGenerator.mobile();

  const createBody1 = {
    email,
    password,
    name,
    phone,
  } satisfies IShoppingMallCustomer.ICreate;
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: createBody1,
    });
  typia.assert(customer);
  TestValidator.equals(
    "registered customer email matches input",
    customer.email,
    email,
  );

  // Step 2: Attempt registration with the same email (should be rejected)
  const createBody2 = {
    email, // reusing same email
    password: typia.random<
      string & tags.MinLength<8> & tags.Format<"password">
    >(), // new password
    name: RandomGenerator.name(), // new name
    phone: RandomGenerator.mobile(), // new phone
  } satisfies IShoppingMallCustomer.ICreate;

  await TestValidator.error(
    "duplicate registration with same email should be rejected",
    async () => {
      await api.functional.auth.customer.join(connection, {
        body: createBody2,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Validates successful login for a registered customer using correct email,
 * password, connection URL, and referrer. Ensures authentication endpoint
 * returns expected JWT tokens and identity fields.
 *
 * 1. Register a new customer with randomized credentials via the join API
 * 2. Attempt login using the exact credentials (email, password) and valid
 *    href/referrer URLs
 * 3. Validate that the login returns an authorized customer object
 * 4. Assert that response fields match expected values (identity, session data,
 *    and token structure)
 */
export async function test_api_customer_login_success(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string & tags.MinLength<8> & tags.Format<"password"> =
    typia.random<string & tags.MinLength<8> & tags.Format<"password">>();
  const name: string & tags.MinLength<2> & tags.MaxLength<64> = typia.random<
    string & tags.MinLength<2> & tags.MaxLength<64>
  >();
  const phone: string & tags.Pattern<"^[0-9\\-+() ]{8,20}$"> = typia.random<
    string & tags.Pattern<"^[0-9\\-+() ]{8,20}$">
  >();

  const registerBody = {
    email,
    password,
    name,
    phone,
  } satisfies IShoppingMallCustomer.ICreate;
  const registered: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: registerBody,
    });
  typia.assert(registered);
  TestValidator.equals(
    "registration email matches input",
    registered.email,
    email,
  );
  TestValidator.equals(
    "registration name matches input",
    registered.name,
    name,
  );
  TestValidator.equals(
    "registration phone matches input",
    registered.phone,
    phone,
  );

  // 2. Attempt customer login with correct credentials and URLs
  const href: string & tags.Format<"uri"> = "https://shop.e2e-test.com/login";
  const referrer: string & tags.Format<"uri"> = "https://shop.e2e-test.com/";
  const loginBody = {
    email,
    password,
    href,
    referrer,
  } satisfies IShoppingMallCustomer.ILogin;
  const loggedIn: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.login(connection, {
      body: loginBody,
    });
  typia.assert(loggedIn);

  // 3. Validate that returned identity fields match those from registration (except for token and timestamp fields)
  TestValidator.equals(
    "login customer id matches registration",
    loggedIn.id,
    registered.id,
  );
  TestValidator.equals("login email matches input", loggedIn.email, email);
  TestValidator.equals("login name matches input", loggedIn.name, name);
  TestValidator.equals("login phone matches input", loggedIn.phone, phone);
  TestValidator.predicate(
    "login returns a JWT token structure",
    typeof loggedIn.token === "object" &&
      typeof loggedIn.token.access === "string" &&
      typeof loggedIn.token.refresh === "string",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Test invalid password during customer login authentication.
 *
 * This scenario registers a new customer and then attempts login with the
 * correct email and an incorrect password to ensure authentication does not
 * succeed. The test validates secure password checking and appropriate error
 * error handling. Steps:
 *
 * 1. Register a new random customer to obtain a valid email and correct password.
 * 2. Attempt to login with the correct email but an invalid password, keeping same
 *    format constraints.
 * 3. Verify that login fails and the API raises an error, matching business and
 *    security expectations.
 */
export async function test_api_customer_login_invalid_password(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = RandomGenerator.alphaNumeric(12);
  const customerName = RandomGenerator.name();
  const customerPhone = RandomGenerator.mobile();
  const registrationInput = {
    email: customerEmail,
    password: customerPassword satisfies string,
    name: customerName,
    phone: customerPhone,
  } satisfies IShoppingMallCustomer.ICreate;

  const registered = await api.functional.auth.customer.join(connection, {
    body: registrationInput,
  });
  typia.assert(registered);
  TestValidator.equals(
    "registered email matches",
    registered.email,
    customerEmail,
  );

  // 2. Attempt login with correct email but wrong password
  const wrongPassword = customerPassword + "wrong";
  const loginInput = {
    email: customerEmail,
    password: wrongPassword,
    href: "https://mall.example.com/login",
    referrer: "https://mall.example.com/welcome",
  } satisfies IShoppingMallCustomer.ILogin;

  // 3. Validates authentication fails and returns an error
  await TestValidator.error(
    "login should fail with invalid password",
    async () => {
      await api.functional.auth.customer.login(connection, {
        body: loginInput,
      });
    },
  );
}

