import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallExternalPaymentProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallExternalPaymentProvider";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";

/**
 * Validate that an authenticated admin can retrieve a payment's complete
 * details by its ID, and that all returned fields match the created payment.
 * This test checks proper admin authentication handling and data integrity of
 * the retrieval API. The workflow also ensures the existence of prerequisite
 * payment and admin records.
 */
export async function test_api_payment_retrieval_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Admin registration (join)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) + "#Aa1",
    name: RandomGenerator.name(2),
  } satisfies IShoppingMallAdmin.ICreate;
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(admin);

  // Step 2: Create test payment (simulate as admin)
  // Fabricate minimal references for required customer and provider objects
  const fakeCustomer: IShoppingMallCustomer.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.name(),
  };
  const fakeProvider: IShoppingMallExternalPaymentProvider.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.name(2),
    provider_code: RandomGenerator.alphabets(4).toUpperCase(),
    status: RandomGenerator.pick(["active", "inactive", "deprecated"] as const),
    description: RandomGenerator.paragraph({
      sentences: 3,
      wordMin: 5,
      wordMax: 10,
    }),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    deleted_at: null,
  };
  // Prepare the payment creation body
  const paymentCreateBody = {
    customer_id: fakeCustomer.id,
    provider_id: fakeProvider.id,
    amount: 12345.67,
    currency: "USD",
    method_type: RandomGenerator.pick([
      "card",
      "e-wallet",
      "bank_transfer",
    ] as const),
    status: RandomGenerator.pick([
      "initiated",
      "pending",
      "authorized",
      "rejected",
      "completed",
      "refunded",
      "failed",
    ] as const),
    external_payment_id: RandomGenerator.alphaNumeric(18),
    transaction_token: RandomGenerator.alphaNumeric(32),
    requested_at: new Date().toISOString(),
  } satisfies IShoppingMallPayment.ICreate;
  // Directly call the payment creation API
  const created: IShoppingMallPayment =
    await api.functional.shoppingMall.admin.payments.create(connection, {
      body: paymentCreateBody,
    });
  typia.assert(created);

  // Step 3: Retrieve the payment by its id as admin
  const retrieved: IShoppingMallPayment =
    await api.functional.shoppingMall.admin.payments.at(connection, {
      paymentId: created.id,
    });
  typia.assert(retrieved);
  // Match each business-critical field
  TestValidator.equals("payment id", retrieved.id, created.id);
  TestValidator.equals("amount", retrieved.amount, paymentCreateBody.amount);
  TestValidator.equals(
    "currency",
    retrieved.currency,
    paymentCreateBody.currency,
  );
  TestValidator.equals(
    "method type",
    retrieved.method_type,
    paymentCreateBody.method_type,
  );
  TestValidator.equals("status", retrieved.status, paymentCreateBody.status);
  TestValidator.equals(
    "external payment id",
    retrieved.external_payment_id,
    paymentCreateBody.external_payment_id,
  );
  TestValidator.equals(
    "transaction token",
    retrieved.transaction_token,
    paymentCreateBody.transaction_token,
  );
  TestValidator.equals(
    "requested at",
    retrieved.requested_at,
    paymentCreateBody.requested_at,
  );

  // Check customer and provider linkage
  TestValidator.equals("customer id", retrieved.customer.id, fakeCustomer.id);
  TestValidator.equals(
    "customer name",
    retrieved.customer.name,
    fakeCustomer.name,
  );
  TestValidator.equals("provider id", retrieved.provider.id, fakeProvider.id);
  TestValidator.equals(
    "provider name",
    retrieved.provider.name,
    fakeProvider.name,
  );
  TestValidator.equals(
    "provider code",
    retrieved.provider.provider_code,
    fakeProvider.provider_code,
  );
  TestValidator.equals(
    "provider status",
    retrieved.provider.status,
    fakeProvider.status,
  );
  TestValidator.equals(
    "provider description",
    retrieved.provider.description,
    fakeProvider.description,
  );

  // Check created_at/updated_at/processed_at/deleted_at fields are present and formatted correctly
  TestValidator.predicate(
    "created_at is present",
    typeof retrieved.created_at === "string" && retrieved.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at is present",
    typeof retrieved.updated_at === "string" && retrieved.updated_at.length > 0,
  );
  // These may be nullable, so just check existence and/or null/undefined
  TestValidator.predicate(
    "processed_at is null or ISO string",
    retrieved.processed_at === null ||
      retrieved.processed_at === undefined ||
      (typeof retrieved.processed_at === "string" &&
        retrieved.processed_at.length > 0),
  );
  TestValidator.predicate(
    "deleted_at is null or ISO string",
    retrieved.deleted_at === null ||
      retrieved.deleted_at === undefined ||
      (typeof retrieved.deleted_at === "string" &&
        retrieved.deleted_at.length > 0),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductSku";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate seller SKU list retrieval with various valid filters and pagination.
 *
 * 1. Register and authenticate a new seller (for test isolation)
 * 2. Register a new product under that seller
 * 3. List SKUs for the product via /shoppingMall/seller/products/{productId}/skus
 *    using filter and pagination combinations:
 *
 *    - No filter (all SKUs)
 *    - By status (e.g., "active")
 *    - By partial sku_code
 *    - By price range, stock range
 *    - By sorting and different paging
 * 4. Assert only SKUs of this product are returned
 * 5. Confirm filtering, paging, sorting work as described in the business rules
 *    and DTO contracts
 * 6. Verify correct result structure and pagination metadata
 */
export async function test_api_seller_sku_list_with_valid_filters(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const registrationNumber = RandomGenerator.alphaNumeric(10);
  const sellerAuth: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: RandomGenerator.alphaNumeric(12) as string &
          tags.Format<"password">,
        business_name: RandomGenerator.name(),
        registration_number: registrationNumber,
        business_phone: RandomGenerator.mobile(),
        href: "https://example.com/onboarding",
        referrer: "https://google.com/",
        ip: undefined,
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(sellerAuth);
  TestValidator.equals("seller email matches", sellerAuth.email, sellerEmail);
  const sellerId = sellerAuth.id;

  // 2. Register a new product by the seller
  const productTitle = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 4,
    wordMax: 9,
  });
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.products.create(connection, {
      body: {
        title: productTitle,
        description: RandomGenerator.content({
          paragraphs: 1,
          sentenceMin: 5,
          sentenceMax: 8,
          wordMin: 4,
          wordMax: 10,
        }),
        default_price: 2500,
        business_status: "draft",
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(product);
  TestValidator.equals("product seller matches", product.seller.id, sellerId);

  // 3. SKU list retrievals with various filters
  // a. No filters: fetch all SKUs (default paging)
  const allSkusPage: IPageIShoppingMallProductSku.ISummary =
    await api.functional.shoppingMall.seller.products.skus.index(connection, {
      productId: product.id,
      body: {} satisfies IShoppingMallProductSku.IRequest,
    });
  typia.assert(allSkusPage);
  TestValidator.equals(
    "no filter pagination product",
    allSkusPage.pagination.current,
    1,
  );
  TestValidator.predicate("non-empty SKU data", allSkusPage.data.length >= 0);

  const sampleSku = allSkusPage.data[0];
  if (sampleSku) {
    // b. By status (using the status of first sku if available)
    const statusValue = "active"; // If known: may need real enum or sample
    const byStatus =
      await api.functional.shoppingMall.seller.products.skus.index(connection, {
        productId: product.id,
        body: {
          status: statusValue,
        } satisfies IShoppingMallProductSku.IRequest,
      });
    typia.assert(byStatus);
    for (const sku of byStatus.data) {
      TestValidator.equals(
        "sku belongs to product",
        sku.product_title,
        product.title,
      );
    }
  }

  // c. By partial sku_code (if found)
  if (sampleSku) {
    const partialCode = sampleSku.code.slice(0, 2);
    const byCode = await api.functional.shoppingMall.seller.products.skus.index(
      connection,
      {
        productId: product.id,
        body: {
          sku_code: partialCode,
        } satisfies IShoppingMallProductSku.IRequest,
      },
    );
    typia.assert(byCode);
    for (const sku of byCode.data) {
      TestValidator.predicate(
        "sku code contains search substring",
        sku.code.includes(partialCode),
      );
    }
  }

  // d. Filtering by price and stock ranges (using sample data)
  const priceFiltered =
    await api.functional.shoppingMall.seller.products.skus.index(connection, {
      productId: product.id,
      body: {
        min_price: 2000,
        max_price: 3000,
      } satisfies IShoppingMallProductSku.IRequest,
    });
  typia.assert(priceFiltered);
  for (const sku of priceFiltered.data) {
    TestValidator.predicate(
      "sku price in range (pseudo, field may not exist)",
      typeof sku === "object",
    );
  }

  // e. Pagination: fetch page 2 (if data length > default limit)
  const paged = await api.functional.shoppingMall.seller.products.skus.index(
    connection,
    {
      productId: product.id,
      body: { page: 2, limit: 1 } satisfies IShoppingMallProductSku.IRequest, // Force page 2 if enough SKUs
    },
  );
  typia.assert(paged);
  TestValidator.equals("pagination page = 2", paged.pagination.current, 2);

  // f. Sorting: by code asc
  const sortedByCode =
    await api.functional.shoppingMall.seller.products.skus.index(connection, {
      productId: product.id,
      body: {
        sort_by: "sku_code",
        order: "asc",
      } satisfies IShoppingMallProductSku.IRequest,
    });
  typia.assert(sortedByCode);
  for (let i = 1; i < sortedByCode.data.length; ++i) {
    TestValidator.predicate(
      "sku_code asc sorting",
      sortedByCode.data[i - 1].code <= sortedByCode.data[i].code,
    );
  }

  // Confirm all returned SKUs reference only this product title
  for (const pagedSkus of [allSkusPage, priceFiltered, paged, sortedByCode]) {
    for (const sku of pagedSkus.data) {
      TestValidator.equals(
        "sku product title matches",
        sku.product_title,
        product.title,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallExternalPaymentProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallExternalPaymentProvider";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";

/**
 * Test the soft-deletion workflow for a shopping mall payment as an admin user.
 *
 * Steps:
 *
 * 1. Admin user registration (/auth/admin/join)
 * 2. Create a payment record with /shoppingMall/admin/payments (as admin)
 * 3. Soft delete the payment via /shoppingMall/admin/payments/{id} (DELETE)
 * 4. Verify that deleted_at is set (auditable, not actually deleted)
 * 5. Attempt to delete the already deleted record and ensure error is raised
 */
export async function test_api_payment_soft_delete_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminName = RandomGenerator.name();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: adminName,
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. Create a fake provider and customer summary for payment (minimal fields)
  // In this test we must mock provider and customer summary IDs as required
  // Since only summary types are available for these, make up UUIDs and minimal names
  const providerId = typia.random<string & tags.Format<"uuid">>();
  const customerId = typia.random<string & tags.Format<"uuid">>();

  // 3. Create payment as admin
  const createBody = {
    customer_id: customerId,
    provider_id: providerId,
    amount: 10000,
    currency: "KRW",
    method_type: "card",
    status: "initiated",
    external_payment_id: RandomGenerator.alphaNumeric(16),
    transaction_token: RandomGenerator.alphaNumeric(16),
    requested_at: new Date().toISOString(),
  } satisfies IShoppingMallPayment.ICreate;
  const payment: IShoppingMallPayment =
    await api.functional.shoppingMall.admin.payments.create(connection, {
      body: createBody,
    });
  typia.assert(payment);
  TestValidator.equals(
    "created payment amount",
    payment.amount,
    createBody.amount,
  );
  TestValidator.equals(
    "created payment is not soft-deleted initially",
    payment.deleted_at,
    null,
  );

  // 4. Soft-delete the payment
  const erased: IShoppingMallPayment =
    await api.functional.shoppingMall.admin.payments.erase(connection, {
      paymentId: payment.id,
    });
  typia.assert(erased);
  TestValidator.equals(
    "payment ID should match after deletion",
    erased.id,
    payment.id,
  );
  TestValidator.predicate(
    "deleted_at should be set after soft-delete",
    typeof erased.deleted_at === "string" && erased.deleted_at.length > 0,
  );

  // 5. Second deletion attempt (should be denied)
  await TestValidator.error(
    "double soft-delete is denied per compliance/audit policy",
    async () => {
      await api.functional.shoppingMall.admin.payments.erase(connection, {
        paymentId: payment.id,
      });
    },
  );
}

