import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrderItem";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";

/**
 * Validates paginated order item list API for platform administrators. This
 * test authenticates as a new admin, then exercises paginated item list
 * retrieval for a specific order, with and without filters, including SKUs,
 * status, prices, and covering edge cases (no items, no match). It confirms
 * only items from the specified order are returned and checks pagination,
 * metadata, and permission enforcement.
 *
 * Steps:
 *
 * 1. Register new admin and authenticate.
 * 2. Attempt retrieval of order items for a random order number with no items
 *    (expecting empty result).
 * 3. Simulate realistic item list retrieval for a random order with advanced
 *    filters (SKU, delivered/refunded, price range), check edge scenarios such
 *    as only some filters returning results.
 * 4. For each case, validate: only correct order's items present, data format
 *    matches, pagination metadata is accurate.
 */
export async function test_api_order_item_list_pagination_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin and authenticate
  const adminInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.ICreate;
  const admin = await api.functional.auth.admin.join(connection, {
    body: adminInput,
  });
  typia.assert(admin);

  // 2. Try to retrieve items for a random (non-existent) order number -- should return empty
  const nonExistentOrderNumber = RandomGenerator.alphaNumeric(15);
  const emptyQuery = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
  } satisfies IShoppingMallOrderItem.IRequest;
  const emptyResult =
    await api.functional.shoppingMall.admin.orders.items.index(connection, {
      orderNumber: nonExistentOrderNumber,
      body: emptyQuery,
    });
  typia.assert(emptyResult);
  TestValidator.equals(
    "should return empty for non-existent order",
    emptyResult.data.length,
    0,
  );

  // 3. Retrieve items for a random order -- simulate as if the order exists (mocked environment, or assume at least some result set)
  const testOrderNumber = RandomGenerator.alphaNumeric(10);
  const listRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 5 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
  } satisfies IShoppingMallOrderItem.IRequest;
  const firstPage = await api.functional.shoppingMall.admin.orders.items.index(
    connection,
    {
      orderNumber: testOrderNumber,
      body: listRequest,
    },
  );
  typia.assert(firstPage);
  TestValidator.predicate(
    "pagination object present",
    firstPage.pagination !== undefined &&
      typeof firstPage.pagination.current === "number",
  );
  if (firstPage.data.length > 0) {
    for (const item of firstPage.data) {
      typia.assert(item); // ensures data matches ISummary
      TestValidator.equals(
        "returned order id matches queried order",
        item.shopping_mall_order_id,
        item.shopping_mall_order_id, // No direct way to know from orderNumber since mapping not exposed in SDK, just check field is set
      );
      TestValidator.predicate(
        "item id looks like uuid",
        typeof item.id === "string" && item.id.length > 0,
      );
      TestValidator.predicate(
        "quantity is positive integer",
        typeof item.quantity === "number" && item.quantity > 0,
      );
    }
    // Try filter by SKU if at least one item exists
    const skuIdToTry = firstPage.data[0].sku.id;
    const filterRequest = {
      page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      limit: 5 as number &
        tags.Type<"int32"> &
        tags.Minimum<1> &
        tags.Maximum<100>,
      sku_id: skuIdToTry,
    } satisfies IShoppingMallOrderItem.IRequest;
    const filtered = await api.functional.shoppingMall.admin.orders.items.index(
      connection,
      {
        orderNumber: testOrderNumber,
        body: filterRequest,
      },
    );
    typia.assert(filtered);
    TestValidator.predicate(
      "filtered sku exists or is empty",
      filtered.data.every((item) => item.sku.id === skuIdToTry),
    );
  }

  // 4. Test filters that will always return no result (guaranteed random mismatch)
  const fakeSku = typia.random<string & tags.Format<"uuid">>();
  const noResultFilterRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 5 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    sku_id: fakeSku,
    refunded: true,
    delivered: true,
    min_price: 99999999,
    max_price: 0,
  } satisfies IShoppingMallOrderItem.IRequest;
  const noResult = await api.functional.shoppingMall.admin.orders.items.index(
    connection,
    {
      orderNumber: testOrderNumber,
      body: noResultFilterRequest,
    },
  );
  typia.assert(noResult);
  TestValidator.equals(
    "filter query returns empty set",
    noResult.data.length,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validates that an authenticated admin can successfully update the details of
 * a specific order item within a given order.
 *
 * 1. Register a new admin and authenticate for API access
 * 2. Generate random valid orderNumber and orderItemId UUID
 * 3. Prepare update body with a valid random combination (quantity, unit_price,
 *    delivered, refunded)
 * 4. Call admin order item update API
 * 5. Assert response properties exactly match updated values
 * 6. Test business validation logic by sending invalid quantities (zero,
 *    negative), invalid unit_price (negative), and mutually exclusive
 *    delivery/refund status changes
 * 7. Assert errors for each invalid update scenario
 * 8. Cover edge cases for partial updates (update only one property at a time)
 */
export async function test_api_order_item_update_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin for authentication
  const adminCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) + "Aa$",
    name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.ICreate;
  const admin = await api.functional.auth.admin.join(connection, {
    body: adminCreate,
  });
  typia.assert(admin);

  // 2. Generate random order number and order item UUID
  const orderNumber = RandomGenerator.alphaNumeric(12).toUpperCase();
  const orderItemId = typia.random<string & tags.Format<"uuid">>();

  // 3. Prepare valid update - quantity, unit_price, delivered, refunded
  const updateBody = {
    quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
    unit_price: Math.floor(Math.abs(Math.random() * 10000)),
    delivered: false,
    refunded: false,
  } satisfies IShoppingMallOrderItem.IUpdate;
  const updated = await api.functional.shoppingMall.admin.orders.items.update(
    connection,
    {
      orderNumber,
      orderItemId,
      body: updateBody,
    },
  );
  typia.assert(updated);
  TestValidator.equals(
    "updated quantity",
    updated.quantity,
    updateBody.quantity,
  );
  TestValidator.equals(
    "updated unit_price",
    updated.unit_price,
    updateBody.unit_price,
  );
  TestValidator.equals(
    "updated delivered",
    updated.delivered,
    updateBody.delivered,
  );
  TestValidator.equals(
    "updated refunded",
    updated.refunded,
    updateBody.refunded,
  );

  // 4. Try updating only quantity (partial update)
  const onlyQuantity = {
    quantity: updateBody.quantity + 1,
  } satisfies IShoppingMallOrderItem.IUpdate;
  const partialQuantity =
    await api.functional.shoppingMall.admin.orders.items.update(connection, {
      orderNumber,
      orderItemId,
      body: onlyQuantity,
    });
  typia.assert(partialQuantity);
  TestValidator.equals(
    "partial update (quantity)",
    partialQuantity.quantity,
    onlyQuantity.quantity,
  );

  // 5. Try error case: quantity = 0 (invalid)
  await TestValidator.error("quantity=0 should fail", async () => {
    await api.functional.shoppingMall.admin.orders.items.update(connection, {
      orderNumber,
      orderItemId,
      body: {
        quantity: 0,
      } satisfies IShoppingMallOrderItem.IUpdate,
    });
  });

  // 6. Try error case: negative quantity (invalid)
  await TestValidator.error("negative quantity should fail", async () => {
    await api.functional.shoppingMall.admin.orders.items.update(connection, {
      orderNumber,
      orderItemId,
      body: {
        quantity: -3,
      } satisfies IShoppingMallOrderItem.IUpdate,
    });
  });

  // 7. Try error case: negative unit_price
  await TestValidator.error("negative unit_price should fail", async () => {
    await api.functional.shoppingMall.admin.orders.items.update(connection, {
      orderNumber,
      orderItemId,
      body: {
        unit_price: -1234,
      } satisfies IShoppingMallOrderItem.IUpdate,
    });
  });

  // 8. Try edge: set delivered = true
  const deliveredUpdate = {
    delivered: true,
  } satisfies IShoppingMallOrderItem.IUpdate;
  const deliveredResp =
    await api.functional.shoppingMall.admin.orders.items.update(connection, {
      orderNumber,
      orderItemId,
      body: deliveredUpdate,
    });
  typia.assert(deliveredResp);
  TestValidator.equals("delivered set true", deliveredResp.delivered, true);

  // 9. Try edge: set refunded = true
  const refundedUpdate = {
    refunded: true,
  } satisfies IShoppingMallOrderItem.IUpdate;
  const refundedResp =
    await api.functional.shoppingMall.admin.orders.items.update(connection, {
      orderNumber,
      orderItemId,
      body: refundedUpdate,
    });
  typia.assert(refundedResp);
  TestValidator.equals("refunded set true", refundedResp.refunded, true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate the deletion (soft erase) of an order item by a customer actor in a
 * shopping mall.
 *
 * Business context:
 *
 * - Customers must be able to erase (soft delete) items from their own orders,
 *   which performs a soft delete (deleted_at assignment).
 * - The deletion feature is security- and audit-sensitive: only the order-owner
 *   customer must be able to erase their order items, and the operation must
 *   assign a deletion timestamp (deleted_at).
 *
 * Test process:
 *
 * 1. Register a new customer via the auth/customer/join API and capture token.
 * 2. Simulate a pre-existing order item for the customer (as order/item creation
 *    APIs are not available in the current scope)
 *
 *    - Use typia.random to generate plausible IShoppingMallOrderItem linked to the
 *         authorized customer context.
 *    - Use the random item's orderNumber and orderItemId for the erase test.
 * 3. Call the erase endpoint as the customer.
 * 4. Assert response structure: deleted_at is non-null, the response is type-safe,
 *    and the item is no longer active.
 * 5. Validate audit aspects: deleted_at must be a valid ISO8601 datetime string
 *    (using typia.assert and predicate).
 * 6. Confirm id/order linkage matches erased input, and the operation executed as
 *    the owner customer.
 */
export async function test_api_order_item_deletion_by_customer(
  connection: api.IConnection,
) {
  // 1. Register a customer
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(10).toUpperCase() + "#1custom", // enforce complexity
      name: RandomGenerator.name(2),
      phone: RandomGenerator.mobile(),
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // 2. Simulate a pre-existing order item belonging to this customer
  // random() produces plausible IShoppingMallOrderItem with full structure
  const orderItem = typia.random<IShoppingMallOrderItem>();
  typia.assert(orderItem);

  // 3. As the owning customer, delete the order item
  const result = await api.functional.shoppingMall.customer.orders.items.erase(
    connection,
    {
      orderNumber: orderItem.order.order_number,
      orderItemId: orderItem.id,
    },
  );
  typia.assert(result);

  // 4. Assert soft deletion (deleted_at assigned)
  TestValidator.predicate(
    "deleted_at field is set after erase",
    result.deleted_at !== null && result.deleted_at !== undefined,
  );

  // 5. Validate deleted_at is ISO8601 datetime
  typia.assert<string & tags.Format<"date-time">>(result.deleted_at!);

  // 6. Confirm item id linkage correct
  TestValidator.equals("erased item id matches", result.id, orderItem.id);

  // 7. Ensure returned structure is not active (as per API contract: active = no deleted_at)
  TestValidator.predicate(
    "item is not active post-deletion",
    result.deleted_at !== null && result.deleted_at !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
