 *    - Filter by is_email_verified (should be false by default)
 *    - Created_from/created_to window queries (test match and no-match)
 *    - Sorting by email, name, status, created_at ascending/descending
 *    - Confirm pagination metadata (current, pages, records)
 *    - Query with unmatched filters (gibberish name)
 *    - For each result, validate only id/name/email are visible (no password/token)
 * 3. Unauthenticated call to PATCH /shoppingMall/admin/admins gets rejected
 */
export async function test_api_admins_index_query_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // Register three distinct platform admins and collect their info
  const admins: IShoppingMallAdmin.IAuthorized[] = [];
  for (let i = 0; i < 3; ++i) {
    const adminData = {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
    } satisfies IShoppingMallAdmin.ICreate;
    const admin = await api.functional.auth.admin.join(connection, {
      body: adminData,
    });
    typia.assert(admin);
    admins.push(admin);
  }

  // Use the first admin for all authenticated scenarios
  const main = admins[0];
  // Pagination & limit tests
  {
    const page1 = await api.functional.shoppingMall.admin.admins.index(
      connection,
      {
        body: {
          page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 2 as number &
            tags.Type<"int32"> &
            tags.Minimum<1> &
            tags.Maximum<100>,
        } satisfies IShoppingMallAdmin.IRequest,
      },
    );
    typia.assert(page1);
    TestValidator.equals("pagination limit=2", page1.pagination.limit, 2);
    // Should have data for first two admins
    TestValidator.equals("page records <= limit", page1.data.length <= 2, true);
  }
  // Pagination next page
  {
    const page2 = await api.functional.shoppingMall.admin.admins.index(
      connection,
      {
        body: {
          page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 2 as number &
            tags.Type<"int32"> &
            tags.Minimum<1> &
            tags.Maximum<100>,
        } satisfies IShoppingMallAdmin.IRequest,
      },
    );
    typia.assert(page2);
    // Depending on account order, length can be 1 or 2
    TestValidator.predicate(
      "page2 has admins or is empty",
      page2.data.length >= 0 && page2.data.length <= 2,
    );
  }
  // Filtering by known admin email (should be only 1 result)
  for (const a of admins) {
    const list = await api.functional.shoppingMall.admin.admins.index(
      connection,
      {
        body: {
          email: a.email,
          page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 10 as number &
            tags.Type<"int32"> &
            tags.Minimum<1> &
            tags.Maximum<100>,
        } satisfies IShoppingMallAdmin.IRequest,
      },
    );
    typia.assert(list);
    TestValidator.equals(
      "filter by email returns exactly 1",
      list.data.length,
      1,
    );
    const found = list.data[0];
    TestValidator.equals("admin email matches", found.email, a.email);
  }
  // Partial email filter (use first half)
  {
    const partial = main.email.slice(0, Math.floor(main.email.length / 2));
    const list = await api.functional.shoppingMall.admin.admins.index(
      connection,
      {
        body: {
          email: partial,
          page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 10 as number & tags.Type<"int32"> & tags.Maximum<100>,
        } satisfies IShoppingMallAdmin.IRequest,
      },
    );
    typia.assert(list);
    TestValidator.predicate(
      "partial email match returns at least 1",
      list.data.length >= 1,
    );
    TestValidator.predicate(
      "result contains the admin with full email",
      list.data.some((x) => x.email === main.email),
    );
  }
  // Filter by admin name (full match and partial)
  {
    const full = main.name;
    const partial = main.name.length > 2 ? main.name.slice(0, 2) : main.name;
    {
      const list = await api.functional.shoppingMall.admin.admins.index(
        connection,
        {
          body: {
            name: full,
            page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
            limit: 20 as number & tags.Type<"int32"> & tags.Maximum<100>,
          } satisfies IShoppingMallAdmin.IRequest,
        },
      );
      typia.assert(list);
      TestValidator.predicate(
        "full name filter returns at least 1",
        list.data.length >= 1,
      );
      TestValidator.predicate(
        "result contains admin with name",
        list.data.some((x) => x.name === main.name),
      );
    }
    {
      const list = await api.functional.shoppingMall.admin.admins.index(
        connection,
        {
          body: {
            name: partial,
            page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
            limit: 20 as number & tags.Type<"int32"> & tags.Maximum<100>,
          } satisfies IShoppingMallAdmin.IRequest,
        },
      );
      typia.assert(list);
      TestValidator.predicate(
        "partial name filter returns >=1",
        list.data.length >= 1,
      );
    }
  }
  // Filter by is_email_verified=false (should catch all just-registered)
  {
    const list = await api.functional.shoppingMall.admin.admins.index(
      connection,
      {
        body: {
          is_email_verified: false,
          page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 20 as number & tags.Type<"int32"> & tags.Maximum<100>,
        } satisfies IShoppingMallAdmin.IRequest,
      },
    );
    typia.assert(list);
    TestValidator.predicate(
      "is_email_verified=false returns at least some results",
      list.data.length >= 1,
    );
    for (const x of list.data)
      TestValidator.equals(
        "is_email_verified never leaks",
        typeof (x as any).is_email_verified,
        "undefined",
      );
  }
  // Filter by impossible gibberish name
  {
    const list = await api.functional.shoppingMall.admin.admins.index(
      connection,
      {
        body: {
          name: "@@@@gibberish@@@@",
          page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 10 as number & tags.Type<"int32"> & tags.Maximum<100>,
        } satisfies IShoppingMallAdmin.IRequest,
      },
    );
    typia.assert(list);
    TestValidator.equals("no results for gibberish name", list.data.length, 0);
  }
  // created_at range tests: bracket tightly around main account creation
  {
    const created = main.created_at;
    const before = new Date(Date.parse(created) - 5000).toISOString();
    const after = new Date(Date.parse(created) + 5000).toISOString();
    {
      const list = await api.functional.shoppingMall.admin.admins.index(
        connection,
        {
          body: {
            created_from: before,
            created_to: after,
            page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
            limit: 10 as number & tags.Type<"int32"> & tags.Maximum<100>,
          } satisfies IShoppingMallAdmin.IRequest,
        },
      );
      typia.assert(list);
      TestValidator.predicate(
        "main admin in created_at window",
        list.data.some((x) => x.email === main.email),
      );
    }
    {
      const now = new Date().toISOString();
      const early = new Date(0).toISOString();
      // Filter for non-existent window
      const list = await api.functional.shoppingMall.admin.admins.index(
        connection,
        {
          body: {
            created_from: now,
            created_to: now,
            page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
            limit: 10 as number & tags.Type<"int32"> & tags.Maximum<100>,
          } satisfies IShoppingMallAdmin.IRequest,
        },
      );
      typia.assert(list);
      TestValidator.equals(
        "created_at range with no matches is empty",
        list.data.length,
        0,
      );
    }
  }
  // Sorting by email ASC/DESC
  for (const sort_by of ["email", "name", "status", "created_at"] as const) {
    for (const sort_order of ["asc", "desc"] as const) {
      const list = await api.functional.shoppingMall.admin.admins.index(
        connection,
        {
          body: {
            sort_by,
            sort_order,
            page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
            limit: 10 as number & tags.Type<"int32"> & tags.Maximum<100>,
          } satisfies IShoppingMallAdmin.IRequest,
        },
      );
      typia.assert(list);
      // Simple check: at least as many as admins we created exist
      TestValidator.predicate(
        `${sort_by}:${sort_order} returns >= 3`,
        list.data.length >= 3,
      );
      // Check all fields match summary schema
      for (const x of list.data) {
        // id is uuid, name and email are strings, no other fields
        TestValidator.predicate(
          "id is present",
          typeof x.id === "string" && x.id.length > 0,
        );
        TestValidator.predicate(
          "name is present",
          typeof x.name === "string" && x.name.length > 0,
        );
        TestValidator.predicate(
          "email is present",
          typeof x.email === "string" && x.email.length > 0,
        );
        // No sensitive data
        TestValidator.equals(
          "no password leak",
          typeof (x as any).password,
          "undefined",
        );
        TestValidator.equals(
          "no token leak",
          typeof (x as any).token,
          "undefined",
        );
      }
    }
  }

  // Negative: unauthenticated call must be rejected
  const anonConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated admin index is rejected",
    async () => {
      await api.functional.shoppingMall.admin.admins.index(anonConn, {
        body: {
          page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 1 as number &
            tags.Type<"int32"> &
            tags.Minimum<1> &
            tags.Maximum<100>,
        } satisfies IShoppingMallAdmin.IRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";

/**
 * Test retrieving administrator details and RBAC enforcement.
 *
 * This test covers the following scenarios for GET
 * /shoppingMall/admin/admins/{adminId}:
 *
 * 1. Register a new admin and authenticate (save id/token)
 * 2. Successfully retrieve details using the admin's id and an admin session
 *
 *    - Validate all returned fields match IShoppingMallAdmin (no sensitive data like
 *         password)
 *    - Validate the returned record matches original registration data (except
 *         timestamps/ids)
 * 3. Error: Attempt to access detail for random/nonexistent adminId (should fail
 *    with not-found)
 * 4. Error: Attempt to access with unauthenticated session (should fail)
 * 5. Error: Attempt to access with invalid/expired token (should fail)
 *
 * Assumptions:
 *
 * - Only authenticated admins can use this endpoint (RBAC enforced)
 * - Email, name, and status are included in the response
 * - System-managed fields (created_at/updated_at) are present
 *
 * Steps:
 *
 * 1. Register a new admin (random unique email + secure password + name)
 * 2. Fetch the registered admin's full detail using their id
 * 3. Assert all expected fields exist
 * 4. Assert no password or sensitive fields exposed (not possible via DTO, but
 *    double check)
 * 5. Assert error when requesting with random UUID (not found)
 * 6. Assert error when not authenticated
 */
export async function test_api_admin_detail_retrieval_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin account
  const createAdminBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(2),
  } satisfies IShoppingMallAdmin.ICreate;
  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: createAdminBody,
  });
  typia.assert(adminAuth);

  // 2. Retrieve admin detail with correct admin session
  const adminDetail = await api.functional.shoppingMall.admin.admins.at(
    connection,
    {
      adminId: adminAuth.id,
    },
  );
  typia.assert(adminDetail);
  // Validate the fields are matching what was registered (except timestamps)
  TestValidator.equals("admin id matches", adminDetail.id, adminAuth.id);
  TestValidator.equals(
    "admin email matches",
    adminDetail.email,
    createAdminBody.email,
  );
  TestValidator.equals(
    "admin name matches",
    adminDetail.name,
    createAdminBody.name,
  );
  // No sensitive fields present by DTO definition; check type only

  // 3. Attempt retrieval with random non-existent adminId (should error)
  await TestValidator.error("not-found for random admin id", async () => {
    await api.functional.shoppingMall.admin.admins.at(connection, {
      adminId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 4. Attempt retrieval with unauthenticated session (should error)
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated access fails", async () => {
    await api.functional.shoppingMall.admin.admins.at(unauthConn, {
      adminId: adminAuth.id,
    });
  });

  // 5. Attempt retrieval after token removal/invalid (simulate invalid session)
  // We'll simulate by deleting headers and using again (effectively like 4), or use random invalid token
  const invalidConn: api.IConnection = {
    ...connection,
    headers: { Authorization: "Bearer invalid-token" },
  };
  await TestValidator.error("invalid token access fails", async () => {
    await api.functional.shoppingMall.admin.admins.at(invalidConn, {
      adminId: adminAuth.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductRating } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductRating";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Verify successful creation of a product review by a verified customer who has
 * purchased the product through a specific order item.
 *
 * This test covers the following steps:
 *
 * 1. Generate required reference objects for customer, session, product, product
 *    SKU, order, order item, and product rating, each as summary instances
 *    (real-life setup would include full purchase workflow, but for test scope
 *    we use random valid summary payloads to focus on review creation).
 * 2. Construct valid review creation request body according to
 *    IShoppingMallReview.ICreate, ensuring:
 *
 *    - Title is non-empty string;
 *    - Body is between 10 and 1000 characters;
 *    - All required summary IDs are included;
 *    - Is_draft and moderation_status are properly set (as per business rules:
 *         system initially sets as draft and in pending moderation, if
 *         applicable).
 * 3. Call api.functional.shoppingMall.reviews.create with the request body.
 * 4. Validate the response:
 *
 *    - Full review object is returned according to IShoppingMallReview
 *    - All contextual references (customer, session, product, SKU, order, order
 *         item, rating) are present as summaries
 *    - The review's properties (title, body, is_draft, moderation_status) match
 *         those provided in the creation request
 *    - Review has a unique id and correct timestamps.
 */
export async function test_api_review_creation_by_verified_customer(
  connection: api.IConnection,
) {
  // Step 1: Randomly generate summary reference objects for all required fields
  const customer = typia.random<IShoppingMallCustomer.ISummary>();
  const session = typia.random<IShoppingMallCustomerSession.ISummary>();
  const product = typia.random<IShoppingMallProduct.ISummary>();
  const productSku = typia.random<IShoppingMallProductSku.ISummary>();
  const order = typia.random<IShoppingMallOrder.ISummary>();
  const orderItem: IShoppingMallOrderItem.ISummary = {
    ...typia.random<IShoppingMallOrderItem.ISummary>(),
    shopping_mall_order_id: order.id,
    sku: productSku,
  };
  const rating = typia.random<IShoppingMallProductRating.ISummary>();

  // Step 2: Create valid review request body satisfying creation constraints
  const requestBody = {
    title: RandomGenerator.paragraph({
      sentences: 2,
      wordMin: 4,
      wordMax: 10,
    }) as string & tags.MinLength<1>,
    body: RandomGenerator.paragraph({
      sentences: 15,
      wordMin: 4,
      wordMax: 10,
    }) as string & tags.MinLength<10> & tags.MaxLength<1000>,
    shopping_mall_product_id: product.id,
    shopping_mall_product_sku_id: productSku.id,
    shopping_mall_order_id: order.id,
    shopping_mall_order_item_id: orderItem.id,
    shopping_mall_product_rating_id: rating.id,
    is_draft: false,
    moderation_status: "pending",
    withdrawn_at: null,
  } satisfies IShoppingMallReview.ICreate;

  // Step 3: Call review creation API
  const review = await api.functional.shoppingMall.reviews.create(connection, {
    body: requestBody,
  });
  typia.assert(review);

  // Step 4: Validate returned data integrity and context
  TestValidator.predicate(
    "review id must be a valid uuid",
    typeof review.id === "string" && review.id.length > 0,
  );
  TestValidator.equals(
    "review title matches request",
    review.title,
    requestBody.title,
  );
  TestValidator.equals(
    "review body matches request",
    review.body,
    requestBody.body,
  );
  TestValidator.equals(
    "review is_draft flag matches",
    review.is_draft,
    requestBody.is_draft,
  );
  TestValidator.equals(
    "review moderation_status matches",
    review.moderation_status,
    requestBody.moderation_status,
  );
  TestValidator.equals(
    "review withdrawn_at should be null",
    review.withdrawn_at,
    null,
  );
  TestValidator.equals(
    "review product id matches",
    review.product.id,
    product.id,
  );
  TestValidator.equals(
    "review productSku id matches",
    review.productSku.id,
    productSku.id,
  );
  TestValidator.equals("review order id matches", review.order.id, order.id);
  TestValidator.equals(
    "review orderItem id matches",
    review.orderItem.id,
    orderItem.id,
  );
  TestValidator.equals("review rating id matches", review.rating.id, rating.id);
  TestValidator.equals(
    "review customer id matches",
    review.customer.id,
    customer.id,
  );
  TestValidator.equals(
    "review customerSession id matches",
    review.customerSession.id,
    session.id,
  );
  TestValidator.predicate(
    "review created_at is non-empty ISO 8601 string",
    typeof review.created_at === "string" && review.created_at.length > 0,
  );
  TestValidator.predicate(
    "review updated_at is non-empty ISO 8601 string",
    typeof review.updated_at === "string" && review.updated_at.length > 0,
  );
  TestValidator.equals(
    "review deleted_at should be null",
    review.deleted_at,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductRating } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductRating";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test updating a product review by its rightful owner customer.
 *
 * - Authenticates as a newly registered customer and creates a review as the
 *   owner.
 * - Successfully updates the review's content (title, body), toggles
 *   draft/publish state, and changes moderation status using allowed fields.
 * - Ensures modified fields are actually updated and audit (updated_at) is
 *   refreshed.
 * - Validates the update is only permitted for the owner within allowed edit
 *   times and states.
 * - Attempts to update the review as a non-owner customer and expects failure
 *   (forbidden error).
 */
export async function test_api_review_update_by_owner_customer(
  connection: api.IConnection,
) {
  // Register and authenticate as Owner Customer
  const ownerInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) + "Aa.",
    name: RandomGenerator.name(2),
    phone: RandomGenerator.mobile(),
  } satisfies IShoppingMallCustomer.ICreate;
  const ownerAuth: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, { body: ownerInput });
  typia.assert(ownerAuth);

  // Create a review as Owner Customer
  const reviewCreateInput = {
    // For realistic linking, generate all as random UUIDs
    title: RandomGenerator.paragraph({ sentences: 2 }),
    body: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 10,
      sentenceMax: 20,
    }),
    shopping_mall_product_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_product_sku_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_order_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_order_item_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_product_rating_id: typia.random<
      string & tags.Format<"uuid">
    >(),
    is_draft: false,
    moderation_status: "pending",
    withdrawn_at: null,
  } satisfies IShoppingMallReview.ICreate;
  const review: IShoppingMallReview =
    await api.functional.shoppingMall.reviews.create(connection, {
      body: reviewCreateInput,
    });
  typia.assert(review);

  // Owner updates the review (change title, body, draft, and moderation status)
  const updateInput = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    body: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 12,
      sentenceMax: 30,
    }),
    is_draft: true,
    moderation_status: "approved",
    moderation_reason: "Automated review quality verified",
    withdrawn_at: null,
  } satisfies IShoppingMallReview.IUpdate;
  const updatedReview: IShoppingMallReview =
    await api.functional.shoppingMall.customer.reviews.update(connection, {
      reviewId: review.id,
      body: updateInput,
    });
  typia.assert(updatedReview);
  TestValidator.notEquals(
    "review updated_at changes after update",
    updatedReview.updated_at,
    review.updated_at,
  );
  TestValidator.equals("review id is unchanged", updatedReview.id, review.id);
  TestValidator.equals("title updated", updatedReview.title, updateInput.title);
  TestValidator.equals("body updated", updatedReview.body, updateInput.body);
  TestValidator.equals(
