 *    duplicate position.
 * 8. Confirm access control by simulating an unauthenticated request (new
 *    connection instance) and expect an error.
 */
export async function test_api_sku_image_upload_by_seller(
  connection: api.IConnection,
) {
  // 1. Register seller
  const sellerAuth: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.Format<"password">>(),
        business_name: RandomGenerator.name(),
        registration_number: RandomGenerator.alphaNumeric(10),
        business_phone: RandomGenerator.mobile(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
        ip: null,
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(sellerAuth);

  // 2. Generate random valid productId and skuId (simulate existing)
  const productId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const skuId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  // Prepare valid image data
  const cdn_uri: string & tags.Format<"uri"> = typia.random<
    string & tags.Format<"uri">
  >();
  const position: number & tags.Type<"int32"> = typia.random<
    number & tags.Type<"int32">
  >();
  const alt_text: string = RandomGenerator.paragraph({ sentences: 3 });

  // 3. Upload image (should succeed)
  const imgInput = {
    cdn_uri,
    alt_text,
    position,
    shopping_mall_product_id: null,
    shopping_mall_product_sku_id: skuId,
  } satisfies IShoppingMallProductImage.ICreate;
  const image: IShoppingMallProductImage =
    await api.functional.shoppingMall.seller.products.skus.images.create(
      connection,
      {
        productId,
        skuId,
        body: imgInput,
      },
    );
  typia.assert(image);
  TestValidator.equals(
    "image attaches only to SKU",
    image.shopping_mall_product_sku_id,
    skuId,
  );
  TestValidator.equals(
    "product association is null on SKU image",
    image.shopping_mall_product_id,
    null,
  );
  TestValidator.equals("cdn_uri matches input", image.cdn_uri, cdn_uri);
  TestValidator.equals("position matches input", image.position, position);
  TestValidator.equals("alt_text matches input", image.alt_text, alt_text);

  // 4. Try to upload a second image with duplicate position (should fail)
  await TestValidator.error(
    "duplicate position on same SKU is rejected",
    async () => {
      await api.functional.shoppingMall.seller.products.skus.images.create(
        connection,
        {
          productId,
          skuId,
          body: {
            cdn_uri: typia.random<string & tags.Format<"uri">>(),
            alt_text: RandomGenerator.paragraph({ sentences: 2 }),
            position, // same position as previous
            shopping_mall_product_id: null,
            shopping_mall_product_sku_id: skuId,
          } satisfies IShoppingMallProductImage.ICreate,
        },
      );
    },
  );

  // 5. Access control: Unauthenticated call must be rejected
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated actor cannot upload SKU image",
    async () => {
      await api.functional.shoppingMall.seller.products.skus.images.create(
        unauthConn,
        {
          productId,
          skuId,
          body: {
            cdn_uri: typia.random<string & tags.Format<"uri">>(),
            alt_text: null,
            position: typia.random<number & tags.Type<"int32">>(),
            shopping_mall_product_id: null,
            shopping_mall_product_sku_id: skuId,
          } satisfies IShoppingMallProductImage.ICreate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test updating SKU-level image metadata as a seller, enforcing
 * updatable/protected field constraints and business rules.
 *
 * Steps:
 *
 * 1. Seller account registration (auth.seller.join).
 * 2. Upload SKU-level image (shoppingMall.seller.products.skus.images.create) for
 *    random product/sku IDs.
 * 3. Update allowed fields: position, alt_text, label -- verify OK.
 * 4. Register another seller and verify that unauthorized update by other seller
 *    fails.
 * 5. Validate successful update for allowed fields and correct enforcement of
 *    business rules (protected fields cannot be updated by type system,
 *    uniqueness cannot be checked in this test as only one image is created for
 *    this SKU).
 */
export async function test_api_sku_image_update_by_seller(
  connection: api.IConnection,
) {
  // 1. Register seller
  const seller_input = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    business_name: RandomGenerator.name(),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://seller.example.com/register",
    referrer: "https://seller.example.com/",
    ip: undefined,
  } satisfies IShoppingMallSeller.ICreate;
  const seller = await api.functional.auth.seller.join(connection, {
    body: seller_input,
  });
  typia.assert(seller);

  // 2. Upload SKU-level image
  const productId = typia.random<string & tags.Format<"uuid">>();
  const skuId = typia.random<string & tags.Format<"uuid">>();
  const image_create_body = {
    cdn_uri:
      "https://cdn.example.com/image/" + RandomGenerator.alphaNumeric(16),
    alt_text: RandomGenerator.paragraph({ sentences: 2 }),
    position: 1,
    label: RandomGenerator.name(2),
    shopping_mall_product_sku_id: skuId,
    shopping_mall_product_id: undefined,
  } satisfies IShoppingMallProductImage.ICreate;
  const image =
    await api.functional.shoppingMall.seller.products.skus.images.create(
      connection,
      {
        productId,
        skuId,
        body: image_create_body,
      },
    );
  typia.assert(image);
  TestValidator.equals(
    "image association correct",
    image.shopping_mall_product_sku_id,
    skuId,
  );
  TestValidator.equals(
    "image association correct",
    image.shopping_mall_product_id,
    undefined,
  );

  // 3. Update allowed fields
  const new_alt_text = RandomGenerator.paragraph({ sentences: 2 });
  const new_label = RandomGenerator.name(3);
  const new_position = 2;
  const updated =
    await api.functional.shoppingMall.seller.products.skus.images.update(
      connection,
      {
        productId,
        skuId,
        imageId: image.id,
        body: {
          alt_text: new_alt_text,
          label: new_label,
          position: new_position,
        } satisfies IShoppingMallProductImage.IUpdate,
      },
    );
  typia.assert(updated);
  TestValidator.equals("alt_text updated", updated.alt_text, new_alt_text);
  TestValidator.equals("label updated", updated.label, new_label);
  TestValidator.equals("position updated", updated.position, new_position);
  TestValidator.equals("cdn_uri unchanged", updated.cdn_uri, image.cdn_uri);

  // 4. Register another seller and check permission error
  const otherSeller = await api.functional.auth.seller.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      business_name: RandomGenerator.name(),
      registration_number: RandomGenerator.alphaNumeric(10),
      business_phone: RandomGenerator.mobile(),
      href: "https://seller2.example.com/register",
      referrer: "https://seller2.example.com/",
      ip: undefined,
    },
  });
  typia.assert(otherSeller);
  await TestValidator.error(
    "unauthorized seller cannot update image",
    async () => {
      await api.functional.shoppingMall.seller.products.skus.images.update(
        connection,
        {
          productId,
          skuId,
          imageId: image.id,
          body: {
            alt_text: RandomGenerator.paragraph({ sentences: 2 }),
          } satisfies IShoppingMallProductImage.IUpdate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validates that a seller can successfully update a product image: sellers can
 * update only mutable fields (label, alt_text, position), and cannot change
 * immutable fields like product association or cdn_uri.
 *
 * Workflow:
 *
 * 1. Seller registration (join)
 * 2. Create an image for a product (simulate with a random UUID for product)
 * 3. Update the image: change position, alt_text, and label
 * 4. Assert that immutable fields did not change and writable fields are updated.
 * 5. Check that updated_at is properly refreshed.
 */
export async function test_api_product_image_update_successful_by_seller(
  connection: api.IConnection,
) {
  // 1. Register seller
  const sellerCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    business_name: RandomGenerator.name(),
    registration_number: RandomGenerator.alphaNumeric(12),
    business_phone: RandomGenerator.mobile(),
    href: "https://mall.wrtn.test/shopseller/signup",
    referrer: "https://mall.wrtn.test/",
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies IShoppingMallSeller.ICreate;
  const seller = await api.functional.auth.seller.join(connection, {
    body: sellerCreate,
  });
  typia.assert(seller);
  TestValidator.equals("seller is created", seller.email, sellerCreate.email);
  // 2. Create product image
  const productId = typia.random<string & tags.Format<"uuid">>();
  const origImageBody = {
    cdn_uri:
      "https://cdn.mall.wrtn.test/assets/" + RandomGenerator.alphaNumeric(24),
    position: typia.random<number & tags.Type<"int32">>(),
    alt_text: RandomGenerator.paragraph({ sentences: 2 }),
    label: RandomGenerator.name(2),
    shopping_mall_product_id: productId,
    shopping_mall_product_sku_id: null,
  } satisfies IShoppingMallProductImage.ICreate;
  const image = await api.functional.shoppingMall.seller.products.images.create(
    connection,
    { productId, body: origImageBody },
  );
  typia.assert(image);
  TestValidator.equals(
    "image created at expected position",
    image.position,
    origImageBody.position,
  );
  TestValidator.equals(
    "image's original alt_text",
    image.alt_text,
    origImageBody.alt_text,
  );
  TestValidator.equals("image's label", image.label, origImageBody.label);
  TestValidator.equals(
    "image's product id",
    image.shopping_mall_product_id,
    productId,
  );
  TestValidator.equals("image's cdn_uri", image.cdn_uri, origImageBody.cdn_uri);
  // 3. Update the image: change position, alt_text and label
  const updateBody = {
    position: origImageBody.position + 1,
    alt_text: RandomGenerator.paragraph({ sentences: 3 }),
    label: RandomGenerator.name(3),
  } satisfies IShoppingMallProductImage.IUpdate;
  // capture existing values for comparison
  const prevUpdatedAt = image.updated_at;
  const updated =
    await api.functional.shoppingMall.seller.products.images.update(
      connection,
      { productId, imageId: image.id, body: updateBody },
    );
  typia.assert(updated);
  // 4. Assert updated fields match
  TestValidator.equals(
    "updated position is reflected",
    updated.position,
    updateBody.position,
  );
  TestValidator.equals(
    "updated alt_text is reflected",
    updated.alt_text,
    updateBody.alt_text,
  );
  TestValidator.equals(
    "updated label is reflected",
    updated.label,
    updateBody.label,
  );
  // 5. Assert that immutable fields have not changed
  TestValidator.equals(
    "shopping_mall_product_id is unchanged",
    updated.shopping_mall_product_id,
    image.shopping_mall_product_id,
  );
  TestValidator.equals("cdn_uri is unchanged", updated.cdn_uri, image.cdn_uri);
  TestValidator.equals("image id is unchanged", updated.id, image.id);
  // 6. updated_at should be refreshed (string comparison)
  TestValidator.notEquals(
    "updated_at field is refreshed",
    updated.updated_at,
    prevUpdatedAt,
  );
  // 7. created_at is not changed
  TestValidator.equals(
    "created_at unchanged",
    updated.created_at,
    image.created_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test that a seller can soft-delete an image of their product, and various
 * business rules on deletion are enforced.
 *
 * 1. Register two seller accounts (owner and other).
 * 2. Using the owner seller, create a dummy product and attach two images
 *    (positions 1 and 2).
 * 3. Verify that authentication is required for deletion.
 * 4. Owner seller soft-deletes the first image using the API; verify deleted_at is
 *    set, and position recalculation for the remaining image occurs.
 * 5. Verify deleted image is no longer present when listing gallery images.
 * 6. Attempt to delete the image as the second seller; verify permission is
 *    denied.
 * 7. Attempt to delete a non-associated image (e.g., non-existent, or not for this
 *    product); verify error.
 */
export async function test_api_product_image_delete_successful_by_seller(
  connection: api.IConnection,
) {
  // 1. Register first (owner) seller
  const ownerSellerEmail = typia.random<string & tags.Format<"email">>();
  const seller1 = await api.functional.auth.seller.join(connection, {
    body: {
      email: ownerSellerEmail,
      password: RandomGenerator.alphaNumeric(10) as string &
        tags.Format<"password">,
      business_name: RandomGenerator.name(),
      registration_number: RandomGenerator.alphaNumeric(10),
      business_phone: RandomGenerator.mobile(),
      href: "https://test.local/register",
      referrer: "https://test.local/landing",
      ip: null,
    },
  });
  typia.assert(seller1);
  const ownerSellerId = seller1.id;

  // 2. Register the second seller (attacker)
  const attackerEmail = typia.random<string & tags.Format<"email">>();
  const seller2 = await api.functional.auth.seller.join(connection, {
    body: {
      email: attackerEmail,
      password: RandomGenerator.alphaNumeric(10) as string &
        tags.Format<"password">,
      business_name: RandomGenerator.name(),
      registration_number: RandomGenerator.alphaNumeric(10),
      business_phone: RandomGenerator.mobile(),
      href: "https://test.local/register2",
      referrer: "https://test.local/landing2",
      ip: null,
    },
  });
  typia.assert(seller2);

  // Imagine the owner seller has a productId, using a random UUID for this test
  const productId = typia.random<string & tags.Format<"uuid">>();

  // 3. Create two images for the product
  const imgReq1 = {
    cdn_uri: "https://img.cdn.test/asset1.jpg",
    alt_text: "Main product image",
    position: 1,
    label: "Main",
    shopping_mall_product_id: productId,
    shopping_mall_product_sku_id: null,
  } satisfies IShoppingMallProductImage.ICreate;
  const img1 = await api.functional.shoppingMall.seller.products.images.create(
    connection,
    {
      productId,
      body: imgReq1,
    },
  );
  typia.assert(img1);
  const image1Id = img1.id;

  const imgReq2 = {
    cdn_uri: "https://img.cdn.test/asset2.jpg",
    alt_text: "Second product image",
    position: 2,
    label: "Gallery",
    shopping_mall_product_id: productId,
    shopping_mall_product_sku_id: null,
  } satisfies IShoppingMallProductImage.ICreate;
  const img2 = await api.functional.shoppingMall.seller.products.images.create(
    connection,
    {
      productId,
      body: imgReq2,
    },
  );
  typia.assert(img2);

  // 4. Owner seller soft-deletes the first image
  await api.functional.shoppingMall.seller.products.images.erase(connection, {
    productId,
    imageId: image1Id,
  });
  // There is no direct fetch endpoint, so after deletion, we would typically check listing, but this is skipped due to API constraints

  // 5. Ensure deleted image is not accessible anymore (simulate by trying to delete again and expecting error)
  await TestValidator.error(
    "cannot delete same image twice (already deleted)",
    async () => {
      await api.functional.shoppingMall.seller.products.images.erase(
        connection,
        {
          productId,
          imageId: image1Id,
        },
      );
    },
  );

  // 6. Attempt to delete img2 as another seller (should fail with permission denied)
  // Switch authentication to second seller: we can just re-join (token in connection) for e2e
  await api.functional.auth.seller.join(connection, {
    body: {
      email: attackerEmail,
      password: seller2.token.access as string & tags.Format<"password">,
      business_name: seller2.business_name,
      registration_number: seller2.registration_number,
      business_phone: seller2.business_phone,
      href: "https://test.local/register2",
      referrer: "https://test.local/landing2",
      ip: null,
    },
  });
  await TestValidator.error(
    "non-owner cannot delete product's images",
    async () => {
      await api.functional.shoppingMall.seller.products.images.erase(
        connection,
        {
          productId,
          imageId: img2.id,
        },
      );
    },
  );

  // 7. Cleanup: Delete non-existent image (should error)
  await TestValidator.error("deleting non-existent image fails", async () => {
    await api.functional.shoppingMall.seller.products.images.erase(connection, {
      productId,
      imageId: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";
import type { IShoppingMallShipmentTrackingHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipmentTrackingHistory";
import type { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";

/**
 * Validates that an authenticated customer can retrieve a specific shipment
 * tracking history event.
 *
 * **Business context**: Shipment tracking enables customers to view the status
 * of their orders during logistics fulfillment. Only the owning customer should
 * be able to access shipment tracking histories for their orders; cross-user or
 * unauthorized access must be denied by business rules. This test sets up the
 * full multi-actor flow so customer access boundaries and event structure are
 * validated.
 *
 * **Flow**:
 *
 * 1. Register a new customer and retain credentials (join)
 * 2. Register a new admin and retain credentials (join)
 * 3. Authenticate as admin; create a new 'active' shipping partner
 * 4. As admin, create a shipment for the customer's (mock) order/order item,
 *    assigning to the shipping partner
 * 5. As admin, append a tracking event to the shipment (realistic values)
 * 6. Switch to customer session
 * 7. Retrieve the tracking event as customer using shipmentId/trackingHistoryId
 * 8. Assert the returned event DTO matches schema and business constraints,
 *    including shipment_id links
 * 9. (Optional) Negative: Cross-user attempts or invalid IDs are not permitted
 *    (not shown in this positive-path flow)
 */
export async function test_api_customer_shipment_tracking_event_retrieval(
  connection: api.IConnection,
) {
  // 1. Register new customer and retain credentials
  const customerPassword = RandomGenerator.alphaNumeric(10);
  const customerEmail = RandomGenerator.alphaNumeric(12) + "@customer.com";
  const customerName = RandomGenerator.name();
  const customerPhone = RandomGenerator.mobile();
  const customerJoin = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword satisfies string as string,
      name: customerName,
      phone: customerPhone,
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customerJoin);

  // 2. Register new admin and retain credentials
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminEmail = RandomGenerator.alphaNumeric(10) + "@admin.com";
  const adminName = RandomGenerator.name();
  const adminJoin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword satisfies string as string,
      name: adminName,
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(adminJoin);

  // 3. Authenticate as admin (ensure correct actor)
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IShoppingMallAdmin.ILogin,
  });

  // 4. Admin creates new shipping partner
  const shippingPartner =
    await api.functional.shoppingMall.admin.shippingPartners.create(
      connection,
      {
        body: {
          partner_name: RandomGenerator.name(),
          partner_code: RandomGenerator.alphaNumeric(8),
          status: "active",
          description: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies IShoppingMallShippingPartner.ICreate,
      },
    );
  typia.assert(shippingPartner);

  // 5. Create a shipment referencing shippingPartner and customer (mock order/order_item references)
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  const shipment = await api.functional.shoppingMall.admin.shipments.create(
    connection,
    {
      body: {
        order_id: orderId,
        order_item_id: orderItemId,
        shipping_partner_id: shippingPartner.id,
        status: "in_transit",
        created_by_admin_id: adminJoin.id,
      } satisfies IShoppingMallShipment.ICreate,
    },
  );
  typia.assert(shipment);

  // 6. Create a tracking event (admin)
  const trackingEventCreate = {
    event_time: new Date().toISOString(),
    location: RandomGenerator.paragraph({ sentences: 1 }),
    latitude: null,
    longitude: null,
    event_code: "IN_TRANSIT",
    status: "in_transit",
    tracking_message: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies IShoppingMallShipmentTrackingHistory.ICreate;
  const trackingEvent =
    await api.functional.shoppingMall.admin.shipments.trackingHistories.create(
      connection,
      {
        shipmentId: shipment.id,
        body: trackingEventCreate,
      },
    );
  typia.assert(trackingEvent);

  // 7. Log in as the customer actor
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://shop.example.com/login",
      referrer: "https://shop.example.com/",
      ip: null,
