import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductsCategory";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate that a seller can list category assignments for a product they own.
 *
 * This test follows a minimal business flow:
 *
 * 1. Register a new seller
 * 2. Create a new product under this seller
 * 3. Use the category assignment listing API for this product (results should be
 *    empty initially)
 * 4. Verify response structure, ownership, and that there are no initial
 *    assignments
 */
export async function test_api_seller_product_category_assignment_listing(
  connection: api.IConnection,
) {
  // 1. Register a new seller
  const sellerRequestBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    business_name: RandomGenerator.name(2),
    registration_number: RandomGenerator.alphaNumeric(12),
    business_phone: RandomGenerator.mobile(),
    href: "https://seller-portal.example.com/register",
    referrer: "https://seller-portal.example.com/landing",
    ip: undefined,
  } satisfies IShoppingMallSeller.ICreate;
  const sellerAuth = await api.functional.auth.seller.join(connection, {
    body: sellerRequestBody,
  });
  typia.assert(sellerAuth);

  // 2. Create a new product as this seller (auth context)
  const createProductBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 3, wordMax: 8 }),
    description: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 6,
      sentenceMax: 12,
      wordMin: 3,
      wordMax: 12,
    }),
    default_price: 19999,
    business_status: "draft",
  } satisfies IShoppingMallProduct.ICreate;
  const product = await api.functional.shoppingMall.products.create(
    connection,
    { body: createProductBody },
  );
  typia.assert(product);

  // 3. Query product's category assignments (should be empty)
  const categoriesRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
  } satisfies IShoppingMallProductsCategory.IRequest;
  const result =
    await api.functional.shoppingMall.seller.products.categories.index(
      connection,
      {
        productId: product.id,
        body: categoriesRequest,
      },
    );
  typia.assert(result);

  // 4. Validate response structure and absence of assignments
  TestValidator.equals(
    "initial category assignment list should be empty",
    result.data,
    [],
  );
  TestValidator.equals(
    "pagination current page is 1",
    result.pagination.current,
    1 satisfies number,
  );
  TestValidator.equals(
    "pagination limit matches request",
    result.pagination.limit,
    10 satisfies number,
  );
  TestValidator.equals(
    "total records is 0 on new product",
    result.pagination.records,
    0 satisfies number,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductsCategory";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validates that admins can list all product category assignments.
 *
 * This test verifies that, after a product is created by a seller and assigned
 * a category, an admin can list category mappings for that product via the
 * admin category listing endpoint. Multiple actor authentication is validated
 * (admin/seller), business entity creation flows are covered, and cross-actor
 * catalog visibility is asserted.
 *
 * 1. Register and authenticate a new admin
 * 2. Register and authenticate a new seller
 * 3. Seller creates a product
 * 4. Seller assigns a category to the product
 * 5. Login as admin again (actor switch)
 * 6. Admin lists the product's category assignments
 * 7. Assert listing contains the assigned category
 */
export async function test_api_admin_product_category_assignment_listing(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(10);
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: RandomGenerator.name(1),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. Register and authenticate a new seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(12);
  const href = `https://example.com/${RandomGenerator.alphaNumeric(8)}`;
  const referrer = `https://example.com/${RandomGenerator.alphaNumeric(8)}`;

  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: sellerPassword,
        business_name: RandomGenerator.name(2),
        registration_number: RandomGenerator.alphaNumeric(10),
        business_phone: RandomGenerator.mobile(),
        href,
        referrer,
        ip: null,
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // 3. Seller creates a product
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.products.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        default_price: Math.floor(Math.random() * 50000) + 1000,
        business_status: "published",
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(product);

  // 4. Seller assigns a category to the product
  // Because category IDs are not directly creatable by this test, simulate a random UUID (see business scenario)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const mapping: IShoppingMallProductsCategory =
    await api.functional.shoppingMall.seller.products.categories.create(
      connection,
      {
        productId: product.id,
        body: {
          shopping_mall_category_id: categoryId,
        } satisfies IShoppingMallProductsCategory.ICreate,
      },
    );
  typia.assert(mapping);

  // 5. Login as admin (actor switch)
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IShoppingMallAdmin.ILogin,
  });

  // 6. Admin lists the product's category assignments
  const list: IPageIShoppingMallProductsCategory.ISummary =
    await api.functional.shoppingMall.admin.products.categories.index(
      connection,
      {
        productId: product.id,
        body: {
          page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
          limit: 10 as number &
            tags.Type<"int32"> &
            tags.Minimum<1> &
            tags.Maximum<100>,
        },
      },
    );
  typia.assert(list);

  // 7. Assert listing contains the assigned category mapping
  TestValidator.predicate(
    "admin can see category mapping for seller's product",
    list.data.some((item) => item.id === mapping.id),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate the retrieval of complete product details by productId through
 * public access (no authentication required).
 *
 * This test ensures that the API returns all required fields in the product
 * detail response for a valid product, including title, description, default
 * price, business status, seller summary, category assignments, and audit
 * timestamps, and omits any internal or sensitive data. It also checks the
 * correct error handling (404) for a non-existent productId. Business rules
 * demand public data only, proper category/seller linkage, and presence of
 * audit and soft-delete fields. The test covers both active and soft-deleted
 * product retrieval scenarios (if soft-delete is supported by API for GET).
 *
 * 1. Create a new product (POST /shoppingMall/products).
 * 2. Retrieve product details for this productId with GET
 *    /shoppingMall/products/{productId}.
 * 3. Validate all critical fields – id, title, description, default_price,
 *    business_status, seller, primary_categories, created_at, updated_at,
 *    (deleted_at optional)
 * 4. Attempt GET of a non-existent random productId and verify not found handling
 *    (404 or error).
 */
export async function test_api_shopping_mall_product_detail_public_access(
  connection: api.IConnection,
) {
  // 1. Create a new product to have a known valid productId
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 4, wordMax: 10 }),
    description: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 8,
      sentenceMax: 15,
      wordMin: 5,
      wordMax: 10,
    }),
    default_price: typia.random<number>(),
    business_status: RandomGenerator.pick([
      "draft",
      "published",
      "archived",
      "blocked",
      "pending_approval",
    ] as const),
  } satisfies IShoppingMallProduct.ICreate;
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.products.create(connection, {
      body: createBody,
    });
  typia.assert(product);

  // 2. Retrieve product detail publicly
  const detail: IShoppingMallProduct =
    await api.functional.shoppingMall.products.at(connection, {
      productId: product.id,
    });
  typia.assert(detail);
  TestValidator.equals("detail.id matches created id", detail.id, product.id);
  TestValidator.equals(
    "detail.title matches created",
    detail.title,
    createBody.title,
  );
  TestValidator.equals(
    "detail.description matches created",
    detail.description,
    createBody.description,
  );
  TestValidator.equals(
    "detail.default_price matches created",
    detail.default_price,
    createBody.default_price,
  );
  TestValidator.equals(
    "detail.business_status matches created",
    detail.business_status,
    createBody.business_status,
  );
  TestValidator.predicate(
    "seller summary must have valid id",
    typeof detail.seller.id === "string" && detail.seller.id.length > 0,
  );
  TestValidator.predicate(
    "seller summary must have business_name",
    typeof detail.seller.business_name === "string" &&
      detail.seller.business_name.length > 0,
  );
  TestValidator.predicate(
    "primary_categories must be an array",
    Array.isArray(detail.primary_categories),
  );
  TestValidator.predicate(
    "created_at is ISO 8601",
    typeof detail.created_at === "string" &&
      !isNaN(Date.parse(detail.created_at)),
  );
  TestValidator.predicate(
    "updated_at is ISO 8601",
    typeof detail.updated_at === "string" &&
      !isNaN(Date.parse(detail.updated_at)),
  );
  // deleted_at should be null or typeof string or undefined
  TestValidator.predicate(
    "deleted_at is null/string/undef",
    detail.deleted_at === null ||
      detail.deleted_at === undefined ||
      (typeof detail.deleted_at === "string" &&
        !isNaN(Date.parse(detail.deleted_at))),
  );

  // 3. Try to access a non-existing productId (random UUID)
  const randomId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("404 for non-existent productId", async () => {
    await api.functional.shoppingMall.products.at(connection, {
      productId: randomId,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate that public product creation works for shopping mall catalog via the
 * unauthenticated endpoint.
 *
 * - Creates a product with all required fields using random data
 * - Verifies response matches request for business fields
 * - Asserts system fields (seller, primary_categories, created_at, updated_at)
 *   are set by backend
 * - Repeats with required fields missing, confirming rejection on business logic
 *   error
 */
export async function test_api_shopping_mall_product_creation_public_access(
  connection: api.IConnection,
) {
  // --- 1. Happy path: Successful product creation with valid data ---
  const validBody = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 4, wordMax: 8 }),
    description: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 8,
      sentenceMax: 15,
      wordMin: 4,
      wordMax: 12,
    }),
    default_price: typia.random<
      number & tags.Type<"uint32"> & tags.Minimum<1000> & tags.Maximum<1000000>
    >(),
    business_status: RandomGenerator.pick([
      "draft",
      "published",
      "archived",
      "blocked",
      "pending_approval",
    ] as const),
  } satisfies IShoppingMallProduct.ICreate;

  const created: IShoppingMallProduct =
    await api.functional.shoppingMall.products.create(connection, {
      body: validBody,
    });
  typia.assert(created);
  // Business fields match request
  TestValidator.equals("title matches", created.title, validBody.title);
  TestValidator.equals(
    "description matches",
    created.description,
    validBody.description,
  );
  TestValidator.equals(
    "default_price matches",
    created.default_price,
    validBody.default_price,
  );
  TestValidator.equals(
    "business_status matches",
    created.business_status,
    validBody.business_status,
  );
  // System fields populated
  TestValidator.predicate(
    "id is present",
    typeof created.id === "string" && created.id.length > 0,
  );
  TestValidator.predicate(
    "created_at set",
    typeof created.created_at === "string" && created.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at set",
    typeof created.updated_at === "string" && created.updated_at.length > 0,
  );
  TestValidator.predicate(
    "seller summary present",
    typeof created.seller === "object" &&
      !!created.seller.id &&
      !!created.seller.business_name,
  );
  TestValidator.predicate(
    "primary_categories exists as array",
    Array.isArray(created.primary_categories),
  );

  // --- 2. Error paths: Missing required fields should be rejected (business logic error, never type error) ---
  const requiredFieldKeys = [
    "title",
    "description",
    "default_price",
    "business_status",
  ] as const;
  for (const missingKey of requiredFieldKeys) {
    const incompleteBody = { ...validBody };
    delete (incompleteBody as any)[missingKey];
    // Remove the field to test backend required field business error
    await TestValidator.error(
      `error on missing required field: ${missingKey}`,
      async () => {
        await api.functional.shoppingMall.products.create(connection, {
          body: incompleteBody as any,
        });
      },
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallDisputeMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallDisputeMessage";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validates that a seller can update their own message in an active dispute and
 * business logic around edit permissions and state.
 *
 * Workflow:
 *
 * 1. Register a new seller (and login).
 * 2. Simulate a dispute and an initial message authored by this seller (generate
 *    IDs and use the update endpoint directly, because only dispute and message
 *    IDs are required for update). The test bypasses actual dispute creation as
 *    there is no API for that here.
 * 3. Seller updates the content and role of their own message.
 * 4. Validate that the returned dispute message reflects the update by checking
 *    the content and role.
 * 5. (Negative case): Register a second seller and attempt to update the message -
 *    should fail (forbidden).
 * 6. (Negative case): Simulate deletion of the message by calling update with a
 *    deleted_at timestamp (not possible directly, so we skip this unless API is
 *    available).
 * 7. (Negative case): Simulate dispute closure (state is not present in the DTO,
 *    so skip actual closure test).
 *
 * Key assertions:
 *
 * - Seller can update their own undeleted message.
 * - Other sellers cannot update the message.
 * - Response structure is validated.
 */
export async function test_api_dispute_message_update_by_seller(
  connection: api.IConnection,
) {
  // 1. Register seller (join)
  const sellerInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    business_name: RandomGenerator.name(),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://shop.test.com/join/seller",
    referrer: "https://shop.test.com/register",
    ip: null,
  } satisfies IShoppingMallSeller.ICreate;
  const sellerAuth = await api.functional.auth.seller.join(connection, {
    body: sellerInput,
  });
  typia.assert(sellerAuth);
  TestValidator.equals(
    "seller business name recorded",
    sellerAuth.business_name,
    sellerInput.business_name,
  );

  // 2. Simulate dispute and dispute message (random UUIDs), as there is no dispute/message creation API
  const disputeId = typia.random<string & tags.Format<"uuid">>();
  const messageId = typia.random<string & tags.Format<"uuid">>();

  // 3. Seller updates their own message: change content and role
  const newContent = RandomGenerator.paragraph({ sentences: 3 });
  const newRole = "seller";
  const updatedMsg =
    await api.functional.shoppingMall.seller.disputes.messages.update(
      connection,
      {
        disputeId,
        disputeMessageId: messageId,
        body: {
          content: newContent,
          role: newRole,
        } satisfies IShoppingMallDisputeMessage.IUpdate,
      },
    );
  typia.assert(updatedMsg);
  TestValidator.equals(
    "dispute message content updated",
    updatedMsg.content,
    newContent,
  );
  TestValidator.equals(
    "dispute message role updated",
    updatedMsg.role,
    newRole,
  );
  TestValidator.equals("dispute message id matches", updatedMsg.id, messageId);
  TestValidator.equals(
    "dispute linkage id correct",
    updatedMsg.shopping_mall_dispute_id,
    disputeId,
  );

  // 4. Register a second seller and login as them
  const otherSellerInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    business_name: RandomGenerator.name(),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://shop.test.com/join/seller",
    referrer: "https://shop.test.com/register",
    ip: null,
  } satisfies IShoppingMallSeller.ICreate;
  const otherSellerAuth = await api.functional.auth.seller.join(connection, {
    body: otherSellerInput,
  });
  typia.assert(otherSellerAuth);

  // 5. Other seller attempts to update the message - should fail
  await TestValidator.error(
    "other sellers cannot update the message",
    async () => {
      await api.functional.shoppingMall.seller.disputes.messages.update(
        connection,
        {
          disputeId,
          disputeMessageId: messageId,
          body: {
            content: RandomGenerator.paragraph(),
            role: "seller",
          } satisfies IShoppingMallDisputeMessage.IUpdate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
