import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductAttribute";
import type { IShoppingMallProductAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductAttributeValue";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * End-to-end test for retrieval of a SKU attribute value mapping by a seller
 * after setup of product, attribute, SKU, and value mapping flow.
 *
 * This test covers the following scenario:
 *
 * 1. Seller registers a new account to gain authorization (calling POST
 *    /auth/seller/join).
 * 2. Seller creates a new product (POST /shoppingMall/products).
 * 3. Seller adds a product attribute to the product (POST
 *    /shoppingMall/seller/products/{productId}/attributes).
 * 4. Seller creates a SKU for the product (POST
 *    /shoppingMall/seller/products/{productId}/skus).
 * 5. Seller assigns an attribute value to the SKU (POST
 *    /shoppingMall/seller/skus/{skuId}/attributeValues).
 * 6. Seller retrieves the attribute value mapping (GET
 *    /shoppingMall/skus/{skuId}/attributeValues/{attributeValueId}) and
 *    verifies correct linkage and audit fields.
 *
 * The test verifies:
 *
 * - End-to-end linkage and data integrity of product, attribute, SKU, and value
 *   mapping
 * - Seller authentication and permission flows
 * - Type safety of all DTOs and business logic property compatibility
 * - That fetch returns the same values supplied during creation
 */
export async function test_api_sku_attribute_value_retrieval_by_seller(
  connection: api.IConnection,
) {
  // 1. Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerJoinBody = {
    email: sellerEmail,
    password: RandomGenerator.alphaNumeric(12),
    business_name: RandomGenerator.name(3),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://www.example.com/onboarding",
    referrer: "https://www.example.com/",
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies IShoppingMallSeller.ICreate;
  const sellerAuthorized = await api.functional.auth.seller.join(connection, {
    body: sellerJoinBody,
  });
  typia.assert(sellerAuthorized);

  // 2. Create product
  const prodTitle = RandomGenerator.name(2);
  const prodBody = {
    title: prodTitle,
    description: RandomGenerator.content(),
    default_price: 19900,
    business_status: "draft",
  } satisfies IShoppingMallProduct.ICreate;
  const product = await api.functional.shoppingMall.products.create(
    connection,
    { body: prodBody },
  );
  typia.assert(product);
  TestValidator.equals("product title", product.title, prodBody.title);

  // 3. Add product attribute
  const attrName = RandomGenerator.name(1);
  const attrBody = {
    attribute_name: attrName,
    position: 0,
  } satisfies IShoppingMallProductAttribute.ICreate;
  const attribute =
    await api.functional.shoppingMall.seller.products.attributes.create(
      connection,
      { productId: product.id, body: attrBody },
    );
  typia.assert(attribute);
  TestValidator.equals(
    "attribute product id matches",
    attribute.shopping_mall_product_id,
    product.id,
  );
  TestValidator.equals(
    "attribute name matches",
    attribute.attribute_name,
    attrBody.attribute_name,
  );

  // 4. Register SKU
  const skuBody = {
    sku_code: RandomGenerator.alphaNumeric(6),
    price: 19900,
    stock: 15,
    status: "active",
  } satisfies IShoppingMallProductSku.ICreate;
  const sku = await api.functional.shoppingMall.seller.products.skus.create(
    connection,
    { productId: product.id, body: skuBody },
  );
  typia.assert(sku);
  TestValidator.equals("SKU product id", sku.product.id, product.id);

  // 5. Assign attribute value to SKU
  const valueDisplayName = RandomGenerator.name(1);
  const attrValueBody = {
    shopping_mall_product_attribute_id: attribute.id,
    value_display_name: valueDisplayName,
  } satisfies IShoppingMallProductAttributeValue.ICreate;
  const attrValue =
    await api.functional.shoppingMall.seller.skus.attributeValues.create(
      connection,
      { skuId: sku.id, body: attrValueBody },
    );
  typia.assert(attrValue);
  TestValidator.equals(
    "mapping attribute id",
    attrValue.shopping_mall_product_attribute_id,
    attribute.id,
  );
  TestValidator.equals(
    "mapping value_display_name",
    attrValue.value_display_name,
    valueDisplayName,
  );

  // 6. Retrieve mapping by GET endpoint
  const mapping = await api.functional.shoppingMall.skus.attributeValues.at(
    connection,
    { skuId: sku.id, attributeValueId: attrValue.id },
  );
  typia.assert(mapping);
  TestValidator.equals(
    "fetched attribute mapping id",
    mapping.id,
    attrValue.id,
  );
  TestValidator.equals(
    "fetched SKU id",
    mapping.shopping_mall_product_sku_id,
    sku.id,
  );
  TestValidator.equals(
    "fetched attribute id",
    mapping.shopping_mall_product_attribute_id,
    attribute.id,
  );
  TestValidator.equals(
    "fetched value_display_name",
    mapping.value_display_name,
    valueDisplayName,
  );
  TestValidator.equals(
    "created_at present",
    typeof mapping.created_at,
    "string",
  );
  TestValidator.equals(
    "updated_at present",
    typeof mapping.updated_at,
    "string",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductAttribute";
import type { IShoppingMallProductAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductAttributeValue";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate creation of a product SKU attribute value mapping by an
 * authenticated seller.
 *
 * 1. Register and authenticate a new seller.
 * 2. Create a new product for the seller.
 * 3. Add an attribute to the product (e.g., color).
 * 4. Register a SKU for the product.
 * 5. Create an attribute value mapping linking the created attribute (e.g., color:
 *    Red) to the SKU using the
 *    /shoppingMall/seller/skus/{skuId}/attributeValues endpoint.
 * 6. Test that creating a duplicate mapping for the same (sku, attribute) pair
 *    fails (business rule enforcement).
 * 7. Test mapping a different attribute or SKU is permitted (per business rules).
 * 8. Assert audit fields (created_at, updated_at), linkage, and value display
 *    correctness for attribute value mapping.
 */
export async function test_api_sku_attribute_value_creation_by_seller(
  connection: api.IConnection,
) {
  // 1. Register and authenticate new seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerRegNum = RandomGenerator.alphaNumeric(12);
  const sellerBusinessName = RandomGenerator.name();
  const sellerPhone = RandomGenerator.mobile();
  const href = "https://shoppingmall.example.com/onboard";
  const referrer = "https://shoppingmall.example.com/register";
  const sellerAuth = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: RandomGenerator.alphaNumeric(12),
      business_name: sellerBusinessName,
      registration_number: sellerRegNum,
      business_phone: sellerPhone,
      href,
      referrer,
      ip: undefined,
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(sellerAuth);
  TestValidator.predicate(
    "seller is authenticated",
    typeof sellerAuth.id === "string",
  );

  // 2. Create a product
  const product = await api.functional.shoppingMall.products.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({
          paragraphs: 1,
          sentenceMin: 3,
          sentenceMax: 6,
        }),
        default_price: Math.round(Math.random() * 10000 + 1000),
        business_status: RandomGenerator.pick([
          "draft",
          "published",
          "archived",
          "blocked",
        ] as const),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  TestValidator.equals(
    "product seller",
    product.seller.business_name,
    sellerBusinessName,
  );

  // 3. Add attribute (e.g., color)
  const attributeName = RandomGenerator.pick([
    "Color",
    "Size",
    "Material",
  ] as const);
  const attribute =
    await api.functional.shoppingMall.seller.products.attributes.create(
      connection,
      {
        productId: product.id,
        body: {
          attribute_name: attributeName,
          position: 0,
        } satisfies IShoppingMallProductAttribute.ICreate,
      },
    );
  typia.assert(attribute);
  TestValidator.equals(
    "attribute parent",
    attribute.shopping_mall_product_id,
    product.id,
  );

  // 4. Register SKU
  const skuCode = RandomGenerator.alphaNumeric(8);
  const sku = await api.functional.shoppingMall.seller.products.skus.create(
    connection,
    {
      productId: product.id,
      body: {
        sku_code: skuCode,
        price: product.default_price,
        stock: 50,
        status: RandomGenerator.pick([
          "active",
          "draft",
          "out_of_stock",
        ] as const),
      } satisfies IShoppingMallProductSku.ICreate,
    },
  );
  typia.assert(sku);
  TestValidator.equals("SKU product link", sku.product.id, product.id);

  // 5. Assign attribute value (e.g., 'Red')
  const attrValueLabel = RandomGenerator.pick([
    "Red",
    "Blue",
    "L",
    "XL",
    "Cotton",
  ] as const);
  const attributeValue =
    await api.functional.shoppingMall.seller.skus.attributeValues.create(
      connection,
      {
        skuId: sku.id,
        body: {
          shopping_mall_product_attribute_id: attribute.id,
          value_display_name: attrValueLabel,
        } satisfies IShoppingMallProductAttributeValue.ICreate,
      },
    );
  typia.assert(attributeValue);
  TestValidator.equals(
    "attribute value mapping: SKU id",
    attributeValue.shopping_mall_product_sku_id,
    sku.id,
  );
  TestValidator.equals(
    "attribute value mapping: attribute id",
    attributeValue.shopping_mall_product_attribute_id,
    attribute.id,
  );
  TestValidator.equals(
    "attribute value mapping: value display name",
    attributeValue.value_display_name,
    attrValueLabel,
  );
  TestValidator.predicate(
    "attribute value mapping has created_at",
    typeof attributeValue.created_at === "string",
  );
  TestValidator.predicate(
    "attribute value mapping has updated_at",
    typeof attributeValue.updated_at === "string",
  );

  // 6. Attempt to create duplicate attribute value mapping for same (sku, attribute) pair - expect failure
  await TestValidator.error(
    "duplicate attribute value mapping is rejected",
    async () => {
      await api.functional.shoppingMall.seller.skus.attributeValues.create(
        connection,
        {
          skuId: sku.id,
          body: {
            shopping_mall_product_attribute_id: attribute.id,
            value_display_name: RandomGenerator.pick([
              "Red",
              "Blue",
              "L",
              "XL",
              "Cotton",
            ] as const),
          } satisfies IShoppingMallProductAttributeValue.ICreate,
        },
      );
    },
  );

  // 7. Create and map a different attribute or different SKU (should work)
  // 7a. Create another attribute for the same product
  const anotherAttributeName = attributeName === "Color" ? "Size" : "Color";
  const anotherAttribute =
    await api.functional.shoppingMall.seller.products.attributes.create(
      connection,
      {
        productId: product.id,
        body: {
          attribute_name: anotherAttributeName,
          position: 1,
        } satisfies IShoppingMallProductAttribute.ICreate,
      },
    );
  typia.assert(anotherAttribute);
  TestValidator.notEquals(
    "second attribute different from first",
    anotherAttribute.id,
    attribute.id,
  );

  // 7b. Add mapping to same SKU, different attribute (should succeed)
  const anotherValueLabel = RandomGenerator.pick([
    "Small",
    "Medium",
    "Black",
    "White",
  ] as const);
  const anotherAttributeValue =
    await api.functional.shoppingMall.seller.skus.attributeValues.create(
      connection,
      {
        skuId: sku.id,
        body: {
          shopping_mall_product_attribute_id: anotherAttribute.id,
          value_display_name: anotherValueLabel,
        } satisfies IShoppingMallProductAttributeValue.ICreate,
      },
    );
  typia.assert(anotherAttributeValue);
  TestValidator.equals(
    "second attribute value mapping: SKU id",
    anotherAttributeValue.shopping_mall_product_sku_id,
    sku.id,
  );
  TestValidator.equals(
    "second attribute value mapping: attribute id",
    anotherAttributeValue.shopping_mall_product_attribute_id,
    anotherAttribute.id,
  );
  TestValidator.equals(
    "second attribute value mapping: value display name",
    anotherAttributeValue.value_display_name,
    anotherValueLabel,
  );

  // 7c. Register another SKU, and assign the first attribute to that SKU (should succeed)
  const anotherSkuCode = RandomGenerator.alphaNumeric(8);
  const anotherSku =
    await api.functional.shoppingMall.seller.products.skus.create(connection, {
      productId: product.id,
      body: {
        sku_code: anotherSkuCode,
        price: product.default_price + 500,
        stock: 25,
        status: RandomGenerator.pick([
          "active",
          "draft",
          "out_of_stock",
        ] as const),
      } satisfies IShoppingMallProductSku.ICreate,
    });
  typia.assert(anotherSku);
  TestValidator.notEquals(
    "second SKU different from first",
    anotherSku.id,
    sku.id,
  );

  // Add attribute value mapping (should succeed)
  const anotherSkuValueLabel = RandomGenerator.pick([
    "Red",
    "Blue",
    "L",
    "XL",
    "Cotton",
  ] as const);
  const mappingForAnotherSku =
    await api.functional.shoppingMall.seller.skus.attributeValues.create(
      connection,
      {
        skuId: anotherSku.id,
        body: {
          shopping_mall_product_attribute_id: attribute.id,
          value_display_name: anotherSkuValueLabel,
        } satisfies IShoppingMallProductAttributeValue.ICreate,
      },
    );
  typia.assert(mappingForAnotherSku);
  TestValidator.equals(
    "another SKU mapping: SKU id",
    mappingForAnotherSku.shopping_mall_product_sku_id,
    anotherSku.id,
  );
  TestValidator.equals(
    "another SKU mapping: attribute id",
    mappingForAnotherSku.shopping_mall_product_attribute_id,
    attribute.id,
  );
  TestValidator.equals(
    "another SKU mapping: value display name",
    mappingForAnotherSku.value_display_name,
    anotherSkuValueLabel,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSellerVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSellerVerification";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerVerification";

/**
 * Test the ability of a newly registered admin to search and retrieve paginated
 * seller verification records, using filtering and pagination options.
 *
 * Validates that only admins can access this operation, including permission
 * checks, auditability, and response structure for dashboard integration. If
 * the seller has no verifications, ensures response is empty and paginated
 * properly. Checks status and compliance document filters as well as date
 * ranges and reviewer admin filters.
 */
export async function test_api_admin_verification_search_admin_authenticated(
  connection: api.IConnection,
) {
  // 1. Register new admin user and authenticate
  const adminInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) + "#A1",
    name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.ICreate;
  const adminAuth: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminInput });
  typia.assert(adminAuth);
  TestValidator.predicate(
    "admin token present",
    typeof adminAuth.token.access === "string" &&
      adminAuth.token.access.length > 0,
  );

  // 2. Search for verifications for a random sellerId (should have no records)
  const sellerId = typia.random<string & tags.Format<"uuid">>();

  // No filter, default page/limit
  const emptyPage: IPageIShoppingMallSellerVerification.ISummary =
    await api.functional.shoppingMall.admin.sellers.verifications.index(
      connection,
      {
        sellerId,
        body: {} satisfies IShoppingMallSellerVerification.IRequest,
      },
    );
  typia.assert(emptyPage);
  TestValidator.equals(
    "empty verifications data for new seller",
    emptyPage.data.length,
    0,
  );

  // 3. Try with additional filter combinations
  const filters: IShoppingMallSellerVerification.IRequest[] = [
    { status: "pending", page: 1, limit: 5 },
    {
      status: "approved",
      compliance_document_present: true,
      page: 1,
      limit: 10,
    },
    {
      reviewer_admin_id: adminAuth.id,
      sort_by: "created_at",
      sort_order: "desc",
    },
    {
      date_from: new Date(Date.now() - 1000 * 60 * 60 * 24 * 30).toISOString(),
      date_to: new Date().toISOString(),
    },
  ];
  for (const filter of filters) {
    const page: IPageIShoppingMallSellerVerification.ISummary =
      await api.functional.shoppingMall.admin.sellers.verifications.index(
        connection,
        {
          sellerId,
          body: filter,
        },
      );
    typia.assert(page);
    TestValidator.equals(
      "filtered verifications is empty for new seller",
      page.data.length,
      0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerVerification";

/**
 * Validate that an authenticated seller can retrieve their own business
 * verification record by ID.
 *
 * This test ensures the following business logic and compliance requirements:
 *
 * 1. Seller registration and authentication flow: Register a new seller using
 *    random, unique registration data and perform authorization. This
 *    guarantees proper token issuance and session context.
 * 2. Pre-populate a business verification record for the seller using a random ID
 *    and known link to the seller created above. (Simulation/mock recommended
 *    if direct creation is not permitted, otherwise skip direct DB insertion
 *    but use random ID for boundary test.)
 * 3. Use seller token and credentials to attempt a GET request to
 *    /shoppingMall/seller/sellers/{sellerId}/verifications/{verificationId} for
 *    the created verification record.
 * 4. Validate that the response structure matches IShoppingMallSellerVerification
 *    and passes typia.assert.
 * 5. Check all entity relations are correctly resolved: seller summary must match
 *    created seller, reviewer/admin summary may be null or valid admin
 *    structure, status value is string, timestamps are valid ISO strings.
 * 6. Assert proper access control: Seller can only access their own verification.
 *    Attempt to access a non-associated verificationId or use a random,
 *    non-existent sellerId should result in error.
 * 7. Error scenarios: Validate error via TestValidator.error when providing
 *    mismatched sellerId/verificationId or non-existent IDs.
 */
export async function test_api_seller_verification_detail_seller_authenticated(
  connection: api.IConnection,
) {
  // 1. Register a new seller with random, unique data and authenticate.
  const sellerBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    business_name: RandomGenerator.paragraph({ sentences: 2 }),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://shoppingmall.test/seller-onboard",
    referrer: "https://google.com",
    ip: undefined, // Optional, may be omitted
  } satisfies IShoppingMallSeller.ICreate;
  const sellerAuth = await api.functional.auth.seller.join(connection, {
    body: sellerBody,
  });
  typia.assert(sellerAuth);
  // Seller summary for comparison
  const { id: sellerId } = sellerAuth;
  const sellerSummary = sellerAuth.seller;

  // 2. Pre-simulate a verification record for this seller since no POST create-API exists (simulate with known ID)
  // In real staging, this would require a creation endpoint or DB setup. Simulate a known uuid for verificationId.
  // We'll use the simulation mode to retrieve random data as if we created a record for this seller.
  const verificationId = typia.random<string & tags.Format<"uuid">>();

  // 3. Retrieve the verification record as the authenticated seller.
  const verification =
    await api.functional.shoppingMall.seller.sellers.verifications.at(
      connection,
      {
        sellerId,
        verificationId,
      },
    );
  typia.assert(verification);

  // 4. Validate that the returned seller matches the authenticated seller.
  if (sellerSummary) {
    TestValidator.equals(
      "verification.seller matches original",
      verification.seller,
      sellerSummary,
    );
  } else {
    // fallback: check that verification.seller.id equals sellerId and business_name is the same
    TestValidator.equals(
      "verification.seller.id matches auth",
      verification.seller.id,
      sellerId,
    );
    TestValidator.equals(
      "verification.seller.business_name matches",
      verification.seller.business_name,
      sellerBody.business_name,
    );
  }

  // 5. Validate reviewer_admin is either null/undefined or a valid IShoppingMallAdmin.ISummary
  if (
    verification.reviewer_admin !== null &&
    verification.reviewer_admin !== undefined
  ) {
    typia.assert<IShoppingMallAdmin.ISummary>(verification.reviewer_admin);
  }
  // 6. Validate status is a string, created_at is ISO, etc.
  TestValidator.predicate(
    "status is string",
    typeof verification.status === "string",
  );
  TestValidator.predicate(
    "created_at is ISO string",
    typeof verification.created_at === "string" &&
      !isNaN(Date.parse(verification.created_at)),
  );

  // 7. Error: Try retrieving a verification with random, non-existent sellerId
  const otherSellerId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("error for non-existent sellerId", async () => {
    await api.functional.shoppingMall.seller.sellers.verifications.at(
      connection,
      {
        sellerId: otherSellerId,
        verificationId,
      },
    );
  });

  // 8. Error: Try retrieving a verification with random, non-existent verificationId
  const otherVerificationId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "error for non-existent verificationId",
    async () => {
      await api.functional.shoppingMall.seller.sellers.verifications.at(
        connection,
