/**
 * Validate admin customer list advanced filtered pagination API.
 *
 * 1. Register a new admin (join) with random valid credentials
 * 2. Ensure authentication (token set in connection)
 * 3. Fetch customer list with no filters (should return empty or proper data)
 * 4. (Optional but realistic) Populate system with a few customers for
 *    filter/paging to work, skipped here (mock data assumed)
 * 5. Re-run advanced customer list with:
 *
 *    - Filter by email substring
 *    - Filter by name substring
 *    - Filter by phone substring
 *    - Filter by registration date range
 *    - Filter by email verification status
 *    - Sorting by name/email/phone/created_at/updated_at, asc and desc
 *    - Pagination via page/limit
 * 6. For each non-empty result, validate all customers only contain allowed
 *    summary properties, no sensitive fields.
 * 7. Validate result sets: pagination info matches page/limit; no more than limit
 *    per page; total counts reasonable for filter; empty results for impossible
 *    searches.
 * 8. Overbroad search (e.g., no filters, large limit) returns paginated results,
 *    never all data or password hashes.
 * 9. Error handling for limits > 100 (should truncate or error as per contract).
 *
 * Note: Creating actual customers is omitted here for cross-feature isolation.
 * If customer creation API is present, test should insert data and verify
 * expected results. In current scope, focus on admin join, auth, and customer
 * list API integrity.
 */
export async function test_api_admin_customer_list_advanced_filtered_pagination(
  connection: api.IConnection,
) {
  // 1. Register new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphabets(10) + "A1!";
  const adminName = RandomGenerator.name();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword satisfies string as string,
      name: adminName,
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);
  TestValidator.predicate(
    "admin join returns proper authorized structure",
    typeof admin.id === "string" &&
      admin.email === adminEmail &&
      typeof admin.token.access === "string",
  );

  // 2. connection is now authenticated as admin

  // 3. Fetch customer list: (no filters, expect empty or valid list)
  const resp1 = await api.functional.shoppingMall.admin.customers.index(
    connection,
    { body: {} satisfies IShoppingMallCustomer.IRequest },
  );
  typia.assert(resp1);
  TestValidator.equals(
    "pagination current >= 0",
    resp1.pagination.current >= 0,
    true,
  );
  TestValidator.equals(
    "pagination limit >= 0",
    resp1.pagination.limit >= 0,
    true,
  );
  TestValidator.equals(
    "pagination records >= 0",
    resp1.pagination.records >= 0,
    true,
  );
  TestValidator.equals(
    "pagination pages >= 0",
    resp1.pagination.pages >= 0,
    true,
  );
  for (const cust of resp1.data) {
    typia.assert(cust);
    TestValidator.predicate(
      "no extra property on customer summary IE: id+name only",
      Object.keys(cust).length === 2 &&
        typeof cust.id === "string" &&
        typeof cust.name === "string",
    );
  }

  // 4. Try filtered search with unlikely email
  const resp2 = await api.functional.shoppingMall.admin.customers.index(
    connection,
    {
      body: { email: "impossible_email_value@autobe-test-domain.com" },
    },
  );
  typia.assert(resp2);
  TestValidator.equals(
    "empty data for impossible email query",
    resp2.data.length,
    0,
  );

  // 5. Try paginated + sorted request
  const page = 1 satisfies number as number;
  const limit = 5 satisfies number as number;
  const resp3 = await api.functional.shoppingMall.admin.customers.index(
    connection,
    {
      body: { page, limit, sort_by: "name", sort_order: "asc" },
    },
  );
  typia.assert(resp3);
  TestValidator.equals(
    "limit per page respected",
    resp3.data.length <= limit,
    true,
  );
  TestValidator.equals(
    "pagination meta page matches",
    resp3.pagination.current,
    page,
  );
  TestValidator.equals(
    "pagination meta limit matches",
    resp3.pagination.limit,
    limit,
  );

  // 6. Try registration date filter (future range yields 0 results)
  const registered_start_at = new Date(Date.now() + 10000000).toISOString();
  const registered_end_at = new Date(Date.now() + 20000000).toISOString();
  const resp4 = await api.functional.shoppingMall.admin.customers.index(
    connection,
    {
      body: { registered_start_at, registered_end_at },
    },
  );
  typia.assert(resp4);
  TestValidator.equals(
    "future registration date yields zero results",
    resp4.data.length,
    0,
  );

  // 7. Try email verification filter
  const resp5 = await api.functional.shoppingMall.admin.customers.index(
    connection,
    {
      body: { is_email_verified: true },
    },
  );
  typia.assert(resp5);

  for (const cust of resp5.data) {
    typia.assert(cust);
    TestValidator.predicate(
      "no sensitive field in summary (id+name)",
      Object.keys(cust).length === 2 &&
        typeof cust.id === "string" &&
        typeof cust.name === "string",
    );
  }

  // 8. Try using limit above contract (should not exceed 100)
  const resp6 = await api.functional.shoppingMall.admin.customers.index(
    connection,
    {
      body: { limit: 150 satisfies number as number },
    },
  );
  typia.assert(resp6);
  TestValidator.predicate(
    "limit is clipped to 100 or less",
    resp6.data.length <= 100,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Validates authenticated customer profile access and business field
 * restriction.
 *
 * This test ensures the following user journey and validations:
 *
 * 1. A new customer is registered using randomized, valid credentials (email,
 *    password, name, phone).
 * 2. The customer is authenticated by join, and their UUID and token are received.
 * 3. Using the authenticated session, the customer requests their own full
 *    profile.
 *
 *    - Validate that all expected business-visible fields match registration (id,
 *         email, name, phone, is_email_verified, timestamps).
 *    - Ensure sensitive/authentication fields (e.g., password, password_hash, token)
 *         are not present in the response object.
 *    - Validate data is returned for correct self-access only.
 * 4. Register a second, unrelated customer and authenticate as them.
 * 5. Attempt to access the first customer’s profile via the GET API using the
 *    second customer’s identity. Assert that this is denied (throws error).
 * 6. Never test type validation or missing properties/scenario combinations
 *    forbidden by system—focus is on business logic, authentication, and strict
 *    data visibility.
 */
export async function test_api_customer_profile_detail_access_by_customer(
  connection: api.IConnection,
) {
  // 1. Register Customer #1
  const customer1_input = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  } satisfies IShoppingMallCustomer.ICreate;
  const customer1_auth = await api.functional.auth.customer.join(connection, {
    body: customer1_input,
  });
  typia.assert(customer1_auth);
  const customer1_id = customer1_auth.id;
  const expected_fields = {
    id: customer1_auth.id,
    email: customer1_input.email,
    name: customer1_input.name,
    phone: customer1_input.phone,
    is_email_verified: customer1_auth.is_email_verified,
    created_at: customer1_auth.created_at,
    updated_at: customer1_auth.updated_at,
  };

  // 2. Fetch own profile via GET, validate data
  const customer1_profile =
    await api.functional.shoppingMall.customer.customers.at(connection, {
      customerId: customer1_id,
    });
  typia.assert(customer1_profile);
  // All business fields visible
  TestValidator.equals(
    "customer profile matches own registration (id, email, name, phone, email_verified)",
    {
      id: customer1_profile.id,
      email: customer1_profile.email,
      name: customer1_profile.name,
      phone: customer1_profile.phone,
      is_email_verified: customer1_profile.is_email_verified,
    },
    {
      id: expected_fields.id,
      email: expected_fields.email,
      name: expected_fields.name,
      phone: expected_fields.phone,
      is_email_verified: expected_fields.is_email_verified,
    },
  );
  // Timestamps present
  TestValidator.equals(
    "customer profile has same created_at",
    customer1_profile.created_at,
    expected_fields.created_at,
  );
  TestValidator.equals(
    "customer profile has same updated_at",
    customer1_profile.updated_at,
    expected_fields.updated_at,
  );

  // Password and tokens never present
  TestValidator.predicate(
    "customer profile does not contain password/hash/token fields",
    !Object.prototype.hasOwnProperty.call(customer1_profile, "password") &&
      !Object.prototype.hasOwnProperty.call(
        customer1_profile,
        "password_hash",
      ) &&
      !Object.prototype.hasOwnProperty.call(customer1_profile, "token"),
  );

  // 3. Register Customer #2 and authenticate as them
  const customer2_input = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  } satisfies IShoppingMallCustomer.ICreate;
  const customer2_auth = await api.functional.auth.customer.join(connection, {
    body: customer2_input,
  });
  typia.assert(customer2_auth);
  const customer2_id = customer2_auth.id;

  // 4. Attempt access to Customer #1's profile as Customer #2 (should be denied)
  await TestValidator.error(
    "unauthorized customer cannot access another customer's profile",
    async () => {
      await api.functional.shoppingMall.customer.customers.at(connection, {
        customerId: customer1_id,
      });
    },
  );
}

