import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";
import type { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";

/**
 * E2E test for shipment update by admin actor.
 *
 * This test covers the following workflow and business rules:
 *
 * 1. Registers both a seller and an admin actor (ensuring separate actors for
 *    correct authorization).
 * 2. Admin creates a new shipping partner (needed for shipment creation).
 * 3. Seller creates an initial shipment using a sample order and order item.
 * 4. Switches session to admin for the update operation and verifies the ability
 *    to update shipment details such as status, tracking code, manifest url,
 *    and provider response code.
 * 5. Checks that updated_by_admin_id is respected in the update and correct actor
 *    attribution appears in the result, while seller attribution is
 *    unmodified.
 * 6. Attempts to perform an invalid status transition and expects it to be
 *    rejected by the API (e.g., moving to 'delivered' directly from pending
 *    without the proper prerequisites).
 * 7. Switches session between actors and verifies permission boundaries.
 */
export async function test_api_shipment_update_by_admin(
  connection: api.IConnection,
) {
  // 1. Register admin (for update action)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: RandomGenerator.name(2),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. Register seller (for shipment creation)
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(12);
  const sellerBusinessName = RandomGenerator.name(2);
  const sellerRegistrationNum = RandomGenerator.alphaNumeric(10);
  const sellerPhone = RandomGenerator.mobile();
  const sellerHref = "https://" + RandomGenerator.alphaNumeric(8) + ".test";
  const sellerReferrer = "https://" + RandomGenerator.alphaNumeric(8) + ".ref";
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: sellerPassword,
        business_name: sellerBusinessName,
        registration_number: sellerRegistrationNum,
        business_phone: sellerPhone,
        href: sellerHref,
        referrer: sellerReferrer,
        ip: undefined,
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // 3. Switch to admin for shipping partner creation
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IShoppingMallAdmin.ILogin,
  });
  // Create a shipping partner
  const partner: IShoppingMallShippingPartner =
    await api.functional.shoppingMall.admin.shippingPartners.create(
      connection,
      {
        body: {
          partner_name: RandomGenerator.name(2),
          partner_code: RandomGenerator.alphaNumeric(10),
          status: "active",
          description: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IShoppingMallShippingPartner.ICreate,
      },
    );
  typia.assert(partner);

  // 4. Switch to seller for shipment creation
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: sellerHref,
      referrer: sellerReferrer,
      ip: undefined,
    } satisfies IShoppingMallSeller.ILogin,
  });
  // Create a sample order and order item for the shipment
  // For E2E, fake order and item (minimal required fields for IDs)
  const fakeOrder: IShoppingMallOrder.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    order_number: RandomGenerator.alphaNumeric(12),
    status: "paid",
    total_amount: 47000,
    currency: "KRW",
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    deleted_at: undefined,
  };
  const fakeSku: IShoppingMallProductSku.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(10),
    product_title: RandomGenerator.paragraph({ sentences: 2 }),
    option_summary: RandomGenerator.name(2),
    in_stock: true,
  };
  const fakeOrderItem: IShoppingMallOrderItem.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_order_id: fakeOrder.id,
    sku: fakeSku,
    quantity: 2,
    unit_price: 20000,
    subtotal: 40000,
    currency: "KRW",
    delivered: false,
    refunded: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  // Create the shipment as seller
  const sellerShipment: IShoppingMallShipment =
    await api.functional.shoppingMall.seller.shipments.create(connection, {
      body: {
        order_id: fakeOrder.id,
        order_item_id: fakeOrderItem.id,
        shipping_partner_id: partner.id,
        status: "pending",
        created_by_seller_id: seller.id,
        carrier_tracking_code: null,
        manifest_url: null,
        provider_response_code: null,
      } satisfies IShoppingMallShipment.ICreate,
    });
  typia.assert(sellerShipment);
  TestValidator.equals(
    "shipment created by seller is pending",
    sellerShipment.status,
    "pending",
  );
  TestValidator.equals(
    "shipment seller attribution",
    sellerShipment.createdBySeller?.id,
    seller.id,
  );

  // 5. Switch to admin for update operation
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IShoppingMallAdmin.ILogin,
  });
  // Prepare update request (status to 'in_transit', new carrier code, new manifest URL, new provider code, add updated_by_admin_id)
  const adminUpdateBody = {
    status: "in_transit",
    carrier_tracking_code: RandomGenerator.alphaNumeric(16),
    manifest_url:
      "https://" + RandomGenerator.alphaNumeric(8) + ".cdn/manifest.pdf",
    provider_response_code: RandomGenerator.alphaNumeric(6),
    updated_by_admin_id: admin.id,
  } satisfies IShoppingMallShipment.IUpdate;
  const updated: IShoppingMallShipment =
    await api.functional.shoppingMall.admin.shipments.update(connection, {
      shipmentId: sellerShipment.id,
      body: adminUpdateBody,
    });
  typia.assert(updated);
  TestValidator.equals(
    "shipment status updated by admin",
    updated.status,
    "in_transit",
  );
  TestValidator.equals(
    "carrier tracking code updated",
    updated.carrier_tracking_code,
    adminUpdateBody.carrier_tracking_code,
  );
  TestValidator.equals(
    "manifest url updated",
    updated.manifest_url,
    adminUpdateBody.manifest_url,
  );
  TestValidator.equals(
    "provider response code updated",
    updated.provider_response_code,
    adminUpdateBody.provider_response_code,
  );
  TestValidator.equals(
    "shipment updatedByAdmin attribution",
    updated.createdByAdmin?.id,
    admin.id,
  );
  TestValidator.equals(
    "shipment original seller attribution remains",
    updated.createdBySeller?.id,
    seller.id,
  );

  // 6. Try invalid status transition: e.g. skipping to 'delivered' from pending without proper steps (should error)
  // Create new shipment for this
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: sellerHref,
      referrer: sellerReferrer,
      ip: undefined,
    } satisfies IShoppingMallSeller.ILogin,
  });
  const anotherShipment: IShoppingMallShipment =
    await api.functional.shoppingMall.seller.shipments.create(connection, {
      body: {
        order_id: fakeOrder.id,
        order_item_id: fakeOrderItem.id,
        shipping_partner_id: partner.id,
        status: "pending",
        created_by_seller_id: seller.id,
      } satisfies IShoppingMallShipment.ICreate,
    });
  typia.assert(anotherShipment);
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IShoppingMallAdmin.ILogin,
  });
  await TestValidator.error(
    "admin forbidden to update shipment directly to delivered from pending",
    async () => {
      await api.functional.shoppingMall.admin.shipments.update(connection, {
        shipmentId: anotherShipment.id,
        body: {
          status: "delivered",
          updated_by_admin_id: admin.id,
          delivery_at: new Date().toISOString(),
        } satisfies IShoppingMallShipment.IUpdate,
      });
    },
  );

  // 7. Switch to seller and try admin-only update field (should fail)
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: sellerHref,
      referrer: sellerReferrer,
      ip: undefined,
    } satisfies IShoppingMallSeller.ILogin,
  });
  await TestValidator.error(
    "seller forbidden to update with admin-only field",
    async () => {
      await api.functional.shoppingMall.admin.shipments.update(connection, {
        shipmentId: sellerShipment.id,
        body: {
          updated_by_admin_id: admin.id, // forbidden for seller to specify
        } satisfies IShoppingMallShipment.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";

/**
 * Validate update of shipping partner by admin immediately after creation.
 *
 * 1. Register a new admin.
 * 2. Create new shipping partner with unique name/code/status/description.
 * 3. Update the partner to new name, status, description (all permitted fields).
 * 4. Check response reflects changes and audit fields are correct.
 * 5. Confirm uniqueness and audit rules.
 * 6. Optionally attempt update to conflicting code/name to trigger business error.
 */
export async function test_api_shipping_partner_update_after_creation_by_admin(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: RandomGenerator.alphaNumeric(12),
      name: RandomGenerator.name(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // 2. Create shipping partner
  const partnerName = RandomGenerator.name();
  const partnerCode = RandomGenerator.alphaNumeric(10);
  const shippingPartner =
    await api.functional.shoppingMall.admin.shippingPartners.create(
      connection,
      {
        body: {
          partner_name: partnerName,
          partner_code: partnerCode,
          status: "active",
          description: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IShoppingMallShippingPartner.ICreate,
      },
    );
  typia.assert(shippingPartner);

  // 3. Update the partner (to a new name, new status, new description)
  const updateName = RandomGenerator.name();
  const updateStatus = "inactive";
  const updateDescription = RandomGenerator.paragraph({ sentences: 8 });

  const updatedPartner =
    await api.functional.shoppingMall.admin.shippingPartners.update(
      connection,
      {
        partnerCode: partnerCode,
        body: {
          partner_name: updateName,
          status: updateStatus,
          description: updateDescription,
        } satisfies IShoppingMallShippingPartner.IUpdate,
      },
    );
  typia.assert(updatedPartner);

  // 4. Business assertions: all updated fields are reflected
  TestValidator.equals(
    "updated partner name",
    updatedPartner.partner_name,
    updateName,
  );
  TestValidator.equals("updated status", updatedPartner.status, updateStatus);
  TestValidator.equals(
    "updated description",
    updatedPartner.description,
    updateDescription,
  );
  TestValidator.equals(
    "partner code remains unchanged",
    updatedPartner.partner_code,
    partnerCode,
  );
  TestValidator.notEquals(
    "updated_at is different after update",
    updatedPartner.updated_at,
    shippingPartner.updated_at,
  );
  TestValidator.equals(
    "created_at unchanged after update",
    updatedPartner.created_at,
    shippingPartner.created_at,
  );
  TestValidator.predicate(
    "updated_at >= created_at",
    updatedPartner.updated_at >= updatedPartner.created_at,
  );
  // 5. Negative: try updating partner_name to an existing one (conflict)
  const anotherPartner =
    await api.functional.shoppingMall.admin.shippingPartners.create(
      connection,
      {
        body: {
          partner_name: RandomGenerator.name(),
          partner_code: RandomGenerator.alphaNumeric(10),
          status: "active",
          description: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IShoppingMallShippingPartner.ICreate,
      },
    );
  typia.assert(anotherPartner);

  await TestValidator.error(
    "updating code to an existing partner's code should fail",
    async () => {
      await api.functional.shoppingMall.admin.shippingPartners.update(
        connection,
        {
          partnerCode: partnerCode,
          body: {
            partner_code: anotherPartner.partner_code,
          } satisfies IShoppingMallShippingPartner.IUpdate,
        },
      );
    },
  );
  await TestValidator.error(
    "updating name to an existing partner's name should fail",
    async () => {
      await api.functional.shoppingMall.admin.shippingPartners.update(
        connection,
        {
          partnerCode: partnerCode,
          body: {
            partner_name: anotherPartner.partner_name,
          } satisfies IShoppingMallShippingPartner.IUpdate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";

/**
 * Validate hard deletion of a shipping partner by admin.
 *
 * 1. Register a new admin via /auth/admin/join, obtaining an authenticated admin
 *    session.
 * 2. Register a new shipping partner as admin via
 *    /shoppingMall/admin/shippingPartners.
 * 3. Hard delete the newly created shipping partner via
 *    /shoppingMall/admin/shippingPartners/{partnerCode}.
 * 4. (Optional) Attempt to get or delete the same partner again to verify it's
 *    removed.
 * 5. Attempt to hard delete a partner as an unauthenticated user; expect failure.
 */
export async function test_api_shipping_partner_hard_delete_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin (join)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminName = RandomGenerator.name();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      name: adminName,
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);
  // Now connection is authenticated as this admin.

  // 2. Register a shipping partner as admin
  const partnerCode = RandomGenerator.alphaNumeric(8);
  const partnerName = RandomGenerator.name();
  const shippingPartner =
    await api.functional.shoppingMall.admin.shippingPartners.create(
      connection,
      {
        body: {
          partner_name: partnerName,
          partner_code: partnerCode,
          status: RandomGenerator.pick([
            "active",
            "inactive",
            "deprecated",
          ] as const),
          description: RandomGenerator.paragraph({ sentences: 5 }),
        } satisfies IShoppingMallShippingPartner.ICreate,
      },
    );
  typia.assert(shippingPartner);
  TestValidator.equals(
    "shipping partner code should match",
    shippingPartner.partner_code,
    partnerCode,
  );

  // 3. Hard delete the shipping partner as admin
  await api.functional.shoppingMall.admin.shippingPartners.erase(connection, {
    partnerCode,
  });

  // 4. Attempt to delete again as admin, should error (already removed)
  await TestValidator.error(
    "deleting already deleted partner should fail",
    async () => {
      await api.functional.shoppingMall.admin.shippingPartners.erase(
        connection,
        {
          partnerCode,
        },
      );
    },
  );

  // 5. Register another shipping partner and try to delete as unauthenticated
  const partnerCode2 = RandomGenerator.alphaNumeric(8);
  const partnerName2 = RandomGenerator.name();
  const partner2 =
    await api.functional.shoppingMall.admin.shippingPartners.create(
      connection,
      {
        body: {
          partner_name: partnerName2,
          partner_code: partnerCode2,
          status: "active",
          description: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IShoppingMallShippingPartner.ICreate,
      },
    );
  typia.assert(partner2);
  TestValidator.equals(
    "second shipping partner code should match",
    partner2.partner_code,
    partnerCode2,
  );

  // Make an unauthenticated connection (no headers)
  const unauthConnection: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "deletion without admin authentication should fail",
    async () => {
      await api.functional.shoppingMall.admin.shippingPartners.erase(
        unauthConnection,
        {
          partnerCode: partnerCode2,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAdminSession";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminSession";

/**
 * Validate admin session log search and auditing.
 *
 * This test ensures a platform admin can retrieve their own session log records
 * using filtering and pagination.
 *
 * Step-by-step:
 *
 * 1. Register a new admin using valid random data (email, password, name)
 * 2. Query session logs for that admin (filters: random referrer string, random
 *    page/limit)
 * 3. Verify result is paginated, and each session record contains required keys
 *    (id, ip, href, referrer, created_at, expired_at)
 * 4. Validate field types and data consistency, especially the filter criteria
 *    (referrer-matching sessions only)
 * 5. Verify that the request is authorized – if possible, check unauthenticated
 *    access is disallowed (not implemented due to SDK auto-auth)
 */
export async function test_api_admin_sessions_search_auditing(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<
    string & tags.MinLength<8> & tags.Format<"password">
  >();
  const adminName: string = RandomGenerator.name();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: adminName,
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. Search for sessions (with random filtering/pagination)
  const filterReferrer: string = RandomGenerator.paragraph({ sentences: 2 });
  const filterHref: string = RandomGenerator.paragraph({ sentences: 2 });

  // We expect at least ONE session (this login), but filterReferrer is random (might not exist)
  // So use undefined on first query (fetch all), filter by referrer in second round
  const page: number & tags.Type<"int32"> = 1 satisfies number as number;
  const limit: number & tags.Type<"int32"> = 10 satisfies number as number;
  const baseRequest = {
    page,
    limit,
  } satisfies IShoppingMallAdminSession.IRequest;

  const allSessions: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin.id,
      body: baseRequest,
    });
  typia.assert(allSessions);
  TestValidator.predicate(
    "session results must be array",
    Array.isArray(allSessions.data),
  );
  if (allSessions.data.length > 0) {
    // Check required fields & types
    allSessions.data.forEach((session, idx) => {
      TestValidator.predicate(
        `session[${idx}] must have id`,
        typeof session.id === "string",
      );
      TestValidator.predicate(
        `session[${idx}] must have ip`,
        typeof session.ip === "string",
      );
      TestValidator.predicate(
        `session[${idx}] must have href`,
        typeof session.href === "string",
      );
      TestValidator.predicate(
        `session[${idx}] must have referrer`,
        typeof session.referrer === "string",
      );
      TestValidator.predicate(
        `session[${idx}] must have valid created_at`,
        typeof session.created_at === "string",
      );
      // expired_at can be string or null/undefined
      if (session.expired_at !== null && session.expired_at !== undefined) {
        TestValidator.predicate(
          `session[${idx}] expired_at, if present, must be string`,
          typeof session.expired_at === "string",
        );
      }
    });
  }
  // 3. Now filter with random referrer (expecting likely 0 results, but test filter mechanics)
  const filteredSessions: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin.id,
      body: {
        ...baseRequest,
        referrer: filterReferrer,
      },
    });
  typia.assert(filteredSessions);
  filteredSessions.data.forEach((session, idx) => {
    TestValidator.equals(
      `filteredSessions[${idx}] must have referrer = filterReferrer`,
      session.referrer,
      filterReferrer,
    );
  });

  // 4. Pagination edge case: query a page number beyond available pages
  const outOfRangePage = (allSessions.pagination.pages +
    1) satisfies number as number;
  const emptyPageSessions: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin.id,
      body: {
        ...baseRequest,
        page: outOfRangePage,
      },
    });
  typia.assert(emptyPageSessions);
  TestValidator.equals(
    "empty page must return zero sessions",
    emptyPageSessions.data.length,
    0,
  );
}

