import type { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";

/**
 * Test the error handling when attempting to fetch a non-existent wishlist item
 * by ID.
 *
 * Steps:
 *
 * 1. Register a new seller.
 * 2. Seller logs in.
 * 3. Seller creates a product.
 * 4. Seller creates a SKU for the product.
 * 5. Register a new customer.
 * 6. Customer logs in.
 * 7. Customer creates a wishlist (no items added).
 * 8. Attempt to fetch a wishlist item with a random, valid UUID as the itemId.
 * 9. Expect an error indicating item does not exist or is not accessible.
 */
export async function test_api_wishlist_item_detail_nonexistent(
  connection: api.IConnection,
) {
  // 1. Register a new seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "SellerPW!" + RandomGenerator.alphaNumeric(8);
  const sellerJoin = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      business_name: RandomGenerator.name(2),
      registration_number: RandomGenerator.alphaNumeric(12),
      business_phone: RandomGenerator.mobile(),
      href: "https://example.com/join/seller",
      referrer: "https://example.com/landing",
      ip: "127.0.0.1",
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(sellerJoin);

  // 2. Seller logs in
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: "https://example.com/login/seller",
      referrer: "https://example.com/landing",
      ip: "127.0.0.1",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // 3. Seller creates a product
  const product = await api.functional.shoppingMall.products.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 5,
          wordMax: 10,
        }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        default_price: 4000,
        business_status: "published",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // 4. Seller creates a SKU for that product
  const sku = await api.functional.shoppingMall.seller.products.skus.create(
    connection,
    {
      productId: product.id,
      body: {
        sku_code: RandomGenerator.alphaNumeric(8),
        price: 4000,
        stock: 20,
        status: "active",
      } satisfies IShoppingMallProductSku.ICreate,
    },
  );
  typia.assert(sku);

  // 5. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CustomerPW!" + RandomGenerator.alphaNumeric(8);
  const customerJoin = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(2),
      phone: RandomGenerator.mobile(),
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customerJoin);

  // 6. Customer logs in
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://example.com/login/customer",
      referrer: "https://example.com/landing",
      ip: "127.0.0.1",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // 7. Customer creates a wishlist (starts empty)
  const wishlist = await api.functional.shoppingMall.customer.wishlists.create(
    connection,
    {
      body: {} satisfies IShoppingMallWishlist.ICreate,
    },
  );
  typia.assert(wishlist);

  // 8. Attempt to fetch a wishlist item with a random, validly formatted but non-existent itemId
  const randomItemId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "fetching non-existent wishlist item should fail",
    async () => {
      await api.functional.shoppingMall.customer.wishlists.items.at(
        connection,
        {
          wishlistId: wishlist.id,
          itemId: randomItemId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallWishlist } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlist";
import type { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";

/**
 * Validate enforcement of wishlist item detail access control.
 *
 * Scenario: Verifies that a customer cannot access another customer's wishlist
 * item, enforcing privacy.
 *
 * Steps:
 *
 * 1. Register and authenticate as customer A (legitimate wishlist owner).
 * 2. Register and authenticate as a seller.
 * 3. Seller creates a product.
 * 4. Seller creates a SKU for the product.
 * 5. Switch to customer A and create a wishlist.
 * 6. Add a wishlist item (with the SKU) to customer A's wishlist.
 * 7. Register and authenticate as customer B (snooper/attacker).
 * 8. Customer B attempts to retrieve customer A's wishlist item.
 * 9. Assert that access is denied—i.e., a permission or ownership error is thrown.
 */
export async function test_api_wishlist_item_detail_access_control(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as customer A
  const emailA = typia.random<string & tags.Format<"email">>();
  const passwordA = RandomGenerator.alphaNumeric(12);
  const customerA = await api.functional.auth.customer.join(connection, {
    body: {
      email: emailA,
      password: passwordA as string &
        tags.MinLength<8> &
        tags.Format<"password">,
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customerA);

  // 2. Register & authenticate as seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(12);
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword as string & tags.Format<"password">,
      business_name: RandomGenerator.name(),
      registration_number: RandomGenerator.alphaNumeric(10),
      business_phone: RandomGenerator.mobile(),
      href: "https://example.com/seller/join",
      referrer: "https://example.com/landing",
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // 3. Seller creates a product
  const product = await api.functional.shoppingMall.products.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        default_price: 9999,
        business_status: "published",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // 4. Seller creates a SKU for the product
  const sku = await api.functional.shoppingMall.seller.products.skus.create(
    connection,
    {
      productId: product.id,
      body: {
        sku_code: RandomGenerator.alphaNumeric(8),
        price: 9999,
        stock: 100,
        status: "active",
      } satisfies IShoppingMallProductSku.ICreate,
    },
  );
  typia.assert(sku);

  // 5. Authenticate as customer A again and create wishlist
  await api.functional.auth.customer.login(connection, {
    body: {
      email: emailA,
      password: passwordA,
      href: "https://example.com/customer/re-login",
      referrer: "https://example.com/somepage",
    } satisfies IShoppingMallCustomer.ILogin,
  });
  const wishlist = await api.functional.shoppingMall.customer.wishlists.create(
    connection,
    {
      body: {} satisfies IShoppingMallWishlist.ICreate,
    },
  );
  typia.assert(wishlist);

  // 6. Add an item to customer A's wishlist
  const wishlistItem =
    await api.functional.shoppingMall.customer.wishlists.items.create(
      connection,
      {
        wishlistId: wishlist.id,
        body: {
          shopping_mall_product_sku_id: sku.id,
        } satisfies IShoppingMallWishlistItem.ICreate,
      },
    );
  typia.assert(wishlistItem);

  // 7. Register and authenticate as customer B
  const emailB = typia.random<string & tags.Format<"email">>();
  const passwordB = RandomGenerator.alphaNumeric(12);
  const customerB = await api.functional.auth.customer.join(connection, {
    body: {
      email: emailB,
      password: passwordB as string &
        tags.MinLength<8> &
        tags.Format<"password">,
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customerB);

  // 8. Customer B attempts to retrieve customer A's wishlist item
  await TestValidator.error(
    "customer B cannot access customer A's wishlist item",
    async () => {
      await api.functional.shoppingMall.customer.wishlists.items.at(
        connection,
        {
          wishlistId: wishlist.id,
          itemId: wishlistItem.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallWishlist } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlist";
import type { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";

/**
 * Validate successful workflow for adding a valid SKU to a customer's wishlist.
 *
 * This end-to-end test covers the following steps:
 *
 * 1. Register a new customer (includes authentication on join)
 * 2. Register a new seller and authenticate as seller
 * 3. Seller creates a new product
 * 4. Seller creates a SKU for the product
 * 5. Authenticate as the customer again (to switch actor)
 * 6. Customer creates a wishlist
 * 7. Customer adds the product SKU to the wishlist via POST
 *    /shoppingMall/customer/wishlists/{wishlistId}/items
 * 8. Validate that the wishlist item response references the correct SKU summary
 *    and associations
 * 9. Validate that duplicate inserts throw an error (duplicate constraint
 *    enforcement)
 */
export async function test_api_add_wishlist_item_success(
  connection: api.IConnection,
) {
  // 1. Register customer (auto-authenticates)
  const customer_email = typia.random<string & tags.Format<"email">>();
  const customer_password = RandomGenerator.alphabets(12);
  const customer_join = await api.functional.auth.customer.join(connection, {
    body: {
      email: customer_email,
      password: customer_password,
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer_join);
  const customer_id = customer_join.id;

  // 2. Register seller and login
  const seller_email = typia.random<string & tags.Format<"email">>();
  const seller_password = RandomGenerator.alphabets(14);
  const seller_join = await api.functional.auth.seller.join(connection, {
    body: {
      email: seller_email,
      password: seller_password satisfies string as string, // typia tagging workaround
      business_name: RandomGenerator.name(),
      registration_number: RandomGenerator.alphaNumeric(10),
      business_phone: RandomGenerator.mobile(),
      href: "https://seller-join.example.com",
      referrer: "https://entry.example.com",
      ip: undefined,
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller_join);

  // 3. Seller creates product
  const product = await api.functional.shoppingMall.products.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 3,
          wordMax: 10,
        }),
        description: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 5,
          sentenceMax: 12,
          wordMin: 3,
          wordMax: 8,
        }),
        default_price: Math.floor(Math.random() * 10000) + 500,
        business_status: "published",
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // 4. Seller creates SKU for product
  const sku_code = RandomGenerator.alphaNumeric(10);
  const sku = await api.functional.shoppingMall.seller.products.skus.create(
    connection,
    {
      productId: product.id,
      body: {
        sku_code,
        price: product.default_price + 100,
        stock: 15,
        status: "active",
      } satisfies IShoppingMallProductSku.ICreate,
    },
  );
  typia.assert(sku);

  // 5. Switch back to customer by logging in
  const customer_login = await api.functional.auth.customer.login(connection, {
    body: {
      email: customer_email,
      password: customer_password,
      href: "https://customer-login.example.com",
      referrer: "https://shop.example.com",
      ip: undefined,
    } satisfies IShoppingMallCustomer.ILogin,
  });
  typia.assert(customer_login);

  // 6. Customer creates wishlist
  const wishlist = await api.functional.shoppingMall.customer.wishlists.create(
    connection,
    {
      body: {} satisfies IShoppingMallWishlist.ICreate,
    },
  );
  typia.assert(wishlist);

  // 7. Customer adds product SKU to wishlist
  const wishlist_item =
    await api.functional.shoppingMall.customer.wishlists.items.create(
      connection,
      {
        wishlistId: wishlist.id,
        body: {
          shopping_mall_product_sku_id: sku.id,
        } satisfies IShoppingMallWishlistItem.ICreate,
      },
    );
  typia.assert(wishlist_item);

  // 8. Validate correct SKU association on wishlist item
  TestValidator.equals(
    "wishlist item SKU id matches",
    wishlist_item.productSku.id,
    sku.id,
  );
  TestValidator.equals(
    "wishlist item SKU code matches",
    wishlist_item.productSku.code,
    sku.sku_code,
  );
  TestValidator.equals(
    "wishlist item SKU product title matches",
    wishlist_item.productSku.product_title,
    product.title,
  );

  // 9. Attempt duplicate insert (should be rejected by unique constraint)
  await TestValidator.error(
    "duplicate SKU in wishlist should fail",
    async () => {
      await api.functional.shoppingMall.customer.wishlists.items.create(
        connection,
        {
          wishlistId: wishlist.id,
          body: {
            shopping_mall_product_sku_id: sku.id,
          } satisfies IShoppingMallWishlistItem.ICreate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
