 * Validate update error handling for platform administrator updating seller
 * using PUT /shoppingMall/admin/sellers/{sellerId}.
 *
 * Notes:
 *
 * - As there is no API to create or enumerate seller entities, no positive-path
 *   update with a reachable sellerId can be tested here. For this API surface,
 *   only negative path error scenarios are testable.
 *
 * Steps:
 *
 * 1. Register a new admin account for authentication.
 * 2. Attempt to update a non-existent seller (random UUID) and ensure the system
 *    rejects it.
 * 3. Validate that request with an unauthenticated connection is rejected.
 */
export async function test_api_seller_update_by_admin(
  connection: api.IConnection,
) {
  // 1. Register an admin account
  const adminCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12) + "!1A",
    name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.ICreate;
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminCreate,
    });
  typia.assert(admin);

  // Prepare nonexistent sellerId
  const sellerId: string & tags.Format<"uuid"> =
    "00000000-0000-0000-0000-000000000000";
  // Prepare random update body
  const updateBody = {
    email: typia.random<string & tags.Format<"email">>(),
    business_name: RandomGenerator.paragraph({
      sentences: 1,
      wordMin: 5,
      wordMax: 10,
    }),
    registration_number: RandomGenerator.alphaNumeric(12),
    business_phone: RandomGenerator.mobile(),
    is_email_verified: true,
    status: RandomGenerator.pick([
      "pending",
      "approved",
      "rejected",
      "suspended",
    ] as const),
  } satisfies IShoppingMallSeller.IUpdate;

  // 2. Negative test: updating non-existent sellerId yields error
  await TestValidator.error("invalid sellerId is rejected", async () => {
    await api.functional.shoppingMall.admin.sellers.update(connection, {
      sellerId,
      body: updateBody,
    });
  });

  // 3. Negative test: unauthenticated request is rejected
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated fails update", async () => {
    await api.functional.shoppingMall.admin.sellers.update(unauthConn, {
      sellerId,
      body: updateBody,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallAdminActionLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminActionLog";

/**
 * Verifies that an authenticated admin can fetch detailed admin action log
 * information by log ID (UUID).
 *
 * 1. Register a new platform admin using the join endpoint.
 * 2. Confirm all core fields and tokens of the admin authorization response.
 * 3. Simulate the existence of an admin action log that this admin can query
 *    (randomized log object).
 * 4. Use the admin's authentication (token is auto-set by SDK) to request the log
 *    detail for the given log ID.
 * 5. Confirm all major fields: id (uuid), shopping_mall_admin_id (uuid),
 *    action_type (string), context_info (string|null|undefined), created_at
 *    (date-time string).
 * 6. Business assertions: context_info can be present, null, or undefined—test at
 *    least two of these cases; verify field presence and type.
 * 7. Verify correct authorization: attempting to fetch the admin action log with
 *    an unauthenticated connection fails (authorization required).
 */
export async function test_api_admin_action_log_details_retrieval_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin
  const adminCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password:
      RandomGenerator.alphabets(3) + "1a$" + RandomGenerator.alphabets(5),
    name: RandomGenerator.name(2),
  } satisfies IShoppingMallAdmin.ICreate;
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminCreate });
  typia.assert(admin);

  // 2. Simulate the existence of admin action logs. (In real scenario, this would be created via business operations; here, we use random log for testing.)
  const logWithContext: IShoppingMallAdminActionLog =
    typia.random<IShoppingMallAdminActionLog>();
  const logWithNullContext: IShoppingMallAdminActionLog = {
    ...typia.random<IShoppingMallAdminActionLog>(),
    context_info: null,
  };

  // (We assume these action log entries are valid and exist for this test; in a live system, creation via endpoint would be needed.)

  // 3. Fetch admin action log detail with context_info present
  const fetchedLog1 =
    await api.functional.shoppingMall.admin.adminActionLogs.at(connection, {
      id: logWithContext.id,
    });
  typia.assert(fetchedLog1);
  TestValidator.equals("log id matches", fetchedLog1.id, logWithContext.id);
  TestValidator.equals(
    "shopping_mall_admin_id present",
    typeof fetchedLog1.shopping_mall_admin_id,
    "string",
  );
  TestValidator.equals(
    "action_type present",
    typeof fetchedLog1.action_type,
    "string",
  );
  TestValidator.predicate(
    "created_at is ISO string",
    typeof fetchedLog1.created_at === "string" &&
      !isNaN(Date.parse(fetchedLog1.created_at)),
  );
  if (
    logWithContext.context_info !== undefined &&
    logWithContext.context_info !== null
  ) {
    TestValidator.equals(
      "context_info present and matches",
      fetchedLog1.context_info,
      logWithContext.context_info,
    );
  }

  // 4. Fetch admin action log detail with context_info null
  const fetchedLog2 =
    await api.functional.shoppingMall.admin.adminActionLogs.at(connection, {
      id: logWithNullContext.id,
    });
  typia.assert(fetchedLog2);
  TestValidator.equals(
    "log id matches (null context)",
    fetchedLog2.id,
    logWithNullContext.id,
  );
  TestValidator.equals("context_info is null", fetchedLog2.context_info, null);

  // 5. Negative case: Using an unauthenticated connection should fail to retrieve log details
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated admin cannot access action log",
    async () => {
      await api.functional.shoppingMall.admin.adminActionLogs.at(unauthConn, {
        id: logWithContext.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallEscalationQueue } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallEscalationQueue";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallEscalationQueue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallEscalationQueue";

/**
 * Test searching and filtering of admin escalation queues after creation by an
 * authenticated admin.
 *
 * Steps:
 *
 * 1. Register admin for authentication context.
 * 2. Create a new escalation queue entry as the admin (initiator_actor_admin_id =
 *    admin.id).
 * 3. Run multiple PATCH /shoppingMall/admin/escalationQueues searches:
 *
 *    - By status
 *    - By escalation_type
 *    - By priority
 *    - By assigned_admin_id (should be unassigned after creation)
 *    - By initiator_actor_admin_id
 *    - By pagination (limit=1, page=1)
 * 4. Validate the created escalation appears in filtered results, with correct
 *    summary fields and proper pagination structure.
 * 5. All TestValidator assertions use descriptive titles.
 */
export async function test_api_escalation_queues_search_after_creation_by_admin(
  connection: api.IConnection,
) {
  // 1. Register admin for authentication context
  const adminCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(2),
  } satisfies IShoppingMallAdmin.ICreate;
  const admin = await api.functional.auth.admin.join(connection, {
    body: adminCreate,
  });
  typia.assert(admin);

  // 2. Create a new escalation queue entry as the admin
  const escalationCreate = {
    escalation_type: RandomGenerator.pick([
      "refund_dispute",
      "policy_violation",
      "compliance_check",
      "complaint",
      "delivery_exception",
    ] as const),
    reason_detail: RandomGenerator.paragraph({ sentences: 5 }),
    status: RandomGenerator.pick([
      "open",
      "investigating",
      "resolved",
      "closed",
      "rejected",
      "admin_pending",
      "compliance_review",
    ] as const),
    priority: RandomGenerator.pick([
      "low",
      "normal",
      "high",
      "urgent",
      "critical",
    ] as const),
    initiator_actor_admin_id: admin.id,
  } satisfies IShoppingMallEscalationQueue.ICreate;
  const escalation =
    await api.functional.shoppingMall.admin.escalationQueues.create(
      connection,
      { body: escalationCreate },
    );
  typia.assert(escalation);

  // 3. Test filter by status
  const pageByStatus =
    await api.functional.shoppingMall.admin.escalationQueues.index(connection, {
      body: { status: escalation.status },
    });
  typia.assert(pageByStatus);
  TestValidator.predicate(
    "search by status includes created escalation",
    pageByStatus.data.some((q) => q.id === escalation.id),
  );

  // 4. Test filter by escalation_type
  const pageByType =
    await api.functional.shoppingMall.admin.escalationQueues.index(connection, {
      body: { escalation_type: escalation.escalation_type },
    });
  typia.assert(pageByType);
  TestValidator.predicate(
    "search by escalation_type includes created escalation",
    pageByType.data.some((q) => q.id === escalation.id),
  );

  // 5. Test filter by priority
  const pageByPriority =
    await api.functional.shoppingMall.admin.escalationQueues.index(connection, {
      body: { priority: escalation.priority },
    });
  typia.assert(pageByPriority);
  TestValidator.predicate(
    "search by priority includes created escalation",
    pageByPriority.data.some((q) => q.id === escalation.id),
  );

  // 6. Test filter by initiator_actor_admin_id
  const pageByInitiator =
    await api.functional.shoppingMall.admin.escalationQueues.index(connection, {
      body: { initiator_actor_admin_id: admin.id },
    });
  typia.assert(pageByInitiator);
  TestValidator.predicate(
    "search by initiator_actor_admin_id includes created escalation",
    pageByInitiator.data.some((q) => q.id === escalation.id),
  );

  // 7. Test filter by assigned_admin_id should return empty or not include the created one (since not assigned)
  if (
    escalation.assigned_admin_id !== undefined &&
    escalation.assigned_admin_id !== null
  ) {
    const pageByAssigned =
      await api.functional.shoppingMall.admin.escalationQueues.index(
        connection,
        { body: { assigned_admin_id: escalation.assigned_admin_id } },
      );
    typia.assert(pageByAssigned);
    TestValidator.predicate(
      "search by assigned_admin_id must include the created escalation if assigned",
      pageByAssigned.data.some((q) => q.id === escalation.id),
    );
  }

  // 8. Test pagination - limit=1, page=1
  const pagePaginated =
    await api.functional.shoppingMall.admin.escalationQueues.index(connection, {
      body: {
        limit: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      },
    });
  typia.assert(pagePaginated);
  TestValidator.equals(
    "pagination has limit 1",
    pagePaginated.pagination.limit,
    1,
  );
  TestValidator.predicate(
    "pagination current page is 1",
    pagePaginated.pagination.current === 1,
  );

  // 9. Validate summary fields of the created escalation in the result
  const summaryPages = [
    pageByStatus,
    pageByType,
    pageByPriority,
    pageByInitiator,
    pagePaginated,
  ];
  for (const page of summaryPages) {
    const found = page.data.find((q) => q.id === escalation.id);
    if (found) {
      TestValidator.equals(
        "escalation_type matches",
        found.escalation_type,
        escalation.escalation_type,
      );
      TestValidator.equals("status matches", found.status, escalation.status);
      TestValidator.equals(
        "priority matches",
        found.priority,
        escalation.priority,
      );
      TestValidator.equals(
        "reason_detail matches",
        found.reason_detail,
        escalation.reason_detail,
      );
      TestValidator.equals(
        "created_at matches",
        found.created_at,
        escalation.created_at,
      );
      TestValidator.equals(
        "last_updated_at matches",
        found.last_updated_at,
        escalation.last_updated_at,
      );
    }
  }
}

