import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallReturnRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnRequest";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";

/**
 * Validate successful creation of a customer-initiated return request.
 *
 * 1. Register and authenticate a new customer using the join API.
 * 2. Simulate preexisting order and order item context as prerequisites, since no
 *    creation or searching APIs for orders/items are available within the scope
 *    of this scenario. Randomly generate valid order and order item UUIDs and
 *    structure as required for test input. (Note: In actual full E2E, this
 *    would require actual order placement and delivery steps, but such
 *    workflows are not available within exposed APIs here.)
 * 3. Customer sends a valid POST /shoppingMall/customer/returnRequests request,
 *    including only the required fields: order_id, order_item_id, and a
 *    free-form reason for return. Omit all optional fields (pickup_address,
 *    scheduled_pickup_at, provider_tracking_code, shipping_partner_id) as per
 *    scenario requirement that these can be omitted at creation.
 * 4. Validate that the API returns an IShoppingMallReturnRequest object with
 *    proper linkage to the provided order and order_item references, reason is
 *    correct, and initial status is set (e.g., 'pending' or as defined by
 *    backend). Ensure that only requestedByCustomer is present and correct,
 *    that requestedBySeller and shippingPartner are null/undefined.
 * 5. Confirm that returned DTO includes required timestamps and correct structure,
 *    and that only the customer actor is associated as the requestor at
 *    creation time.
 */
export async function test_api_customer_return_request_creation_success(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new customer
  const customerJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<
      string & tags.MinLength<8> & tags.Format<"password">
    >(),
    name: RandomGenerator.name(),
    phone: RandomGenerator.mobile(),
  } satisfies IShoppingMallCustomer.ICreate;

  const customerAuth = await api.functional.auth.customer.join(connection, {
    body: customerJoinBody,
  });
  typia.assert(customerAuth);

  // Prepare actor reference for post-checks
  const customerSummary: IShoppingMallCustomer.ISummary = {
    id: customerAuth.id,
    name: customerAuth.name,
  };

  // 2. Simulate preexisting order and item - generate valid summary stubs
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const orderNumber = RandomGenerator.alphaNumeric(12);
  const skuId = typia.random<string & tags.Format<"uuid">>();
  const orderItemId = typia.random<string & tags.Format<"uuid">>();

  const skuSummary: IShoppingMallProductSku.ISummary = {
    id: skuId,
    code: RandomGenerator.alphaNumeric(10),
    product_title: RandomGenerator.paragraph({ sentences: 3 }),
    option_summary: RandomGenerator.paragraph({ sentences: 2 }),
    in_stock: true,
  };

  const orderSummary: IShoppingMallOrder.ISummary = {
    id: orderId,
    order_number: orderNumber,
    status: "delivered",
    total_amount: 10000,
    currency: "KRW",
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  const orderItemSummary: IShoppingMallOrderItem.ISummary = {
    id: orderItemId,
    shopping_mall_order_id: orderId,
    sku: skuSummary,
    quantity: 1,
    unit_price: 10000,
    subtotal: 10000,
    currency: "KRW",
    delivered: true,
    refunded: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  // 3. Customer sends return request (required fields only)
  const reason = RandomGenerator.paragraph({ sentences: 4 });
  const createReturnBody = {
    order_id: orderId,
    order_item_id: orderItemId,
    reason: reason,
  } satisfies IShoppingMallReturnRequest.ICreate;

  const returnRequest =
    await api.functional.shoppingMall.customer.returnRequests.create(
      connection,
      {
        body: createReturnBody,
      },
    );
  typia.assert(returnRequest);

  // 4. Validate returned structure and linkage
  TestValidator.equals("order linkage", returnRequest.order.id, orderId);
  TestValidator.equals(
    "order item linkage",
    returnRequest.orderItem.id,
    orderItemId,
  );
  TestValidator.equals("return reason", returnRequest.reason, reason);

  // requestedByCustomer - must be present and match authenticated customer
  TestValidator.predicate(
    "requestedByCustomer present and correct",
    !!returnRequest.requestedByCustomer &&
      returnRequest.requestedByCustomer.id === customerSummary.id &&
      returnRequest.requestedByCustomer.name === customerSummary.name,
  );
  // requestedBySeller - must be null or undefined
  TestValidator.equals(
    "requestedBySeller is null/undefined",
    returnRequest.requestedBySeller,
    null,
  );
  // shippingPartner - must be null/undefined
  TestValidator.equals(
    "shippingPartner is null/undefined",
    returnRequest.shippingPartner,
    null,
  );
  // Any optional address/carrier fields - should be null/undefined
  TestValidator.equals(
    "pickup_address is null/undefined",
    returnRequest.pickup_address,
    null,
  );
  TestValidator.equals(
    "scheduled_pickup_at is null/undefined",
    returnRequest.scheduled_pickup_at,
    null,
  );
  TestValidator.equals(
    "provider_tracking_code is null/undefined",
    returnRequest.provider_tracking_code,
    null,
  );
  TestValidator.equals(
    "shippingPartner is null/undefined",
    returnRequest.shippingPartner,
    null,
  );

  // status - must be present with non-empty string value
  TestValidator.predicate(
    "status is non-empty string",
    typeof returnRequest.status === "string" && returnRequest.status.length > 0,
  );
  // created_at and updated_at must be present
  TestValidator.predicate(
    "created_at is present",
    typeof returnRequest.created_at === "string" &&
      returnRequest.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at is present",
    typeof returnRequest.updated_at === "string" &&
      returnRequest.updated_at.length > 0,
  );

  // Only customer is the actor - requestedBySeller and shippingPartner must not be present
  TestValidator.equals(
    "only the customer actor present at creation",
    returnRequest.requestedBySeller,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallReturnRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnRequest";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";

/**
 * Test that a seller can successfully create a seller-initiated return request
 * via the /shoppingMall/seller/returnRequests endpoint with required fields
 * only.
 *
 * Steps:
 *
 * 1. Register a new seller via api.functional.auth.seller.join.
 * 2. Simulate a scenario with a dummy/linked order and order item (using random
 *    values as there is no creation flow available).
 * 3. Submit a return request as the seller with valid order linkage, reason, and
 *    omitting all optional fields.
 * 4. Confirm the return request is created with a "pending" status and attribution
 *    is set to the seller only.
 * 5. Ensure required fields are present and optional fields are null or omitted.
 */
export async function test_api_seller_return_request_creation_success(
  connection: api.IConnection,
) {
  // 1. Register a new seller
  const sellerCreateBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    business_name: RandomGenerator.name(),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://example.com/onboard",
    referrer: "https://example.com/landing",
    ip: typia.random<string & tags.Format<"ipv4">>(),
  } satisfies IShoppingMallSeller.ICreate;

  const sellerAuth = await api.functional.auth.seller.join(connection, {
    body: sellerCreateBody,
  });
  typia.assert(sellerAuth);
  TestValidator.equals(
    "seller attribution matches summary",
    sellerAuth.seller?.business_name,
    sellerCreateBody.business_name,
  );

  // 2. Create simulated order and order item
  const order: IShoppingMallOrder.ISummary =
    typia.random<IShoppingMallOrder.ISummary>();
  const orderItem: IShoppingMallOrderItem.ISummary = {
    ...typia.random<IShoppingMallOrderItem.ISummary>(),
    shopping_mall_order_id: order.id,
  };

  // 3. Submit the return request as seller
  const body = {
    order_id: order.id,
    order_item_id: orderItem.id,
    reason: RandomGenerator.paragraph({ sentences: 2 }),
    // Omit all optionals for minimal test
  } satisfies IShoppingMallReturnRequest.ICreate;

  const result = await api.functional.shoppingMall.seller.returnRequests.create(
    connection,
    { body },
  );
  typia.assert(result);

  // 4. Validate required workflow and attribution
  TestValidator.equals(
    "return request status is pending",
    result.status,
    "pending",
  );
  TestValidator.equals(
    "associated seller as requestor",
    result.requestedBySeller?.business_name,
    sellerCreateBody.business_name,
  );
  TestValidator.equals(
    "associated customer as requestor is null",
    result.requestedByCustomer,
    null,
  );
  TestValidator.equals("order id matches", result.order.id, order.id);
  TestValidator.equals(
    "order item id matches",
    result.orderItem.id,
    orderItem.id,
  );
  TestValidator.equals("reason matches", result.reason, body.reason);
  // 5. Ensure optionals are unset/null
  TestValidator.equals(
    "pickup_address is null or undefined",
    result.pickup_address ?? null,
    null,
  );
  TestValidator.equals(
    "scheduled_pickup_at is null or undefined",
    result.scheduled_pickup_at ?? null,
    null,
  );
  TestValidator.equals(
    "provider_tracking_code is null or undefined",
    result.provider_tracking_code ?? null,
    null,
  );
  TestValidator.equals(
    "shippingPartner is null or undefined",
    result.shippingPartner ?? null,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallRefundRequest";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

export async function test_api_refund_requests_admin_search_and_filter(
  connection: api.IConnection,
) {
  // 1. Register as an admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPass123$"; // Matches MinLength<8>
  const adminName = RandomGenerator.name();
  const adminJoin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      name: adminName,
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(adminJoin);
  const adminId = adminJoin.id;

  // 2. Register as a customer account
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CustomerPass123$";
  const customerName = RandomGenerator.name();
  const customerPhone = RandomGenerator.mobile();
  const customerJoin = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: customerName,
      phone: customerPhone,
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customerJoin);
  const customerId = customerJoin.id;

  // 3. Customer submits a refund request for a random order/seller context
  // As we have no order API, we mock an order & seller summary here
  // Just generate UUIDs for relation
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const sellerId = typia.random<string & tags.Format<"uuid">>();
  const refundReason = RandomGenerator.paragraph({ sentences: 3 });
  const requestedAmount = Math.floor(10000 + Math.random() * 90000);
  const refundCreate =
    await api.functional.shoppingMall.customer.refundRequests.create(
      connection,
      {
        body: {
          shopping_mall_order_id: orderId,
          reason: refundReason,
          requested_amount: requestedAmount,
          shopping_mall_seller_id: sellerId,
        } satisfies IShoppingMallRefundRequest.ICreate,
      },
    );
  typia.assert(refundCreate);
  const refundId = refundCreate.id;

  // 4. Switch to admin context (login if needed)
  const adminLogin = await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IShoppingMallAdmin.ILogin,
  });
  typia.assert(adminLogin);
  TestValidator.equals(
    "admin login id matches join id",
    adminLogin.id,
    adminId,
  );

  // 5. Perform admin refundRequests search/filter queries
  // a. Status search: pending
  const pageStatus =
    await api.functional.shoppingMall.admin.refundRequests.index(connection, {
      body: {
        status: refundCreate.status,
        limit: 10 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      } satisfies IShoppingMallRefundRequest.IRequest,
    });
  typia.assert(pageStatus);
  TestValidator.predicate(
    "at least one result for status",
    pageStatus.data.length > 0,
  );
  TestValidator.predicate(
    "all with pending status",
    pageStatus.data.every((r) => r.status === refundCreate.status),
  );

  // b. Customer filter
  const pageCustomer =
    await api.functional.shoppingMall.admin.refundRequests.index(connection, {
      body: {
        customer_id: customerId,
        limit: 10 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      } satisfies IShoppingMallRefundRequest.IRequest,
    });
  typia.assert(pageCustomer);
  TestValidator.predicate(
    "at least one result for customer",
    pageCustomer.data.length > 0,
  );
  TestValidator.predicate(
    "all items customer id match",
    pageCustomer.data.every((d) => d.customer.id === customerId),
  );

  // c. Order filter
  const pageOrder =
    await api.functional.shoppingMall.admin.refundRequests.index(connection, {
      body: {
        order_id: orderId,
        limit: 10 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      } satisfies IShoppingMallRefundRequest.IRequest,
    });
  typia.assert(pageOrder);
  TestValidator.predicate(
    "items found for order id",
    pageOrder.data.length > 0,
  );
  TestValidator.predicate(
    "all items order id match",
    pageOrder.data.every((d) => d.order.id === orderId),
  );

  // d. Seller filter
  const pageSeller =
    await api.functional.shoppingMall.admin.refundRequests.index(connection, {
      body: {
        seller_id: sellerId,
        limit: 10 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      } satisfies IShoppingMallRefundRequest.IRequest,
    });
  typia.assert(pageSeller);
  TestValidator.predicate(
    "items found for seller id",
    pageSeller.data.length > 0,
  );
  TestValidator.predicate(
    "all items seller id match",
    pageSeller.data.every((d) => d.seller.id === sellerId),
  );

  // e. Reason keyword search
  const pageReason =
    await api.functional.shoppingMall.admin.refundRequests.index(connection, {
      body: {
        reason: refundReason.split(" ")[0], // Use first word as keyword
        limit: 10 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      } satisfies IShoppingMallRefundRequest.IRequest,
    });
  typia.assert(pageReason);
  TestValidator.predicate(
    "reason keyword present",
    pageReason.data.some(
      (d) => d.reason.indexOf(refundReason.split(" ")[0]) !== -1,
    ),
  );

  // f. Requested amount exact match and range
  const pageAmountExact =
    await api.functional.shoppingMall.admin.refundRequests.index(connection, {
      body: {
        requested_amount_min: requestedAmount,
        requested_amount_max: requestedAmount,
        limit: 10 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      } satisfies IShoppingMallRefundRequest.IRequest,
    });
  typia.assert(pageAmountExact);
  TestValidator.predicate(
    "requested amount exact match",
    pageAmountExact.data.some((d) => d.requested_amount === requestedAmount),
  );
  TestValidator.predicate(
    "all items within requested amount range",
    pageAmountExact.data.every(
      (d) =>
        d.requested_amount >= requestedAmount &&
        d.requested_amount <= requestedAmount,
    ),
  );

  // g. Created/updated at window (test with now)
  const nowIsoString = new Date().toISOString();
  const pageCreated =
    await api.functional.shoppingMall.admin.refundRequests.index(connection, {
      body: {
        created_from: refundCreate.created_at,
        created_to: nowIsoString,
        limit: 10 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      } satisfies IShoppingMallRefundRequest.IRequest,
    });
  typia.assert(pageCreated);
  TestValidator.predicate(
    "created_at within range",
    pageCreated.data.some(
      (d) =>
        d.created_at >= refundCreate.created_at && d.created_at <= nowIsoString,
    ),
  );

  // h. Pagination: limit 1 per page, get first page, and second page
  const page1 = await api.functional.shoppingMall.admin.refundRequests.index(
    connection,
    {
      body: {
        limit: 1 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      } satisfies IShoppingMallRefundRequest.IRequest,
    },
  );
  typia.assert(page1);
  TestValidator.equals("pagination: per page = 1", page1.pagination.limit, 1);
  if (page1.pagination.pages > 1) {
    const page2 = await api.functional.shoppingMall.admin.refundRequests.index(
      connection,
      {
        body: {
          limit: 1 as number & tags.Type<"int32">,
          page: 2 as number & tags.Type<"int32">,
        } satisfies IShoppingMallRefundRequest.IRequest,
      },
    );
    typia.assert(page2);
    TestValidator.equals(
      "pagination: current page = 2",
      page2.pagination.current,
      2,
    );
  }

  // i. Sorting (if supported): try sort_by "created_at" descending
  const pageSort = await api.functional.shoppingMall.admin.refundRequests.index(
    connection,
    {
      body: {
        sort_by: "created_at",
        sort_order: "desc",
        limit: 3 as number & tags.Type<"int32">,
        page: 1 as number & tags.Type<"int32">,
      } satisfies IShoppingMallRefundRequest.IRequest,
    },
  );
  typia.assert(pageSort);
  if (pageSort.data.length > 1) {
    // Check descending order
    for (let i = 1; i < pageSort.data.length; ++i) {
      TestValidator.predicate(
        `created_at order: ${i} vs ${i - 1}`,
        pageSort.data[i - 1].created_at >= pageSort.data[i].created_at,
      );
    }
  }

  // Validate audit fields are present (for at least one item)
  const example = pageStatus.data[0];
  TestValidator.predicate("refund id is uuid", typeof example.id === "string");
  TestValidator.predicate(
    "order summary exists",
    typeof example.order === "object" && example.order !== null,
  );
  TestValidator.predicate(
    "customer summary exists",
    typeof example.customer === "object" && example.customer !== null,
  );
  TestValidator.predicate(
    "seller summary exists",
    typeof example.seller === "object" && example.seller !== null,
  );
  TestValidator.predicate("reason present", typeof example.reason === "string");
  TestValidator.predicate(
    "created_at present",
    typeof example.created_at === "string",
  );
  TestValidator.predicate(
    "updated_at present",
    typeof example.updated_at === "string",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";

/**
 * Test the hard deletion of a specific customer address by an authenticated
 * admin actor.
 *
 * This scenario covers the full workflow, including:
 *
 * 1. Admin registration (join): Authenticates as a new admin using unique
 *    email/password/name.
 * 2. Attempts to hard delete a customer address using random (nonexistent)
 *    customerId and addressId (UUID format).
 * 3. Validates business rule compliance: since the address does not exist,
 *    operation should succeed or result in no-op, but no address should be
 *    recoverable, and no permission errors should occur.
 * 4. Ensures strict compliance with audit trail and that admin permissions are
 *    enforced (only admin can perform the action).
 */
export async function test_api_customer_address_hard_delete_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin registration (join)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminName = RandomGenerator.name();

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: adminName,
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. Hard delete of a customer address using random UUIDs
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const addressId = typia.random<string & tags.Format<"uuid">>();

  // This should succeed (no error), even if the entities do not exist (idempotency of DELETE)
  await api.functional.shoppingMall.admin.customers.addresses.erase(
    connection,
    {
      customerId,
      addressId,
    },
  );

  // Since we have no endpoint to verify existence after delete, this test just ensures no permission errors.
  // If the operation is successful and no error is thrown, it is considered a pass for the hard-deletion business rule.
  TestValidator.predicate(
    "admin is authenticated and delete customer address endpoint succeeded with no error",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSeller";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate admin paginated and filtered search of registered sellers.
 *
 * Demonstrates advanced admin-side seller listing with multi-criteria
 * filtering, partial match, sorting, and strict authentication requirement. The
 * test verifies successful queries, proper filter enforcement, pagination and
 * sorting, and access control.
 *
 * Steps:
 *
 * 1. Register and authenticate as an admin.
 * 2. Create several seller-like entries (stub: for test, assume a seller already
 *    exists or skip creation).
 * 3. Run filtered search queries:
 *
 *    - By exact registration_number, partial business_name, partial email, status,
 *         verification, created_at/updated_at ranges.
 *    - Try filter combinations, sort variations, and pagination.
 *    - Test edge cases (no match/empty result, contradictory filters).
 * 4. Assert returned records match filters and highlight page metadata.
 * 5. Check forbidden access: unauthenticated search should fail.
 */
export async function test_api_seller_admin_paginated_search_with_filters(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminName = RandomGenerator.name();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      name: adminName,
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // 2. Basic search (no filters)
  const result1 = await api.functional.shoppingMall.admin.sellers.index(
    connection,
    {
      body: {} satisfies IShoppingMallSeller.IRequest,
    },
  );
  typia.assert(result1);
  TestValidator.predicate(
    "pagination data present for basic search",
    result1.pagination !== undefined && Array.isArray(result1.data),
  );

  // 3. Search with random advanced filters
  const filterBusinessName = RandomGenerator.paragraph({ sentences: 2 });
  const filterRegistrationNumber = RandomGenerator.alphaNumeric(10);
  const filterStatus = RandomGenerator.pick([
    "pending",
    "approved",
    "rejected",
    "suspended",
  ] as const);
  const filterEmail = typia.random<string & tags.Format<"email">>();
  const filterVerified = RandomGenerator.pick([true, false] as const);
  const filterCreatedFrom = new Date(Date.now() - 86400000 * 14).toISOString(); // 14 days ago
  const filterCreatedTo = new Date().toISOString();
  const filterUpdatedFrom = new Date(Date.now() - 86400000 * 7).toISOString(); // 7 days ago
  const filterUpdatedTo = new Date().toISOString();

  const complexResult = await api.functional.shoppingMall.admin.sellers.index(
    connection,
    {
      body: {
        business_name: filterBusinessName,
        registration_number: filterRegistrationNumber,
        email: filterEmail,
        status: filterStatus,
        is_email_verified: filterVerified,
        created_from: filterCreatedFrom,
        created_to: filterCreatedTo,
        updated_from: filterUpdatedFrom,
        updated_to: filterUpdatedTo,
        sort_by: RandomGenerator.pick([
          "business_name",
          "email",
          "status",
          "created_at",
          "updated_at",
        ] as const),
        sort_direction: RandomGenerator.pick(["asc", "desc"] as const),
        page: 1, // Test first page
        page_size: 10,
      } satisfies IShoppingMallSeller.IRequest,
    },
  );
  typia.assert(complexResult);
  TestValidator.predicate(
    "pagination with filters returns valid structure",
    complexResult.pagination !== undefined && Array.isArray(complexResult.data),
  );

  // 4. Test edge: page with no data
  const emptyResult = await api.functional.shoppingMall.admin.sellers.index(
    connection,
    {
      body: {
        business_name: "THIS_NAME_DOES_NOT_EXIST_PROBABLY",
        page: 1,
        page_size: 5,
      } satisfies IShoppingMallSeller.IRequest,
    },
  );
  typia.assert(emptyResult);
  TestValidator.equals(
    "no results for non-matching business_name",
    emptyResult.data.length,
    0,
  );

  // 5. Pagination check: ask for a deep page (likely empty)
  const deepPageResult = await api.functional.shoppingMall.admin.sellers.index(
    connection,
    {
      body: {
        page: 1000,
        page_size: 10,
      } satisfies IShoppingMallSeller.IRequest,
    },
  );
  typia.assert(deepPageResult);
  TestValidator.predicate(
    "deep page should be empty or partially filled",
    Array.isArray(deepPageResult.data) &&
      (deepPageResult.data.length === 0 || deepPageResult.data.length <= 10),
  );

  // 6. Sorting: test sorting by created_at desc
  const sortedResult = await api.functional.shoppingMall.admin.sellers.index(
    connection,
    {
      body: {
        sort_by: "created_at",
        sort_direction: "desc",
        page: 1,
        page_size: 5,
      } satisfies IShoppingMallSeller.IRequest,
    },
  );
  typia.assert(sortedResult);
  TestValidator.predicate(
    "sorted data present and valid",
    Array.isArray(sortedResult.data) && sortedResult.data.length <= 5,
  );

  // 7. Access control: must fail for unauthenticated/invalid actors
  const connNoAuth: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "search as unauthenticated actor should fail",
    async () => {
      await api.functional.shoppingMall.admin.sellers.index(connNoAuth, {
        body: {} satisfies IShoppingMallSeller.IRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallDisputeHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallDisputeHistory";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallDispute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallDispute";
import type { IShoppingMallDisputeHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallDisputeHistory";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate that an admin user can retrieve the full audit trail of status
 * changes and actions for a given dispute.
 *
 * 1. Onboard a new admin by registering with a unique email, password, and name.
 * 2. Register a second admin to test actor-based filtering and access controls.
 * 3. As admin, create a customer and seller (using minimal necessary mock data for
 *    required IDs).
 * 4. Create a new dispute record with the admin's info, linking the created
 *    customer and seller.
 * 5. Retrieve the dispute's history as the admin, using paging and various
 *    filters.
 * 6. Assert that the response is a valid page, all audit trail entities are
 *    included, each has its snapshot, actor, timestamp, and note.
 * 7. Optionally, verify the effects of access restrictions by attempting with
 *    another admin account, and test pagination and filtering parameters for
 *    actor/status.
 */
export async function test_api_dispute_history_list_retrieval_by_admin(
  connection: api.IConnection,
) {
  // 1. Onboard a new admin
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<
    string & tags.MinLength<8> & tags.Format<"password">
  >();
  const adminName: string = RandomGenerator.name();

  const adminAuth: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: adminName,
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(adminAuth);

  // 2. Register a second admin (for filtering test)
  const otherAdminEmail: string = typia.random<string & tags.Format<"email">>();
  const otherAdminPassword: string = typia.random<
    string & tags.MinLength<8> & tags.Format<"password">
  >();
  const otherAdminName: string = RandomGenerator.name();

  const otherAdminAuth: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: otherAdminEmail,
        password: otherAdminPassword,
        name: otherAdminName,
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(otherAdminAuth);

  // 3. Setup required actors: customer and seller (minimal mock summary objects)
  const customer: IShoppingMallCustomer.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.name(2),
  };
  const seller: IShoppingMallSeller.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    business_name: RandomGenerator.name(2),
  };
  // These would come from API normally, but we mock as only IDs are required for creating a dispute.

  // 4. Create a new dispute using admin account
  const disputeCreateBody = {
    shopping_mall_customer_id: customer.id,
    shopping_mall_seller_id: seller.id,
    status: "open",
    subject: RandomGenerator.paragraph({ sentences: 2 }),
    root_cause: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies IShoppingMallDispute.ICreate;

  const dispute: IShoppingMallDispute =
    await api.functional.shoppingMall.admin.disputes.create(connection, {
      body: disputeCreateBody,
    });
  typia.assert(dispute);

  // 5. Retrieve the dispute's audit trail (history) as admin
  const pageNum = 1 satisfies number;
  const pageLimit = 10 satisfies number;
  const pageRequest = {
    page: pageNum,
    limit: pageLimit,
  } satisfies IShoppingMallDisputeHistory.IRequest;

  const historyPage: IPageIShoppingMallDisputeHistory =
    await api.functional.shoppingMall.admin.disputes.histories.index(
      connection,
      {
        disputeId: dispute.id,
        body: pageRequest,
      },
    );
  typia.assert(historyPage);
  TestValidator.equals(
    "history page belongs to correct dispute",
    historyPage.data.every((h) => h.shopping_mall_dispute_id === dispute.id),
    true,
  );
  TestValidator.equals(
    "page limit respected",
    historyPage.pagination.limit,
    pageLimit,
  );
  TestValidator.predicate(
    "each record has valid status",
    historyPage.data.every((h) => !!h.status && typeof h.status === "string"),
  );
  TestValidator.predicate(
    "all have creation timestamp",
    historyPage.data.every(
      (h) => typeof h.created_at === "string" && h.created_at.length > 0,
    ),
  );

  // 6. Test status-based filtering
  if (historyPage.data.length > 0) {
    const firstStatus = historyPage.data[0].status;
    const statusFilterRequest = {
      page: 1,
      limit: 5,
      status: firstStatus,
    } satisfies IShoppingMallDisputeHistory.IRequest;
    const statusFiltered: IPageIShoppingMallDisputeHistory =
      await api.functional.shoppingMall.admin.disputes.histories.index(
        connection,
        {
          disputeId: dispute.id,
          body: statusFilterRequest,
        },
      );
    typia.assert(statusFiltered);
    TestValidator.equals(
      "all histories are filtered by status",
      statusFiltered.data.every((h) => h.status === firstStatus),
      true,
    );
  }

  // 7. Test actor_admin_id-based filtering (should return records created by admin)
  if (adminAuth.id) {
    const actorFilterRequest = {
      page: 1,
      limit: 5,
      actor_admin_id: adminAuth.id,
    } satisfies IShoppingMallDisputeHistory.IRequest;
    const adminFiltered: IPageIShoppingMallDisputeHistory =
      await api.functional.shoppingMall.admin.disputes.histories.index(
        connection,
        {
          disputeId: dispute.id,
          body: actorFilterRequest,
        },
      );
    typia.assert(adminFiltered);
    TestValidator.equals(
      "all histories filtered by actor_admin_id",
      adminFiltered.data.every(
        (h) =>
          h.shopping_mall_actor_admin_id === adminAuth.id ||
          h.shopping_mall_actor_admin_id === null ||
          h.shopping_mall_actor_admin_id === undefined,
      ),
      true,
    );
  }

  // 8. Test pagination (should fetch subsequent pages with correct limit)
  if (historyPage.pagination.pages > 1) {
    const nextPageRequest = {
      page: 2,
      limit: pageLimit,
    } satisfies IShoppingMallDisputeHistory.IRequest;
    const nextPage: IPageIShoppingMallDisputeHistory =
      await api.functional.shoppingMall.admin.disputes.histories.index(
        connection,
        {
          disputeId: dispute.id,
          body: nextPageRequest,
        },
      );
    typia.assert(nextPage);
    TestValidator.equals(
      "history second page number",
      nextPage.pagination.current,
      2,
    );
    TestValidator.equals(
      "history second page limit",
      nextPage.pagination.limit,
      pageLimit,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
