import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductRating } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductRating";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test retrieval of a specific product rating by its unique identifier.
 *
 * 1. Register a new customer (join), authenticating as that customer.
 * 2. Create a new product rating as the authenticated customer. (Since the
 *    referenced product/order/skus must exist to create a rating, use
 *    typia.random to produce valid/consistent dummy values for those reference
 *    fields.)
 * 3. Retrieve the created product rating using its ID with the public endpoint (no
 *    authentication required on this endpoint).
 * 4. Assert that the retrieved rating matches the details of the rating created in
 *    step 2.
 * 5. (If deletion flow supported) Simulate rating deletion and confirm retrieval
 *    is not possible. (Skipped unless endpoint for deletion is present.)
 */
export async function test_api_product_rating_retrieve_by_id(
  connection: api.IConnection,
) {
  // 1. Register a customer
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<
        string & tags.MinLength<8> & tags.Format<"password">
      >(),
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // 2. Create a product rating as this customer
  // (References are randomized but required structure is satisfied)
  const ratingInput = {
    shopping_mall_product_sku_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_order_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_order_item_id: typia.random<string & tags.Format<"uuid">>(),
    value: RandomGenerator.pick([1, 2, 3, 4, 5]) satisfies number as number,
  } satisfies IShoppingMallProductRating.ICreate;
  const createdRating =
    await api.functional.shoppingMall.customer.productRatings.create(
      connection,
      {
        body: ratingInput,
      },
    );
  typia.assert(createdRating);

  // 3. Retrieve the product rating by its ID
  const retrievedRating = await api.functional.shoppingMall.productRatings.at(
    connection,
    {
      productRatingId: createdRating.id,
    },
  );
  typia.assert(retrievedRating);

  // 4. Assertions: the retrieved rating should equal the created rating
  TestValidator.equals(
    "retrieved rating should match created rating (by id)",
    retrievedRating.id,
    createdRating.id,
  );
  TestValidator.equals(
    "retrieved rating must have the same value property",
    retrievedRating.value,
    createdRating.value,
  );
  TestValidator.equals(
    "retrieved rating must not be soft-deleted",
    retrievedRating.deleted_at,
    null,
  );

  // Cross-check major reference properties for presence and matching types
  typia.assert<IShoppingMallProductRating>(retrievedRating);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallPaymentAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallPaymentAuditLog";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import type { IShoppingMallPaymentAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentAuditLog";
import type { IShoppingMallPaymentRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentRefund";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test that an admin can search and filter payment audit logs.
 *
 * This test covers correct registration (join) of an admin, checks
 * authentication token storage, then issues a search request for payment audit
 * logs using various filter combinations. It verifies page format, type and
 * presence of returned audit log data, correct filtering by action_types and
 * actor (admin ID), temporal filter with start and end window, expected
 * pagination, correct sorting, and that actor admin fields are fulfilled in
 * returned logs. Since payment creation is not possible here, a random UUID is
 * used for paymentId and at least structural validation and correct filter
 * passage is asserted. Error-handling, empty results, and edge cases are not
 * tested here.
 */
export async function test_api_payment_auditlog_search_admin_auth(
  connection: api.IConnection,
) {
  // 1. Register an admin to obtain authentication
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<
        string & tags.MinLength<8> & tags.Format<"password">
      >(),
      name: RandomGenerator.name(2),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // 2. Prepare filter/search request for payment audit logs
  const paymentId = typia.random<string & tags.Format<"uuid">>();
  const actionType = RandomGenerator.pick([
    "payment_created",
    "payment_updated",
    "refund_requested",
    "provider_callback",
    "admin_override",
    "escalation",
  ] as const);
  const now = new Date();
  const dateWindowStart = new Date(
    now.getTime() - 1000 * 60 * 60 * 24 * 30,
  ).toISOString(); // 30 days ago
  const dateWindowEnd = now.toISOString();

  const filterBody = {
    action_types: [actionType],
    actor_admin_id: admin.id,
    // other actor filters omitted (null/undefined) for targeting admin actor
    start_date: dateWindowStart,
    end_date: dateWindowEnd,
    page: 1 satisfies number &
      tags.Type<"int32"> &
      tags.Default<1> &
      tags.Minimum<1>,
    limit: 10 satisfies number &
      tags.Type<"int32"> &
      tags.Default<25> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    sort_by: "created_at",
    sort_direction: "desc",
  } satisfies IShoppingMallPaymentAuditLog.IRequest;

  // 3. List/search payment audit log entries for the given payment
  const pageResult =
    await api.functional.shoppingMall.admin.payments.auditLogs.index(
      connection,
      {
        paymentId,
        body: filterBody,
      },
    );
  typia.assert(pageResult);

  // 4. Validate result structure and key filtering (if any data is present)
  TestValidator.equals(
    "audit log page shape",
    Object.keys(pageResult).sort(),
    ["pagination", "data"].sort(),
  );
  TestValidator.predicate(
    "pagination structure present",
    typeof pageResult.pagination.current === "number" &&
      typeof pageResult.pagination.limit === "number",
  );
  TestValidator.predicate("data is array", Array.isArray(pageResult.data));

  // 5. If logs exist, validate filters applied (if not, pass shape checks)
  if (pageResult.data.length > 0) {
    // All entries must have at least one of the filtered action types and actor_admin_id
    for (const log of pageResult.data) {
      TestValidator.equals("action_type filtered", log.action_type, actionType);
      TestValidator.equals("admin.id filtered", log.admin?.id, admin.id);
      TestValidator.predicate(
        "date in range",
        (!filterBody.start_date || log.created_at >= filterBody.start_date) &&
          (!filterBody.end_date || log.created_at <= filterBody.end_date),
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallOrderAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrderAuditLog";
import type { IShoppingMallAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAddress";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderAuditLog";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validates that administrator users can search and retrieve paginated order
 * audit logs, while enforcing access controls as per business rules.
 *
 * Steps:
 *
 * 1. Register and log in as both customer and admin accounts, capturing tokens.
 * 2. As customer, create a valid order (which should generate at least one audit
 *    log event).
 * 3. Switch to admin account.
 * 4. As admin, call the order audit log search endpoint for the created
 *    order_number, providing pagination and sort options.
 * 5. Assert the audit log response is not empty, contains expected event fields,
 *    and pagination works.
 * 6. Switch to customer authentication and verify audit log endpoint access is
 *    denied for customer users.
 * 7. Attempt unauthenticated access and assert audit log endpoint access is denied
 *    as well.
 */
export async function test_api_order_audit_log_retrieval_by_admin(
  connection: api.IConnection,
) {
  // 1. Register and log in a random customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = RandomGenerator.alphaNumeric(12);
  const customerName = RandomGenerator.name();
  const customerPhone = RandomGenerator.mobile();
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword as string &
        tags.MinLength<8> &
        tags.Format<"password">,
      name: customerName,
      phone: customerPhone,
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // 2. Register and log in a random admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminName = RandomGenerator.name();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword as string &
        tags.MinLength<8> &
        tags.Format<"password">,
      name: adminName,
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // 3. (Re)authenticate as customer if necessary (in practice token is set above)
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://customer-client-testing/", // using plausible values
      referrer: "https://testing-referrer/",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // Create a dummy address and seller summary for order creation (using randomized UUIDs/fields)
  const dummyAddress: IShoppingMallAddress.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    full_name: customerName,
    street: RandomGenerator.paragraph({
      sentences: 1,
      wordMin: 10,
      wordMax: 24,
    }),
    city: RandomGenerator.name(1),
    province: RandomGenerator.name(1),
    postal_code: RandomGenerator.alphaNumeric(7),
    country: "South Korea",
    phone: customerPhone,
    is_default: true,
  };
  const dummySeller: IShoppingMallSeller.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    business_name: RandomGenerator.paragraph({
      sentences: 2,
      wordMin: 4,
      wordMax: 14,
    }),
  };
  // 4. Create a customer-side order
  const orderNumber = `ORD${typia.random<number & tags.Type<"uint32"> & tags.Minimum<10000000> & tags.Maximum<99999999>>()}`;
  const orderStatus = "pending";
  const orderTotal = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1000> & tags.Maximum<9999999>
  >() satisfies number as number;

  const order = await api.functional.shoppingMall.customer.orders.create(
    connection,
    {
      body: {
        order_number: orderNumber,
        shopping_mall_customer_id: customer.id,
        shopping_mall_address_id: dummyAddress.id,
        shopping_mall_seller_id: dummySeller.id,
        status: orderStatus,
        total_amount: orderTotal,
        currency: "KRW",
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  TestValidator.equals(
    "created order_number matches",
    order.order_number,
    orderNumber,
  );

  // 5. Switch session to admin
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IShoppingMallAdmin.ILogin,
  });

  // 6. As admin, request order audit log (test pagination/query options)
  const auditRequest = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
    sort_by: "created_at",
    order_by: "desc",
    action_type: undefined,
    from_created_at: undefined,
    to_created_at: undefined,
    actor_admin_id: undefined,
    actor_seller_id: undefined,
    actor_customer_id: undefined,
  } satisfies IShoppingMallOrderAuditLog.IRequest;
  const auditResult =
    await api.functional.shoppingMall.admin.orders.auditLogs.index(connection, {
      orderNumber: orderNumber,
      body: auditRequest,
    });
  typia.assert(auditResult);

  // 7. Assert result is paginated, has >= 1 log, basic field checks
  TestValidator.predicate(
    "audit log result has at least one event",
    auditResult.data.length >= 1,
  );
  TestValidator.equals(
    "pagination current page is 1",
    auditResult.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit is 10",
    auditResult.pagination.limit,
    10,
  );

  for (const log of auditResult.data) {
    typia.assert(log);
    TestValidator.equals(
      "order_number in audit log matches",
      log.order.order_number,
      orderNumber,
    );
    TestValidator.predicate(
      "action_type is non-empty",
      typeof log.action_type === "string" && log.action_type.length > 0,
    );
    TestValidator.predicate(
      "created_at is non-empty",
      typeof log.created_at === "string" && log.created_at.length > 0,
    );
    // Only one of actor_admin/actor_seller/actor_customer is non-null/undefined
    TestValidator.predicate(
      "at least one actor is present",
      Boolean(log.actor_admin) ||
        Boolean(log.actor_seller) ||
        Boolean(log.actor_customer),
    );
    // All present actors have expected fields
    if (log.actor_admin) {
      typia.assert(log.actor_admin);
      TestValidator.predicate(
        "actor_admin name non-empty",
        typeof log.actor_admin.name === "string" &&
          log.actor_admin.name.length > 0,
      );
      TestValidator.predicate(
        "actor_admin email format valid",
        log.actor_admin.email.includes("@"),
      );
    }
    if (log.actor_seller) {
      typia.assert(log.actor_seller);
      TestValidator.predicate(
        "actor_seller business_name non-empty",
        typeof log.actor_seller.business_name === "string" &&
          log.actor_seller.business_name.length > 0,
      );
    }
    if (log.actor_customer) {
      typia.assert(log.actor_customer);
      TestValidator.predicate(
        "actor_customer name non-empty",
        typeof log.actor_customer.name === "string" &&
          log.actor_customer.name.length > 0,
      );
    }
  }

  // 8. Switch session back to customer
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://customer-client-testing/",
      referrer: "https://testing-referrer/",
    } satisfies IShoppingMallCustomer.ILogin,
  });
  // As customer, attempt to access admin audit log endpoint
  await TestValidator.error(
    "customer users cannot access admin audit logs",
    async () => {
      await api.functional.shoppingMall.admin.orders.auditLogs.index(
        connection,
        {
          orderNumber: orderNumber,
          body: auditRequest,
        },
      );
    },
  );

  // 9. As unauthenticated, create a new session
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated access to admin audit logs is forbidden",
    async () => {
      await api.functional.shoppingMall.admin.orders.auditLogs.index(
        unauthConn,
        {
          orderNumber: orderNumber,
          body: auditRequest,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallExternalPaymentProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallExternalPaymentProvider";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallExternalPaymentProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallExternalPaymentProvider";

/**
 * Validates paginated and filtered listing of external payment providers by an
 * authenticated admin.
 *
 * - Registers a new admin account to guarantee authenticated, authorized context.
 * - Registers several payment providers with varying names and statuses (active,
 *   inactive, deprecated) to set up filtering test data.
 * - Verifies that filtering by provider_name, provider_code, status, and q
 *   (search) only returns matching records and that pagination metadata matches
 *   expectations for various page sizes/limits.
 * - Checks that only authenticated admin can access this listing.
 * - Validates that filtering out by non-matching queries or by explicit status
 *   results in zero-length or fully-matching results.
 * - Ensures that no extra or omitted results are present beyond filter criteria.
 * - Pagination checks verify total, pages, current page, and limit fields.
 */
export async function test_api_external_payment_providers_admin_index_filter_pagination(
  connection: api.IConnection,
) {
  // Create a new admin for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(10) + "A!";
  const adminName = RandomGenerator.name();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword satisfies string,
      name: adminName,
    },
  });
  typia.assert(admin);

  // Prepare providers with diverse data
  const statuses = ["active", "inactive", "deprecated"] as const;
  const providers: IShoppingMallExternalPaymentProvider[] =
    await ArrayUtil.asyncMap(
      [
        {
          provider_name: "StripeX0",
          provider_code: "stripex",
          status: "active",
        },
        {
          provider_name: "PayPalY1",
          provider_code: "paypaly",
          status: "inactive",
        },
        { provider_name: "TossA2", provider_code: "tossa", status: "active" },
        {
          provider_name: "FooBar",
          provider_code: "foobar",
          status: "deprecated",
        },
        {
          provider_name: "ZenoGate",
          provider_code: "zenogate",
          status: "active",
        },
        {
          provider_name: "InactiveGate",
          provider_code: "inactivegate",
          status: "inactive",
        },
      ],
      async (base) => {
        const output =
          await api.functional.shoppingMall.admin.externalPaymentProviders.create(
            connection,
            {
              body: {
                provider_name: base.provider_name,
                provider_code: base.provider_code,
                status: base.status,
                description: RandomGenerator.paragraph({ sentences: 2 }),
              },
            },
          );
        typia.assert(output);
        return output;
      },
    );

  // Filter by provider_name (exact match)
  const providerToTest = providers[0];
  const resName =
    await api.functional.shoppingMall.admin.externalPaymentProviders.index(
      connection,
      {
        body: {
          provider_name: providerToTest.provider_name,
        },
      },
    );
  typia.assert(resName);
  TestValidator.predicate(
    "result for exact provider_name match only contains that provider",
    resName.data.length === 1 &&
      resName.data[0].name === providerToTest.provider_name,
  );

  // Filter by provider_code (exact match, should be unique)
  const providerByCode = providers[1];
  const resCode =
    await api.functional.shoppingMall.admin.externalPaymentProviders.index(
      connection,
      {
        body: {
          provider_code: providerByCode.provider_code,
        },
      },
    );
  typia.assert(resCode);
  TestValidator.predicate(
    "result for exact provider_code match only contains that provider",
    resCode.data.length === 1 &&
      resCode.data[0].provider_code === providerByCode.provider_code,
  );

  // Filter by status: all 'active' records
  const resStatus =
    await api.functional.shoppingMall.admin.externalPaymentProviders.index(
      connection,
      {
        body: { status: "active" },
      },
    );
  typia.assert(resStatus);
  TestValidator.predicate(
    "all listed providers have status active",
    resStatus.data.length > 0 &&
      resStatus.data.every((p) => p.status === "active"),
  );

  // Case: Free-text search q hits by description or name
  const searchString = providerToTest.provider_name.substring(0, 4);
  const resQ =
    await api.functional.shoppingMall.admin.externalPaymentProviders.index(
      connection,
      {
        body: { q: searchString },
      },
    );
  typia.assert(resQ);
  TestValidator.predicate(
    "free-text q filters by name/description/codes",
    resQ.data.some(
      (p) =>
        p.name.includes(searchString) || p.provider_code.includes(searchString),
    ),
  );

  // Filter resulting in no matches (random string)
  const resNone =
    await api.functional.shoppingMall.admin.externalPaymentProviders.index(
      connection,
      {
        body: { q: "NO_MATCH_THIS_QWERZXCV" },
      },
    );
  typia.assert(resNone);
  TestValidator.equals(
    "no results for random search q",
    resNone.data.length,
    0,
  );

  // Pagination checks
  const resPage1 =
    await api.functional.shoppingMall.admin.externalPaymentProviders.index(
      connection,
      {
        body: { page: 1 as number, limit: 2 as number },
      },
    );
  typia.assert(resPage1);
  TestValidator.equals("pagination current=1", resPage1.pagination.current, 1);
  TestValidator.equals("pagination limit=2", resPage1.pagination.limit, 2);
  TestValidator.predicate(
    "page 1 data is at most 2 length",
    resPage1.data.length <= 2,
  );
  // page 2, should match if more than 2 rows
  const resPage2 =
    await api.functional.shoppingMall.admin.externalPaymentProviders.index(
      connection,
      {
        body: { page: 2 as number, limit: 2 as number },
      },
    );
  typia.assert(resPage2);
  TestValidator.equals("pagination current=2", resPage2.pagination.current, 2);
  TestValidator.equals("pagination limit=2", resPage2.pagination.limit, 2);
  TestValidator.predicate(
    "page 2 data is at most 2 length",
    resPage2.data.length <= 2,
  );

  // Security: must be authenticated as admin - create a guest/unauth connection and expect error
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated externalPaymentProviders.index fails",
    async () => {
      await api.functional.shoppingMall.admin.externalPaymentProviders.index(
        unauthConn,
        {
          body: {},
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
