import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductAttribute";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test the seller's ability to search and filter product attribute definitions
 * for a product they own.
 *
 * 1. Register and authenticate a new seller.
 * 2. Create a new product as that seller.
 * 3. Query the attributes for this product using various search and pagination
 *    parameters (page, limit, search by attribute_name substring, filter by
 *    position, apply sort order).
 * 4. Validate that the attributes returned belong only to the specified product
 *    and the structure matches IPageIShoppingMallProductAttribute.ISummary,
 *    including correct pagination meta.
 * 5. Edge case: on a new product, querying attributes returns an empty data set
 *    but correct pagination metadata.
 * 6. Attempt to fetch attributes for a product with incorrect authentication
 *    (simulate unauthorized access by joining as a second seller and querying
 *    the first seller's product), and expect an error.
 */
export async function test_api_product_attribute_search_by_seller(
  connection: api.IConnection,
) {
  // 1. Register and authenticate seller #1
  const seller1Email = typia.random<string & tags.Format<"email">>();
  const seller1Auth = await api.functional.auth.seller.join(connection, {
    body: {
      email: seller1Email,
      password: RandomGenerator.alphaNumeric(12) as string &
        tags.Format<"password">,
      business_name: RandomGenerator.name(),
      registration_number: RandomGenerator.alphabets(8),
      business_phone: RandomGenerator.mobile(),
      href: "https://seller1-register.test/",
      referrer: "https://homepage.seller1.test/",
      ip: null,
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller1Auth);

  // 2. Create a new product (as seller #1)
  const productCreate = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({ paragraphs: 2 }),
    default_price: typia.random<number>(),
    business_status: "draft",
  } satisfies IShoppingMallProduct.ICreate;
  const product = await api.functional.shoppingMall.products.create(
    connection,
    { body: productCreate },
  );
  typia.assert(product);

  // 3. Query attributes for the product - default pagination (page=1, limit=10), expect empty for new product
  const attrParamsDefault = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
  } satisfies IShoppingMallProductAttribute.IRequest;
  const attrPageDefault =
    await api.functional.shoppingMall.seller.products.attributes.index(
      connection,
      { productId: product.id, body: attrParamsDefault },
    );
  typia.assert(attrPageDefault);
  TestValidator.equals(
    "should have empty data when no attributes exist",
    attrPageDefault.data.length,
    0,
  );
  TestValidator.equals(
    "should show correct pagination meta for empty data",
    attrPageDefault.pagination.current,
    1,
  );
  TestValidator.equals(
    "records is zero for empty data",
    attrPageDefault.pagination.records,
    0,
  );

  // 4. Query with non-existent search substring (should also return empty)
  const attrParamsSearchMiss = {
    page: 1 as number & tags.Type<"int32">,
    limit: 5 as number & tags.Type<"int32">,
    search: "__impossible__",
  } satisfies IShoppingMallProductAttribute.IRequest;
  const attrPageSearchMiss =
    await api.functional.shoppingMall.seller.products.attributes.index(
      connection,
      { productId: product.id, body: attrParamsSearchMiss },
    );
  typia.assert(attrPageSearchMiss);
  TestValidator.equals(
    "search miss gives empty",
    attrPageSearchMiss.data.length,
    0,
  );

  // 5. Edge: Requesting an out-of-bounds page (e.g., page 100)
  const attrParamsPageFar = {
    page: 100 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
  } satisfies IShoppingMallProductAttribute.IRequest;
  const attrPageFar =
    await api.functional.shoppingMall.seller.products.attributes.index(
      connection,
      { productId: product.id, body: attrParamsPageFar },
    );
  typia.assert(attrPageFar);
  TestValidator.equals(
    "far page should have empty data",
    attrPageFar.data.length,
    0,
  );
  TestValidator.equals(
    "current page reflects request",
    attrPageFar.pagination.current,
    100,
  );

  // 6. Negative: Second seller cannot access first seller's product attributes
  const seller2Email = typia.random<string & tags.Format<"email">>();
  const seller2Auth = await api.functional.auth.seller.join(connection, {
    body: {
      email: seller2Email,
      password: RandomGenerator.alphaNumeric(12) as string &
        tags.Format<"password">,
      business_name: RandomGenerator.name(),
      registration_number: RandomGenerator.alphabets(8),
      business_phone: RandomGenerator.mobile(),
      href: "https://seller2-register.test/",
      referrer: "https://homepage.seller2.test/",
      ip: null,
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller2Auth);
  // Now authenticated as seller2
  await TestValidator.error(
    "non-owner should not access another seller's product attributes",
    async () => {
      await api.functional.shoppingMall.seller.products.attributes.index(
        connection,
        { productId: product.id, body: attrParamsDefault },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductAttribute";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductAttribute";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate admin attribute search, pagination, filtering for any product
 *
 * - Register and authenticate a new shopping mall admin.
 * - Create a new product (ensures product exists to query attributes).
 * - Query that product's attributes using all available
 *   IShoppingMallProductAttribute.IRequest options (search, position,
 *   pagination, sort), via
 *   /shoppingMall/admin/products/{productId}/attributes.
 * - Validate empty and non-existent filter scenarios (should always be empty
 *   initially), correct pagination, and business rule that admin can access any
 *   product's attributes.
 */
export async function test_api_product_attribute_search_by_admin(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new admin.
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword satisfies string,
      name: RandomGenerator.name(),
    },
  });
  typia.assert(admin);

  // 2. Create a new product to query
  const productInput = {
    title: RandomGenerator.paragraph({ sentences: 4 }),
    description: RandomGenerator.content({ paragraphs: 2 }),
    default_price: 5000,
    business_status: "published",
  } satisfies IShoppingMallProduct.ICreate;
  const product = await api.functional.shoppingMall.products.create(
    connection,
    { body: productInput },
  );
  typia.assert(product);

  // 3. Query attributes for the product (should be none - edge case)
  const emptyQuery = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
  } satisfies IShoppingMallProductAttribute.IRequest;
  const emptyResult =
    await api.functional.shoppingMall.admin.products.attributes.index(
      connection,
      {
        productId: product.id,
        body: emptyQuery,
      },
    );
  typia.assert(emptyResult);
  TestValidator.predicate(
    "admin querying attributes on new product returns empty data",
    emptyResult.data.length === 0,
  );

  // 4. Query using non-existent attribute name filter
  const nameFilteredQuery = {
    ...emptyQuery,
    search: "foobar-nonexistent",
  } satisfies IShoppingMallProductAttribute.IRequest;
  const nonexistNameResult =
    await api.functional.shoppingMall.admin.products.attributes.index(
      connection,
      {
        productId: product.id,
        body: nameFilteredQuery,
      },
    );
  typia.assert(nonexistNameResult);
  TestValidator.predicate(
    "non-existent attribute name returns 0 data",
    nonexistNameResult.data.length === 0,
  );

  // 5. Query using a position that is unlikely to exist
  const positionFilteredQuery = {
    ...emptyQuery,
    position: 9999 as number & tags.Type<"int32">,
  } satisfies IShoppingMallProductAttribute.IRequest;
  const nonexistPosResult =
    await api.functional.shoppingMall.admin.products.attributes.index(
      connection,
      {
        productId: product.id,
        body: positionFilteredQuery,
      },
    );
  typia.assert(nonexistPosResult);
  TestValidator.predicate(
    "non-existent attribute position returns 0 data",
    nonexistPosResult.data.length === 0,
  );

  // 6. Validate pagination for various limits (data always empty)
  for (const limit of [1, 5, 10, 20] as const) {
    const pagedQuery = {
      ...emptyQuery,
      limit: limit as number & tags.Type<"int32">,
    } satisfies IShoppingMallProductAttribute.IRequest;
    const pagedResult =
      await api.functional.shoppingMall.admin.products.attributes.index(
        connection,
        {
          productId: product.id,
          body: pagedQuery,
        },
      );
    typia.assert(pagedResult);
    TestValidator.equals(
      `pagination with limit ${limit} returns 0 data`,
      pagedResult.data.length,
      0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrderShipment";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderShipment";
import type { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";

/**
 * Validate that admin can search order shipments with various filters and that
 * only authorized admin accounts can retrieve shipment data.
 *
 * 1. Register a new admin account.
 * 2. Generate a mock order number for shipment search (since order creation is not
 *    available in accessible SDK functions).
 * 3. Attempt to retrieve shipments while authenticated, using shipment filter
 *    fields.
 * 4. Validate shipments, pagination, and that field filters (status,
 *    tracking_number, shipping_partner_id, date ranges) work logically.
 * 5. Attempt shipment search with deliberate mismatched filter (e.g., bad status
 *    or random tracking number), assert empty result.
 * 6. Switch to unauthenticated connection and assert shipment search is forbidden.
 */
export async function test_api_order_shipments_search_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin (establish authentication)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12) + ".Aa1!";
  const adminName: string = RandomGenerator.name();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: adminName,
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);
  // 2. Generate a plausible order number and shipment filter values
  const orderNumber: string =
    "ORD" +
    typia
      .random<
        number & tags.Type<"uint32"> & tags.Minimum<10000> & tags.Maximum<99999>
      >()
      .toString();
  // 3. Search shipments by admin (all filters left undefined, get all shipments for this order number)
  const response: IPageIShoppingMallOrderShipment.ISummary =
    await api.functional.shoppingMall.admin.orders.shipments.index(connection, {
      orderNumber,
      body: {},
    });
  typia.assert(response);
  TestValidator.equals(
    "pagination.current defaults to 1",
    response.pagination.current,
    1,
  );
  TestValidator.predicate(
    "pagination limit is sensible",
    response.pagination.limit > 0 && response.pagination.limit <= 100,
  );
  // 4. If there's any shipment in the result, run filtered queries on each
  if (response.data.length > 0) {
    const sample = RandomGenerator.pick(response.data);
    // Filter by status
    const statusFiltered =
      await api.functional.shoppingMall.admin.orders.shipments.index(
        connection,
        {
          orderNumber,
          body: { status: sample.status },
        },
      );
    typia.assert(statusFiltered);
    TestValidator.predicate(
      "all shipments match status filter",
      statusFiltered.data.every((s) => s.status === sample.status),
    );
    // Filter by tracking_number
    const numberFiltered =
      await api.functional.shoppingMall.admin.orders.shipments.index(
        connection,
        {
          orderNumber,
          body: { tracking_number: sample.tracking_number },
        },
      );
    typia.assert(numberFiltered);
    TestValidator.predicate(
      "all shipments match tracking_number filter",
      numberFiltered.data.every(
        (s) => s.tracking_number === sample.tracking_number,
      ),
    );
    // Filter by shipping_partner_id
    const partnerFiltered =
      await api.functional.shoppingMall.admin.orders.shipments.index(
        connection,
        {
          orderNumber,
          body: { shipping_partner_id: sample.shipping_partner.id },
        },
      );
    typia.assert(partnerFiltered);
    TestValidator.predicate(
      "all shipments match shipping_partner_id filter",
      partnerFiltered.data.every(
        (s) => s.shipping_partner.id === sample.shipping_partner.id,
      ),
    );
    // Filter by date range
    const createdAt = sample.created_at;
    const dateFiltered =
      await api.functional.shoppingMall.admin.orders.shipments.index(
        connection,
        {
          orderNumber,
          body: { start_created_at: createdAt, end_created_at: createdAt },
        },
      );
    typia.assert(dateFiltered);
    TestValidator.predicate(
      "all shipments created exactly at the filtered date",
      dateFiltered.data.every((s) => s.created_at === createdAt),
    );
    // Paginate with limit=1
    const paged =
      await api.functional.shoppingMall.admin.orders.shipments.index(
        connection,
        {
          orderNumber,
          body: { limit: 1 },
        },
      );
    typia.assert(paged);
    TestValidator.equals("page has only 1 item", paged.data.length, 1);
    TestValidator.equals(
      "pagination.limit matches query",
      paged.pagination.limit,
      1,
    );
  }
  // 5. Search with filters that should yield 0 results
  const emptyStatus = "nonexistent-status-test";
  const emptyStatusResp =
    await api.functional.shoppingMall.admin.orders.shipments.index(connection, {
      orderNumber,
      body: { status: emptyStatus },
    });
  typia.assert(emptyStatusResp);
  TestValidator.equals(
    "no shipment for unknown status",
    emptyStatusResp.data.length,
    0,
  );
  // 6. Attempt access with unauthenticated connection
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "forbid access without admin authentication",
    async () => {
      await api.functional.shoppingMall.admin.orders.shipments.index(
        unauthConn,
        {
          orderNumber,
          body: {},
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAddress";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderShipment";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";

/**
 * Test that a customer can retrieve shipment detail for their order and
 * validates access and fields.
 *
 * 1. Register customer (with real info)
 * 2. Register seller and admin
 * 3. Admin: Register shipping partner
 * 4. Customer: (mock address summary)
 * 5. Customer: Create order (reference self & address & seller)
 * 6. Seller: Create shipment for customer order, referencing shipping partner
 * 7. Customer: Retrieve shipment by orderNumber+shipmentId, confirm correct
 *    fields/associations
 * 8. Unauthorized: Create another customer, try access (should fail)
 * 9. Customer: Fails with invalid shipmentId/orderNumber (should fail)
 */
export async function test_api_order_shipment_detail_retrieval_by_customer(
  connection: api.IConnection,
) {
  // (1) Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "abcABC12$";
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // (2) Register a seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Seller888!";
  const sellerHref = "https://seller.mall/join";
  const sellerRef = "https://mall.com/";
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      business_name: RandomGenerator.paragraph({ sentences: 2 }),
      registration_number: RandomGenerator.alphaNumeric(8),
      business_phone: RandomGenerator.mobile(),
      href: sellerHref,
      referrer: sellerRef,
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // (3) Register admin and create shipping partner
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin123!";
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      name: RandomGenerator.name(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);
  // Login as admin
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IShoppingMallAdmin.ILogin,
  });
  // Register shipping partner
  const shippingPartner =
    await api.functional.shoppingMall.admin.shippingPartners.create(
      connection,
      {
        body: {
          partner_name: RandomGenerator.paragraph({ sentences: 2 }),
          partner_code: RandomGenerator.alphaNumeric(8),
          status: "active",
          description: RandomGenerator.paragraph({ sentences: 4 }),
        } satisfies IShoppingMallShippingPartner.ICreate,
      },
    );
  typia.assert(shippingPartner);

  // Switch back to customer
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://customer.mall/orders",
      referrer: "https://search.mall.com/",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // (4) Create a mock address summary (simulate address DB record, shortcut)
  // (address summary is not created via an API in the available SDK)
  const addressSummary: IShoppingMallAddress.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    full_name: RandomGenerator.name(),
    street: RandomGenerator.paragraph({ sentences: 2 }),
    city: RandomGenerator.name(1),
    province: RandomGenerator.name(1),
    postal_code: RandomGenerator.alphaNumeric(6),
    country: "TestLand",
    phone: RandomGenerator.mobile(),
    is_default: true,
  };

  // (5) Create order for customer
  const orderNumber = RandomGenerator.alphaNumeric(12);
  const order = await api.functional.shoppingMall.customer.orders.create(
    connection,
    {
      body: {
        order_number: orderNumber,
        shopping_mall_customer_id: customer.id,
        shopping_mall_address_id: addressSummary.id,
        shopping_mall_seller_id: seller.id,
        status: "pending",
        total_amount: 10000,
        currency: "USD",
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);

  // (6) Login as seller to create shipment for order
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: sellerHref,
      referrer: sellerRef,
    } satisfies IShoppingMallSeller.ILogin,
  });
  const trackingNumber = RandomGenerator.alphaNumeric(13);
  const shipDate = new Date().toISOString();
  const shipment =
    await api.functional.shoppingMall.seller.orders.shipments.create(
      connection,
      {
        orderNumber: orderNumber,
        body: {
          shipping_partner_id: shippingPartner.id,
          tracking_number: trackingNumber,
          status: "shipped",
          ship_date: shipDate,
          expected_delivery_date: null,
        } satisfies IShoppingMallOrderShipment.ICreate,
      },
    );
  typia.assert(shipment);

  // (7) Login as customer to retrieve shipment detail
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://customer.mall/orders",
      referrer: "https://search.mall.com/",
    } satisfies IShoppingMallCustomer.ILogin,
  });
  const retrieved =
    await api.functional.shoppingMall.customer.orders.shipments.at(connection, {
      orderNumber: orderNumber,
      shipmentId: shipment.id,
    });
  typia.assert(retrieved);

  TestValidator.equals(
    "retrieved shipment should match created shipment id",
    retrieved.id,
    shipment.id,
  );
  TestValidator.equals(
    "retrieved shipment order number should match order number",
    retrieved.order.order_number,
    orderNumber,
  );
  TestValidator.equals(
    "retrieved shipment tracking number correct",
    retrieved.tracking_number,
    trackingNumber,
  );
  TestValidator.equals(
    "shipping partner association",
    retrieved.shippingPartner.id,
    shippingPartner.id,
  );
  TestValidator.equals("shipment status", retrieved.status, "shipped");
  TestValidator.equals("shipment ship_date", retrieved.ship_date, shipDate);

  // (8) Create another customer, try to access the shipment (should fail)
  const customer2Email = typia.random<string & tags.Format<"email">>();
  const customer2Password = "otherCust$12";
  const customer2 = await api.functional.auth.customer.join(connection, {
    body: {
      email: customer2Email,
      password: customer2Password,
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer2);
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customer2Email,
      password: customer2Password,
      href: "https://customer2.mall/orders",
      referrer: "https://login.customer2.com/",
    } satisfies IShoppingMallCustomer.ILogin,
  });
  await TestValidator.error(
    "unauthorized customer cannot access other customer's shipment",
