/**
 * Validates that an authenticated seller can retrieve detailed information for
 * an order item (in an order containing their product) using the
 * /shoppingMall/seller/orders/{orderNumber}/items/{orderItemId} endpoint and
 * that cross-seller access is denied.
 *
 * Workflow:
 *
 * 1. Register seller1 (acting as catalog/product owner).
 * 2. Register seller2 (will be used to verify cross-seller isolation).
 * 3. Register a third seller to simulate a buyer (as only seller registration is
 *    available for data setup, this account acts as the customer placing the
 *    order).
 * 4. Use the simulated customer/seller3 to order from seller1’s catalog, manually
 *    assembling order and order item as only seller registration exists.
 * 5. With seller1’s authorization token, attempt to retrieve order item using
 *    order number and item ID (should succeed).
 * 6. With seller2’s token, attempt to retrieve same order item (should fail with
 *    authorization error).
 * 7. Verify both positive and negative scenarios, and assert returned data
 *    structure is an IShoppingMallOrderItem.
 */
export async function test_api_seller_order_item_detail_by_seller(
  connection: api.IConnection,
) {
  // 1. Register seller1 (product owner)
  const seller1Info = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password123!",
    business_name: RandomGenerator.paragraph({ sentences: 2 }),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://example.com/register",
    referrer: "https://example.com/login",
    ip: undefined,
  } satisfies IShoppingMallSeller.ICreate;
  const seller1 = await api.functional.auth.seller.join(connection, {
    body: seller1Info,
  });
  typia.assert(seller1);

  // 2. Register seller2 (non-owner, will be denied authorization)
  const seller2Info = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password456!",
    business_name: RandomGenerator.paragraph({ sentences: 2 }),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://example.com/register",
    referrer: "https://example.com/login",
    ip: undefined,
  } satisfies IShoppingMallSeller.ICreate;
  const seller2 = await api.functional.auth.seller.join(connection, {
    body: seller2Info,
  });
  typia.assert(seller2);

  // 3. Register third seller as mock customer (since only seller registration is available)
  const buyerInfo = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password789!",
    business_name: RandomGenerator.paragraph({ sentences: 2 }),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://example.com/register",
    referrer: "https://example.com/login",
    ip: undefined,
  } satisfies IShoppingMallSeller.ICreate;
  const buyerSeller = await api.functional.auth.seller.join(connection, {
    body: buyerInfo,
  });
  typia.assert(buyerSeller);

  // 4. Simulate order and item referencing seller1's ownership (simulate as no order creation API is available)
  // Use typia.random to simulate an order referencing seller1's product
  const productOwnerSummary = seller1.seller!;
  const productSummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph({ sentences: 2 }),
    default_price: 1000,
    business_status: "published",
    seller: productOwnerSummary,
    categories: [],
    created_at: new Date().toISOString(),
  } satisfies IShoppingMallProduct.ISummary;
  const skuSummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(12),
    product_title: productSummary.title,
    option_summary: RandomGenerator.name(),
    in_stock: true,
  } satisfies IShoppingMallProductSku.ISummary;
  const orderSummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    order_number: RandomGenerator.alphaNumeric(16),
    status: "paid",
    total_amount: productSummary.default_price,
    currency: "USD",
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    deleted_at: null,
  } satisfies IShoppingMallOrder.ISummary;
  const orderItemToTest = {
    id: typia.random<string & tags.Format<"uuid">>(),
    order: orderSummary,
    product: productSummary,
    sku: skuSummary,
    quantity: 1,
    unit_price: productSummary.default_price,
    subtotal: productSummary.default_price,
    currency: "USD",
    delivered: false,
    refunded: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    deleted_at: null,
  } satisfies IShoppingMallOrderItem;

  // 5. Seller1: Retrieve order item detail (should succeed)
  // Assume orderItemToTest.order.order_number and orderItemToTest.id are the keys
  const output = await api.functional.shoppingMall.seller.orders.items.at(
    connection,
    {
      orderNumber: orderItemToTest.order.order_number,
      orderItemId: orderItemToTest.id,
    },
  );
  typia.assert(output);
  // 6. Seller2: Simulate cross-seller token by logging in as seller2 (token switching is handled by join)
  await api.functional.auth.seller.join(connection, {
    body: seller2Info,
  });
  // Try to retrieve same order item with seller2 token (should fail with error)
  await TestValidator.error("cross-seller access is denied", async () => {
    await api.functional.shoppingMall.seller.orders.items.at(connection, {
      orderNumber: orderItemToTest.order.order_number,
      orderItemId: orderItemToTest.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";
import type { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";

/**
 * End-to-end test verifying shipment status transition workflow and business
 * rule compliance for seller-initiated updates.
 *
 * This test registers a new seller, mocks or assumes the existence of a
 * shipment in status 'ready', and performs the full shipment workflow:
 *
 * 1. Seller registration and authentication.
 * 2. Shipment selection/setup (shipment must be in 'ready' state and belong to the
 *    seller).
 * 3. Update shipment: Transition from 'ready' → 'picked_up'.
 *
 *    - Provide tracking code, manifest URL, and set updated_by_seller_id.
 * 4. Update shipment: Transition from 'picked_up' → 'in_transit'.
 *
 *    - Optionally update tracking/manifest; must maintain seller attribution.
 * 5. Update shipment: Transition from 'in_transit' → 'delivered'.
 *
 *    - Supply delivery_at timestamp, ensure updated_by_seller_id is set.
 * 6. Attempt invalid transition: Try to move from 'delivered' → 'in_transit'.
 *
 *    - Expect business rule error (should throw, error validation).
 * 7. Throughout, validate the following after each update:
 *
 *    - Shipment.status matches new status.
 *    - Shipment.updated_by_seller_id is set to seller's id.
 *    - Manifest/tracking code changes persist.
 *    - Delivery_at property is set when status is 'delivered'.
 *    - No unauthorized field changes occur.
 */
export async function test_api_shipment_update_by_seller_status_workflow(
  connection: api.IConnection,
) {
  // 1. Register a seller and retrieve authorized seller info
  const sellerJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    business_name: RandomGenerator.name(2),
    registration_number: RandomGenerator.alphaNumeric(12),
    business_phone: RandomGenerator.mobile(),
    href: "https://example.com/seller/test",
    referrer: "https://example.com/ref",
  } satisfies IShoppingMallSeller.ICreate;
  const sellerAuth = await api.functional.auth.seller.join(connection, {
    body: sellerJoinBody,
  });
  typia.assert(sellerAuth);

  // 2. Create a mock shipment for this seller (in real test suite this would be inserted via test data factory or fixture)
  //    Here, we mock a shipment object in 'ready' state. Realistically, this would be created by preceding order→fulfillment APIs.
  let shipment = typia.random<IShoppingMallShipment>();
  shipment = {
    ...shipment,
    status: "ready",
    createdBySeller: {
      id: sellerAuth.id,
      business_name: sellerAuth.business_name,
    },
  };
  const shipmentId = shipment.id;

  // 3. Transition shipment to 'picked_up'
  const pickedUpTrackingCode = RandomGenerator.alphaNumeric(15);
  const pickedUpManifestUrl =
    "https://logistic.example.com/manifest/" + RandomGenerator.alphaNumeric(10);
  let out = await api.functional.shoppingMall.seller.shipments.update(
    connection,
    {
      shipmentId,
      body: {
        status: "picked_up",
        carrier_tracking_code: pickedUpTrackingCode,
        manifest_url: pickedUpManifestUrl,
        updated_by_seller_id: sellerAuth.id,
      } satisfies IShoppingMallShipment.IUpdate,
    },
  );
  typia.assert(out);
  TestValidator.equals("Status changed to picked_up", out.status, "picked_up");
  TestValidator.equals(
    "Tracking code updated",
    out.carrier_tracking_code,
    pickedUpTrackingCode,
  );
  TestValidator.equals(
    "Manifest url updated",
    out.manifest_url,
    pickedUpManifestUrl,
  );
  TestValidator.equals(
    "Attribution to seller",
    out.createdBySeller?.id,
    sellerAuth.id,
  );

  // 4. Transition shipment to 'in_transit'
  const inTransitTracking = RandomGenerator.alphaNumeric(15);
  const inTransitManifest =
    "https://logistic.example.com/manifest/" + RandomGenerator.alphaNumeric(10);
  out = await api.functional.shoppingMall.seller.shipments.update(connection, {
    shipmentId,
    body: {
      status: "in_transit",
      carrier_tracking_code: inTransitTracking,
      manifest_url: inTransitManifest,
      updated_by_seller_id: sellerAuth.id,
    } satisfies IShoppingMallShipment.IUpdate,
  });
  typia.assert(out);
  TestValidator.equals(
    "Status changed to in_transit",
    out.status,
    "in_transit",
  );
  TestValidator.equals(
    "Tracking code updated for in_transit",
    out.carrier_tracking_code,
    inTransitTracking,
  );
  TestValidator.equals(
    "Manifest url updated for in_transit",
    out.manifest_url,
    inTransitManifest,
  );
  TestValidator.equals(
    "Attribution to seller (in_transit)",
    out.createdBySeller?.id,
    sellerAuth.id,
  );

  // 5. Transition shipment to 'delivered' (requires delivery_at)
  const deliveredAt = new Date().toISOString();
  out = await api.functional.shoppingMall.seller.shipments.update(connection, {
    shipmentId,
    body: {
      status: "delivered",
      carrier_tracking_code: inTransitTracking, // use previous tracking
      manifest_url: inTransitManifest,
      updated_by_seller_id: sellerAuth.id,
      delivery_at: deliveredAt,
    } satisfies IShoppingMallShipment.IUpdate,
  });
  typia.assert(out);
  TestValidator.equals("Status changed to delivered", out.status, "delivered");
  TestValidator.equals(
    "Delivery timestamp recorded",
    out.delivery_at,
    deliveredAt,
  );
  TestValidator.equals(
    "Attribution to seller (delivered)",
    out.createdBySeller?.id,
    sellerAuth.id,
  );

  // 6. Attempt invalid transition: Move from 'delivered' → 'in_transit' (should fail)
  await TestValidator.error(
    "Invalid transition from delivered to in_transit should be rejected",
    async () => {
      await api.functional.shoppingMall.seller.shipments.update(connection, {
        shipmentId,
        body: {
          status: "in_transit",
          updated_by_seller_id: sellerAuth.id,
        } satisfies IShoppingMallShipment.IUpdate,
      });
    },
  );
}

