import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate that a platform admin can retrieve detailed seller review response
 * info.
 *
 * 1. Register a new admin via /auth/admin/join to establish admin context.
 * 2. Generate random UUIDs for reviewId and responseId.
 * 3. Call /shoppingMall/admin/reviews/{reviewId}/responses/{responseId} as admin
 *    to fetch seller response detail.
 * 4. Assert the result matches IShoppingMallReviewResponse and includes all
 *    fields:
 *
 *    - Body, moderation status, withdrawn_at, moderation_reason, created_at,
 *         updated_at, deleted_at, review reference, seller reference.
 * 5. Confirm admin-only fields (moderation/audit info) are present and correct.
 */
export async function test_api_review_response_detail_retrieval_by_admin(
  connection: api.IConnection,
) {
  // 1. Register and authenticate an admin
  const adminCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.ICreate;

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminCreate,
    });
  typia.assert(admin);

  // 2. Prepare random reviewId and responseId
  const reviewId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const responseId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 3. Attempt to retrieve seller response details as admin
  const detail: IShoppingMallReviewResponse =
    await api.functional.shoppingMall.admin.reviews.responses.at(connection, {
      reviewId,
      responseId,
    });
  typia.assert(detail);

  // 4. Validate all fields are present and plausible according to schema
  TestValidator.predicate(
    "response body present",
    typeof detail.body === "string" &&
      detail.body.length >= 10 &&
      detail.body.length <= 1000,
  );
  TestValidator.predicate(
    "valid moderation_status",
    typeof detail.moderation_status === "string" &&
      detail.moderation_status.length > 0,
  );
  TestValidator.predicate(
    "review reference exists",
    !!detail.review &&
      typeof detail.review.id === "string" &&
      detail.review.id.length > 0,
  );
  TestValidator.predicate(
    "seller reference exists",
    !!detail.seller &&
      typeof detail.seller.id === "string" &&
      detail.seller.id.length > 0,
  );
  TestValidator.predicate(
    "created_at is ISO date-time",
    typeof detail.created_at === "string" &&
      !isNaN(Date.parse(detail.created_at)),
  );
  TestValidator.predicate(
    "updated_at is ISO date-time",
    typeof detail.updated_at === "string" &&
      !isNaN(Date.parse(detail.updated_at)),
  );
  // Optional fields: withdrawn_at, moderation_reason, deleted_at can be null/undefined or valid date/strings

  // 5. Confirm admin is permitted to see audit/moderation fields (moderation_status, moderation_reason, deleted_at)
  TestValidator.predicate(
    "admin has access to moderation fields",
    "moderation_status" in detail && "moderation_reason" in detail,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductRating } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductRating";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import type { IShoppingMallReviewResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReviewResponse";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate seller response creation for a product review, ensuring correct
 * prerequisites are established.
 *
 * 1. Register a new seller via /auth/seller/join.
 * 2. (Assume required product, SKU, order, customer, session, and rating test data
 *    exist/are preconditioned.)
 * 3. Create a product review as prerequisite through /shoppingMall/reviews (with
 *    all required fields).
 * 4. As the associated seller, post a response to the review under test.
 * 5. Assertions:
 *
 *    - Only the product seller is permitted as responder.
 *    - Each review allows at most one seller response.
 *    - Seller response correctly associates to the right review and seller.
 *    - Moderation status is correctly set.
 */
export async function test_api_seller_review_response_creation_with_required_prerequisites(
  connection: api.IConnection,
) {
  // 1. Register a new seller for authentication context
  const sellerAuth = await api.functional.auth.seller.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(12),
      business_name: RandomGenerator.paragraph({ sentences: 2 }),
      registration_number: RandomGenerator.alphaNumeric(15),
      business_phone: RandomGenerator.mobile(),
      href: "https://test.seller.platform/join",
      referrer: "https://test.platform/login",
      ip: null,
    },
  });
  typia.assert(sellerAuth);
  TestValidator.equals(
    "seller email matches",
    sellerAuth.email,
    sellerAuth.email,
  );

  // 2. Assume existence of all business prerequisites, but create a test product review with valid context:
  // Mock UUIDs for all required context ids
  const product_id = typia.random<string & tags.Format<"uuid">>();
  const sku_id = typia.random<string & tags.Format<"uuid">>();
  const order_id = typia.random<string & tags.Format<"uuid">>();
  const order_item_id = typia.random<string & tags.Format<"uuid">>();
  const product_rating_id = typia.random<string & tags.Format<"uuid">>();

  // Create a product review (this would normally require actual purchased context - here, synthesize)
  const review = await api.functional.shoppingMall.reviews.create(connection, {
    body: {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      body: RandomGenerator.content({
        paragraphs: 1,
        sentenceMin: 10,
        sentenceMax: 18,
        wordMin: 6,
        wordMax: 10,
      }),
      shopping_mall_product_id: product_id,
      shopping_mall_product_sku_id: sku_id,
      shopping_mall_order_id: order_id,
      shopping_mall_order_item_id: order_item_id,
      shopping_mall_product_rating_id: product_rating_id,
      is_draft: false,
      moderation_status: "approved",
      withdrawn_at: null,
    },
  });
  typia.assert(review);
  TestValidator.equals(
    "review 'is_draft' should be false",
    review.is_draft,
    false,
  );

  // 3. Post a seller response to the created review
  const responsePayload = {
    body: RandomGenerator.paragraph({ sentences: 4, wordMin: 5, wordMax: 16 }), // 10-1000 chars
    moderation_status: "approved",
  } satisfies IShoppingMallReviewResponse.ICreate;
  const sellerResponse =
    await api.functional.shoppingMall.seller.reviews.responses.create(
      connection,
      {
        reviewId: review.id,
        body: responsePayload,
      },
    );
  typia.assert(sellerResponse);
  TestValidator.equals(
    "response review id matches review",
    sellerResponse.review.id,
    review.id,
  );
  TestValidator.equals(
    "seller in response is current seller",
    sellerResponse.seller.id,
    sellerAuth.id,
  );
  TestValidator.equals(
    "moderation_status is respected",
    sellerResponse.moderation_status,
    responsePayload.moderation_status,
  );

  // 4. Attempt duplicate seller response to verify only one is allowed
  await TestValidator.error(
    "duplicate response on same review must fail",
    async () => {
      await api.functional.shoppingMall.seller.reviews.responses.create(
        connection,
        {
          reviewId: review.id,
          body: responsePayload,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";
import type { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";

/**
 * Validate that a platform administrator can view the complete shipment detail
 * for a specific shipment record via the admin API.
 *
 * - Ensures authentication as an admin, using the join endpoint
 * - Creates a shipping partner for assignment
 * - Creates a shipment using the shipping partner, in admin context
 * - Fetches the shipment detail via the shipment's unique id
 * - Validates all shipment detail fields:
 *
 *   - Order (summary)
 *   - OrderItem (summary)
 *   - ShippingPartner (summary)
 *   - Status, tracking code, manifest url, provider_response_code
 *   - Audit actor (createdByAdmin)
 *   - All relevant timestamps
 * - Verifies that all references are populated and IDs match and that audit/admin
 *   actor fields are accessible by admin user
 * - Verifies that fields reflect the system state as expected from creation and
 *   assignment (permissions/edge cases like non-existent ID or wrong role are
 *   not tested here)
 */
export async function test_api_shipment_detail_view_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin joins and is authenticated
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<
    string & tags.MinLength<8> & tags.Format<"password">
  >();
  const adminName = RandomGenerator.name();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      name: adminName,
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // 2. Admin creates a shipping partner
  const partnerInput = {
    partner_name: RandomGenerator.name(),
    partner_code: RandomGenerator.alphaNumeric(10),
    status: "active",
    description: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies IShoppingMallShippingPartner.ICreate;
  const partner =
    await api.functional.shoppingMall.admin.shippingPartners.create(
      connection,
      { body: partnerInput },
    );
  typia.assert(partner);

  // 3. Create sample order summary and item summary
  // Because shipment requires valid order/orderItem/SKU,
  // We'll simulate these as random summaries (in real e2e, these would be created via order flow)
  const order: IShoppingMallOrder.ISummary =
    typia.random<IShoppingMallOrder.ISummary>();
  const item: IShoppingMallOrderItem.ISummary =
    typia.random<IShoppingMallOrderItem.ISummary>();

  // 4. Create the shipment as admin, assigning partner and self as creator
  const createInput = {
    order_id: order.id,
    order_item_id: item.id,
    shipping_partner_id: partner.id,
    carrier_tracking_code: RandomGenerator.alphaNumeric(12),
    status: "ready",
    manifest_url: null,
    provider_response_code: RandomGenerator.alphaNumeric(6),
    created_by_admin_id: admin.id,
    created_by_seller_id: undefined,
  } satisfies IShoppingMallShipment.ICreate;
  const created = await api.functional.shoppingMall.admin.shipments.create(
    connection,
    { body: createInput },
  );
  typia.assert(created);

  // 5. Fetch shipment detail as admin using shipmentId
  const fetched = await api.functional.shoppingMall.admin.shipments.at(
    connection,
    { shipmentId: created.id },
  );
  typia.assert(fetched);

  // 6. Validate all fields
  // Core entity and reference IDs match
  TestValidator.equals("shipment id matches", fetched.id, created.id);
  TestValidator.equals("order ref matches", fetched.order.id, order.id);
  TestValidator.equals("order item id matches", fetched.orderItem.id, item.id);
  TestValidator.equals(
    "shipping partner id matches",
    fetched.shippingPartner.id,
    partner.id,
  );

  // Audit/actor field (createdByAdmin)
  TestValidator.equals(
    "createdByAdmin id matches",
    fetched.createdByAdmin?.id,
    admin.id,
  );
  TestValidator.equals(
    "createdByAdmin email matches",
    fetched.createdByAdmin?.email,
    admin.email,
  );
  TestValidator.equals(
    "createdByAdmin name matches",
    fetched.createdByAdmin?.name,
    admin.name,
  );

  // Status and codes
  TestValidator.equals("shipment status is 'ready'", fetched.status, "ready");
  TestValidator.equals(
    "carrier tracking code matches",
    fetched.carrier_tracking_code,
    createInput.carrier_tracking_code,
  );
  TestValidator.equals(
    "provider response code matches",
    fetched.provider_response_code,
    createInput.provider_response_code,
  );
  TestValidator.equals("manifest url is null", fetched.manifest_url, null);
  // Ensure timestamps are ISO date strings (typia.assert already guarantees this)
  // All non-applicable fields (createdBySeller, delivery_at, cancelled_at) should be null or undefined
  TestValidator.equals(
    "createdBySeller is null",
    fetched.createdBySeller,
    null,
  );
  TestValidator.equals(
    "delivery_at is null or undefined",
    fetched.delivery_at,
    null,
  );
  TestValidator.equals(
    "cancelled_at is null or undefined",
    fetched.cancelled_at,
    null,
  );
}

