import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductRating } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductRating";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import type { IShoppingMallReviewResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReviewResponse";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate that an authenticated seller can successfully update their existing
 * response to a customer product review.
 *
 * 1. Create a review as a customer (random-valid payload).
 * 2. Register and authenticate as a new seller, using fresh email and registration
 *    number, for a valid seller with business details.
 * 3. As the seller, create an initial review response to the review. (Link with
 *    reviewId, body, moderation_status, and null moderation_reason.)
 * 4. Update the created seller response, modifying the "body" (ensure 10+ chars)
 *    and optionally moderation_status (random string again).
 * 5. Assert the update result: returned response matches updated body, status, and
 *    keeps consistent IDs, ownership, and review linkage.
 * 6. Also, verify the ownership/permission and business rules are respected
 *    (positive path only).
 */
export async function test_api_seller_review_response_update_workflow(
  connection: api.IConnection,
) {
  // 1. Create a customer product review (simulate real customer experience)
  const review: IShoppingMallReview =
    await api.functional.shoppingMall.reviews.create(connection, {
      body: typia.random<IShoppingMallReview.ICreate>(),
    });
  typia.assert(review);

  // 2. Register and authenticate as a unique seller
  const sellerAuth: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(12),
        business_name: RandomGenerator.paragraph({ sentences: 2 }),
        registration_number: RandomGenerator.alphaNumeric(10),
        business_phone: RandomGenerator.mobile(),
        href: "https://domain.example/seller-join",
        referrer: "https://domain.example/landing",
        ip: undefined,
      },
    });
  typia.assert(sellerAuth);

  // 3. As seller, create response to review
  const initialResponse: IShoppingMallReviewResponse =
    await api.functional.shoppingMall.seller.reviews.responses.create(
      connection,
      {
        reviewId: review.id,
        body: {
          body: RandomGenerator.paragraph({
            sentences: 5,
            wordMin: 4,
            wordMax: 8,
          }),
          moderation_status: RandomGenerator.pick([
            "pending",
            "approved",
            "rejected",
            "flagged",
          ] as const),
          moderation_reason: null,
        },
      },
    );
  typia.assert(initialResponse);

  // 4. Prepare update payload
  const updatedBody = RandomGenerator.paragraph({ sentences: 8 });
  const updatedModStatus = RandomGenerator.pick([
    "pending",
    "approved",
    "rejected",
    "flagged",
  ] as const);
  // 5. Update seller response
  const updatedResponse: IShoppingMallReviewResponse =
    await api.functional.shoppingMall.seller.reviews.responses.update(
      connection,
      {
        reviewId: review.id,
        responseId: initialResponse.id,
        body: {
          body: updatedBody,
          moderation_status: updatedModStatus,
          // moderation_reason stays the same (null)
        },
      },
    );
  typia.assert(updatedResponse);

  // 6. Assert update was successful and reflected appropriately
  TestValidator.equals(
    "seller response ID remains the same",
    updatedResponse.id,
    initialResponse.id,
  );
  TestValidator.equals(
    "seller review linkage remains correct",
    updatedResponse.review.id,
    review.id,
  );
  TestValidator.equals(
    "seller identity remains",
    updatedResponse.seller.id,
    sellerAuth.id,
  );
  TestValidator.equals("body updated", updatedResponse.body, updatedBody);
  TestValidator.equals(
    "moderation_status updated",
    updatedResponse.moderation_status,
    updatedModStatus,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductRating } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductRating";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import type { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import type { IShoppingMallReviewResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReviewResponse";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate seller's ability to delete their own review response, enforcing
 * access control and business logic for soft deletion.
 *
 * Scenario steps:
 *
 * 1. Register and authenticate Seller A
 * 2. Create a dummy product review (simulate all required IDs and values for
 *    review creation)
 * 3. Post a seller response to the review as Seller A
 * 4. Delete the response using the correct seller context
 * 5. Assert: Deletion does not throw and is successful
 * 6. Optionally, attempt to fetch/recreate the response to check it's soft-deleted
 *    (if applicable to the current SDK API)
 * 7. Register and authenticate Seller B
 * 8. Attempt to delete the same response as Seller B; expect error
 */
export async function test_api_seller_review_response_deletion(
  connection: api.IConnection,
) {
  // 1. Register and authenticate Seller A
  const sellerAEmail = typia.random<string & tags.Format<"email">>();
  const sellerARegistration = {
    email: sellerAEmail,
    password: "passw0rdA!",
    business_name: RandomGenerator.name(2),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://seller-a-test.com/onboarding",
    referrer: "https://referrer.com/",
  } satisfies IShoppingMallSeller.ICreate;
  const sellerAAuth = await api.functional.auth.seller.join(connection, {
    body: sellerARegistration,
  });
  typia.assert(sellerAAuth);

  // 2. Create a dummy product review; simulate all nested IDs and required values.
  const reviewBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    body: RandomGenerator.paragraph({ sentences: 15 }),
    shopping_mall_product_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_product_sku_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_order_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_order_item_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_product_rating_id: typia.random<
      string & tags.Format<"uuid">
    >(),
    is_draft: false,
    moderation_status: "approved",
  } satisfies IShoppingMallReview.ICreate;
  const review = await api.functional.shoppingMall.reviews.create(connection, {
    body: reviewBody,
  });
  typia.assert(review);

  // 3. Post a seller response to the review as Seller A
  const responseBody = {
    body: RandomGenerator.paragraph({ sentences: 10 }),
    moderation_status: "approved",
  } satisfies IShoppingMallReviewResponse.ICreate;
  const response =
    await api.functional.shoppingMall.seller.reviews.responses.create(
      connection,
      { reviewId: review.id, body: responseBody },
    );
  typia.assert(response);

  // 4. Delete the response as Seller A
  await api.functional.shoppingMall.seller.reviews.responses.erase(connection, {
    reviewId: review.id,
    responseId: response.id,
  });

  // 5. (Optionally) Check that additional delete leads to error (already deleted)
  await TestValidator.error(
    "Deleting already-deleted response should fail",
    async () => {
      await api.functional.shoppingMall.seller.reviews.responses.erase(
        connection,
        { reviewId: review.id, responseId: response.id },
      );
    },
  );

  // 6. Register and authenticate Seller B
  const sellerBEmail = typia.random<string & tags.Format<"email">>();
  const sellerBRegistration = {
    email: sellerBEmail,
    password: "passw0rdB!",
    business_name: RandomGenerator.name(2),
    registration_number: RandomGenerator.alphaNumeric(10),
    business_phone: RandomGenerator.mobile(),
    href: "https://seller-b-test.com/onboarding",
    referrer: "https://referrer.com/",
  } satisfies IShoppingMallSeller.ICreate;
  const sellerBAuth = await api.functional.auth.seller.join(connection, {
    body: sellerBRegistration,
  });
  typia.assert(sellerBAuth);

  // 7. Attempt to delete Seller A's response as Seller B (should fail by access control)
  await TestValidator.error(
    "Non-owner seller cannot delete another seller's review response",
    async () => {
      await api.functional.shoppingMall.seller.reviews.responses.erase(
        connection,
        { reviewId: review.id, responseId: response.id },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallDispute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallDispute";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate that an admin can successfully update the details, status, subject,
 * root cause, or resolution note of an existing shopping mall dispute.
 *
 * This test covers the full e2e workflow:
 *
 * 1. Create two admin accounts to allow reassignment
 * 2. Register a new dispute using admin #1
 * 3. Admin #1 updates the dispute with new subject/root cause
 * 4. Admin #1 transitions the dispute status (e.g., open → investigating →
 *    resolved → closed)
 * 5. Reassign to admin #2, verify admin assignment is updated
 * 6. Add a resolution note and verify it is updated and persists
 * 7. Attempt an unauthorized update (e.g., using wrong admin ID) and confirm
 *    update is NOT permitted
 * 8. For every update, check that status changes, admin assignment, and audit
 *    fields (updated_at) are reflected and correct business rules are enforced
 */
export async function test_api_dispute_update_by_admin(
  connection: api.IConnection,
) {
  // 1. Create two admin accounts to allow admin assignment and transitions
  const admin1Email = RandomGenerator.name(1) + "1@admin.com";
  const admin2Email = RandomGenerator.name(1) + "2@admin.com";
  const adminPassword = "AdminPass123!";
  const admin1Name = RandomGenerator.name();
  const admin2Name = RandomGenerator.name();

  const admin1: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: admin1Email satisfies string,
        password: adminPassword satisfies string,
        name: admin1Name satisfies string,
      },
    });
  typia.assert(admin1);

  // Register a second admin account (to test reassignment)
  const admin2: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: admin2Email satisfies string,
        password: adminPassword satisfies string,
        name: admin2Name satisfies string,
      },
    });
  typia.assert(admin2);

  // Prepare required customer and seller summary objects for dispute
  const customer: IShoppingMallCustomer.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.name(1),
  };
  const seller: IShoppingMallSeller.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    business_name: RandomGenerator.paragraph({ sentences: 2 }),
  };

  // 2. Register a new dispute using admin #1
  const disputeCreateBody = {
    shopping_mall_customer_id: customer.id,
    shopping_mall_seller_id: seller.id,
    shopping_mall_admin_id: admin1.id,
    status: "open",
    subject: "Initial subject",
    root_cause: "Original cause",
  } satisfies IShoppingMallDispute.ICreate;
  const initialDispute: IShoppingMallDispute =
    await api.functional.shoppingMall.admin.disputes.create(connection, {
      body: disputeCreateBody,
    });
  typia.assert(initialDispute);
  TestValidator.equals(
    "dispute status after creation is open",
    initialDispute.status,
    "open",
  );
  TestValidator.equals(
    "created dispute subject",
    initialDispute.subject,
    disputeCreateBody.subject,
  );
  TestValidator.equals(
    "created dispute root_cause",
    initialDispute.root_cause,
    disputeCreateBody.root_cause,
  );
  TestValidator.equals(
    "admin id is assigned",
    initialDispute.admin && initialDispute.admin.id,
    admin1.id,
  );

  // Save original updated_at for audit comparison
  const originalUpdatedAt = initialDispute.updated_at;

  // 3. Admin #1 updates the dispute subject and root_cause
  const updateBody1 = {
    subject: "Updated subject by admin1",
    root_cause: "Updated root cause by admin1",
  } satisfies IShoppingMallDispute.IUpdate;
  const updatedDispute1 =
    await api.functional.shoppingMall.admin.disputes.update(connection, {
      disputeId: initialDispute.id,
      body: updateBody1,
    });
  typia.assert(updatedDispute1);
  TestValidator.equals(
    "subject updated",
    updatedDispute1.subject,
    updateBody1.subject,
  );
  TestValidator.equals(
    "root_cause updated",
    updatedDispute1.root_cause,
    updateBody1.root_cause,
  );
  TestValidator.notEquals(
    "updated_at must be changed after update",
    updatedDispute1.updated_at,
    originalUpdatedAt,
  );

  // 4. Admin #1 transitions the dispute status: open → investigating → resolved → closed
  const statusTransitions = ["investigating", "resolved", "closed"];
  let lastStatus = updatedDispute1.status;
  let currentDisputeId = initialDispute.id;
  let latestDispute = updatedDispute1;
  for (const newStatus of statusTransitions) {
    const updateStatusBody = {
      status: newStatus,
    } satisfies IShoppingMallDispute.IUpdate;
    const result = await api.functional.shoppingMall.admin.disputes.update(
      connection,
      {
        disputeId: currentDisputeId,
        body: updateStatusBody,
      },
    );
    typia.assert(result);
    TestValidator.equals(
      `status transition to ${newStatus}`,
      result.status,
      newStatus,
    );
    TestValidator.notEquals(
      "updated_at must change each time",
      result.updated_at,
      latestDispute.updated_at,
    );
    latestDispute = result;
    lastStatus = result.status;
  }

  // 5. Reassign to admin #2; verify admin assignment
  const updateAssignAdminBody = {
    shopping_mall_admin_id: admin2.id,
  } satisfies IShoppingMallDispute.IUpdate;
  const reassignedDispute =
    await api.functional.shoppingMall.admin.disputes.update(connection, {
      disputeId: currentDisputeId,
      body: updateAssignAdminBody,
    });
  typia.assert(reassignedDispute);
  TestValidator.equals(
    "dispute admin reassignment",
    reassignedDispute.admin && reassignedDispute.admin.id,
    admin2.id,
  );

  // 6. Add a resolution note
  const resolutionNoteBody = {
    resolution_note: "Resolved. Item delivered after admin intervention.",
  } satisfies IShoppingMallDispute.IUpdate;
  const resolvedDispute =
    await api.functional.shoppingMall.admin.disputes.update(connection, {
      disputeId: currentDisputeId,
      body: resolutionNoteBody,
    });
  typia.assert(resolvedDispute);
  TestValidator.equals(
    "resolution note updated",
    resolvedDispute.resolution_note,
    resolutionNoteBody.resolution_note,
  );

  // 7. Attempt an unauthorized update (wrong admin id) - verification logic: should NOT allow unauthorized update.
  // Simulate with a random UUID as an unassigned admin, assuming business logic prohibits update for unauthorized actor
  await TestValidator.error(
    "unauthorized admin update should fail",
    async () => {
      await api.functional.shoppingMall.admin.disputes.update(connection, {
        disputeId: currentDisputeId,
        body: {
          shopping_mall_admin_id: typia.random<string & tags.Format<"uuid">>(),
          subject: "Malicious update attempt", // attempt unauthorized change
        } satisfies IShoppingMallDispute.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallDispute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallDispute";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Verify admin can delete (soft-delete) a dispute and audit-trail is honored.
 *
 * 1. Register a new admin and authenticate (acquire admin session).
 * 2. Using admin session, create a new dispute as target.
 * 3. Issue delete (soft-delete) operation on the dispute via admin endpoint.
 * 4. Confirm API call succeeds (void or proper error if dispute does not exist).
 * 5. Optionally, verify business rules: only admin can delete, "deleted_at"
 *    timestamp is set, and dispute is hidden from active workflows.
 */
export async function test_api_dispute_deletion_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<
    string & tags.MinLength<8> & tags.Format<"password">
  >();
  const adminName = RandomGenerator.name();
  const adminJoin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      name: adminName,
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(adminJoin);
  TestValidator.equals("admin email matches", adminJoin.email, adminEmail);
  TestValidator.equals("admin name matches", adminJoin.name, adminName);

  // 2. Create a new dispute via admin endpoint
  const disputeCreateBody = {
    shopping_mall_customer_id: typia.random<string & tags.Format<"uuid">>(),
    shopping_mall_seller_id: typia.random<string & tags.Format<"uuid">>(),
    status: RandomGenerator.pick([
      "open",
      "investigating",
      "resolved",
      "rejected",
      "escalated",
      "closed",
    ] as const),
    subject: RandomGenerator.paragraph({ sentences: 2 }),
    root_cause: RandomGenerator.paragraph({ sentences: 2 }),
    // Optional fields: Leave as undefined/null for creation
  } satisfies IShoppingMallDispute.ICreate;

  const dispute = await api.functional.shoppingMall.admin.disputes.create(
    connection,
    {
      body: disputeCreateBody,
    },
  );
  typia.assert(dispute);
  TestValidator.equals(
    "dispute subject matches",
    dispute.subject,
    disputeCreateBody.subject,
  );
  TestValidator.equals(
    "dispute root_cause matches",
    dispute.root_cause,
    disputeCreateBody.root_cause,
  );
  TestValidator.equals("is not deleted initially", dispute.deleted_at, null);

  // 3. Delete (soft-delete) the dispute via admin endpoint
  await api.functional.shoppingMall.admin.disputes.erase(connection, {
    disputeId: dispute.id,
  });

  // 4. (No return) Optionally, try to read the dispute again if an access endpoint existed.
  // However, as we do not have a dispute-get endpoint, we assume business rules are enforced via "deleted_at" and successful erase call.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallEscalationQueue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallEscalationQueue";

/**
 * Validate the creation of a new escalation queue record by an admin user.
 *
 * Steps:
 *
 * 1. Register a new admin (join operation) using admin email, password, and name
 * 2. As the newly registered admin, create a new escalation queue by submitting
 *    all required fields (escalation_type, reason_detail, status, priority,
 *    initiator_actor_admin_id)
 * 3. Validate that the escalation queue record is created, returned fields match
 *    input, and the initiator_actor_admin_id correctly matches the
 *    authenticated admin
 */
export async function test_api_escalation_queue_creation_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a new admin and obtain identity
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<
    string & tags.MinLength<8> & tags.Format<"password">
  >();
  const adminName: string = RandomGenerator.name();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: adminName,
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. Create a new escalation queue as this admin
  const input = {
    escalation_type: RandomGenerator.pick([
      "refund_dispute",
      "policy_violation",
      "compliance_check",
      "complaint",
      "delivery_exception",
    ] as const),
    reason_detail: RandomGenerator.paragraph({ sentences: 6 }),
    status: RandomGenerator.pick([
      "open",
      "investigating",
      "resolved",
      "closed",
      "rejected",
      "admin_pending",
      "compliance_review",
    ] as const),
    priority: RandomGenerator.pick([
      "low",
      "normal",
      "high",
      "urgent",
      "critical",
    ] as const),
    initiator_actor_admin_id: admin.id,
  } satisfies IShoppingMallEscalationQueue.ICreate;
  const escalationQueue: IShoppingMallEscalationQueue =
    await api.functional.shoppingMall.admin.escalationQueues.create(
      connection,
      {
        body: input,
      },
    );
  typia.assert(escalationQueue);

  // 3. Validate returned escalation record fields and linkage to admin
  TestValidator.equals(
    "escalation_type matches input",
    escalationQueue.escalation_type,
    input.escalation_type,
  );
  TestValidator.equals(
    "reason_detail matches input",
    escalationQueue.reason_detail,
    input.reason_detail,
  );
  TestValidator.equals(
    "status matches input",
    escalationQueue.status,
    input.status,
  );
  TestValidator.equals(
    "priority matches input",
    escalationQueue.priority,
    input.priority,
  );
  TestValidator.equals(
    "initiator_actor_admin_id matches admin id",
    escalationQueue.initiator_actor_admin_id,
    admin.id,
  );

  // Ensure required response fields exist (non-empty id, created_at, last_updated_at)
  TestValidator.predicate(
    "escalation id must be a UUID",
    typeof escalationQueue.id === "string" &&
      /^([0-9a-fA-F\-]){36}$/.test(escalationQueue.id!),
  );
  TestValidator.predicate(
    "created_at must be an ISO date-time string",
    typeof escalationQueue.created_at === "string" &&
      escalationQueue.created_at.length > 0,
  );
  TestValidator.predicate(
    "last_updated_at must be an ISO date-time string",
    typeof escalationQueue.last_updated_at === "string" &&
      escalationQueue.last_updated_at.length > 0,
  );

  // Ensure optional actor linkage fields not relevant are undefined
  TestValidator.equals(
    "initiator_actor_seller_id should be undefined for admin-initiated escalation",
    escalationQueue.initiator_actor_seller_id,
    undefined,
  );
  TestValidator.equals(
    "initiator_actor_customer_id should be undefined for admin-initiated escalation",
    escalationQueue.initiator_actor_customer_id,
    undefined,
  );
}

