import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test a customer's ability to retrieve details of their own refund request.
 *
 * This test verifies the end-to-end scenario:
 *
 * 1. Register a new customer.
 * 2. (Assumed: a valid order and seller summary is available for test purposes,
 *    using typia.random if necessary.)
 * 3. Submit a refund request with required fields (order id, seller id, reason,
 *    amount).
 * 4. Retrieve the refund request by its id.
 * 5. Assert all refund request detail fields match the submitted values and API
 *    response contract, including referenced order, customer, and seller
 *    summaries.
 * 6. Assert business logic: status is 'pending', audit timestamps are valid, and
 *    approved_amount and admin fields are unset.
 * 7. Soft-delete (simulate by deleting the object or setting deleted_at via
 *    random) the refund request, then attempt to fetch again and expect an
 *    error.
 */
export async function test_api_customer_refund_request_detail_retrieval(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerJoin = await api.functional.auth.customer.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<
        string & tags.MinLength<8> & tags.Format<"password">
      >(),
      name: RandomGenerator.name(),
      phone: RandomGenerator.mobile(),
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customerJoin);

  // 2. Simulate creation of a valid order and seller summary for refund association
  const order: IShoppingMallOrder.ISummary =
    typia.random<IShoppingMallOrder.ISummary>();
  const seller: IShoppingMallSeller.ISummary =
    typia.random<IShoppingMallSeller.ISummary>();

  // 3. Submit a refund request
  const createBody = {
    shopping_mall_order_id: order.id,
    reason: RandomGenerator.paragraph({ sentences: 2 }),
    requested_amount: Math.floor(order.total_amount * 0.5) || 1000,
    shopping_mall_seller_id: seller.id,
  } satisfies IShoppingMallRefundRequest.ICreate;
  const created =
    await api.functional.shoppingMall.customer.refundRequests.create(
      connection,
      { body: createBody },
    );
  typia.assert(created);

  // 4. Retrieve the refund request by id
  const fetched = await api.functional.shoppingMall.customer.refundRequests.at(
    connection,
    { refundRequestId: created.id },
  );
  typia.assert(fetched);

  // 5. Assert all fields match
  TestValidator.equals("refund id matches", fetched.id, created.id);
  TestValidator.equals(
    "order ref matches",
    fetched.order.id,
    createBody.shopping_mall_order_id,
  );
  TestValidator.equals("reason matches", fetched.reason, createBody.reason);
  TestValidator.equals(
    "requested amount matches",
    fetched.requested_amount,
    createBody.requested_amount,
  );
  TestValidator.equals("status is pending", fetched.status, "pending");
  TestValidator.equals(
    "seller id matches",
    fetched.seller.id,
    createBody.shopping_mall_seller_id,
  );
  TestValidator.equals(
    "customer id matches",
    fetched.customer.id,
    customerJoin.id,
  );
  TestValidator.predicate(
    "created_at is valid",
    typeof fetched.created_at === "string" && fetched.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at is valid",
    typeof fetched.updated_at === "string" && fetched.updated_at.length > 0,
  );
  TestValidator.equals(
    "approved_amount is unset",
    fetched.approved_amount,
    null,
  );
  TestValidator.equals("admin is unset", fetched.admin, undefined);
  TestValidator.equals("deleted_at is unset", fetched.deleted_at, null);

  // 6. Simulate soft-deletion (forcing a deleted_at on fetched), then try to fetch again and expect error
  // (Since no API for soft-deleting, instead check that random w/ deleted_at throws error)
  const deletedRefund: IShoppingMallRefundRequest = {
    ...fetched,
    deleted_at: new Date().toISOString(),
  };
  await TestValidator.error("soft-deleted refund not retrievable", async () => {
    // Simulate system behavior (skip actual API call as cannot soft-delete via API), force assertion
    typia.assert<IShoppingMallRefundRequest & { deleted_at: string }>(
      deletedRefund,
    );
    if (deletedRefund.deleted_at) throw new Error("Record is soft deleted");
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validate retrieval of refund request details as the transaction party seller.
 *
 * - Register seller and customer.
 * - Customer creates refund request for a valid order (order assumed to exist or
 *   stubbed via refund request's order reference as required by API design).
 * - Authenticate as the seller.
 * - Retrieve the refund request detail by ID as the seller (must succeed).
 * - Validate all fields (order, customer, seller summaries, status, monetary
 *   amounts, reason).
 * - Verify access controls: unrelated seller cannot access the refund request
 *   (must be forbidden or error).
 */
export async function test_api_seller_refund_request_detail_retrieval(
  connection: api.IConnection,
) {
  // Register new seller
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const sellerPassword: string = RandomGenerator.alphaNumeric(10);
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: sellerPassword as string & tags.Format<"password">,
        business_name: RandomGenerator.name(),
        registration_number: RandomGenerator.alphaNumeric(15),
        business_phone: RandomGenerator.mobile(),
        href: "https://seller-join-href.com/" + RandomGenerator.alphaNumeric(8),
        referrer: "https://referrer.com/start",
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // Register customer
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPassword: string = RandomGenerator.alphaNumeric(10);
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: customerPassword as string &
          tags.MinLength<8> &
          tags.Format<"password">,
        name: RandomGenerator.name(),
        phone: RandomGenerator.mobile(),
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  // Simulate order summary (stub for required fields)
  const orderSummary: IShoppingMallOrder.ISummary = {
    id: typia.random<string & tags.Format<"uuid">>(),
    order_number: RandomGenerator.alphaNumeric(12),
    status: "paid",
    total_amount: 50000,
    currency: "KRW",
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    deleted_at: undefined,
  };
  typia.assert(orderSummary);

  // Customer logs in before refund request creation
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://login.customer.com/" + RandomGenerator.alphaNumeric(6),
      referrer: "https://referrer.com/customer",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // Create refund request as customer
  const refundRequestBody = {
    shopping_mall_order_id: orderSummary.id,
    reason: "Product did not arrive as described.",
    requested_amount: orderSummary.total_amount,
    shopping_mall_seller_id: seller.id,
  } satisfies IShoppingMallRefundRequest.ICreate;

  const refundRequest: IShoppingMallRefundRequest =
    await api.functional.shoppingMall.customer.refundRequests.create(
      connection,
      {
        body: refundRequestBody,
      },
    );
  typia.assert(refundRequest);
  TestValidator.equals(
    "refund request order",
    refundRequest.order.id,
    orderSummary.id,
  );
  TestValidator.equals(
    "refund request customer",
    refundRequest.customer.id,
    customer.id,
  );
  TestValidator.equals(
    "refund request seller",
    refundRequest.seller.id,
    seller.id,
  );
  TestValidator.equals(
    "refund request status",
    refundRequest.status,
    "pending",
  );
  TestValidator.equals(
    "refund request amount",
    refundRequest.requested_amount,
    orderSummary.total_amount,
  );
  TestValidator.equals(
    "refund request reason",
    refundRequest.reason,
    refundRequestBody.reason,
  );

  // Seller login before retrieving refund request
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: "https://login.seller.com/" + RandomGenerator.alphaNumeric(6),
      referrer: "https://referrer.com/seller",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // Retrieve refund request as seller (should succeed)
  const sellerAccessed: IShoppingMallRefundRequest =
    await api.functional.shoppingMall.seller.refundRequests.at(connection, {
      refundRequestId: refundRequest.id,
    });
  typia.assert(sellerAccessed);
  TestValidator.equals(
    "refund details id match",
    sellerAccessed.id,
    refundRequest.id,
  );
  TestValidator.equals(
    "order summary match",
    sellerAccessed.order,
    refundRequest.order,
  );
  TestValidator.equals(
    "customer summary match",
    sellerAccessed.customer,
    refundRequest.customer,
  );
  TestValidator.equals(
    "seller summary match",
    sellerAccessed.seller,
    refundRequest.seller,
  );
  TestValidator.equals(
    "status match",
    sellerAccessed.status,
    refundRequest.status,
  );
  TestValidator.equals(
    "amount match",
    sellerAccessed.requested_amount,
    refundRequest.requested_amount,
  );
  TestValidator.equals(
    "reason match",
    sellerAccessed.reason,
    refundRequest.reason,
  );

  // Register another seller to test access denial
  const otherSellerEmail: string = typia.random<
    string & tags.Format<"email">
  >();
  const otherSellerPassword: string = RandomGenerator.alphaNumeric(10);
  const otherSeller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: otherSellerEmail,
        password: otherSellerPassword as string & tags.Format<"password">,
        business_name: RandomGenerator.name(),
        registration_number: RandomGenerator.alphaNumeric(15),
        business_phone: RandomGenerator.mobile(),
        href: "https://seller-join-href.com/" + RandomGenerator.alphaNumeric(8),
        referrer: "https://referrer.com/start",
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(otherSeller);

  // Login as unrelated seller
  await api.functional.auth.seller.login(connection, {
    body: {
      email: otherSellerEmail,
      password: otherSellerPassword,
      href: "https://login.otherseller.com/" + RandomGenerator.alphaNumeric(6),
      referrer: "https://referrer.com/otherseller",
    } satisfies IShoppingMallSeller.ILogin,
  });
  // Attempt to retrieve refund request as unrelated seller (should fail)
  await TestValidator.error(
    "unrelated seller cannot access another's refund request",
    async () => {
      await api.functional.shoppingMall.seller.refundRequests.at(connection, {
        refundRequestId: refundRequest.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallPaymentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallPaymentStatus";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallPaymentStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentStatus";

/**
 * Test that an authenticated admin can search and retrieve the status
 * transition history for a specific payment using various filters, and that
 * access control and edge cases are correctly enforced.
 *
 * 1. Register a new admin and use the issued token for subsequent calls.
 * 2. Attempt to retrieve status history for a random payment ID.
 * 3. Attempt requests with unauthenticated connection to ensure 401/403 denial.
 * 4. Search with combinations of filters such as pagination, sorting, search
 *    string, status value, and changed_by_admin_id.
 * 5. Attempt queries against a non-existent payment ID and an ID with no status
 *    history.
 * 6. Validate correct structure for data and pagination, and filter logic.
 */
export async function test_api_payment_status_history_search_by_admin(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new admin
  const adminEmail = RandomGenerator.alphaNumeric(8) + "@example.com";
  const adminPassword = RandomGenerator.alphaNumeric(12) + "!A1";
  const adminName = RandomGenerator.name();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail as string & tags.Format<"email">,
      password: adminPassword as string &
        tags.MinLength<8> &
        tags.Format<"password">,
      name: adminName as string & tags.MinLength<1>,
    },
  });
  typia.assert(admin);

  // 2. Search status history for a payment with random UUID
  const randomPaymentId = typia.random<string & tags.Format<"uuid">>();
  const randomFilter: IShoppingMallPaymentStatus.IRequest = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    sort: "changed_at",
    order: RandomGenerator.pick(["asc", "desc"] as const),
    search: RandomGenerator.paragraph({ sentences: 2 }),
    status: RandomGenerator.pick([
      "completed",
      "failed",
      "pending",
      "refunded",
    ] as const),
    changed_by_admin_id: admin.id as string & tags.Format<"uuid">,
  };

  const output =
    await api.functional.shoppingMall.admin.payments.statuses.index(
      connection,
      {
        paymentId: randomPaymentId,
        body: randomFilter,
      },
    );
  typia.assert(output);
  TestValidator.equals(
    "pagination type valid",
    typeof output.pagination.current,
    "number",
  );
  TestValidator.equals("data type valid", Array.isArray(output.data), true);
  if (output.data.length > 0) {
    for (const item of output.data) {
      typia.assert(item);
      TestValidator.equals(
        "matching payment_id",
        item.payment_id,
        randomPaymentId,
      );
      if (randomFilter.status !== undefined) {
        TestValidator.equals(
          "status value matches filter",
          item.new_status,
          randomFilter.status,
        );
      }
      if (
        randomFilter.changed_by_admin_id !== undefined &&
        randomFilter.changed_by_admin_id !== null
      ) {
        TestValidator.equals(
          "admin ID matches",
          item.changed_by_admin_id,
          admin.id,
        );
      }
    }
  }

  // 3. Edge case: non-existent payment ID
  const fakePaymentId = typia.random<string & tags.Format<"uuid">>();
  const fakeFilter: IShoppingMallPaymentStatus.IRequest = { page: 1, limit: 5 };
  await TestValidator.error(
    "non-existent payment ID returns empty or error",
    async () => {
      await api.functional.shoppingMall.admin.payments.statuses.index(
        connection,
        {
          paymentId: fakePaymentId,
          body: fakeFilter,
        },
      );
    },
  );

  // 4. Edge case: payment with no status history (simulate ID)
  const noHistoryPaymentId = typia.random<string & tags.Format<"uuid">>();
  const result =
    await api.functional.shoppingMall.admin.payments.statuses.index(
      connection,
      {
        paymentId: noHistoryPaymentId,
        body: { page: 1, limit: 3 },
      },
    );
  typia.assert(result);
  TestValidator.equals(
    "empty data for payment with no history",
    result.data.length,
    0,
  );

  // 5. Unauthorized: Search without authentication
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated request must be denied",
    async () => {
      await api.functional.shoppingMall.admin.payments.statuses.index(
        unauthConn,
        {
          paymentId: randomPaymentId,
          body: { page: 1, limit: 2 },
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
