/**
 * Test that an authenticated administrator can fetch paginated and filtered
 * shipment records via the advanced search endpoint.
 *
 * 1. Register a new admin account and obtain authentication (JWT) tokens.
 * 2. As an authenticated admin, perform shipment search against
 *    /shoppingMall/admin/shipments:
 *
 *    - Provide variety of legitimate filter, sort, and pagination criteria,
 *         including status, time ranges, carrier, etc.
 *    - Cover business-meaningful search cases and check admin has permission to see
 *         filtered results.
 *    - For positive case: Validate returned page and shipment list matches schema
 *         and expectations.
 *    - For negative (invalid filters): Assert clear error feedback for bad
 *         filter/sort scenarios.
 *    - Confirm that sorting and pagination are correctly applied in result.
 *    - Ensure only permitted records are returned (business permissions respected).
 */
export async function test_api_shipment_search_and_filter_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin account registration + authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12) + "A!12";
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: RandomGenerator.name(),
      },
    });
  typia.assert(admin);

  // 2. Shipment search with advanced filters and sorting (happy path)
  const filterBody = {
    status: RandomGenerator.pick([
      "pending",
      "ready",
      "picked_up",
      "in_transit",
      "delivered",
      "cancelled",
      "returned",
    ] as const),
    page: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
    limit: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
    >(),
    sort_by: RandomGenerator.pick([
      "created_at",
      "status",
      "delivery_at",
    ] as const),
    sort_order: RandomGenerator.pick(["asc", "desc"] as const),
    carrier_tracking_code: RandomGenerator.alphaNumeric(10),
    created_from: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(),
    created_to: new Date().toISOString(),
    delivery_from: new Date(
      Date.now() - 14 * 24 * 60 * 60 * 1000,
    ).toISOString(),
    delivery_to: new Date().toISOString(),
    provider_response_code: RandomGenerator.alphaNumeric(8),
  } satisfies IShoppingMallShipment.IRequest;

  const result: IPageIShoppingMallShipment.ISummary =
    await api.functional.shoppingMall.admin.shipments.index(connection, {
      body: filterBody,
    });
  typia.assert(result);
  TestValidator.predicate(
    "pagination must be valid page info",
    typeof result.pagination.current === "number" &&
      result.pagination.current >= 0 &&
      result.pagination.current <= result.pagination.pages,
  );
  TestValidator.predicate(
    "shipment summary data array exists",
    Array.isArray(result.data),
  );
  if (result.data.length > 0) {
    for (const summary of result.data) {
      typia.assert(summary);
      if (filterBody.status) {
        TestValidator.equals(
          "shipment status matches filter",
          summary.status,
          filterBody.status,
        );
      }
    }
  }

  // 3. Invalid filter: date range where 'from' is after 'to', should error
  await TestValidator.error(
    "created_from after created_to triggers error",
    async () => {
      await api.functional.shoppingMall.admin.shipments.index(connection, {
        body: {
          ...filterBody,
          created_from: new Date(
            Date.now() + 24 * 60 * 60 * 1000,
          ).toISOString(),
          created_to: new Date().toISOString(),
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallExternalPaymentProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallExternalPaymentProvider";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import type { IShoppingMallPaymentRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentRefund";

/**
 * Validates the admin-initiated payment refund creation process, including
 * setup, refund business rules, and audit linkages.
 *
 * This scenario tests:
 *
 * - Admin authentication and registration for privileged payment operations
 * - Creation of a payment record for a random customer via the admin API
 * - Creating a refund with required amount, status, and reason for the payment
 * - Verifying business constraints on refund creation (amount cannot exceed
 *   payment)
 * - Ensuring audit trail by fully linking the refund to both payment and admin
 *   actor
 * - Validation of all required fields and business status transitions
 *
 * Steps:
 *
 * 1. Register and authenticate as admin
 * 2. Synthesize a payment entity (reference customer/provider)
 * 3. Create a refund (required amount, reason, status) for the payment
 * 4. Assert refund amount <= payment, and all linkage/audit fields present,
 *    referential integrity maintained
 */
export async function test_api_payment_refund_creation_by_admin(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12) + "!#A";
  const adminName = RandomGenerator.name();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        name: adminName,
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);
  TestValidator.equals("admin email matches input", admin.email, adminEmail);
  TestValidator.equals("admin name matches input", admin.name, adminName);
  TestValidator.predicate("admin status is not empty", admin.status.length > 0);
  TestValidator.predicate(
    "admin token is present",
    typeof admin.token.access === "string" && admin.token.access.length > 0,
  );

  // 2. Synthesize payment entity (simulate customer/provider references)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const providerId = typia.random<string & tags.Format<"uuid">>();
  const paymentAmount = 50000;
  const paymentCurrency = "KRW";
  const paymentMethod = RandomGenerator.pick([
    "card",
    "e-wallet",
    "bank_transfer",
  ] as const);
  const externalPaymentId = RandomGenerator.alphaNumeric(16);
  const transactionToken = RandomGenerator.alphaNumeric(32);
  const requestedAt = new Date().toISOString();
  const paymentCreateBody = {
    customer_id: customerId,
    provider_id: providerId,
    amount: paymentAmount,
    currency: paymentCurrency,
    method_type: paymentMethod,
    status: "initiated",
    external_payment_id: externalPaymentId,
    transaction_token: transactionToken,
    requested_at: requestedAt,
  } satisfies IShoppingMallPayment.ICreate;

  const payment: IShoppingMallPayment =
    await api.functional.shoppingMall.admin.payments.create(connection, {
      body: paymentCreateBody,
    });
  typia.assert(payment);
  TestValidator.equals("payment.amount matches", payment.amount, paymentAmount);
  TestValidator.equals(
    "payment.currency matches",
    payment.currency,
    paymentCurrency,
  );
  TestValidator.equals(
    'payment.status is "initiated"',
    payment.status,
    "initiated",
  );
  TestValidator.equals(
    "payment.external_payment_id matches",
    payment.external_payment_id,
    externalPaymentId,
  );

  // 3. Create refund for that payment
  const refundAmount = payment.amount; // for positive scenario, use full amount
  const refundCurrency = payment.currency;
  const refundReason = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 5,
    wordMax: 10,
  });
  const refundStatus = "requested";
  const refundExternalId = RandomGenerator.alphaNumeric(18);
  const refundBody = {
    amount: refundAmount,
    currency: refundCurrency,
    reason: refundReason,
    status: refundStatus,
    external_refund_id: refundExternalId,
  } satisfies IShoppingMallPaymentRefund.ICreate;

  const refund: IShoppingMallPaymentRefund =
    await api.functional.shoppingMall.admin.payments.refunds.create(
      connection,
      {
        paymentId: payment.id,
        body: refundBody,
      },
    );
  typia.assert(refund);
  TestValidator.equals(
    "refund.payment.id == payment.id",
    refund.payment.id,
    payment.id,
  );
  TestValidator.equals("refund.amount matches", refund.amount, refundAmount);
  TestValidator.equals(
    "refund.currency matches",
    refund.currency,
    refundCurrency,
  );
  TestValidator.equals(
    'refund.status is "requested"',
    refund.status,
    refundStatus,
  );
  TestValidator.equals("refund.reason matches", refund.reason, refundReason);
  TestValidator.predicate(
    "refund.processed_by_admin is present",
    refund.processed_by_admin !== null &&
      refund.processed_by_admin !== undefined,
  );
  TestValidator.equals(
    "refund.processed_by_admin.id == admin.id",
    refund.processed_by_admin!.id,
    admin.id,
  );
  TestValidator.predicate(
    "refund external_refund_id valid",
    refund.external_refund_id.length > 0,
  );
  TestValidator.predicate(
    "refund.requested_at is ISO string",
    typeof refund.requested_at === "string" && refund.requested_at.length > 0,
  );
  TestValidator.predicate(
    "refund.created_at is ISO string",
    typeof refund.created_at === "string" && refund.created_at.length > 0,
  );

  // 4. Negative test: refund amount over original payment should fail
  await TestValidator.error(
    "refund exceeding original payment amount should fail",
    async () => {
      await api.functional.shoppingMall.admin.payments.refunds.create(
        connection,
        {
          paymentId: payment.id,
          body: {
            amount: payment.amount + 1,
            currency: payment.currency,
            reason: "Test exceeding original payment",
            status: refundStatus,
            external_refund_id: RandomGenerator.alphaNumeric(18),
          } satisfies IShoppingMallPaymentRefund.ICreate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallExternalPaymentProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallExternalPaymentProvider";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import type { IShoppingMallPaymentRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentRefund";

/**
 * Validate rejection of refund requests that exceed the original payment
 * amount.
 *
 * 1. Admin registers to obtain authentication.
 * 2. Admin creates a valid payment with a generated amount.
 * 3. Admin attempts to request a refund for that payment, with an amount greater
 *    than original payment amount.
 * 4. Assert that the refund operation is rejected with an error (business rule
 *    enforced).
 * 5. Optionally, confirm that no refund record was created (if a fetch-list API
 *    existed for refunds, but not required here).
 */
export async function test_api_payment_refund_amount_exceeds_original(
  connection: api.IConnection,
) {
  // 1. Register admin
  const adminEmail = RandomGenerator.alphaNumeric(10) + "@test.com";
  const adminPassword = RandomGenerator.alphaNumeric(12) + "1!A";
  const adminName = RandomGenerator.name();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail as string & tags.Format<"email">,
      password: adminPassword as string &
        tags.MinLength<8> &
        tags.Format<"password">,
      name: adminName as string & tags.MinLength<1>,
    },
  });
  typia.assert(admin);

  // 2. Create a payment
  // Simulate minimal payment prerequisites
  const paymentBody = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    provider_id: typia.random<string & tags.Format<"uuid">>(),
    amount: 1000,
    currency: "KRW",
    method_type: "card",
    status: "completed",
    external_payment_id: RandomGenerator.alphaNumeric(12),
    transaction_token: RandomGenerator.alphaNumeric(16),
    requested_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const payment = await api.functional.shoppingMall.admin.payments.create(
    connection,
    {
      body: paymentBody,
    },
  );
  typia.assert(payment);

  // 3. Attempt refund with excessive amount
  const excessiveAmount = payment.amount + 1;
  const refundBody = {
    amount: excessiveAmount,
    currency: payment.currency,
    reason: "Test over-refund prevention",
    status: "requested",
    external_refund_id: RandomGenerator.alphaNumeric(16),
  };
  await TestValidator.error(
    "should reject refund amount exceeding original payment",
    async () => {
      await api.functional.shoppingMall.admin.payments.refunds.create(
        connection,
        {
          paymentId: payment.id,
          body: refundBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallExternalPaymentProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallExternalPaymentProvider";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import type { IShoppingMallPaymentRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentRefund";

/**
 * Verify that creating a refund for a payment requires valid administrator
 * authentication.
 *
 * This test ensures the /shoppingMall/admin/payments/{paymentId}/refunds
 * endpoint denies refund creation requests when no admin is authenticated. The
 * test will:
 *
 * 1. Register a new admin
 * 2. Create a payment using the admin account
 * 3. Attempt to create a refund for the payment using an unauthenticated
 *    (tokenless) connection
 * 4. Assert that the refund creation fails with an error (due to missing or
 *    invalid authorization)
 *
 * Expected result: The refund creation operation should be denied with an
 * authorization error, and no refund is created.
 */
export async function test_api_payment_refund_requires_valid_admin_auth(
  connection: api.IConnection,
) {
  // 1. Register an admin to execute privileged operations
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      name: RandomGenerator.name(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // 2. Use admin context to provision a payment (payment requires admin)
  const paymentPayload = {
    customer_id: typia.random<string & tags.Format<"uuid">>(),
    provider_id: typia.random<string & tags.Format<"uuid">>(),
    amount: 10000,
    currency: "KRW",
    method_type: "card",
    status: "initiated",
    external_payment_id: RandomGenerator.alphaNumeric(16),
    transaction_token: RandomGenerator.alphaNumeric(24),
    requested_at: new Date().toISOString(),
  } satisfies IShoppingMallPayment.ICreate;

  const payment = await api.functional.shoppingMall.admin.payments.create(
    connection,
    {
      body: paymentPayload,
    },
  );
  typia.assert(payment);

  // 3. Attempt refund WITHOUT admin authorization
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  const refundPayload = {
    amount: payment.amount,
    currency: payment.currency,
    reason: RandomGenerator.paragraph({ sentences: 3 }),
    status: "requested",
    external_refund_id: RandomGenerator.alphaNumeric(14),
  } satisfies IShoppingMallPaymentRefund.ICreate;

  await TestValidator.error(
    "refund creation should fail without admin authentication",
    async () => {
      await api.functional.shoppingMall.admin.payments.refunds.create(
        unauthConn,
        {
          paymentId: payment.id,
          body: refundPayload,
        },
      );
    },
  );
}

