    ...(created_from !== undefined || created_to !== undefined
      ? {
          created_at: {
            ...(created_from !== undefined ? { gte: created_from } : {}),
            ...(created_to !== undefined ? { lte: created_to } : {}),
          },
        }
      : {}),
    ...(updated_from !== undefined || updated_to !== undefined
      ? {
          updated_at: {
