        ...(end_at !== undefined ? { lte: end_at } : {}),
      },
    };
  }

  // Build search filter
  let searchFilter = undefined;
  if (search !== undefined && search !== "") {
    searchFilter = {
      OR: [{ reason: { contains: search } }],
    };
  }

  // Merge all filters
  const filters = {
    shopping_mall_review_id: props.reviewId,
    ...(status !== undefined ? { status } : {}),
