  ]);

  const data = events.map((e) => ({
    id: e.id,
    shipment_id: e.shipment_id,
    event_time: toISOStringSafe(e.event_time),
    location:
      e.location === null || typeof e.location === "undefined"
        ? undefined
        : e.location,
    latitude:
      e.latitude === null || typeof e.latitude === "undefined"
        ? undefined
        : e.latitude,
    longitude:
