import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingMallSellerSellersSellerIdSessions(props: {
  seller: SellerPayload;
  sellerId: string & tags.Format<"uuid">;
  body: IShoppingMallSellerSession.IRequest;
}): Promise<IPageIShoppingMallSellerSession.ISummary> {
  // Restrict to the authenticated seller's own account
  if (props.seller.id !== props.sellerId) {
    throw new HttpException(
      "Forbidden: You can only list your own sessions.",
      403,
    );
  }

  const pageNumber = props.body.page !== undefined ? props.body.page : 1;
  const limitValue =
    props.body.limit !== undefined ? Math.min(props.body.limit, 100) : 20;
  const skipValue = (pageNumber - 1) * limitValue;

  const whereCondition = {
    shopping_mall_seller_id: props.sellerId,
    ...(props.body.start_at
      ? { created_at: { gte: props.body.start_at } }
      : {}),
    ...(props.body.end_at ? { created_at: { lt: props.body.end_at } } : {}),
    ...(props.body.ip
      ? {
          ip: {
            contains: props.body.ip,
            mode: "insensitive" as Prisma.QueryMode,
          },
        }
      : {}),
    ...(typeof props.body.expired === "boolean"
      ? props.body.expired
        ? { NOT: { expired_at: null } }
        : { expired_at: null }
      : {}),
  };

  const [sessions, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_seller_sessions.findMany({
      where: whereCondition,
      orderBy: { created_at: "desc" },
      skip: skipValue,
      take: limitValue,
    }),
    MyGlobal.prisma.shopping_mall_seller_sessions.count({
      where: whereCondition,
    }),
  ]);

  return {
    pagination: {
      current: pageNumber,
      limit: limitValue,
      records: total,
      pages: Math.ceil(total / limitValue),
    },
    data: sessions.map((session) => ({
      id: session.id,
      shopping_mall_seller_id: session.shopping_mall_seller_id,
      ip: session.ip,
      href: session.href,
      referrer: session.referrer,
      created_at: toISOStringSafe(session.created_at),
      expired_at:
        session.expired_at === null || session.expired_at === undefined
          ? undefined
          : toISOStringSafe(session.expired_at),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthCustomerJoin(props: {
  body: IShoppingMallCustomer.ICreate;
}): Promise<IShoppingMallCustomer.IAuthorized> {
  // Step 1: Validate unique email
  const existing = await MyGlobal.prisma.shopping_mall_customers.findFirst({
    where: { email: props.body.email },
  });
  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  // Step 2: Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // Generate IDs and timestamps
  const now = toISOStringSafe(new Date());
  const customerId = v4();
  const sessionId = v4();
  // 1h access token expiry, 7d refresh window
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  // Step 3 & 4: Transactional creation
  const [customer, session] = await MyGlobal.prisma.$transaction([
    MyGlobal.prisma.shopping_mall_customers.create({
      data: {
        id: customerId,
        email: props.body.email,
        password_hash: hashedPassword,
        name: props.body.name,
        phone: props.body.phone,
        is_email_verified: false,
        created_at: now,
        updated_at: now,
      },
    }),
    MyGlobal.prisma.shopping_mall_customer_sessions.create({
      data: {
        id: sessionId,
        shopping_mall_customer_id: customerId,
        ip: "", // Not provided, empty string
        href: "", // Not provided, empty string
        referrer: "", // Not provided, empty string
        created_at: now,
        expired_at: accessExpires,
      },
    }),
  ]);

  // Step 5: JWT tokens
  const token = {
    access: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };

  // Step 6: Response
  return {
    id: customer.id,
    email: customer.email,
    name: customer.name,
    phone: customer.phone,
    is_email_verified: customer.is_email_verified,
    created_at: toISOStringSafe(customer.created_at),
    updated_at: toISOStringSafe(customer.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthCustomerRefresh(props: {
  body: IShoppingMallCustomer.IRefresh;
}): Promise<IShoppingMallCustomer.IAuthorized> {
  let decoded: { id: string; session_id: string; type: string };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: string };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (decoded.type !== "customer") {
    throw new HttpException("Token does not match customer type", 403);
  }
  const session =
    await MyGlobal.prisma.shopping_mall_customer_sessions.findUnique({
      where: { id: decoded.session_id },
    });
  if (!session || session.shopping_mall_customer_id !== decoded.id) {
    throw new HttpException(
      "Session does not exist or does not match customer",
      401,
    );
  }
  if (
    session.expired_at !== null &&
    new Date(session.expired_at).getTime() < Date.now()
  ) {
    throw new HttpException("Session expired", 401);
  }
  const customer = await MyGlobal.prisma.shopping_mall_customers.findUnique({
    where: { id: decoded.id },
  });
  if (!customer) {
    throw new HttpException("Customer not found", 404);
  }

  const now = Date.now();
  const accessExpireIso = toISOStringSafe(new Date(now + 60 * 60 * 1000));
  const refreshExpireIso = toISOStringSafe(
    new Date(now + 7 * 24 * 60 * 60 * 1000),
  );
  const token = {
    access: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: session.id,
        created_at: toISOStringSafe(new Date(now)),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date(now)),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpireIso,
    refreshable_until: refreshExpireIso,
  };

  await MyGlobal.prisma.shopping_mall_customer_sessions.update({
    where: { id: session.id },
    data: { expired_at: refreshExpireIso },
  });

  return {
    id: customer.id,
    email: customer.email,
    name: customer.name,
    phone: customer.phone,
    is_email_verified: customer.is_email_verified,
    created_at: toISOStringSafe(customer.created_at),
    updated_at: toISOStringSafe(customer.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
