import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postShoppingMallSellerProductsProductIdSkus(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  body: IShoppingMallProductSku.ICreate;
}): Promise<IShoppingMallProductSku> {
  // Step 1: Parent product lookup and authorization
  const product = await MyGlobal.prisma.shopping_mall_products.findFirst({
    where: {
      id: props.productId,
      shopping_mall_seller_id: props.seller.id,
      deleted_at: null,
    },
  });
  if (!product) {
    throw new HttpException("Product not found or not owned by seller", 404);
  }

  // Step 2: SKU code uniqueness
  const existingSku =
    await MyGlobal.prisma.shopping_mall_product_skus.findFirst({
      where: {
        shopping_mall_product_id: props.productId,
        sku_code: props.body.sku_code,
        deleted_at: null,
      },
    });
  if (existingSku) {
    throw new HttpException("Duplicate sku_code for this product.", 409);
  }

  // Step 3: Business validations
  const allowedStatuses = [
    "draft",
    "active",
    "out_of_stock",
    "archived",
    "blocked",
    "pending_approval",
  ];
  if (typeof props.body.price !== "number" || props.body.price < 0) {
    throw new HttpException("Price must be a non-negative number.", 400);
  }
  if (typeof props.body.stock !== "number" || props.body.stock < 0) {
    throw new HttpException("Stock must be a non-negative integer.", 400);
  }
  if (!allowedStatuses.includes(props.body.status)) {
    throw new HttpException("Invalid SKU status.", 400);
  }

  // Step 4: SKU creation
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_product_skus.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_product_id: props.productId,
      sku_code: props.body.sku_code,
      price: props.body.price,
      stock: props.body.stock,
      status: props.body.status,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // Step 5: Build minimal product summary for response
  const productSummary = {
    id: product.id,
    title: product.title,
    default_price: product.default_price,
    business_status: product.business_status,
    seller: {
      id: props.seller.id,
      business_name: (await MyGlobal.prisma.shopping_mall_sellers.findUnique({
        where: { id: props.seller.id },
        select: { business_name: true },
      }))!.business_name,
    },
    categories: [],
    created_at: toISOStringSafe(product.created_at),
  };

  return {
    id: created.id,
    product: productSummary,
    sku_code: created.sku_code,
    price: created.price,
    stock: created.stock,
    status: created.status,
    created_at: toISOStringSafe(created.created_at) as string &
      tags.Format<"date-time">,
    updated_at: toISOStringSafe(created.updated_at) as string &
      tags.Format<"date-time">,
    deleted_at:
      created.deleted_at === null
        ? undefined
        : (toISOStringSafe(created.deleted_at) as string &
            tags.Format<"date-time">),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postShoppingMallSellerProductsProductIdSkusSkuIdImages(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  skuId: string & tags.Format<"uuid">;
  body: IShoppingMallProductImage.ICreate;
}): Promise<IShoppingMallProductImage> {
  // Step 1: Validate SKU
  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findFirst({
    where: {
      id: props.skuId,
      shopping_mall_product_id: props.productId,
      deleted_at: null,
    },
  });
  if (!sku) {
    throw new HttpException(
      "SKU not found, not associated with product, or is deleted.",
      404,
    );
  }

  // Step 2: Validate Product under Seller's Ownership
  const product = await MyGlobal.prisma.shopping_mall_products.findFirst({
    where: {
      id: props.productId,
      shopping_mall_seller_id: props.seller.id,
      deleted_at: null,
    },
  });
  if (!product) {
    throw new HttpException(
      "Product is not found, not owned by seller, or is deleted.",
      403,
    );
  }

  // Step 3: Enforce position uniqueness for SKU images
  const conflict = await MyGlobal.prisma.shopping_mall_product_images.findFirst(
    {
      where: {
        shopping_mall_product_sku_id: props.skuId,
        position: props.body.position,
        deleted_at: null,
      },
    },
  );
  if (conflict) {
    throw new HttpException("Duplicate image position for this SKU.", 409);
  }

  // Step 4: Enforce SKU attachment only (never both product and SKU)
  if (
    (props.body.shopping_mall_product_id &&
      props.body.shopping_mall_product_id !== null) ||
    (props.body.shopping_mall_product_sku_id &&
      props.body.shopping_mall_product_sku_id !== props.skuId)
  ) {
    throw new HttpException(
      "Image must attach only to the precise SKU, not both product and SKU.",
      400,
    );
  }

  // Step 5: Create image record
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_product_images.create({
    data: {
      id: v4(),
      shopping_mall_product_id: null,
      shopping_mall_product_sku_id: props.skuId,
      cdn_uri: props.body.cdn_uri,
      alt_text: props.body.alt_text ?? null,
      position: props.body.position,
      label: props.body.label ?? null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  return {
    id: created.id,
    shopping_mall_product_id: undefined,
    shopping_mall_product_sku_id:
      created.shopping_mall_product_sku_id ?? undefined,
    cdn_uri: created.cdn_uri,
    alt_text: created.alt_text ?? undefined,
    position: created.position,
    label: created.label ?? undefined,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at:
      created.deleted_at !== null && created.deleted_at !== undefined
        ? toISOStringSafe(created.deleted_at)
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallShipmentTrackingHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipmentTrackingHistory";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postShoppingMallSellerShipmentsShipmentIdTrackingHistories(props: {
  seller: SellerPayload;
  shipmentId: string & tags.Format<"uuid">;
  body: IShoppingMallShipmentTrackingHistory.ICreate;
}): Promise<IShoppingMallShipmentTrackingHistory> {
  // Step 1: Verify the parent shipment exists and is owned by the seller
  const shipment = await MyGlobal.prisma.shopping_mall_shipments.findUnique({
    where: { id: props.shipmentId },
    select: { id: true, created_by_seller_id: true, cancelled_at: true },
  });
  if (!shipment) throw new HttpException("Shipment not found.", 404);
  if (shipment.created_by_seller_id !== props.seller.id)
    throw new HttpException("Forbidden: You do not own this shipment.", 403);
  if (shipment.cancelled_at !== null)
    throw new HttpException(
      "Cannot append tracking events to a cancelled shipment.",
      400,
    );

  // Step 2: Insert the new tracking history event
  const now = toISOStringSafe(new Date());
  const created =
    await MyGlobal.prisma.shopping_mall_shipment_tracking_histories.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        shipment_id: props.shipmentId,
        event_time: props.body.event_time,
        location: props.body.location ?? null,
        latitude: props.body.latitude ?? null,
        longitude: props.body.longitude ?? null,
        event_code: props.body.event_code ?? null,
        status: props.body.status,
        tracking_message: props.body.tracking_message,
        created_at: now,
      },
    });

  return {
    id: created.id,
    shipment_id: created.shipment_id,
    event_time: toISOStringSafe(created.event_time),
    location: created.location ?? undefined,
    latitude: created.latitude ?? undefined,
    longitude: created.longitude ?? undefined,
    event_code: created.event_code ?? undefined,
    status: created.status,
    tracking_message: created.tracking_message,
    created_at: toISOStringSafe(created.created_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallExternalPaymentProvider } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallExternalPaymentProvider";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminPaymentsPaymentId(props: {
  admin: AdminPayload;
  paymentId: string & tags.Format<"uuid">;
  body: IShoppingMallPayment.IUpdate;
}): Promise<IShoppingMallPayment> {
  const payment = await MyGlobal.prisma.shopping_mall_payments.findUnique({
    where: { id: props.paymentId },
  });

  if (!payment) {
    throw new HttpException("Payment record not found.", 404);
  }

  // Check for any forbidden field updates
  if (
    "amount" in props.body ||
    "currency" in props.body ||
    "transaction_token" in props.body ||
    "external_payment_id" in props.body ||
    "id" in props.body ||
    "customer_id" in props.body ||
    "provider_id" in props.body ||
    "method_type" in props.body ||
    "requested_at" in props.body ||
    "created_at" in props.body
  ) {
    throw new HttpException("Attempt to update immutable fields.", 400);
  }

  // Allowed status transitions (example logic)
  // (Ideally, this would come from a config, for now basic validation)
  if (props.body.status !== undefined) {
    const allowedTransitions: Record<string, string[]> = {
      initiated: [
        "pending",
        "authorized",
        "rejected",
        "completed",
        "refunded",
        "failed",
      ],
      pending: ["authorized", "rejected", "completed", "refunded", "failed"],
      authorized: ["completed", "refunded", "failed"],
      rejected: [],
      completed: ["refunded"],
      refunded: [],
      failed: [],
    };
    const currentStatus = payment.status;
    const nextStatus = props.body.status;
    if (!allowedTransitions[currentStatus]?.includes(nextStatus)) {
      throw new HttpException("Invalid status transition.", 400);
    }
  }

  const updateInput: Record<string, unknown> = {
    ...(props.body.status !== undefined && { status: props.body.status }),
    ...(props.body.processed_at !== undefined && {
      processed_at:
        props.body.processed_at === null ? null : props.body.processed_at,
    }),
    ...(props.body.deleted_at !== undefined && {
      deleted_at: props.body.deleted_at === null ? null : props.body.deleted_at,
    }),
    updated_at: toISOStringSafe(new Date()),
  };

  await MyGlobal.prisma.shopping_mall_payments.update({
    where: { id: props.paymentId },
    data: updateInput,
  });

  const updated = await MyGlobal.prisma.shopping_mall_payments.findUnique({
    where: { id: props.paymentId },
  });
  if (!updated) {
    throw new HttpException("Payment record disappeared after update.", 500);
  }

  const customer = await MyGlobal.prisma.shopping_mall_customers.findUnique({
    where: { id: updated.customer_id },
  });
  if (!customer) {
    throw new HttpException("Customer record not found.", 404);
  }
  const provider =
    await MyGlobal.prisma.shopping_mall_external_payment_providers.findUnique({
      where: { id: updated.provider_id },
    });
  if (!provider) {
    throw new HttpException("Provider record not found.", 404);
  }

  return {
    id: updated.id,
    customer: {
      id: customer.id,
      name: customer.name,
    },
    provider: {
      id: provider.id,
      name: provider.provider_name,
      provider_code: provider.provider_code,
      status: provider.status,
      description: provider.description,
      created_at: toISOStringSafe(provider.created_at),
      updated_at: toISOStringSafe(provider.updated_at),
      deleted_at:
        provider.deleted_at === null
          ? null
          : toISOStringSafe(provider.deleted_at),
    },
    amount: updated.amount,
    currency: updated.currency,
    method_type: updated.method_type,
    status: updated.status,
    external_payment_id: updated.external_payment_id,
    transaction_token: updated.transaction_token,
    requested_at: toISOStringSafe(updated.requested_at),
    processed_at:
      updated.processed_at === null
        ? null
        : toISOStringSafe(updated.processed_at),
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at:
      updated.deleted_at === null ? null : toISOStringSafe(updated.deleted_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSellerVerification } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerVerification";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminSellersSellerIdVerificationsVerificationId(props: {
  admin: AdminPayload;
  sellerId: string & tags.Format<"uuid">;
  verificationId: string & tags.Format<"uuid">;
  body: IShoppingMallSellerVerification.IUpdate;
}): Promise<IShoppingMallSellerVerification> {
  // Step 1: Check seller exists
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: props.sellerId },
  });
  if (!seller) {
    throw new HttpException("Seller not found", 404);
  }
  // Step 2: Find the verification and check if associated with the seller
  const verification =
    await MyGlobal.prisma.shopping_mall_seller_verifications.findUnique({
      where: { id: props.verificationId },
    });
  if (
    !verification ||
    verification.shopping_mall_seller_id !== props.sellerId
  ) {
    throw new HttpException(
      "Verification record not found for this seller",
      404,
    );
  }
  // Step 3: If reviewer_admin_id provided and not null, validate that admin exists
  let reviewerAdminSummary: IShoppingMallAdmin.ISummary | null | undefined =
    undefined;
  if (
    props.body.reviewer_admin_id !== undefined &&
    props.body.reviewer_admin_id !== null
  ) {
    const reviewerAdmin = await MyGlobal.prisma.shopping_mall_admins.findUnique(
      {
        where: { id: props.body.reviewer_admin_id },
      },
    );
    if (!reviewerAdmin) {
      throw new HttpException("Reviewer admin not found", 400);
    }
    reviewerAdminSummary = {
      id: reviewerAdmin.id,
      name: reviewerAdmin.name,
      email: reviewerAdmin.email,
    };
  } else if (props.body.reviewer_admin_id === null) {
    reviewerAdminSummary = null;
  }
  // Step 4: Update verification record
  const updated =
    await MyGlobal.prisma.shopping_mall_seller_verifications.update({
      where: { id: props.verificationId },
      data: {
        status: props.body.status ?? verification.status,
        compliance_documents:
          props.body.compliance_documents !== undefined
            ? props.body.compliance_documents
            : verification.compliance_documents,
        reason:
          props.body.reason !== undefined
            ? props.body.reason
            : verification.reason,
        reviewed_at:
          props.body.reviewed_at !== undefined
            ? props.body.reviewed_at
            : verification.reviewed_at,
        reviewer_admin_id:
          props.body.reviewer_admin_id !== undefined
            ? props.body.reviewer_admin_id
            : verification.reviewer_admin_id,
      },
    });
  // Step 5: Compose seller summary
  const sellerSummary = {
    id: seller.id,
    business_name: seller.business_name,
  };
  // Step 6: Compose and return API DTO
  return {
    id: updated.id,
    seller: sellerSummary,
    reviewer_admin:
      reviewerAdminSummary ??
      (updated.reviewer_admin_id != null
        ? await (async () => {
            const admin = await MyGlobal.prisma.shopping_mall_admins.findUnique(
              {
                where: { id: updated.reviewer_admin_id ?? undefined },
              },
            );
            return admin
              ? { id: admin.id, name: admin.name, email: admin.email }
              : null;
          })()
        : undefined),
    status: updated.status,
    compliance_documents:
      updated.compliance_documents === null
        ? null
        : (updated.compliance_documents ?? undefined),
    reason: updated.reason === null ? null : (updated.reason ?? undefined),
    reviewed_at:
      updated.reviewed_at === null || updated.reviewed_at === undefined
        ? updated.reviewed_at
        : toISOStringSafe(updated.reviewed_at),
    created_at: toISOStringSafe(updated.created_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
