import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function getShoppingMallCustomerOrdersOrderNumberItemsOrderItemId(props: {
  customer: CustomerPayload;
  orderNumber: string;
  orderItemId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallOrderItem> {
  // Find the parent order by order number
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: { order_number: props.orderNumber, deleted_at: null },
  });
  if (!order) throw new HttpException("Order not found", 404);

  // Only owner may view
  if (order.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException("Forbidden", 403);
  }

  // Find the order item only in this order
  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findFirst({
    where: {
      id: props.orderItemId,
      shopping_mall_order_id: order.id,
      deleted_at: null,
    },
  });
  if (!orderItem) throw new HttpException("Order item not found", 404);

  const product = await MyGlobal.prisma.shopping_mall_products.findUnique({
    where: { id: orderItem.shopping_mall_product_id },
  });
  if (!product) throw new HttpException("Product not found", 404);

  // Get product's seller
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: product.shopping_mall_seller_id },
  });
  if (!seller) throw new HttpException("Seller not found", 404);

  // Get product categories (many-to-many, join through products_categories -> category)
  const productCategories =
    await MyGlobal.prisma.shopping_mall_products_categories.findMany({
      where: { shopping_mall_product_id: product.id },
      include: { category: true },
    });
  const categories = productCategories.map((pc) => ({
    id: pc.category.id,
    name: pc.category.name,
  }));

  const productSummary = {
    id: product.id,
    title: product.title,
    default_price: product.default_price,
    business_status: product.business_status,
    seller: {
      id: seller.id,
      business_name: seller.business_name,
    },
    categories,
    created_at: toISOStringSafe(product.created_at),
  };

  // Get the SKU belonging to this order item
  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
    where: { id: orderItem.shopping_mall_product_sku_id },
  });
  if (!sku) throw new HttpException("SKU not found", 404);
  const skuSummary = {
    id: sku.id,
    code: sku.sku_code,
    product_title: product.title,
    option_summary: "",
    in_stock: sku.stock > 0 && sku.status === "active",
  };

  const orderSummary = {
    id: order.id,
    order_number: order.order_number,
    status: order.status,
    total_amount: order.total_amount,
    currency: order.currency,
    created_at: toISOStringSafe(order.created_at),
    updated_at: toISOStringSafe(order.updated_at),
    deleted_at: order.deleted_at
      ? toISOStringSafe(order.deleted_at)
      : undefined,
  };

  return {
    id: orderItem.id,
    order: orderSummary,
    product: productSummary,
    sku: skuSummary,
    quantity: orderItem.quantity,
    unit_price: orderItem.unit_price,
    subtotal: orderItem.subtotal,
    currency: orderItem.currency,
    delivered: orderItem.delivered,
    refunded: orderItem.refunded,
    created_at: toISOStringSafe(orderItem.created_at),
    updated_at: toISOStringSafe(orderItem.updated_at),
    deleted_at:
      orderItem.deleted_at !== null && orderItem.deleted_at !== undefined
        ? toISOStringSafe(orderItem.deleted_at)
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function getShoppingMallCustomerWishlistsWishlistIdItemsItemId(props: {
  customer: CustomerPayload;
  wishlistId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallWishlistItem> {
  // Step 1: Verify wishlist exists and belongs to the customer
  const wishlist = await MyGlobal.prisma.shopping_mall_wishlists.findUnique({
    where: { id: props.wishlistId },
    select: { id: true, shopping_mall_customer_id: true },
  });
  if (!wishlist || wishlist.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException("Wishlist not found", 404);
  }

  // Step 2: Fetch wishlist item and check that it belongs to the correct wishlist
  const item = await MyGlobal.prisma.shopping_mall_wishlist_items.findUnique({
    where: { id: props.itemId },
    select: {
      id: true,
      shopping_mall_wishlist_id: true,
      shopping_mall_product_sku_id: true,
      created_at: true,
    },
  });
  if (!item || item.shopping_mall_wishlist_id !== props.wishlistId) {
    throw new HttpException("Wishlist item not found", 404);
  }

  // Step 3: Fetch product SKU and its product for summary info
  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
    where: { id: item.shopping_mall_product_sku_id },
    select: {
      id: true,
      sku_code: true,
      status: true,
      stock: true,
      product: { select: { title: true } },
    },
  });
  if (!sku || !sku.product) {
    throw new HttpException("Product SKU not found", 404);
  }

  // Option summary (not supported in schema: set as empty string)
  const option_summary = "";

  // Compute in-stock flag
  const in_stock = sku.status === "active" && sku.stock > 0;

  return {
    id: item.id,
    productSku: {
      id: sku.id,
      code: sku.sku_code,
      product_title: sku.product.title,
      option_summary,
      in_stock,
    },
    created_at: toISOStringSafe(item.created_at),
  };
}

import { HttpException } from "@nestjs/common";
