    where: { id: props.reviewId },
    include: {
      customer: true,
      customerSession: true,
      product: { include: { seller: true } },
      productSku: true,
      order: true,
      orderItem: { include: { sku: true } },
      productRating: {
        include: {
          customer: true,
          product: { include: { seller: true } },
          productSku: true,
        },
      },
    },
  });
  if (
    !review ||
    review.deleted_at ||
    !review.customer ||
    !review.customerSession ||
    !review.product ||
    !review.productSku ||
    !review.order ||
    !review.orderItem ||
    !review.productRating
  ) {
    throw new HttpException("Review not found", 404);
