import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAuditLog";
import { IPageIShoppingMallAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAuditLog";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminAuditLogs(props: {
  admin: AdminPayload;
  body: IShoppingMallAuditLog.IRequest;
}): Promise<IPageIShoppingMallAuditLog> {
  const body = props.body;
  // Pagination
  const page = body.page && body.page >= 1 ? body.page : 1;
  const limit =
    body.limit && body.limit >= 1 && body.limit <= 100 ? body.limit : 20;
  const skip = (page - 1) * limit;

  // Sorting
  const allowedSortBy = ["created_at", "risk_level", "change_type"];
  const allowedSortDirection = ["asc", "desc"];
  const sort_by = allowedSortBy.includes(body.sort_by ?? "")
    ? body.sort_by!
    : "created_at";
  const sort_direction = allowedSortDirection.includes(
    body.sort_direction ?? "",
  )
    ? body.sort_direction!
    : "desc";
  const orderBy: Record<string, "asc" | "desc"> = {};
  orderBy[sort_by] = sort_direction;

  // Prisma where clause
  const where: Record<string, unknown> = {
    ...(body.change_type && { change_type: body.change_type }),
    ...(body.risk_level && { risk_level: body.risk_level }),
    ...(body.compliance_tag && { compliance_tag: body.compliance_tag }),
    ...(body.actor_admin_id && { actor_admin_id: body.actor_admin_id }),
    ...(body.actor_seller_id && { actor_seller_id: body.actor_seller_id }),
    ...(body.actor_customer_id && {
      actor_customer_id: body.actor_customer_id,
    }),
    ...(body.start_time && {
      created_at: {
        ...(body.start_time && { gte: body.start_time }),
        ...(body.end_time && { lte: body.end_time }),
      },
    }),
    ...(!body.start_time &&
      body.end_time && {
        created_at: { lte: body.end_time },
      }),
    ...(body.search && {
      OR: [
        { audit_detail: { contains: body.search } },
        { change_type: { contains: body.search } },
        { compliance_tag: { contains: body.search } },
        { risk_level: { contains: body.search } },
      ],
    }),
  };

  // If both start_time and end_time are present, ensure created_at clause merges properly
  if (body.start_time && body.end_time) {
    where.created_at = { gte: body.start_time, lte: body.end_time };
  }

  const [records, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_audit_logs.findMany({
      where,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.shopping_mall_audit_logs.count({ where }),
  ]);

  const data = records.map((log) => ({
    id: log.id,
    change_type: log.change_type,
    risk_level: log.risk_level,
    compliance_tag: log.compliance_tag,
    audit_detail: log.audit_detail,
    created_at: toISOStringSafe(log.created_at),
    actor_admin_id: log.actor_admin_id ?? undefined,
    actor_seller_id: log.actor_seller_id ?? undefined,
    actor_customer_id: log.actor_customer_id ?? undefined,
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCart";
import { IPageIShoppingMallCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCart";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminCarts(props: {
  admin: AdminPayload;
  body: IShoppingMallCart.IRequest;
}): Promise<IPageIShoppingMallCart.ISummary> {
  const {
    customer_id,
    created_from,
    created_to,
    updated_from,
    updated_to,
    page,
    limit,
    sort_by,
    sort_order,
  } = props.body;

  const actualPage = page ?? 1;
  const actualLimit = limit ?? 100;
  const skip = (actualPage - 1) * actualLimit;
  const orderByField = sort_by ?? "created_at";
  const orderByDirection = sort_order ?? "desc";

  // Build the 'where' object step by step to avoid referencing itself
  const where: Record<string, unknown> = {};
  if (customer_id) {
    where.customer_id = customer_id;
  }
  if (created_from || created_to) {
    where.created_at = {};
    if (created_from) (where.created_at as any).gte = created_from;
    if (created_to) (where.created_at as any).lte = created_to;
    if (Object.keys(where.created_at as any).length === 0)
      delete where.created_at;
  }
  if (updated_from || updated_to) {
    where.updated_at = {};
    if (updated_from) (where.updated_at as any).gte = updated_from;
    if (updated_to) (where.updated_at as any).lte = updated_to;
    if (Object.keys(where.updated_at as any).length === 0)
      delete where.updated_at;
  }

  const [records, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_carts.findMany({
      where,
      orderBy: { [orderByField]: orderByDirection },
      skip,
      take: actualLimit,
      include: {
        customer: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_carts.count({ where }),
  ]);

  return {
    pagination: {
      current: actualPage,
      limit: actualLimit,
      records: total,
      pages: Math.ceil(total / actualLimit),
    },
    data: records.map((cart) => ({
      id: cart.id,
      customer: {
        id: cart.customer.id,
        name: cart.customer.name,
      },
      created_at: toISOStringSafe(cart.created_at),
      updated_at: toISOStringSafe(cart.updated_at),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IPageIShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrderItem";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminOrdersOrderNumberItems(props: {
  admin: AdminPayload;
  orderNumber: string;
  body: IShoppingMallOrderItem.IRequest;
}): Promise<IPageIShoppingMallOrderItem.ISummary> {
  // 1. Find the order by orderNumber and ensure not soft deleted
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      order_number: props.orderNumber,
      deleted_at: null,
    },
    select: { id: true },
  });

  if (!order) {
    return {
      pagination: {
        current: props.body.page,
        limit: props.body.limit,
        records: 0,
        pages: 0,
      },
      data: [],
    };
  }

  // 2. Build filters for order items
  const filters: Record<string, any> = {
    shopping_mall_order_id: order.id,
    deleted_at: null,
  };
  if (props.body.sku_id !== undefined)
    filters.shopping_mall_product_sku_id = props.body.sku_id;
  if (props.body.delivered !== undefined)
    filters.delivered = props.body.delivered;
  if (props.body.refunded !== undefined) filters.refunded = props.body.refunded;
  if (
    props.body.min_price !== undefined ||
    props.body.max_price !== undefined
  ) {
    filters.unit_price = {};
    if (props.body.min_price !== undefined)
      filters.unit_price.gte = props.body.min_price;
    if (props.body.max_price !== undefined)
      filters.unit_price.lte = props.body.max_price;
  }

  const skip = (props.body.page - 1) * props.body.limit;
  const take = props.body.limit;

  // 3. Query paginated data and total count
  const [items, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_order_items.findMany({
      where: filters,
      skip,
      take,
      orderBy: { created_at: "desc" },
      include: {
        sku: {
          select: {
            id: true,
            sku_code: true,
            status: true,
            shopping_mall_product_id: true,
            stock: true,
          },
        },
      },
    }),
    MyGlobal.prisma.shopping_mall_order_items.count({ where: filters }),
  ]);

  // Find all unique product ids from the sku records
  const productIds = Array.from(
    new Set(
      items.map((item) => item.sku?.shopping_mall_product_id).filter(Boolean),
    ),
  );

  // Batch fetch all product titles
  const productMap =
    productIds.length > 0
      ? Object.fromEntries(
          (
            await MyGlobal.prisma.shopping_mall_products.findMany({
              where: { id: { in: productIds } },
              select: { id: true, title: true },
            })
          ).map((prod) => [prod.id, prod.title]),
        )
      : {};

  const data: IShoppingMallOrderItem.ISummary[] = items.map((item) => ({
    id: item.id,
    shopping_mall_order_id: item.shopping_mall_order_id,
    sku: {
      id: item.sku.id,
      code: item.sku.sku_code,
      product_title: productMap[item.sku.shopping_mall_product_id] ?? "",
      option_summary: "", // See above, not loaded
      in_stock: item.sku.stock > 0 && item.sku.status === "active",
    },
    quantity: item.quantity,
    unit_price: item.unit_price,
    subtotal: item.subtotal,
    currency: item.currency,
    delivered: item.delivered,
    refunded: item.refunded,
    created_at: toISOStringSafe(item.created_at),
    updated_at: toISOStringSafe(item.updated_at),
  }));

  return {
    pagination: {
      current: props.body.page,
      limit: props.body.limit,
      records: total,
      pages: Math.ceil(total / props.body.limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
