          }
        : undefined,
      customer: row.customer
        ? {
            id: row.customer.id,
            name: row.customer.name,
          }
        : undefined,
      action_type: row.action_type,
      action_payload: row.action_payload,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

