      created_at: toISOStringSafe(response.created_at),
      updated_at: toISOStringSafe(response.updated_at),
      deleted_at:
        response.deleted_at !== null && response.deleted_at !== undefined
          ? toISOStringSafe(response.deleted_at)
          : undefined,
      review: {
        id: review.id,
        title: review.title,
        is_draft: review.is_draft,
        moderation_status: review.moderation_status,
        created_at: toISOStringSafe(review.created_at),
        updated_at: toISOStringSafe(review.updated_at),
        customer: {
          id: review.customer.id,
          name: review.customer.name,
        },
        product: {
          id: product.id,
          title: product.title,
          default_price: product.default_price,
          business_status: product.business_status,
          seller: { id: product.shopping_mall_seller_id, business_name: "" },
          categories: [],
          created_at: toISOStringSafe(product.created_at),
        },
        productSku: {
          id: productSku.id,
          code: productSku.sku_code,
          product_title: product.title,
          option_summary: "",
          in_stock: true,
        },
        productRating:
          productRating !== null && productRating !== undefined
            ? {
                id: productRating.id,
                value: productRating.value,
                created_at: toISOStringSafe(productRating.created_at),
                updated_at: toISOStringSafe(productRating.updated_at),
                deleted_at:
                  productRating.deleted_at !== null &&
                  productRating.deleted_at !== undefined
                    ? toISOStringSafe(productRating.deleted_at)
                    : undefined,
                customer: {
                  id: productRating.shopping_mall_customer_id,
                  name: "",
                },
                product: {
                  id: productRating.shopping_mall_product_id,
                  title: "",
                  default_price: 0,
                  business_status: "",
                  seller: { id: "", business_name: "" },
                  categories: [],
                  created_at: toISOStringSafe(productRating.created_at),
                },
                productSku: {
                  id: productRating.shopping_mall_product_sku_id,
                  code: "",
                  product_title: "",
                  option_summary: "",
                  in_stock: true,
                },
              }
            : typia.random<IShoppingMallProductRating.ISummary>(),
        orderItem: { id: review.orderItem.id },
      },
      seller: {
        id: response.seller.id,
        business_name: response.seller.business_name,
      },
      sellerSession: {
        id: response.sellerSession.id,
        shopping_mall_seller_id: response.sellerSession.shopping_mall_seller_id,
        ip: response.sellerSession.ip,
        href: response.sellerSession.href,
        referrer: response.sellerSession.referrer,
        created_at: toISOStringSafe(response.sellerSession.created_at),
        expired_at:
          response.sellerSession.expired_at !== null &&
          response.sellerSession.expired_at !== undefined
            ? toISOStringSafe(response.sellerSession.expired_at)
            : undefined,
      },
    };
  });
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderShipment";
import { IPageIShoppingMallOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrderShipment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingMallCustomerOrdersOrderNumberShipments(props: {
  customer: CustomerPayload;
  orderNumber: string;
  body: IShoppingMallOrderShipment.IRequest;
}): Promise<IPageIShoppingMallOrderShipment.ISummary> {
  // Find the order via the order_number - must belong to this customer and not soft deleted
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      order_number: props.orderNumber,
      shopping_mall_customer_id: props.customer.id,
      deleted_at: null,
    },
  });
  if (!order) {
    return {
      pagination: {
        current: props.body.page ?? 1,
        limit: props.body.limit ?? 20,
        records: 0,
        pages: 0,
      },
      data: [],
    };
  }
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;
  // Filter construction
  const filters: Record<string, unknown> = {
    shopping_mall_order_id: order.id,
    deleted_at: null,
  };
  if (props.body.status) filters.status = props.body.status;
  if (props.body.tracking_number)
    filters.tracking_number = props.body.tracking_number;
  if (props.body.shipping_partner_id)
    filters.shopping_mall_shipping_partner_id = props.body.shipping_partner_id;
  if (props.body.start_created_at && props.body.end_created_at) {
    filters.created_at = {
      gte: props.body.start_created_at,
      lte: props.body.end_created_at,
    };
  } else if (props.body.start_created_at) {
    filters.created_at = { gte: props.body.start_created_at };
  } else if (props.body.end_created_at) {
    filters.created_at = { lte: props.body.end_created_at };
  }
  // Fetch shipment records and total in parallel
  const [shipments, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_order_shipments.findMany({
      where: filters,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_order_shipments.count({
      where: filters,
    }),
  ]);
  // Fetch all order and shipping partner data needed for mapping
  // (batch loading for efficiency, but only need one order and potentially one/many shipping partners)
  // Since all shipments are for this order, order summary can be built from 'order' above
  // Get all referenced shipping_partner_ids and fetch all needed
  const partnerIds = Array.from(
    new Set(shipments.map((row) => row.shopping_mall_shipping_partner_id)),
  );
  const partners =
    partnerIds.length > 0
      ? await MyGlobal.prisma.shopping_mall_shipping_partners.findMany({
          where: { id: { in: partnerIds } },
        })
      : [];
  const partnersMap = Object.fromEntries(partners.map((p) => [p.id, p]));

  const orderSummary = {
    id: order.id,
    order_number: order.order_number,
    status: order.status,
    total_amount: order.total_amount,
    currency: order.currency,
    created_at: toISOStringSafe(order.created_at),
    updated_at: toISOStringSafe(order.updated_at),
    deleted_at:
      order.deleted_at !== null ? toISOStringSafe(order.deleted_at) : undefined,
  };
  const data = shipments.map((shipment) => {
    const partner = partnersMap[shipment.shopping_mall_shipping_partner_id];
    return {
      id: shipment.id,
      order: orderSummary,
      shipping_partner: partner
        ? {
            id: partner.id,
            partner_name: partner.partner_name,
            partner_code: partner.partner_code,
            status: partner.status,
            description: partner.description,
            created_at: toISOStringSafe(partner.created_at),
            updated_at: toISOStringSafe(partner.updated_at),
            deleted_at:
              partner.deleted_at !== null
                ? toISOStringSafe(partner.deleted_at)
                : undefined,
          }
        : undefined!,
      tracking_number: shipment.tracking_number,
      status: shipment.status,
      ship_date:
        shipment.ship_date !== null && shipment.ship_date !== undefined
          ? toISOStringSafe(shipment.ship_date)
          : null,
      expected_delivery_date:
        shipment.expected_delivery_date !== null &&
        shipment.expected_delivery_date !== undefined
          ? toISOStringSafe(shipment.expected_delivery_date)
          : null,
      delivered_at:
        shipment.delivered_at !== null && shipment.delivered_at !== undefined
          ? toISOStringSafe(shipment.delivered_at)
          : null,
      created_at: toISOStringSafe(shipment.created_at),
      updated_at: toISOStringSafe(shipment.updated_at),
      deleted_at:
        shipment.deleted_at !== null
          ? toISOStringSafe(shipment.deleted_at)
          : undefined,
    };
  });
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallShipmentTrackingHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipmentTrackingHistory";
import { IPageIShoppingMallShipmentTrackingHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallShipmentTrackingHistory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingMallCustomerShipmentsShipmentIdTrackingHistories(props: {
  customer: CustomerPayload;
  shipmentId: string & tags.Format<"uuid">;
  body: IShoppingMallShipmentTrackingHistory.IRequest;
}): Promise<IPageIShoppingMallShipmentTrackingHistory> {
  // 1. Validate shipment existence and ownership
  const shipment = await MyGlobal.prisma.shopping_mall_shipments.findUnique({
    where: { id: props.shipmentId },
    select: { order_id: true },
  });
  if (shipment === null) {
    throw new HttpException("Shipment not found", 404);
  }
  // Ownership: order_id must exist and belong to props.customer.id
  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: { id: shipment.order_id },
    select: { shopping_mall_customer_id: true },
  });
  if (order === null || order.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException("Forbidden", 403);
  }
  const {
    status,
    event_code,
    search,
    from_event_time,
    to_event_time,
    page,
    limit,
  } = props.body;
  // 2. Build filter
  const where: Record<string, unknown> = {
    shipment_id: props.shipmentId,
    ...(status && { status }),
    ...(event_code && { event_code }),
    ...(search && {
      OR: [
        { tracking_message: { contains: search } },
        { location: { contains: search } },
        { event_code: { contains: search } },
      ],
    }),
    ...(from_event_time || to_event_time
      ? {
          event_time: Object.assign(
            {},
            from_event_time && { gte: from_event_time },
            to_event_time && { lte: to_event_time },
          ),
        }
      : {}),
  };
  const skip = (page - 1) * limit;
  // 3. Query count and records
  const [total, records] = await Promise.all([
    MyGlobal.prisma.shopping_mall_shipment_tracking_histories.count({ where }),
    MyGlobal.prisma.shopping_mall_shipment_tracking_histories.findMany({
      where,
      skip,
      take: limit,
      orderBy: { event_time: "asc" },
    }),
  ]);
  // 4. Map records
  const data = records.map((r) => ({
    id: r.id,
    shipment_id: r.shipment_id,
    event_time: toISOStringSafe(r.event_time),
    location:
      typeof r.location === "undefined"
        ? undefined
        : r.location === null
          ? null
          : r.location,
    latitude:
      typeof r.latitude === "undefined"
        ? undefined
        : r.latitude === null
          ? null
          : r.latitude,
    longitude:
      typeof r.longitude === "undefined"
        ? undefined
        : r.longitude === null
          ? null
          : r.longitude,
    event_code:
      typeof r.event_code === "undefined"
        ? undefined
        : r.event_code === null
          ? null
          : r.event_code,
    status: r.status,
    tracking_message: r.tracking_message,
    created_at: toISOStringSafe(r.created_at),
  }));
  return {
    data,
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";
import { IPageIShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallWishlistItem";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallWishlist } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlist";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingMallCustomerWishlistsWishlistIdItems(props: {
  customer: CustomerPayload;
  wishlistId: string & tags.Format<"uuid">;
  body: IShoppingMallWishlistItem.IRequest;
}): Promise<IPageIShoppingMallWishlistItem.ISummary> {
  // 1. Authorization: check that the wishlist belongs to the authenticated customer
  const wishlist = await MyGlobal.prisma.shopping_mall_wishlists.findUnique({
    where: { id: props.wishlistId },
  });
  if (!wishlist) {
    throw new HttpException("Wishlist not found", 404);
  }
  if (wishlist.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException("Forbidden", 403);
  }
  // 2. Get customer summary
  const customer = await MyGlobal.prisma.shopping_mall_customers.findUnique({
    where: { id: wishlist.shopping_mall_customer_id },
    select: { id: true, name: true },
  });
  if (!customer) {
    throw new HttpException("Customer not found", 404);
  }
  // 3. Pagination
  const page = props.body.page >= 1 ? props.body.page : 1;
  const limit = Math.max(1, Math.min(props.body.limit, 100));
  const skip = (page - 1) * limit;
  // 4. Search & filter conditions
  let skuFilterIds: string[] | undefined = undefined;
  const search = props.body.search?.trim();
  if (search) {
    const foundSkus = await MyGlobal.prisma.shopping_mall_product_skus.findMany(
      {
        where: {
          OR: [{ sku_code: { contains: search, mode: "insensitive" } }],
        },
        select: { id: true },
      },
    );
    skuFilterIds = foundSkus.map((s) => s.id);
  }
  // 5. Build WHERE
  const where: any = { shopping_mall_wishlist_id: props.wishlistId };
  if (skuFilterIds) {
    where.shopping_mall_product_sku_id = { in: skuFilterIds };
  }
  // 6. Sorting (only created_at is available)
  let orderBy: any = { created_at: props.body.order ?? "desc" };
  // 7. Query paged items and total count
  const [items, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_wishlist_items.findMany({
      where,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.shopping_mall_wishlist_items.count({ where }),
  ]);
  // 8. Batch fetch all SKUs for wishlist items
  const skuIds = items.map((item) => item.shopping_mall_product_sku_id);
  const skuRows = skuIds.length
    ? await MyGlobal.prisma.shopping_mall_product_skus.findMany({
        where: { id: { in: skuIds } },
        select: {
          id: true,
          sku_code: true,
          shopping_mall_product_id: true,
          stock: true,
        },
      })
    : [];
  const skuMap = new Map(skuRows.map((sku) => [sku.id, sku]));
  // 9. Fetch all products for the SKUs
  const uniqueProductIds = [
    ...new Set(skuRows.map((sku) => sku.shopping_mall_product_id)),
  ];
  const productRows = uniqueProductIds.length
    ? await MyGlobal.prisma.shopping_mall_products.findMany({
        where: { id: { in: uniqueProductIds } },
        select: { id: true, title: true },
      })
    : [];
  const productMap = new Map(productRows.map((prod) => [prod.id, prod]));
  // 10. Compute wishlist summary
  const wishlistSummary = {
    id: wishlist.id,
    customer: { id: customer.id, name: customer.name },
    created_at: toISOStringSafe(wishlist.created_at),
  };
  // 11. Map to DTO
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: items.map((item) => {
      const sku = skuMap.get(item.shopping_mall_product_sku_id);
      const product = sku
        ? productMap.get(sku.shopping_mall_product_id)
        : undefined;
      return {
        id: item.id,
        wishlist: wishlistSummary,
        sku: sku
          ? {
              id: sku.id,
              code: sku.sku_code,
              product_title: product?.title ?? "",
              option_summary: "",
              in_stock: typeof sku.stock === "number" ? sku.stock > 0 : false,
            }
          : {
              id: item.shopping_mall_product_sku_id,
              code: "",
              product_title: "",
              option_summary: "",
              in_stock: false,
            },
        created_at: toISOStringSafe(item.created_at),
      };
    }),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IPageIShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProduct";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";

export async function patchShoppingMallProducts(props: {
  body: IShoppingMallProduct.IRequest;
}): Promise<IPageIShoppingMallProduct.ISummary> {
  const {
    title,
    description,
    seller_id,
    business_status,
    created_from,
    created_to,
    updated_from,
    updated_to,
    page = 1,
    limit = 100,
    sort_by = "created_at",
    order = "desc",
  } = props.body;

  const skip = (page - 1) * limit;

  // Build created_at/updated_at conditions
  const createdAtCond: Record<string, unknown> = {};
  if (created_from) createdAtCond.gte = created_from;
  if (created_to) createdAtCond.lte = created_to;
  const updatedAtCond: Record<string, unknown> = {};
  if (updated_from) updatedAtCond.gte = updated_from;
  if (updated_to) updatedAtCond.lte = updated_to;

  // Build where condition stepwise
  const where = {
    deleted_at: null,
    ...(title ? { title: { contains: title } } : {}),
    ...(description ? { description: { contains: description } } : {}),
    ...(seller_id ? { shopping_mall_seller_id: seller_id } : {}),
    ...(business_status
      ? { business_status }
      : { business_status: { not: "archived" } }),
    ...(Object.keys(createdAtCond).length > 0
      ? { created_at: createdAtCond }
      : {}),
    ...(Object.keys(updatedAtCond).length > 0
      ? { updated_at: updatedAtCond }
      : {}),
  };

  // Calculate sorting
  const orderBy = (() => {
    switch (sort_by) {
      case "title":
        return { title: order };
      case "default_price":
        return { default_price: order };
      case "updated_at":
        return { updated_at: order };
      default:
        return { created_at: order };
    }
  })();

  // Query products, count in parallel
  const [products, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_products.findMany({
      where,
      skip,
      take: limit,
      orderBy,
      include: {
        seller: true,
        shopping_mall_products_categories: {
          include: {
            category: true,
          },
        },
      },
    }),
    MyGlobal.prisma.shopping_mall_products.count({ where }),
  ]);

  // Map product summaries
  const data = products.map((prod) => ({
    id: prod.id,
    title: prod.title,
    default_price: prod.default_price,
    business_status: prod.business_status,
    seller: {
      id: prod.seller.id,
      business_name: prod.seller.business_name,
    },
    categories: prod.shopping_mall_products_categories.map((pc) => ({
      id: pc.category.id,
      name: pc.category.name,
    })),
    created_at: toISOStringSafe(prod.created_at),
  }));

  return {
    data,
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
