  });
  if (!sku || sku.product.shopping_mall_seller_id !== seller.id) {
    throw new HttpException("SKU not found or permission denied", 404);
  }

  const whereCondition = {
    shopping_mall_product_sku_id: skuId,
    ...(body.attribute_id !== undefined
      ? { shopping_mall_product_attribute_id: body.attribute_id }
      : {}),
    ...(body.value_display_name !== undefined
      ? { value_display_name: { contains: body.value_display_name } }
      : {}),
  };

  // Fetch attribute values with joined attribute (and its product for minimal ISummary)
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_product_attribute_values.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
      include: {
        attribute: {
          include: { product: { include: { seller: true } } },
        },
      },
    }),
    MyGlobal.prisma.shopping_mall_product_attribute_values.count({
      where: whereCondition,
    }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((row) => ({
      id: row.id,
      sku: {
        id: sku.id,
        code: sku.sku_code,
        product_title: sku.product.title,
        option_summary: "",
        in_stock: sku.stock > 0,
      },
      attribute: {
        id: row.attribute.id,
        product: {
          id: row.attribute.product.id,
          title: row.attribute.product.title,
          default_price: row.attribute.product.default_price,
          business_status: row.attribute.product.business_status,
          seller: {
            id: row.attribute.product.seller.id,
            business_name: row.attribute.product.seller.business_name,
          },
          categories: [],
          created_at: toISOStringSafe(row.attribute.product.created_at),
        },
        attribute_name: row.attribute.attribute_name,
        position: row.attribute.position,
        created_at: toISOStringSafe(row.attribute.created_at),
        updated_at: toISOStringSafe(row.attribute.updated_at),
        deleted_at:
          row.attribute.deleted_at === null ||
          row.attribute.deleted_at === undefined
            ? undefined
            : toISOStringSafe(row.attribute.deleted_at),
      },
      value_display_name: row.value_display_name,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminRefresh(props: {
  body: IShoppingMallAdmin.IRefresh;
}): Promise<IShoppingMallAdmin.IAuthorized> {
  let decoded: { id: string; session_id: string; type: "admin" };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: "admin" };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (decoded.type !== "admin") {
    throw new HttpException("Invalid token subject", 403);
  }
  const session = await MyGlobal.prisma.shopping_mall_admin_sessions.findFirst({
    where: {
      id: decoded.session_id,
      shopping_mall_admin_id: decoded.id,
    },
    include: {
      admin: true,
    },
  });
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  if (!session.admin) {
    throw new HttpException("Admin account not found", 403);
  }
  if (session.admin.status !== "active") {
    throw new HttpException("Admin account is not active", 403);
  }
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
  const token = {
    access: jwt.sign(
      {
        type: "admin",
        id: decoded.id,
        session_id: decoded.session_id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: decoded.id,
        session_id: decoded.session_id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };
  await MyGlobal.prisma.shopping_mall_admin_sessions.update({
    where: { id: decoded.session_id },
    data: {
      expired_at: refreshExpires,
    },
  });
  return {
    id: session.admin.id,
    email: session.admin.email,
    name: session.admin.name,
    is_email_verified: session.admin.is_email_verified,
    status: session.admin.status,
    created_at: toISOStringSafe(session.admin.created_at),
    updated_at: toISOStringSafe(session.admin.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthSellerRefresh(props: {
  body: IShoppingMallSeller.IRefresh;
}): Promise<IShoppingMallSeller.IAuthorized> {
  // Step 1: Decode and verify JWT refresh token
  let decoded: { id: string; session_id: string; type: string };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: string };
  } catch (err) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "seller") {
    throw new HttpException("Invalid actor type for this endpoint", 403);
  }

  // Step 2: Validate session
  const session = await MyGlobal.prisma.shopping_mall_seller_sessions.findFirst(
    {
      where: {
        id: decoded.session_id,
        shopping_mall_seller_id: decoded.id,
      },
    },
  );

  if (!session) {
    throw new HttpException("Session does not exist or has been revoked", 401);
  }

  if (session.expired_at !== null) {
    const now = Date.now();
    if (new Date(session.expired_at).getTime() < now) {
      throw new HttpException("Session has expired", 401);
    }
  }

  // Step 3: Fetch the seller
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: session.shopping_mall_seller_id },
  });

  if (!seller) {
    throw new HttpException("Seller account not found", 403);
  }

  // Step 4: Generate new tokens
  const nowString = toISOStringSafe(new Date());
  const accessExpiry = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpiry = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const access_token = jwt.sign(
    {
      type: "seller",
      id: seller.id,
      session_id: session.id,
      created_at: nowString,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );
  const refresh_token = jwt.sign(
    {
      type: "seller",
      id: seller.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: nowString,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );
  const expired_at = toISOStringSafe(accessExpiry);
  const refreshable_until = toISOStringSafe(refreshExpiry);

  // Step 5: Update session expiration
  await MyGlobal.prisma.shopping_mall_seller_sessions.update({
    where: { id: session.id },
    data: { expired_at: refreshExpiry },
  });

  return {
    id: seller.id,
    email: seller.email,
    business_name: seller.business_name,
    registration_number: seller.registration_number,
    business_phone: seller.business_phone,
    is_email_verified: seller.is_email_verified,
    status: seller.status,
    created_at: toISOStringSafe(seller.created_at),
    updated_at: toISOStringSafe(seller.updated_at),
    token: {
      access: access_token,
      refresh: refresh_token,
      expired_at,
      refreshable_until,
    },
    seller: {
      id: seller.id,
      business_name: seller.business_name,
    },
  };
}

import { HttpException } from "@nestjs/common";
