export async function postShoppingMallCustomerReturnRequests(props: {
  customer: CustomerPayload;
  body: IShoppingMallReturnRequest.ICreate;
}): Promise<IShoppingMallReturnRequest> {
  const now = toISOStringSafe(new Date());
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      id: props.body.order_id,
      shopping_mall_customer_id: props.customer.id,
      deleted_at: null,
    },
  });
  if (!order) {
    throw new HttpException(
      "Order not found or does not belong to this customer",
      404,
    );
  }
  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findFirst({
    where: {
      id: props.body.order_item_id,
      shopping_mall_order_id: props.body.order_id,
      deleted_at: null,
    },
  });
  if (!orderItem) {
    throw new HttpException(
      "Order item not found or does not belong to specified order",
      404,
    );
  }
  // Fetch the SKU for the order item
  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findFirst({
    where: { id: orderItem.shopping_mall_product_sku_id },
  });
  if (!sku) {
    throw new HttpException("SKU not found for the given order item", 404);
  }
  // Create return request
  const created = await MyGlobal.prisma.shopping_mall_return_requests.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      order_id: props.body.order_id,
      order_item_id: props.body.order_item_id,
      requested_by_customer_id: props.customer.id,
      requested_by_seller_id: null,
      shipping_partner_id: props.body.shipping_partner_id ?? null,
      reason: props.body.reason,
      status: "pending",
      pickup_address: Object.prototype.hasOwnProperty.call(
        props.body,
        "pickup_address",
      )
        ? (props.body.pickup_address ?? null)
        : null,
      scheduled_pickup_at: Object.prototype.hasOwnProperty.call(
        props.body,
        "scheduled_pickup_at",
      )
        ? (props.body.scheduled_pickup_at ?? null)
        : null,
      provider_tracking_code: Object.prototype.hasOwnProperty.call(
        props.body,
        "provider_tracking_code",
      )
        ? (props.body.provider_tracking_code ?? null)
        : null,
      created_at: now,
      updated_at: now,
      completed_at: null,
      cancelled_at: null,
      deleted_at: null,
    },
  });
  const customer = await MyGlobal.prisma.shopping_mall_customers.findFirst({
    where: { id: props.customer.id },
  });
  let shippingPartner:
    | IShoppingMallShippingPartner.ISummary
    | null
    | undefined = null;
  if (created.shipping_partner_id) {
    const partner =
      await MyGlobal.prisma.shopping_mall_shipping_partners.findFirst({
        where: { id: created.shipping_partner_id, deleted_at: null },
      });
    if (partner) {
      shippingPartner = {
        id: partner.id,
        partner_name: partner.partner_name,
        partner_code: partner.partner_code,
        status: partner.status,
        description: partner.description,
        created_at: toISOStringSafe(partner.created_at),
        updated_at: toISOStringSafe(partner.updated_at),
        deleted_at: partner.deleted_at
          ? toISOStringSafe(partner.deleted_at)
          : undefined,
      };
    } else {
      shippingPartner = null;
    }
  }
  return {
    id: created.id,
    order: {
      id: order.id,
      order_number: order.order_number,
      status: order.status,
      total_amount: order.total_amount,
      currency: order.currency,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      deleted_at: order.deleted_at
        ? toISOStringSafe(order.deleted_at)
        : undefined,
    },
    orderItem: {
      id: orderItem.id,
      shopping_mall_order_id: orderItem.shopping_mall_order_id,
      sku: {
        id: sku.id,
        code: sku.sku_code,
        product_title: "", // cannot provide, not in schema
        option_summary: "", // cannot provide, not in schema
        in_stock: sku.stock > 0,
      },
      quantity: orderItem.quantity,
      unit_price: orderItem.unit_price,
      subtotal: orderItem.subtotal,
      currency: orderItem.currency,
      delivered: orderItem.delivered,
      refunded: orderItem.refunded,
      created_at: toISOStringSafe(orderItem.created_at),
      updated_at: toISOStringSafe(orderItem.updated_at),
    },
    requestedByCustomer: customer
      ? { id: customer.id, name: customer.name }
      : undefined,
    requestedBySeller: null,
    shippingPartner: shippingPartner ?? null,
    reason: created.reason,
    status: created.status,
    pickup_address: Object.prototype.hasOwnProperty.call(
      created,
      "pickup_address",
    )
      ? (created.pickup_address ?? null)
      : null,
    scheduled_pickup_at: Object.prototype.hasOwnProperty.call(
      created,
      "scheduled_pickup_at",
    )
      ? created.scheduled_pickup_at
        ? toISOStringSafe(created.scheduled_pickup_at)
        : null
      : null,
    provider_tracking_code: Object.prototype.hasOwnProperty.call(
      created,
      "provider_tracking_code",
    )
      ? (created.provider_tracking_code ?? null)
      : null,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    completed_at: created.completed_at
      ? toISOStringSafe(created.completed_at)
      : null,
    cancelled_at: created.cancelled_at
      ? toISOStringSafe(created.cancelled_at)
      : null,
    deleted_at: created.deleted_at
      ? toISOStringSafe(created.deleted_at)
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerWishlistsWishlistIdItems(props: {
  customer: CustomerPayload;
  wishlistId: string & tags.Format<"uuid">;
  body: IShoppingMallWishlistItem.ICreate;
}): Promise<IShoppingMallWishlistItem> {
  // Step 1: Validate wishlist belongs to customer
  const wishlist = await MyGlobal.prisma.shopping_mall_wishlists.findUnique({
    where: { id: props.wishlistId },
  });
  if (!wishlist || wishlist.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException("Wishlist not found or access denied", 404);
  }

  // Step 2: Validate SKU exists and is active (not deleted)
  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findFirst({
    where: {
      id: props.body.shopping_mall_product_sku_id,
      deleted_at: null,
    },
    include: {
      product: true,
    },
  });
  if (!sku) {
    throw new HttpException("Product SKU not found", 404);
  }

  // Step 3: Attempt to insert wishlist item
  let item;
  try {
    item = await MyGlobal.prisma.shopping_mall_wishlist_items.create({
      data: {
        id: v4(),
        shopping_mall_wishlist_id: props.wishlistId,
        shopping_mall_product_sku_id: props.body.shopping_mall_product_sku_id,
        created_at: toISOStringSafe(new Date()),
      },
    });
  } catch (err) {
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2002"
    ) {
      throw new HttpException("SKU is already in the wishlist", 409);
    }
    throw err;
  }

  // Step 4: Prepare productSku summary for response
  const in_stock =
    sku.status === "active" && sku.stock > 0 && sku.deleted_at === null;
  return {
    id: item.id,
    productSku: {
      id: sku.id,
      code: sku.sku_code,
      product_title: sku.product.title,
      option_summary: "",
      in_stock: in_stock,
    },
    created_at: item.created_at
      ? toISOStringSafe(item.created_at)
      : toISOStringSafe(new Date()),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postShoppingMallSellerProductsProductIdCategories(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  body: IShoppingMallProductsCategory.ICreate;
}): Promise<IShoppingMallProductsCategory> {
  // 1. Verify product ownership and existence.
  const product = await MyGlobal.prisma.shopping_mall_products.findFirst({
    where: {
      id: props.productId,
      shopping_mall_seller_id: props.seller.id,
      deleted_at: null,
    },
  });
  if (!product) {
    throw new HttpException(
      "Product not found, deleted, or you do not have permission to modify.",
      404,
    );
  }
  // 2. Verify category existence.
  const category = await MyGlobal.prisma.shopping_mall_categories.findFirst({
    where: {
      id: props.body.shopping_mall_category_id,
      deleted_at: null,
    },
  });
  if (!category) {
    throw new HttpException("Category not found or has been deleted.", 404);
  }
  // 3. Check uniqueness (no duplicate mapping).
  const existingMapping =
    await MyGlobal.prisma.shopping_mall_products_categories.findFirst({
      where: {
        shopping_mall_product_id: props.productId,
        shopping_mall_category_id: props.body.shopping_mall_category_id,
      },
    });
  if (existingMapping) {
    throw new HttpException(
      "This category is already assigned to the product.",
      409,
    );
  }
  // 4. Insert new product-category mapping.
  const now = toISOStringSafe(new Date());
  const mapping =
    await MyGlobal.prisma.shopping_mall_products_categories.create({
      data: {
        id: v4(),
        shopping_mall_product_id: props.productId,
        shopping_mall_category_id: props.body.shopping_mall_category_id,
        created_at: now,
      },
    });
  // 5. Build the list of all categories for this product and their summaries.
  const allMappings =
    await MyGlobal.prisma.shopping_mall_products_categories.findMany({
      where: { shopping_mall_product_id: props.productId },
      include: { category: true },
    });
  const categorySummaries = allMappings.map((m) => {
    const c = m.category;
    return {
      id: c.id,
      name: c.name,
      parent_id: c.parent_id ?? undefined,
      description: c.description,
      status: c.status,
      sort_order: c.sort_order,
      updated_at: toISOStringSafe(c.updated_at),
      deleted_at: c.deleted_at ? toISOStringSafe(c.deleted_at) : undefined,
    };
  });

  // 6. Compose seller summary
  const sellerEntity = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: props.seller.id },
  });
  const sellerSummary = {
    id: props.seller.id,
    business_name: sellerEntity?.business_name ?? "",
  };

  // 7. Compose product summary
  const productSummary = {
    id: product.id,
    title: product.title,
    default_price: product.default_price,
    business_status: product.business_status,
    seller: sellerSummary,
    categories: categorySummaries,
    created_at: toISOStringSafe(product.created_at),
  };

  // 8. Compose assigned category summary
  const cat: typeof category = category;
  const categorySummary = {
    id: cat.id,
    name: cat.name,
    parent_id: cat.parent_id ?? undefined,
    description: cat.description,
    status: cat.status,
    sort_order: cat.sort_order,
    updated_at: toISOStringSafe(cat.updated_at),
    deleted_at: cat.deleted_at ? toISOStringSafe(cat.deleted_at) : undefined,
  };

  // 9. Return mapping entity, all types and fields matched to DTO (including date conversions)
  return {
    id: mapping.id,
    product: productSummary,
    category: categorySummary,
    created_at: now,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminProductsProductId(props: {
  admin: AdminPayload;
  productId: string & tags.Format<"uuid">;
  body: IShoppingMallProduct.IUpdate;
}): Promise<IShoppingMallProduct> {
  const product = await MyGlobal.prisma.shopping_mall_products.findUnique({
    where: { id: props.productId },
  });
  if (!product || product.deleted_at !== null) {
    throw new HttpException("Product not found or deleted", 404);
  }

  const dataToUpdate: Record<string, unknown> = {
    ...("title" in props.body ? { title: props.body.title } : {}),
    ...("description" in props.body
      ? { description: props.body.description }
      : {}),
    ...("default_price" in props.body
      ? { default_price: props.body.default_price }
      : {}),
    ...("business_status" in props.body
      ? { business_status: props.body.business_status }
      : {}),
    updated_at: toISOStringSafe(new Date()),
  };

  const updated = await MyGlobal.prisma.shopping_mall_products.update({
    where: { id: props.productId },
    data: dataToUpdate,
  });

  // Fetch seller summary
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: updated.shopping_mall_seller_id },
  });
  if (!seller) {
    throw new HttpException("Seller not found for product", 500);
  }
  const sellerSummary = {
    id: seller.id,
    business_name: seller.business_name,
  };

  // Fetch categories from join table, then load their ISummary records
  const productCategoryMappings =
    await MyGlobal.prisma.shopping_mall_products_categories.findMany({
      where: { shopping_mall_product_id: updated.id },
      select: { shopping_mall_category_id: true },
    });
  const categoryIds = productCategoryMappings.map(
    (m) => m.shopping_mall_category_id,
  );
  let primary_categories: IShoppingMallCategory.ISummary[] = [];
  if (categoryIds.length > 0) {
    const categories = await MyGlobal.prisma.shopping_mall_categories.findMany({
      where: { id: { in: categoryIds } },
    });
    primary_categories = categories.map((cat) => ({
      id: cat.id,
      name: cat.name,
      parent_id: cat.parent_id ?? undefined,
      description: cat.description,
      status: cat.status,
      sort_order: cat.sort_order,
      updated_at: toISOStringSafe(cat.updated_at),
      deleted_at:
        cat.deleted_at !== null ? toISOStringSafe(cat.deleted_at) : undefined,
    }));
  }

  return {
    id: updated.id,
    title: updated.title,
    description: updated.description,
    default_price: updated.default_price,
    business_status: updated.business_status,
    seller: sellerSummary,
    primary_categories,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at:
      updated.deleted_at !== null
        ? toISOStringSafe(updated.deleted_at)
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallReturnRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnRequest";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminReturnRequestsReturnRequestId(props: {
  admin: AdminPayload;
  returnRequestId: string & tags.Format<"uuid">;
  body: IShoppingMallReturnRequest.IUpdate;
}): Promise<IShoppingMallReturnRequest> {
  // Fetch existing return request
  const existing =
    await MyGlobal.prisma.shopping_mall_return_requests.findUnique({
      where: { id: props.returnRequestId },
      include: {
        order: true,
        orderItem: true,
        requestedByCustomer: true,
        requestedBySeller: true,
        shippingPartner: true,
      },
    });

  if (!existing || existing.deleted_at !== null) {
    throw new HttpException("Return request not found", 404);
  }

  // Define valid status transitions (simple example)
  const validTransitions: Record<string, string[]> = {
    pending: ["approved", "rejected", "cancelled"],
    approved: ["scheduled", "cancelled"],
    scheduled: ["picked_up", "cancelled"],
    picked_up: ["delivered", "cancelled"],
    delivered: ["completed", "cancelled"],
    completed: [],
    rejected: [],
    cancelled: [],
  };
  const currentStatus = existing.status;
  const newStatus = props.body.status ?? currentStatus;
  if (newStatus !== currentStatus) {
    if (
      !validTransitions[currentStatus] ||
      !validTransitions[currentStatus].includes(newStatus)
    ) {
      throw new HttpException(
        `Invalid status transition: ${currentStatus} → ${newStatus}`,
        400,
      );
    }
  }
  // Compose update data (patch only mutable fields)
  const updateData: Record<string, unknown> = {
    updated_at: toISOStringSafe(new Date()),
  };
  if (typeof props.body.reason === "string")
    updateData.reason = props.body.reason;
  if (typeof props.body.status === "string")
    updateData.status = props.body.status;
  if (Object.prototype.hasOwnProperty.call(props.body, "pickup_address"))
    updateData.pickup_address =
      props.body.pickup_address === undefined
        ? null
        : props.body.pickup_address;
  if (Object.prototype.hasOwnProperty.call(props.body, "scheduled_pickup_at"))
    updateData.scheduled_pickup_at =
      props.body.scheduled_pickup_at === undefined
        ? null
        : props.body.scheduled_pickup_at;
  if (
    Object.prototype.hasOwnProperty.call(props.body, "provider_tracking_code")
  )
    updateData.provider_tracking_code =
      props.body.provider_tracking_code === undefined
        ? null
        : props.body.provider_tracking_code;
  if (Object.prototype.hasOwnProperty.call(props.body, "shipping_partner_id"))
    updateData.shipping_partner_id =
      props.body.shipping_partner_id === undefined
        ? null
        : props.body.shipping_partner_id;

  // If shipping_partner_id is being updated, validate existence of partner
  if (
    Object.prototype.hasOwnProperty.call(props.body, "shipping_partner_id") &&
    props.body.shipping_partner_id
  ) {
    const partner =
      await MyGlobal.prisma.shopping_mall_shipping_partners.findUnique({
        where: { id: props.body.shipping_partner_id },
        select: { id: true },
      });
    if (!partner) {
      throw new HttpException("Shipping partner not found", 404);
    }
  }

  // If nothing to update, error
  if (Object.keys(updateData).length === 1) {
    throw new HttpException("No updatable field provided", 400);
  }

  const updated = await MyGlobal.prisma.shopping_mall_return_requests.update({
    where: { id: props.returnRequestId },
    data: updateData,
    include: {
      order: true,
      orderItem: true,
      requestedByCustomer: true,
      requestedBySeller: true,
      shippingPartner: true,
    },
  });

  // Fetch SKU details for orderItem.sku summary (use only valid fields)
  let skuSummary: IShoppingMallProductSku.ISummary | undefined = undefined;
  if (updated.orderItem && updated.orderItem.shopping_mall_product_sku_id) {
    const sku = await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
      where: { id: updated.orderItem.shopping_mall_product_sku_id },
      select: {
        id: true,
        sku_code: true,
        // product_title: true, // not available
        // option_summary: true, // not available
