      refunded: updated.orderItem.refunded,
      created_at: toISOStringSafe(updated.orderItem.created_at),
      updated_at: toISOStringSafe(updated.orderItem.updated_at),
    },
    requestedByCustomer: updated.requestedByCustomer
      ? {
