import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function putShoppingMallCustomerCartsCartIdItemsItemId(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
  body: IShoppingMallCartItem.IUpdate;
}): Promise<IShoppingMallCartItem> {
  // 1. Load cart item with SKU and cart info plus parent product info
  const item = await MyGlobal.prisma.shopping_mall_cart_items.findUnique({
    where: { id: props.itemId },
    include: {
      cart: true,
      productSku: {
        include: {
          product: true,
        },
      },
    },
  });
  if (!item) {
    throw new HttpException("Cart item not found", 404);
  }
  // 2. Ownership: Ensure customer owns this cart
  if (!item.cart || item.cart.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException("Forbidden: Not your cart", 403);
  }
  // 3. Quantity validation
  if (props.body.quantity > item.productSku.stock) {
    throw new HttpException(
      "Requested quantity exceeds available inventory",
      400,
    );
  }
  // 4. Update quantity and timestamp
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.shopping_mall_cart_items.update({
    where: { id: props.itemId },
    data: {
      quantity: props.body.quantity,
      updated_at: now,
    },
    include: {
      productSku: {
        include: {
          product: true,
        },
      },
    },
  });
  const productSku = updated.productSku;
  // Derive productSku summary for return DTO
  const sku_summary: IShoppingMallProductSku.ISummary = {
    id: productSku.id,
    code: productSku.sku_code,
    product_title: productSku.product?.title ?? "",
    option_summary: "", // Not available on SKU -- spec not implemented
    in_stock: productSku.stock > 0 && productSku.status === "active",
  };
  return {
    id: updated.id,
    shopping_mall_cart_id: updated.shopping_mall_cart_id,
    quantity: updated.quantity,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    productSku: sku_summary,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallReturnRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnRequest";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function putShoppingMallSellerReturnRequestsReturnRequestId(props: {
  seller: SellerPayload;
  returnRequestId: string & tags.Format<"uuid">;
  body: IShoppingMallReturnRequest.IUpdate;
}): Promise<IShoppingMallReturnRequest> {
  // 1. Find the return request (not soft deleted)
  const returnRequest =
    await MyGlobal.prisma.shopping_mall_return_requests.findFirst({
      where: {
        id: props.returnRequestId,
        deleted_at: null,
      },
    });
  if (!returnRequest) {
    throw new HttpException("Return request not found.", 404);
  }

  // 2. Validate seller owns this request (requested_by_seller, or is seller on related order)
  if (returnRequest.requested_by_seller_id !== props.seller.id) {
    // Check if order belongs to seller
    const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
      where: { id: returnRequest.order_id },
    });
    if (!order || order.shopping_mall_seller_id !== props.seller.id) {
      throw new HttpException("Forbidden: Not your return request.", 403);
    }
  }

  // 3. Prepare update data - strictly allow only mutable fields
  const {
    reason,
    status,
    pickup_address,
    scheduled_pickup_at,
    provider_tracking_code,
    shipping_partner_id,
  } = props.body ?? {};

  const validStatuses = [
    "pending",
    "approved",
    "scheduled",
    "picked_up",
    "delivered",
    "completed",
    "rejected",
    "cancelled",
  ];
  if (status && !validStatuses.includes(status)) {
    throw new HttpException("Invalid status value.", 409);
  }
  if (
    ["completed", "cancelled"].includes(returnRequest.status) &&
    status &&
    status !== returnRequest.status
  ) {
    throw new HttpException(
      "Cannot transition from completed or cancelled.",
      409,
    );
  }

  const updateData: Record<string, unknown> = {
    ...(reason !== undefined && { reason }),
    ...(status !== undefined && { status }),
    ...(pickup_address !== undefined && { pickup_address }),
    ...(scheduled_pickup_at !== undefined && { scheduled_pickup_at }),
    ...(provider_tracking_code !== undefined && { provider_tracking_code }),
    ...(shipping_partner_id !== undefined && { shipping_partner_id }),
    updated_at: toISOStringSafe(new Date()),
  };
  if (status === "completed") {
    updateData.completed_at = toISOStringSafe(new Date());
  } else if (status === "cancelled") {
    updateData.cancelled_at = toISOStringSafe(new Date());
  }

  const updated = await MyGlobal.prisma.shopping_mall_return_requests.update({
    where: { id: props.returnRequestId },
    data: updateData,
  });

  // Get order, orderItem, and sku (required for summaries)
  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: { id: updated.order_id },
  });
  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findUnique({
    where: { id: updated.order_item_id },
  });
  let sku: null | any = null;
  if (orderItem) {
    sku = await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
      where: { id: orderItem.shopping_mall_product_sku_id },
    });
  }

  // Compose requestedByCustomer
  let requestedByCustomer = undefined;
  if (updated.requested_by_customer_id) {
    const customer = await MyGlobal.prisma.shopping_mall_customers.findUnique({
      where: { id: updated.requested_by_customer_id },
    });
    if (customer) {
      requestedByCustomer = {
        id: customer.id,
        name: customer.name,
      };
    }
  }
  // Compose requestedBySeller
  let requestedBySeller = undefined;
  if (updated.requested_by_seller_id) {
    const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
      where: { id: updated.requested_by_seller_id },
    });
    if (seller) {
      requestedBySeller = {
        id: seller.id,
        business_name: seller.business_name,
      };
    }
  }
  // Compose shippingPartner
  let shippingPartner = undefined;
  if (updated.shipping_partner_id) {
    const shippingPartnerObj =
      await MyGlobal.prisma.shopping_mall_shipping_partners.findUnique({
        where: { id: updated.shipping_partner_id },
      });
    if (shippingPartnerObj) {
      shippingPartner = {
        id: shippingPartnerObj.id,
        partner_name: shippingPartnerObj.partner_name,
        partner_code: shippingPartnerObj.partner_code,
        status: shippingPartnerObj.status,
        description: shippingPartnerObj.description,
        created_at: toISOStringSafe(shippingPartnerObj.created_at),
        updated_at: toISOStringSafe(shippingPartnerObj.updated_at),
        deleted_at: shippingPartnerObj.deleted_at
          ? toISOStringSafe(shippingPartnerObj.deleted_at)
          : undefined,
      };
    }
  }
  // Compose order summary
  const orderSummary = order && {
    id: order.id,
    order_number: order.order_number,
    status: order.status,
    total_amount: order.total_amount,
    currency: order.currency,
    created_at: toISOStringSafe(order.created_at),
    updated_at: toISOStringSafe(order.updated_at),
    deleted_at: order.deleted_at
      ? toISOStringSafe(order.deleted_at)
      : undefined,
  };

  // Compose orderItem summary only if we have both orderItem and sku
  let orderItemSummary = undefined;
  if (orderItem && sku) {
    // For code, use sku.sku_code; for the rest, provide minimal mock or blank values
    const skuSummary = {
      id: sku.id,
      code: sku.sku_code, // sku_code
      product_title: "", // unavailable, set as blank string
      option_summary: "", // unavailable, set as blank string
      in_stock: false, // unavailable, set as default false
    };
    orderItemSummary = {
      id: orderItem.id,
      shopping_mall_order_id: orderItem.shopping_mall_order_id,
      sku: skuSummary,
      quantity: orderItem.quantity,
      unit_price: orderItem.unit_price,
      subtotal: orderItem.subtotal,
      currency: orderItem.currency,
      delivered: orderItem.delivered,
      refunded: orderItem.refunded,
      created_at: toISOStringSafe(orderItem.created_at),
      updated_at: toISOStringSafe(orderItem.updated_at),
    };
  }

  return {
    id: updated.id,
    order: orderSummary!,
    orderItem: orderItemSummary!,
    requestedByCustomer: requestedByCustomer ?? undefined,
    requestedBySeller: requestedBySeller ?? undefined,
    shippingPartner: shippingPartner ?? undefined,
    reason: updated.reason,
    status: updated.status,
    pickup_address:
      typeof updated.pickup_address !== "undefined"
        ? updated.pickup_address
        : undefined,
    scheduled_pickup_at:
      typeof updated.scheduled_pickup_at !== "undefined" &&
      updated.scheduled_pickup_at !== null
        ? toISOStringSafe(updated.scheduled_pickup_at)
        : updated.scheduled_pickup_at,
    provider_tracking_code:
      typeof updated.provider_tracking_code !== "undefined"
        ? updated.provider_tracking_code
        : undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    completed_at:
      typeof updated.completed_at !== "undefined" &&
      updated.completed_at !== null
        ? toISOStringSafe(updated.completed_at)
        : updated.completed_at,
    cancelled_at:
      typeof updated.cancelled_at !== "undefined" &&
      updated.cancelled_at !== null
        ? toISOStringSafe(updated.cancelled_at)
        : updated.cancelled_at,
    deleted_at:
      typeof updated.deleted_at !== "undefined" && updated.deleted_at !== null
        ? toISOStringSafe(updated.deleted_at)
        : updated.deleted_at,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProductAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductAttributeValue";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function putShoppingMallSellerSkusSkuIdAttributeValuesAttributeValueId(props: {
  seller: SellerPayload;
  skuId: string & tags.Format<"uuid">;
  attributeValueId: string & tags.Format<"uuid">;
  body: IShoppingMallProductAttributeValue.IUpdate;
}): Promise<IShoppingMallProductAttributeValue> {
  // 1. Find the attribute value mapping by id and validate sku
  const found =
    await MyGlobal.prisma.shopping_mall_product_attribute_values.findUnique({
      where: { id: props.attributeValueId },
    });
  if (!found || found.shopping_mall_product_sku_id !== props.skuId) {
    throw new HttpException(
      "Attribute value mapping not found for this SKU.",
      404,
    );
  }
  // 2. Ownership check via product.shopping_mall_seller_id
  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
    where: { id: props.skuId },
    select: { shopping_mall_product_id: true },
  });
  if (!sku) {
    throw new HttpException("Forbidden: You do not own this SKU.", 403);
  }
  const product = await MyGlobal.prisma.shopping_mall_products.findUnique({
    where: { id: sku.shopping_mall_product_id },
    select: { shopping_mall_seller_id: true },
  });
  if (!product || product.shopping_mall_seller_id !== props.seller.id) {
    throw new HttpException("Forbidden: You do not own this SKU.", 403);
  }
  // 3. Uniqueness check if changing attribute id
  const newAttributeId =
    props.body.shopping_mall_product_attribute_id ??
    found.shopping_mall_product_attribute_id;
  if (
    props.body.shopping_mall_product_attribute_id !== undefined &&
    newAttributeId !== found.shopping_mall_product_attribute_id
  ) {
    const duplicate =
      await MyGlobal.prisma.shopping_mall_product_attribute_values.findFirst({
        where: {
          shopping_mall_product_sku_id: props.skuId,
          shopping_mall_product_attribute_id: newAttributeId,
          NOT: { id: props.attributeValueId },
        },
      });
    if (duplicate) {
      throw new HttpException(
        "Duplicate mapping: (SKU, Attribute) pair already exists.",
        409,
      );
    }
  }
  // 4. Perform update
  const updated =
    await MyGlobal.prisma.shopping_mall_product_attribute_values.update({
      where: { id: props.attributeValueId },
      data: {
        ...(props.body.value_display_name !== undefined
          ? { value_display_name: props.body.value_display_name }
          : {}),
        ...(props.body.shopping_mall_product_attribute_id !== undefined
          ? {
              shopping_mall_product_attribute_id:
                props.body.shopping_mall_product_attribute_id,
            }
          : {}),
        updated_at: toISOStringSafe(new Date()),
      },
    });
  // 5. Return DTO formatted result
  return {
    id: updated.id,
    shopping_mall_product_sku_id: updated.shopping_mall_product_sku_id,
    shopping_mall_product_attribute_id:
      updated.shopping_mall_product_attribute_id,
    value_display_name: updated.value_display_name,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IPageIShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAdmin";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminAdmins(props: {
  admin: AdminPayload;
  body: IShoppingMallAdmin.IRequest;
}): Promise<IPageIShoppingMallAdmin.ISummary> {
  const {
    email,
    name,
    status,
    is_email_verified,
    created_from,
    created_to,
    updated_from,
    updated_to,
    page,
    limit,
    sort_by,
    sort_order,
  } = props.body;

  const where: Record<string, unknown> = {};

  if (email !== undefined) {
    where.email = { contains: email, mode: "insensitive" };
  }
  if (name !== undefined) {
    where.name = { contains: name, mode: "insensitive" };
  }
  if (status !== undefined) {
    const statuses = status
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
    if (statuses.length === 1) where.status = statuses[0];
    else if (statuses.length > 1) where.status = { in: statuses };
  }
  if (is_email_verified !== undefined) {
    where.is_email_verified = is_email_verified;
  }

  if (created_from !== undefined || created_to !== undefined) {
    const createdAtFilter: Record<string, unknown> = {};
    if (created_from !== undefined) {
      createdAtFilter.gte = toISOStringSafe(created_from);
    }
    if (created_to !== undefined) {
      createdAtFilter.lte = toISOStringSafe(created_to);
    }
    if (Object.keys(createdAtFilter).length > 0) {
      where.created_at = createdAtFilter;
    }
  }
  if (updated_from !== undefined || updated_to !== undefined) {
    const updatedAtFilter: Record<string, unknown> = {};
    if (updated_from !== undefined) {
      updatedAtFilter.gte = toISOStringSafe(updated_from);
    }
    if (updated_to !== undefined) {
      updatedAtFilter.lte = toISOStringSafe(updated_to);
    }
    if (Object.keys(updatedAtFilter).length > 0) {
      where.updated_at = updatedAtFilter;
    }
  }

  const pageNumber = Number(page) || 1;
  const pageLimit = Number(limit) || 20;
  const offset = (pageNumber - 1) * pageLimit;

  const orderableFields = [
    "created_at",
    "updated_at",
    "email",
    "name",
    "status",
  ] as const;
  let finalSortBy = orderableFields.includes(
    (sort_by ?? "") as (typeof orderableFields)[number],
  )
    ? (sort_by as (typeof orderableFields)[number])
    : "created_at";
  let finalSortOrder =
    sort_order === "asc" || sort_order === "desc" ? sort_order : "desc";

  const [records, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_admins.findMany({
      where,
      skip: offset,
      take: pageLimit,
      orderBy: [{ [finalSortBy as string]: finalSortOrder }],
      select: {
        id: true,
        name: true,
        email: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_admins.count({ where }),
  ]);

  return {
    pagination: {
      current: pageNumber,
      limit: pageLimit,
      records: total,
      pages: Math.ceil(total / pageLimit),
    },
    data: records.map((admin) => ({
      id: admin.id,
      name: admin.name,
      email: admin.email,
    })),
  };
}

import { HttpException } from "@nestjs/common";
