export async function patchShoppingMallCustomerDisputesDisputeIdMessages(props: {
  customer: CustomerPayload;
  disputeId: string & tags.Format<"uuid">;
  body: IShoppingMallDisputeMessage.IRequest;
}): Promise<IPageIShoppingMallDisputeMessage.ISummary> {
  // 1. Authorization: Confirm dispute exists and is associated to customer
  const dispute = await MyGlobal.prisma.shopping_mall_disputes.findUnique({
    where: { id: props.disputeId, deleted_at: null },
    include: {
      customer: true,
      seller: true,
      admin: true,
    },
  });
  if (!dispute) throw new HttpException("Dispute not found", 404);
  if (dispute.shopping_mall_customer_id !== props.customer.id)
    throw new HttpException("Forbidden", 403);

  // 2. Where conditions from body
  const where: Record<string, unknown> = {
    shopping_mall_dispute_id: props.disputeId,
    deleted_at: null,
    ...(props.body.role && { role: props.body.role }),
    ...(props.body.sender_admin_id && {
      shopping_mall_sender_admin_id: props.body.sender_admin_id,
    }),
    ...(props.body.sender_seller_id && {
      shopping_mall_sender_seller_id: props.body.sender_seller_id,
    }),
    ...(props.body.sender_customer_id && {
      shopping_mall_sender_customer_id: props.body.sender_customer_id,
    }),
    ...(props.body.receiver_admin_id && {
      shopping_mall_receiver_admin_id: props.body.receiver_admin_id,
    }),
    ...(props.body.receiver_seller_id && {
      shopping_mall_receiver_seller_id: props.body.receiver_seller_id,
    }),
    ...(props.body.receiver_customer_id && {
      shopping_mall_receiver_customer_id: props.body.receiver_customer_id,
    }),
    ...(props.body.content_contains !== undefined &&
      props.body.content_contains !== null &&
      props.body.content_contains !== "" && {
        content: { contains: props.body.content_contains },
      }),
    ...(props.body.created_at_from && {
      created_at: { gte: props.body.created_at_from },
    }),
    ...(props.body.created_at_to && {
      created_at: {
        ...(props.body.created_at_from
          ? { gte: props.body.created_at_from }
          : {}),
        lte: props.body.created_at_to,
      },
    }),
  };

  // Build created_at filter for date ranges
  if (
    (props.body.created_at_from || props.body.created_at_to) &&
    !(props.body.created_at_from && props.body.created_at_to)
  ) {
    if (props.body.created_at_from) {
      where.created_at = { gte: props.body.created_at_from };
    } else if (props.body.created_at_to) {
      where.created_at = { lte: props.body.created_at_to };
    }
  } else if (props.body.created_at_from && props.body.created_at_to) {
    where.created_at = {
      gte: props.body.created_at_from,
      lte: props.body.created_at_to,
    };
  }

  // 3. Sorting
  let orderBy: Record<string, "asc" | "desc">[];
  if (props.body.sort_by === "role") {
    orderBy = [{ role: props.body.order || "asc" }];
  } else {
    orderBy = [{ created_at: props.body.order || "desc" }];
  }

  // 4. Pagination
  const page = props.body.page && props.body.page > 0 ? props.body.page : 1;
  const limit =
    props.body.limit && props.body.limit > 0 && props.body.limit <= 100
      ? props.body.limit
      : 100;
  const skip = (page - 1) * limit;

  const [messages, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_dispute_messages.findMany({
      where,
      orderBy,
      include: {
        senderAdmin: true,
        senderSeller: true,
        senderCustomer: true,
        receiverAdmin: true,
        receiverSeller: true,
        receiverCustomer: true,
      },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_dispute_messages.count({ where }),
  ]);

  const mapAdminSummary = (admin: any) =>
    admin
      ? ({
          id: admin.id,
          name: admin.name,
          email: admin.email,
        } satisfies IShoppingMallAdmin.ISummary)
      : ({ id: "", name: "", email: "" } satisfies IShoppingMallAdmin.ISummary);
  const mapSellerSummary = (seller: any) =>
    seller
      ? ({
          id: seller.id,
          business_name: seller.business_name,
        } satisfies IShoppingMallSeller.ISummary)
      : ({ id: "", business_name: "" } satisfies IShoppingMallSeller.ISummary);
  const mapCustomerSummary = (customer: any) =>
    customer
      ? ({
          id: customer.id,
          name: customer.name,
        } satisfies IShoppingMallCustomer.ISummary)
      : ({ id: "", name: "" } satisfies IShoppingMallCustomer.ISummary);

  const messageSummaries = messages.map((msg) => ({
    id: msg.id,
    dispute: {
      id: dispute.id,
      status: dispute.status,
      subject: dispute.subject,
      root_cause: dispute.root_cause,
      resolution_note: dispute.resolution_note ?? null,
      customer: mapCustomerSummary(dispute.customer),
      seller: mapSellerSummary(dispute.seller),
      admin: mapAdminSummary(dispute.admin),
      created_at: toISOStringSafe(dispute.created_at),
      updated_at: toISOStringSafe(dispute.updated_at),
      deleted_at: dispute.deleted_at
        ? toISOStringSafe(dispute.deleted_at)
        : null,
    },
    role: msg.role,
    content: msg.content,
    sender_admin: mapAdminSummary(msg.senderAdmin),
    sender_seller: mapSellerSummary(msg.senderSeller),
    sender_customer: mapCustomerSummary(msg.senderCustomer),
    receiver_admin: mapAdminSummary(msg.receiverAdmin),
    receiver_seller: mapSellerSummary(msg.receiverSeller),
    receiver_customer: mapCustomerSummary(msg.receiverCustomer),
    created_at: toISOStringSafe(msg.created_at),
    deleted_at: msg.deleted_at ? toISOStringSafe(msg.deleted_at) : null,
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: messageSummaries,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminJoin(props: {
  body: IShoppingMallAdmin.ICreate;
}): Promise<IShoppingMallAdmin.IAuthorized> {
  // 1. Check for duplicate email
  const duplicate = await MyGlobal.prisma.shopping_mall_admins.findFirst({
    where: { email: props.body.email },
  });
  if (duplicate) {
    throw new HttpException("Email already registered.", 409);
  }

  // 2. Hash the admin password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  // 3. Insert new admin record into the DB
  const now = toISOStringSafe(new Date());
  const admin = await MyGlobal.prisma.shopping_mall_admins.create({
    data: {
      id: v4(),
      email: props.body.email,
      password_hash: hashedPassword,
      name: props.body.name,
      is_email_verified: false,
      status: "active",
      created_at: now,
      updated_at: now,
    },
  });

  // 4. Insert session record for admin login
  const sessionId = v4();
  const accessExpiredAt = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpiredAt = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const session = await MyGlobal.prisma.shopping_mall_admin_sessions.create({
    data: {
      id: sessionId,
      shopping_mall_admin_id: admin.id,
      ip: "",
      href: "",
      referrer: "",
      created_at: now,
      expired_at: accessExpiredAt,
    },
  });

  // 5. Issue JWT tokens as per requirements
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: accessExpiredAt,
    refreshable_until: refreshExpiredAt,
  };

  // 6. Return admin authorized DTO
  return {
    id: admin.id,
    email: admin.email,
    name: admin.name,
    is_email_verified: admin.is_email_verified,
    status: admin.status,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthSellerJoin(props: {
  body: IShoppingMallSeller.ICreate;
}): Promise<IShoppingMallSeller.IAuthorized> {
  // Duplicate check - email
  const existingByEmail = await MyGlobal.prisma.shopping_mall_sellers.findFirst(
    {
      where: { email: props.body.email },
    },
  );
  if (existingByEmail) {
    throw new HttpException("Email already registered", 409);
  }
  // Duplicate check - registration_number
  const existingByRegNum =
    await MyGlobal.prisma.shopping_mall_sellers.findFirst({
      where: { registration_number: props.body.registration_number },
    });
  if (existingByRegNum) {
    throw new HttpException("Registration number already registered", 409);
  }
  const now = toISOStringSafe(new Date());
  const sellerId = v4();
  const hashedPassword = await PasswordUtil.hash(props.body.password);
  const seller = await MyGlobal.prisma.shopping_mall_sellers.create({
    data: {
      id: sellerId,
      email: props.body.email,
      password_hash: hashedPassword,
      business_name: props.body.business_name,
      registration_number: props.body.registration_number,
      business_phone: props.body.business_phone,
      is_email_verified: false,
      status: "pending",
      created_at: now,
      updated_at: now,
    },
  });
  const sessionId = v4();
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const session = await MyGlobal.prisma.shopping_mall_seller_sessions.create({
    data: {
      id: sessionId,
      shopping_mall_seller_id: seller.id,
      ip:
        props.body.ip == null
          ? "unknown"
          : (props.body.ip satisfies string as string),
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: toISOStringSafe(accessExpires),
    },
  });
  const accessToken = jwt.sign(
    {
      type: "seller",
      id: seller.id,
      session_id: session.id,
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const refreshToken = jwt.sign(
    {
      type: "seller",
      id: seller.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );
  return {
    id: seller.id,
    email: seller.email,
    business_name: seller.business_name,
    registration_number: seller.registration_number,
    business_phone: seller.business_phone,
    is_email_verified: seller.is_email_verified,
    status: seller.status,
    created_at: toISOStringSafe(seller.created_at),
    updated_at: toISOStringSafe(seller.updated_at),
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
    seller: {
      id: seller.id,
      business_name: seller.business_name,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerOrdersOrderNumberItems(props: {
  customer: CustomerPayload;
  orderNumber: string;
  body: IShoppingMallOrderItem.ICreate;
}): Promise<IShoppingMallOrderItem> {
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      order_number: props.orderNumber,
      deleted_at: null,
      shopping_mall_customer_id: props.customer.id,
    },
  });
  if (!order) {
    throw new HttpException("Order not found or not owned by customer", 404);
  }

  const product = await MyGlobal.prisma.shopping_mall_products.findFirst({
    where: {
      id: props.body.shopping_mall_product_id,
      deleted_at: null,
      business_status: "published",
    },
  });
  if (!product) {
    throw new HttpException("Invalid or unavailable product.", 400);
  }

  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findFirst({
    where: {
      id: props.body.shopping_mall_product_sku_id,
      shopping_mall_product_id: product.id,
      deleted_at: null,
      status: "active",
    },
  });
  if (!sku) {
    throw new HttpException(
      "SKU not found, inactive, or not part of specified product.",
      400,
    );
  }
  if (sku.stock < props.body.quantity) {
    throw new HttpException(
      "Insufficient inventory for the requested SKU.",
      400,
    );
  }

  const duplicateItem =
    await MyGlobal.prisma.shopping_mall_order_items.findFirst({
      where: {
        shopping_mall_order_id: order.id,
        shopping_mall_product_sku_id: sku.id,
        deleted_at: null,
      },
    });
  if (duplicateItem) {
    throw new HttpException("This SKU is already added to the order.", 409);
  }

  const expectedSubtotal = props.body.quantity * props.body.unit_price;
  if (props.body.subtotal !== expectedSubtotal) {
    throw new HttpException(
      "Subtotal does not match quantity × unit_price.",
      400,
    );
  }

  const now = toISOStringSafe(new Date());
  const createdItem = await MyGlobal.prisma.$transaction(async (tx) => {
    const newItem = await tx.shopping_mall_order_items.create({
      data: {
        id: v4(),
        shopping_mall_order_id: order.id,
        shopping_mall_product_id: product.id,
        shopping_mall_product_sku_id: sku.id,
        quantity: props.body.quantity,
        unit_price: props.body.unit_price,
        subtotal: props.body.subtotal,
        currency: props.body.currency,
        delivered: props.body.delivered,
        refunded: props.body.refunded,
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    });
    // Decrease stock for SKU
    await tx.shopping_mall_product_skus.update({
      where: { id: sku.id },
      data: { stock: sku.stock - props.body.quantity, updated_at: now },
    });
    return newItem;
  });

  const orderSummary = {
    id: order.id,
    order_number: order.order_number,
    status: order.status,
    total_amount: order.total_amount,
    currency: order.currency,
    created_at: toISOStringSafe(order.created_at),
    updated_at: toISOStringSafe(order.updated_at),
    deleted_at: order.deleted_at ? toISOStringSafe(order.deleted_at) : null,
  };

  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: product.shopping_mall_seller_id },
  });

  // Build product summary and only assign 'seller' if defined
  const productSummary: any = {
    id: product.id,
    title: product.title,
    default_price: product.default_price,
    business_status: product.business_status,
    categories: [], // Category lookup omitted for brevity
    created_at: toISOStringSafe(product.created_at),
  };
  if (seller) {
    productSummary.seller = {
      id: seller.id,
      business_name: seller.business_name,
      categories: [],
      created_at: null,
    };
  }
  const skuSummary = {
    id: sku.id,
    code: sku.sku_code,
    product_title: product.title,
    option_summary: "",
    in_stock: sku.stock - props.body.quantity > 0,
  };

  return {
    id: createdItem.id,
    order: orderSummary,
    product: productSummary,
    sku: skuSummary,
    quantity: createdItem.quantity,
    unit_price: createdItem.unit_price,
    subtotal: createdItem.subtotal,
    currency: createdItem.currency,
    delivered: createdItem.delivered,
    refunded: createdItem.refunded,
    created_at: toISOStringSafe(createdItem.created_at),
    updated_at: toISOStringSafe(createdItem.updated_at),
    deleted_at: createdItem.deleted_at
      ? toISOStringSafe(createdItem.deleted_at)
      : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postShoppingMallSellerOrdersOrderNumberItems(props: {
  seller: SellerPayload;
  orderNumber: string;
  body: IShoppingMallOrderItem.ICreate;
}): Promise<IShoppingMallOrderItem> {
  // 1. Find the target order
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      order_number: props.orderNumber,
      shopping_mall_seller_id: props.seller.id,
      deleted_at: null,
    },
  });
  if (!order) {
    throw new HttpException("Order not found or access denied.", 404);
  }

  // 2. Find and check the product
  const product = await MyGlobal.prisma.shopping_mall_products.findFirst({
    where: {
      id: props.body.shopping_mall_product_id,
      shopping_mall_seller_id: props.seller.id,
      deleted_at: null,
      NOT: { business_status: { in: ["archived", "blocked"] } },
    },
  });
  if (!product) {
    throw new HttpException("Product not found or unavailable.", 404);
  }

  // 3. Find and check the SKU
  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findFirst({
    where: {
      id: props.body.shopping_mall_product_sku_id,
      shopping_mall_product_id: product.id,
      deleted_at: null,
      NOT: { status: { in: ["archived", "out_of_stock"] } },
    },
  });
  if (!sku) {
    throw new HttpException("SKU not found or unavailable.", 404);
  }
  if (sku.stock < props.body.quantity) {
    throw new HttpException("Insufficient inventory for this SKU.", 409);
  }

  // 4. Uniqueness: ensure no duplicate item for this order and SKU
  const existingItem =
    await MyGlobal.prisma.shopping_mall_order_items.findFirst({
      where: {
        shopping_mall_order_id: order.id,
        shopping_mall_product_sku_id: sku.id,
        deleted_at: null,
      },
    });
  if (existingItem) {
    throw new HttpException(
      "Item for this SKU already exists in the order.",
      409,
    );
  }

  // 5. Transaction: insert the order item and update SKU inventory
  let createdItem: any = undefined;
  try {
    const now = toISOStringSafe(new Date());
    await MyGlobal.prisma.$transaction(async (tx) => {
      createdItem = await tx.shopping_mall_order_items.create({
        data: {
          id: v4(),
          shopping_mall_order_id: order.id,
          shopping_mall_product_id: product.id,
          shopping_mall_product_sku_id: sku.id,
          quantity: props.body.quantity,
          unit_price: props.body.unit_price,
          subtotal: props.body.subtotal,
          currency: props.body.currency,
          delivered: props.body.delivered,
          refunded: props.body.refunded,
          created_at: now,
          updated_at: now,
          deleted_at: null,
        },
      });
      await tx.shopping_mall_product_skus.update({
        where: { id: sku.id },
        data: { stock: sku.stock - props.body.quantity, updated_at: now },
      });
    });
  } catch (err) {
    throw new HttpException(
      "Failed to create order item (possibly duplicate or integrity error).",
      400,
    );
  }
  if (!createdItem) {
    throw new HttpException("Order item creation failed.", 500);
  }

  // 6. Compose summary objects for return DTO
  const orderSummary: IShoppingMallOrder.ISummary = {
    id: order.id,
    order_number: order.order_number,
    status: order.status,
    total_amount: order.total_amount,
    currency: order.currency,
    created_at: toISOStringSafe(order.created_at),
    updated_at: toISOStringSafe(order.updated_at),
    deleted_at:
      order.deleted_at !== null && order.deleted_at !== undefined
        ? toISOStringSafe(order.deleted_at)
        : null,
  };

  const sellerSummary: IShoppingMallSeller.ISummary = {
    id: product.shopping_mall_seller_id,
    business_name: (await MyGlobal.prisma.shopping_mall_sellers.findUnique({
      where: { id: product.shopping_mall_seller_id },
    }))!.business_name,
  };

  const productSummary: IShoppingMallProduct.ISummary = {
    id: product.id,
    title: product.title,
    default_price: product.default_price,
    business_status: product.business_status,
    seller: sellerSummary,
    categories: [],
    created_at: toISOStringSafe(product.created_at),
  };

  const skuSummary: IShoppingMallProductSku.ISummary = {
    id: sku.id,
    code: sku.sku_code,
    product_title: product.title,
    option_summary: "",
    in_stock: sku.stock - props.body.quantity > 0,
  };

  // 7. Return the fully composed IShoppingMallOrderItem
  return {
    id: createdItem.id,
    order: orderSummary,
    product: productSummary,
    sku: skuSummary,
    quantity: createdItem.quantity,
    unit_price: createdItem.unit_price,
    subtotal: createdItem.subtotal,
    currency: createdItem.currency,
    delivered: createdItem.delivered,
    refunded: createdItem.refunded,
    created_at: toISOStringSafe(createdItem.created_at),
    updated_at: toISOStringSafe(createdItem.updated_at),
    deleted_at:
      createdItem.deleted_at !== null && createdItem.deleted_at !== undefined
        ? toISOStringSafe(createdItem.deleted_at)
        : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminMallCategoriesName(props: {
  admin: AdminPayload;
  name: string;
  body: IShoppingMallCategory.IUpdate;
}): Promise<IShoppingMallCategory> {
  // Find existing category by name (unique constraint)
  const category = await MyGlobal.prisma.shopping_mall_categories.findUnique({
    where: { name: props.name },
  });
  if (!category) {
    throw new HttpException("Category not found", 404);
  }

  // Disallow attempts to update immutable system fields through body (enforced by type system)
  // But defensive code: if body (spread) happens to contain name/id/created_at/deleted_at, ignore those in update

  // If parent_id is present and not null, verify the referenced category exists
  let parentIdToSet = undefined;
  if ("parent_id" in props.body) {
    if (props.body.parent_id === null) {
      parentIdToSet = null;
    } else if (props.body.parent_id !== undefined) {
      // Verify referenced parent exists
      const parentCat =
        await MyGlobal.prisma.shopping_mall_categories.findUnique({
          where: { id: props.body.parent_id },
        });
      if (!parentCat) {
        throw new HttpException("Parent category does not exist", 400);
      }
      parentIdToSet = props.body.parent_id;
    }
  }

  // Only allow updates to description, sort_order, status, parent_id
  const updateFields: Record<string, unknown> = {};
  if (props.body.description !== undefined)
    updateFields.description = props.body.description;
  if (props.body.sort_order !== undefined)
    updateFields.sort_order = props.body.sort_order;
  if (props.body.status !== undefined) updateFields.status = props.body.status;
  if ("parent_id" in props.body) updateFields.parent_id = parentIdToSet;

  // Always update the audit timestamp
  updateFields.updated_at = new Date();

  const updated = await MyGlobal.prisma.shopping_mall_categories.update({
    where: { name: props.name },
    data: updateFields,
  });

  return {
    id: updated.id,
    name: updated.name,
    description: updated.description,
    sort_order: updated.sort_order,
    status: updated.status,
    parent_id: updated.parent_id === null ? null : updated.parent_id,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at:
      updated.deleted_at === null ? null : toISOStringSafe(updated.deleted_at),
  };
}

