export async function patchShoppingMallAdminShipments(props: {
  admin: AdminPayload;
  body: IShoppingMallShipment.IRequest;
}): Promise<IPageIShoppingMallShipment.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;

  const where: Record<string, any> = {};
  if (props.body.status) where.status = props.body.status;
  if (props.body.order_id) where.order_id = props.body.order_id;
  if (props.body.order_item_id) where.order_item_id = props.body.order_item_id;
  if (props.body.shipping_partner_id)
    where.shipping_partner_id = props.body.shipping_partner_id;
  if (props.body.carrier_tracking_code)
    where.carrier_tracking_code = {
      contains: props.body.carrier_tracking_code,
    };
  if (props.body.created_by_admin_id)
    where.created_by_admin_id = props.body.created_by_admin_id;
  if (props.body.created_by_seller_id)
    where.created_by_seller_id = props.body.created_by_seller_id;
  if (props.body.provider_response_code)
    where.provider_response_code = {
      contains: props.body.provider_response_code,
    };
  if (props.body.created_from || props.body.created_to) {
    where.created_at = {};
    if (props.body.created_from) where.created_at.gte = props.body.created_from;
    if (props.body.created_to) where.created_at.lte = props.body.created_to;
  }
  if (props.body.delivery_from || props.body.delivery_to) {
    where.delivery_at = {};
    if (props.body.delivery_from)
      where.delivery_at.gte = props.body.delivery_from;
    if (props.body.delivery_to) where.delivery_at.lte = props.body.delivery_to;
  }

  let orderBy: any = { created_at: "desc" };
  if (props.body.sort_by) {
    orderBy = { [props.body.sort_by]: props.body.sort_order ?? "desc" };
  }

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_shipments.findMany({
      where,
      skip,
      take: limit,
      orderBy,
      include: {
        order: true,
        orderItem: { include: { sku: true } },
        shippingPartner: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_shipments.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((row) => ({
      id: row.id,
      order: {
        id: row.order.id,
        order_number: row.order.order_number,
        status: row.order.status,
        total_amount: row.order.total_amount,
        currency: row.order.currency,
        created_at: toISOStringSafe(row.order.created_at),
        updated_at: toISOStringSafe(row.order.updated_at),
        deleted_at: row.order.deleted_at
          ? toISOStringSafe(row.order.deleted_at)
          : undefined,
      },
      orderItem: {
        id: row.orderItem.id,
        shopping_mall_order_id: row.orderItem.shopping_mall_order_id,
        sku: {
          id: row.orderItem.sku.id,
          code:
            row.orderItem.sku.sku_code ?? (row.orderItem.sku as any).code ?? "",
          product_title: (row.orderItem.sku as any).product_title ?? "",
          option_summary: (row.orderItem.sku as any).option_summary ?? "",
          in_stock: (row.orderItem.sku as any).in_stock ?? true,
        },
        quantity: row.orderItem.quantity,
        unit_price: row.orderItem.unit_price,
        subtotal: row.orderItem.subtotal,
        currency: row.orderItem.currency,
        delivered: row.orderItem.delivered,
        refunded: row.orderItem.refunded,
        created_at: toISOStringSafe(row.orderItem.created_at),
        updated_at: toISOStringSafe(row.orderItem.updated_at),
      },
      shippingPartner: {
        id: row.shippingPartner.id,
        partner_name: row.shippingPartner.partner_name,
        partner_code: row.shippingPartner.partner_code,
        status: row.shippingPartner.status,
        description: row.shippingPartner.description,
        created_at: toISOStringSafe(row.shippingPartner.created_at),
        updated_at: toISOStringSafe(row.shippingPartner.updated_at),
        deleted_at: row.shippingPartner.deleted_at
          ? toISOStringSafe(row.shippingPartner.deleted_at)
          : undefined,
      },
      status: typia.assert<
        | "pending"
        | "ready"
        | "picked_up"
        | "in_transit"
        | "delivered"
        | "cancelled"
        | "returned"
      >(row.status),
      carrier_tracking_code:
        typeof row.carrier_tracking_code === "string"
          ? row.carrier_tracking_code
          : undefined,
      created_at: toISOStringSafe(row.created_at),
      delivery_at: row.delivery_at
        ? toISOStringSafe(row.delivery_at)
        : undefined,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import { IPageIShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCartItem";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingMallCustomerCartsCartIdItems(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  body: IShoppingMallCartItem.IRequest;
}): Promise<IPageIShoppingMallCartItem.ISummary> {
  const page = props.body.page;
  const limit = props.body.limit;
  const skip = (page - 1) * limit;

  // Filtering
  const where: Record<string, unknown> = {
    shopping_mall_cart_id: props.cartId,
  };
  if (typeof props.body.sku_id === "string") {
    where["shopping_mall_product_sku_id"] = props.body.sku_id;
  }
  if (props.body.min_quantity !== undefined) {
    where["quantity"] = Object.assign(where["quantity"] || {}, {
      gte: props.body.min_quantity,
    });
  }
  if (props.body.max_quantity !== undefined) {
    where["quantity"] = Object.assign(where["quantity"] || {}, {
      lte: props.body.max_quantity,
    });
  }

  // Sorting
  let orderBy: Record<string, "asc" | "desc"> = { updated_at: "desc" };
  if (props.body.sort_by) {
    orderBy = { [props.body.sort_by]: props.body.sort_order || "desc" };
  }

  // Confirm cart ownership
  const cart = await MyGlobal.prisma.shopping_mall_carts.findFirst({
    where: {
      id: props.cartId,
      shopping_mall_customer_id: props.customer.id,
    },
  });
  if (cart === null) {
    throw new HttpException(
      "Cart not found or not owned by the customer.",
      404,
    );
  }
  // Query the items and count
  const [items, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_cart_items.findMany({
      where,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.shopping_mall_cart_items.count({ where }),
  ]);

  // Gather SKU IDs
  const skuIds = Array.from(
    new Set(items.map((item) => item.shopping_mall_product_sku_id)),
  );
  let skuMap: Record<string, IShoppingMallProductSku.ISummary> = {};
  if (skuIds.length > 0) {
    const skus = await MyGlobal.prisma.shopping_mall_product_skus.findMany({
      where: { id: { in: skuIds } },
      select: {
        id: true,
        sku_code: true,
        status: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
        shopping_mall_product_id: true,
        price: true,
        stock: true,
      },
    });
    skuMap = skus.reduce(
      (acc, sku) => {
        acc[sku.id] = {
          id: sku.id,
          code: sku.sku_code ?? "",
          product_title: "", // Not available, fallback to empty string
          option_summary: "", // Not available, fallback to empty string
          in_stock: sku.status === "enabled" && sku.stock > 0,
        };
        return acc;
      },
      {} as Record<string, IShoppingMallProductSku.ISummary>,
    );
  }

  const data = items.map((item) => ({
    id: item.id,
    shopping_mall_cart_id: item.shopping_mall_cart_id,
    sku: skuMap[item.shopping_mall_product_sku_id] ?? {
      id: item.shopping_mall_product_sku_id,
      code: "",
      product_title: "",
      option_summary: "",
      in_stock: false,
    },
    quantity: item.quantity,
    created_at: toISOStringSafe(item.created_at),
    updated_at: toISOStringSafe(item.updated_at),
  }));
  return {
    pagination: {
      current: page satisfies number as number,
      limit: limit satisfies number as number,
      records: total,
      pages: limit === 0 ? 0 : Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProductRating } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductRating";
import { IPageIShoppingMallProductRating } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductRating";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingMallSellerProductRatings(props: {
  seller: SellerPayload;
  body: IShoppingMallProductRating.IRequest;
}): Promise<IPageIShoppingMallProductRating.ISummary> {
  const {
    shopping_mall_product_rating_id,
    shopping_mall_customer_id,
    shopping_mall_customer_session_id,
    shopping_mall_product_id,
    shopping_mall_product_sku_id,
    shopping_mall_order_id,
    shopping_mall_order_item_id,
    value,
    created_at,
    updated_at,
    deleted_at,
    page = 1,
    limit = 100,
    sort_by = "created_at",
    sort_order = "desc",
  } = props.body;
  const skip = (page - 1) * limit;
  // Get set of this seller's product ids
  const productRows = await MyGlobal.prisma.shopping_mall_products.findMany({
    where: {
      shopping_mall_seller_id: props.seller.id,
      deleted_at: null,
    },
    select: { id: true },
  });
  const productIdSet = new Set(productRows.map((p) => p.id));
  if (productIdSet.size === 0) {
    return {
      data: [],
      pagination: {
        current: page,
        limit: limit,
        records: 0,
        pages: 1,
      },
    };
  }
  // Get SKUs for the seller's products
  const skuRows = await MyGlobal.prisma.shopping_mall_product_skus.findMany({
    where: {
      shopping_mall_product_id: { in: Array.from(productIdSet) },
      deleted_at: null,
    },
    select: { id: true },
  });
  const skuIdSet = new Set(skuRows.map((s) => s.id));
  if (skuIdSet.size === 0) {
    return {
      data: [],
      pagination: {
        current: page,
        limit: limit,
        records: 0,
        pages: 1,
      },
    };
  }
  // Build Prisma where condition
  const where: Record<string, any> = {
    id: shopping_mall_product_rating_id,
    shopping_mall_customer_id,
    shopping_mall_customer_session_id,
    shopping_mall_product_id: shopping_mall_product_id
      ? shopping_mall_product_id
      : undefined,
    shopping_mall_product_sku_id: shopping_mall_product_sku_id
      ? shopping_mall_product_sku_id
      : { in: Array.from(skuIdSet) },
    shopping_mall_order_id,
    shopping_mall_order_item_id,
    value,
    created_at: created_at ? new Date(created_at) : undefined,
    updated_at: updated_at ? new Date(updated_at) : undefined,
    deleted_at: deleted_at === undefined ? null : deleted_at,
  };
  Object.keys(where).forEach((key) => {
    if (where[key] === undefined) delete where[key];
  });
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_product_ratings.findMany({
      where,
      skip,
      take: limit,
      orderBy: { [sort_by]: sort_order },
    }),
    MyGlobal.prisma.shopping_mall_product_ratings.count({ where }),
  ]);
  if (rows.length === 0) {
    return {
      data: [],
      pagination: {
        current: page,
        limit: limit,
        records: total,
        pages: Math.max(1, Math.ceil(total / limit)),
      },
    };
  }
  const customerIds = Array.from(
    new Set(rows.map((r) => r.shopping_mall_customer_id)),
  );
  const prodIds = Array.from(
    new Set(rows.map((r) => r.shopping_mall_product_id)),
  );
  const skuIds = Array.from(
    new Set(rows.map((r) => r.shopping_mall_product_sku_id)),
  );
  // Batch fetch references
  const [customers, products, skus] = await Promise.all([
    MyGlobal.prisma.shopping_mall_customers.findMany({
      where: { id: { in: customerIds } },
      select: { id: true, name: true },
    }),
    MyGlobal.prisma.shopping_mall_products.findMany({
      where: { id: { in: prodIds } },
      select: {
        id: true,
        title: true,
        default_price: true,
        business_status: true,
        shopping_mall_seller_id: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_product_skus.findMany({
      where: { id: { in: skuIds } },
      select: {
        id: true,
        sku_code: true,
        shopping_mall_product_id: true,
        stock: true,
      },
    }),
  ]);
  const customerMap: Record<string, { id: string; name: string }> = {};
  customers.forEach((c) => {
    customerMap[c.id] = c;
  });
  const productMap: Record<string, (typeof products)[0]> = {};
  products.forEach((p) => {
    productMap[p.id] = p;
  });
  const skuMap: Record<string, (typeof skus)[0]> = {};
  skus.forEach((s) => {
    skuMap[s.id] = s;
  });
  const sellerSummary = {
    id: props.seller.id,
    business_name: "", // No business_name field in schema, fallback to empty string
  };
  const data = rows.map((r) => {
    const prod = productMap[r.shopping_mall_product_id];
    const sku = skuMap[r.shopping_mall_product_sku_id];
    const customer = customerMap[r.shopping_mall_customer_id];
    return {
      id: r.id,
      value: r.value,
      created_at: toISOStringSafe(r.created_at),
      updated_at: toISOStringSafe(r.updated_at),
      deleted_at:
        r.deleted_at === null ? undefined : toISOStringSafe(r.deleted_at),
      customer: customer
        ? { id: customer.id, name: customer.name }
        : { id: r.shopping_mall_customer_id, name: "" },
      product: prod
        ? {
            id: prod.id,
            title: prod.title,
            default_price: prod.default_price,
            business_status: prod.business_status,
            seller: sellerSummary,
            categories: [],
            created_at: toISOStringSafe(prod.created_at),
          }
        : {
            id: r.shopping_mall_product_id,
            title: "",
            default_price: 0,
            business_status: "",
            seller: sellerSummary,
            categories: [],
            created_at: toISOStringSafe(new Date()),
          },
      productSku: sku
        ? {
            id: sku.id,
            code: sku.sku_code,
            product_title: prod ? prod.title : "",
            option_summary: "",
            in_stock: sku.stock > 0,
          }
        : {
            id: r.shopping_mall_product_sku_id,
            code: "",
            product_title: prod ? prod.title : "",
            option_summary: "",
            in_stock: false,
          },
    };
  });
  return {
    data,
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.max(1, Math.ceil(total / limit)),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductAttribute";
import { IPageIShoppingMallProductAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductAttribute";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingMallSellerProductsProductIdAttributes(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  body: IShoppingMallProductAttribute.IRequest;
}): Promise<IPageIShoppingMallProductAttribute.ISummary> {
  // 1. Ownership authorization
  const product = await MyGlobal.prisma.shopping_mall_products.findUnique({
    where: { id: props.productId, deleted_at: null },
    include: {
      seller: true,
    },
  });
  if (!product) {
    throw new HttpException("Product not found", 404);
  }
  if (product.shopping_mall_seller_id !== props.seller.id) {
    throw new HttpException("Forbidden", 403);
  }

  // 2. Fetch categories separately
  const productCategories =
    await MyGlobal.prisma.shopping_mall_products_categories.findMany({
      where: { shopping_mall_product_id: props.productId },
      include: { category: true },
    });
  const categorySummaries = productCategories.map((x: any) => ({
    id: x.category.id,
    name: x.category.name,
  }));

  // 3. Filters
  const filters: Record<string, unknown> = {
    shopping_mall_product_id: props.productId,
    deleted_at: null,
  };
  if (typeof props.body.search === "string" && props.body.search.length > 0) {
    filters.attribute_name = { contains: props.body.search };
  }
  if (typeof props.body.position === "number") {
    filters.position = props.body.position;
  }

  // 4. Sorting
  let orderBy = { position: "asc" } as const;
  if (typeof props.body.sort === "string") {
    if (props.body.sort === "attribute_name") {
      orderBy = { attribute_name: "asc" } as any;
    } else if (props.body.sort === "-attribute_name") {
      orderBy = { attribute_name: "desc" } as any;
    } else if (props.body.sort === "-position") {
      orderBy = { position: "desc" } as any;
    }
  }

  // 5. Pagination
  const page = props.body.page > 0 ? props.body.page : 1;
  const limit = props.body.limit > 0 ? props.body.limit : 10;
  const skip = (page - 1) * limit;

  // 6. Data and total
  const [attributes, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_product_attributes.findMany({
      where: filters,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_product_attributes.count({ where: filters }),
  ]);

  // 7. Response mapping
  const sellerSummary = {
    id: (product as any).seller.id,
    business_name: (product as any).seller.business_name,
  };
  const productSummary = {
    id: product.id,
    title: product.title,
    default_price: product.default_price,
    business_status: product.business_status,
    seller: sellerSummary,
    categories: categorySummaries,
    created_at: toISOStringSafe(product.created_at),
  };
  return {
    pagination: {
      current: page satisfies number as number,
      limit: limit satisfies number as number,
      records: total satisfies number as number,
      pages: Math.ceil(total / limit) satisfies number as number,
    },
    data: attributes.map((a) => ({
      id: a.id,
      product: productSummary,
      attribute_name: a.attribute_name,
      position: a.position,
      created_at: toISOStringSafe(a.created_at),
      updated_at: toISOStringSafe(a.updated_at),
      deleted_at: a.deleted_at ? toISOStringSafe(a.deleted_at) : null,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerCartsCartIdItems(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  body: IShoppingMallCartItem.ICreate;
}): Promise<IShoppingMallCartItem> {
  // 1. Validate cart existence and ownership
  const cart = await MyGlobal.prisma.shopping_mall_carts.findUnique({
    where: { id: props.cartId },
    select: { id: true, shopping_mall_customer_id: true },
  });
  if (!cart || cart.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException(
      "Cart does not exist or you do not own this cart.",
      403,
    );
  }

  // 2. Validate SKU existence and status
  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findFirst({
    where: {
      id: props.body.shopping_mall_product_sku_id,
      deleted_at: null,
    },
    select: {
      id: true,
      sku_code: true,
      stock: true,
      status: true,
      shopping_mall_product_id: true,
    },
  });
  if (!sku) {
    throw new HttpException("Product SKU not found.", 404);
  }
  if (sku.status !== "active") {
    throw new HttpException("SKU is not available for sale.", 409);
  }
  if (sku.stock < props.body.quantity) {
    throw new HttpException(
      "Requested quantity cannot exceed SKU inventory.",
      409,
    );
  }

  // 3. Enforce unique SKU per cart constraint
  const duplicate = await MyGlobal.prisma.shopping_mall_cart_items.findUnique({
    where: {
      shopping_mall_cart_id_shopping_mall_product_sku_id: {
        shopping_mall_cart_id: props.cartId,
        shopping_mall_product_sku_id: props.body.shopping_mall_product_sku_id,
      },
    },
  });
  if (duplicate) {
    throw new HttpException(
      "This SKU already exists in the cart. Use update instead.",
      409,
    );
  }

  // 4. Create cart item with proper datetime and uuid formatting
  const now: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(),
  ) as string & tags.Format<"date-time">;
  const cartItemId: string & tags.Format<"uuid"> = v4() as string &
    tags.Format<"uuid">;

  const created = await MyGlobal.prisma.shopping_mall_cart_items.create({
    data: {
      id: cartItemId,
      shopping_mall_cart_id: props.cartId,
      shopping_mall_product_sku_id: props.body.shopping_mall_product_sku_id,
      quantity: props.body.quantity,
      created_at: now,
      updated_at: now,
    },
  });

  // 5. Query the product title for the summary
  const product = await MyGlobal.prisma.shopping_mall_products.findUnique({
    where: { id: sku.shopping_mall_product_id },
    select: { title: true },
  });
  if (!product) {
    throw new HttpException("Product not found for SKU.", 500);
  }

  // Assemble productSku summary
  const productSkuSummary = {
    id: sku.id,
    code: sku.sku_code,
    product_title: product.title,
    option_summary: sku.sku_code,
    in_stock: sku.stock > 0 && sku.status === "active",
  };

  return {
    id: created.id,
    shopping_mall_cart_id: created.shopping_mall_cart_id,
    quantity: created.quantity,
    created_at: toISOStringSafe(created.created_at) as string &
      tags.Format<"date-time">,
    updated_at: toISOStringSafe(created.updated_at) as string &
      tags.Format<"date-time">,
    productSku: productSkuSummary,
  };
}

