export async function postShoppingMallSellerShipments(props: {
  seller: SellerPayload;
  body: IShoppingMallShipment.ICreate;
}): Promise<IShoppingMallShipment> {
  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: { id: props.body.order_id },
  });
  if (!order) {
    throw new HttpException("Order not found.", 404);
  }

  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findUnique({
    where: { id: props.body.order_item_id },
  });
  if (!orderItem) {
    throw new HttpException("Order item not found.", 404);
  }
  if (orderItem.shopping_mall_order_id !== props.body.order_id) {
    throw new HttpException(
      "Order item does not belong to the specified order.",
      409,
    );
  }

  const partner =
    await MyGlobal.prisma.shopping_mall_shipping_partners.findUnique({
      where: { id: props.body.shipping_partner_id },
    });
  if (!partner || partner.status !== "active" || partner.deleted_at !== null) {
    throw new HttpException("Shipping partner is not available.", 400);
  }

  if (props.body.created_by_admin_id) {
    throw new HttpException(
      "Sellers cannot create admin-attributed shipments.",
      400,
    );
  }

  const now = toISOStringSafe(new Date());

  const shipment = await MyGlobal.prisma.shopping_mall_shipments.create({
    data: {
      id: v4(),
      order_id: props.body.order_id,
      order_item_id: props.body.order_item_id,
      shipping_partner_id: props.body.shipping_partner_id,
      carrier_tracking_code: props.body.carrier_tracking_code ?? null,
      status: props.body.status,
      manifest_url: props.body.manifest_url ?? null,
      provider_response_code: props.body.provider_response_code ?? null,
      created_by_admin_id: null,
      created_by_seller_id: props.seller.id,
      created_at: now,
      updated_at: now,
      delivery_at: props.body.status === "delivered" ? now : null,
      cancelled_at: props.body.status === "cancelled" ? now : null,
    },
  });

  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
    where: { id: orderItem.shopping_mall_product_sku_id },
  });
  if (!sku) {
    throw new HttpException("SKU not found.", 404);
  }

  const sellerEntity = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: props.seller.id },
  });

  return {
    id: shipment.id,
    order: {
      id: order.id,
      order_number: order.order_number,
      status: order.status,
      total_amount: order.total_amount,
      currency: order.currency,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      deleted_at:
        order.deleted_at !== null && order.deleted_at !== undefined
          ? toISOStringSafe(order.deleted_at)
          : undefined,
    },
    orderItem: {
      id: orderItem.id,
      shopping_mall_order_id: orderItem.shopping_mall_order_id,
      sku: {
        id: sku.id,
        code: sku.sku_code,
        product_title: "",
        option_summary: "",
        in_stock: sku.stock > 0,
      },
      quantity: orderItem.quantity,
      unit_price: orderItem.unit_price,
      subtotal: orderItem.subtotal,
      currency: orderItem.currency,
      delivered: orderItem.delivered,
      refunded: orderItem.refunded,
      created_at: toISOStringSafe(orderItem.created_at),
      updated_at: toISOStringSafe(orderItem.updated_at),
    },
    shippingPartner: {
      id: partner.id,
      partner_name: partner.partner_name,
      partner_code: partner.partner_code,
      status: partner.status,
      description: partner.description,
      created_at: toISOStringSafe(partner.created_at),
      updated_at: toISOStringSafe(partner.updated_at),
      deleted_at:
        partner.deleted_at !== null && partner.deleted_at !== undefined
          ? toISOStringSafe(partner.deleted_at)
          : undefined,
    },
    carrier_tracking_code:
      shipment.carrier_tracking_code !== null &&
      shipment.carrier_tracking_code !== undefined
        ? shipment.carrier_tracking_code
        : undefined,
    status: typia.assert<
      | "delivered"
      | "pending"
      | "ready"
      | "picked_up"
      | "in_transit"
      | "cancelled"
      | "returned"
    >(shipment.status),
    manifest_url:
      shipment.manifest_url !== null && shipment.manifest_url !== undefined
        ? shipment.manifest_url
        : undefined,
    provider_response_code:
      shipment.provider_response_code !== null &&
      shipment.provider_response_code !== undefined
        ? shipment.provider_response_code
        : undefined,
    createdByAdmin: undefined,
    createdBySeller: sellerEntity
      ? {
          id: sellerEntity.id,
          business_name: sellerEntity.business_name,
        }
      : undefined,
    created_at: toISOStringSafe(shipment.created_at),
    updated_at: toISOStringSafe(shipment.updated_at),
    delivery_at:
      shipment.delivery_at !== null && shipment.delivery_at !== undefined
        ? toISOStringSafe(shipment.delivery_at)
        : undefined,
    cancelled_at:
      shipment.cancelled_at !== null && shipment.cancelled_at !== undefined
        ? toISOStringSafe(shipment.cancelled_at)
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProductAttributeValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductAttributeValue";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postShoppingMallSellerSkusSkuIdAttributeValues(props: {
  seller: SellerPayload;
  skuId: string & tags.Format<"uuid">;
  body: IShoppingMallProductAttributeValue.ICreate;
}): Promise<IShoppingMallProductAttributeValue> {
  const { seller, skuId, body } = props;

  // 1. Find SKU & check ownership and not deleted
  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findFirst({
    where: {
      id: skuId,
      deleted_at: null,
    },
    select: {
      id: true,
      shopping_mall_product_id: true,
    },
  });
  if (!sku) {
    throw new HttpException("SKU not found, deleted, or inaccessible.", 404);
  }

  // 2. Confirm the SKU's product is owned by this seller
  const product = await MyGlobal.prisma.shopping_mall_products.findFirst({
    where: { id: sku.shopping_mall_product_id, seller: { id: seller.id } },
    select: { id: true },
  });
  if (!product) {
    throw new HttpException("Seller does not own this SKU's product.", 403);
  }

  // 3. Validate attribute exists, not deleted, belongs to same product
  const attribute =
    await MyGlobal.prisma.shopping_mall_product_attributes.findFirst({
      where: {
        id: body.shopping_mall_product_attribute_id,
        deleted_at: null,
        shopping_mall_product_id: sku.shopping_mall_product_id,
      },
      select: { id: true },
    });
  if (!attribute) {
    throw new HttpException(
      "Attribute not found, deleted, or not associated with the SKU's product.",
      404,
    );
  }

  // 4. Enforce uniqueness: no existing mapping for (skuId, attributeId)
  const duplicate =
    await MyGlobal.prisma.shopping_mall_product_attribute_values.findFirst({
      where: {
        shopping_mall_product_sku_id: skuId,
        shopping_mall_product_attribute_id:
          body.shopping_mall_product_attribute_id,
      },
      select: { id: true },
    });
  if (duplicate) {
    throw new HttpException(
      "A value for this attribute and SKU already exists.",
      409,
    );
  }

  // 5. Create the new attribute value mapping
  const now = toISOStringSafe(new Date());
  const created =
    await MyGlobal.prisma.shopping_mall_product_attribute_values.create({
      data: {
        id: v4(),
        shopping_mall_product_sku_id: skuId,
        shopping_mall_product_attribute_id:
          body.shopping_mall_product_attribute_id,
        value_display_name: body.value_display_name,
        created_at: now,
        updated_at: now,
      },
    });

  return {
    id: created.id,
    shopping_mall_product_sku_id: created.shopping_mall_product_sku_id,
    shopping_mall_product_attribute_id:
      created.shopping_mall_product_attribute_id,
    value_display_name: created.value_display_name,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminOrdersOrderNumberItemsOrderItemId(props: {
  admin: AdminPayload;
  orderNumber: string;
  orderItemId: string & tags.Format<"uuid">;
  body: IShoppingMallOrderItem.IUpdate;
}): Promise<IShoppingMallOrderItem> {
  // 1. Find parent order
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: { order_number: props.orderNumber, deleted_at: null },
  });
  if (!order) throw new HttpException("Order not found", 404);

  // 2. Find order item
  const item = await MyGlobal.prisma.shopping_mall_order_items.findFirst({
    where: {
      id: props.orderItemId,
      shopping_mall_order_id: order.id,
      deleted_at: null,
    },
  });
  if (!item) throw new HttpException("Order item not found", 404);

  // 3. Update
  const updated = await MyGlobal.prisma.shopping_mall_order_items.update({
    where: { id: item.id },
    data: {
      ...(props.body.quantity !== undefined && {
        quantity: props.body.quantity,
      }),
      ...(props.body.unit_price !== undefined && {
        unit_price: props.body.unit_price,
      }),
      ...(props.body.delivered !== undefined && {
        delivered: props.body.delivered,
      }),
      ...(props.body.refunded !== undefined && {
        refunded: props.body.refunded,
      }),
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // 4. Get product (no include!), then seller separately
  const product = await MyGlobal.prisma.shopping_mall_products.findUnique({
    where: { id: updated.shopping_mall_product_id },
  });
  if (!product) throw new HttpException("Product not found", 500);
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: product.shopping_mall_seller_id },
  });
  if (!seller) throw new HttpException("Seller not found", 500);

  // 5. SKU
  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
    where: { id: updated.shopping_mall_product_sku_id },
  });
  if (!sku) throw new HttpException("SKU not found", 500);

  // 6. Category summaries
  const categoriesMappings =
    await MyGlobal.prisma.shopping_mall_products_categories.findMany({
      where: { shopping_mall_product_id: product.id },
    });
  const categoryIds = categoriesMappings.map(
    (m) => m.shopping_mall_category_id,
  );
  let categories: IShoppingMallProductsCategory.ISummary[] = [];
  if (categoryIds.length > 0) {
    const cats = await MyGlobal.prisma.shopping_mall_categories.findMany({
      where: { id: { in: categoryIds } },
    });
    categories = cats.map((cat) => ({ id: cat.id, name: cat.name }));
  }

  // 7. DTO response
  return {
    id: updated.id,
    order: {
      id: order.id,
      order_number: order.order_number,
      status: order.status,
      total_amount: order.total_amount,
      currency: order.currency,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      deleted_at:
        order.deleted_at !== null && order.deleted_at !== undefined
          ? toISOStringSafe(order.deleted_at)
          : null,
    },
    product: {
      id: product.id,
      title: product.title,
      default_price: product.default_price,
      business_status: product.business_status,
      seller: {
        id: seller.id,
        business_name: seller.business_name,
      },
      categories,
      created_at: toISOStringSafe(product.created_at),
    },
    sku: {
      id: sku.id,
      code: sku.sku_code,
      product_title: product.title,
      option_summary: "",
      in_stock: sku.status === "active" && sku.stock > 0,
    },
    quantity: updated.quantity,
    unit_price: updated.unit_price,
    subtotal: updated.subtotal,
    currency: updated.currency,
    delivered: updated.delivered,
    refunded: updated.refunded,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at:
      updated.deleted_at !== null && updated.deleted_at !== undefined
        ? toISOStringSafe(updated.deleted_at)
        : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminShipmentsShipmentId(props: {
  admin: AdminPayload;
  shipmentId: string & tags.Format<"uuid">;
  body: IShoppingMallShipment.IUpdate;
}): Promise<IShoppingMallShipment> {
  const existing = await MyGlobal.prisma.shopping_mall_shipments.findUnique({
    where: { id: props.shipmentId },
  });
  if (!existing) {
    throw new HttpException("Shipment not found", 404);
  }

  const currentStatus = existing.status;
  const newStatus = props.body.status ?? currentStatus;
  const statusTransitions: Record<string, string[]> = {
    pending: ["ready", "cancelled"],
    ready: ["picked_up", "cancelled"],
    picked_up: ["in_transit", "cancelled"],
    in_transit: ["delivered", "cancelled", "returned"],
    delivered: ["returned"],
    cancelled: [],
    returned: [],
  };
  const allowedNext = statusTransitions[currentStatus] ?? [];
  if (
    props.body.status &&
    props.body.status !== currentStatus &&
    !allowedNext.includes(props.body.status)
  ) {
    throw new HttpException(
      `Invalid status transition from '${currentStatus}' to '${props.body.status}'`,
      400,
    );
  }
  if (props.body.status === "delivered" && !props.body.delivery_at) {
    throw new HttpException(
      "delivery_at must be set when setting status to 'delivered'",
      400,
    );
  }
  if (props.body.status === "cancelled" && !props.body.cancelled_at) {
    throw new HttpException(
      "cancelled_at must be set when setting status to 'cancelled'",
      400,
    );
  }
  if (props.body.updated_by_admin_id && props.body.updated_by_seller_id) {
    throw new HttpException(
      "Cannot attribute update to both admin and seller",
      400,
    );
  }

  const data: Record<string, unknown> = {
    carrier_tracking_code: props.body.carrier_tracking_code ?? null,
    status: props.body.status ?? currentStatus,
    manifest_url: props.body.manifest_url ?? null,
    provider_response_code: props.body.provider_response_code ?? null,
    delivery_at: props.body.delivery_at ?? null,
    cancelled_at: props.body.cancelled_at ?? null,
    updated_by_admin_id: props.admin.id,
    updated_by_seller_id: null,
    updated_at: toISOStringSafe(new Date()),
  };
  const updated = await MyGlobal.prisma.shopping_mall_shipments.update({
    where: { id: props.shipmentId },
    data,
  });

  const [order, orderItem, shippingPartner, admin, seller] = await Promise.all([
    MyGlobal.prisma.shopping_mall_orders.findUnique({
      where: { id: updated.order_id },
    }),
    MyGlobal.prisma.shopping_mall_order_items.findUnique({
      where: { id: updated.order_item_id },
    }),
    MyGlobal.prisma.shopping_mall_shipping_partners.findUnique({
      where: { id: updated.shipping_partner_id },
    }),
    updated.created_by_admin_id
      ? MyGlobal.prisma.shopping_mall_admins.findUnique({
          where: { id: updated.created_by_admin_id },
        })
      : null,
    updated.created_by_seller_id
      ? MyGlobal.prisma.shopping_mall_sellers.findUnique({
          where: { id: updated.created_by_seller_id },
        })
      : null,
  ]);

  let skuSummary: IShoppingMallProductSku.ISummary | undefined = undefined;
  if (orderItem && orderItem.shopping_mall_product_sku_id) {
    const sku = await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
      where: { id: orderItem.shopping_mall_product_sku_id },
    });
    if (!sku) {
      throw new HttpException("Product SKU not found for order item", 404);
    }
    skuSummary = {
      id: sku.id,
      code: sku.sku_code,
      product_title: "",
      option_summary: "",
      in_stock: sku.stock > 0,
    };
  }

  return {
    id: updated.id,
    order: order
      ? {
          id: order.id,
          order_number: order.order_number,
          status: order.status,
          total_amount: order.total_amount,
          currency: order.currency,
          created_at: toISOStringSafe(order.created_at),
          updated_at: toISOStringSafe(order.updated_at),
          deleted_at: order.deleted_at
            ? toISOStringSafe(order.deleted_at)
            : undefined,
        }
      : (null as never),
    orderItem: orderItem
      ? {
          id: orderItem.id,
          shopping_mall_order_id: orderItem.shopping_mall_order_id,
          sku: skuSummary!,
          quantity: orderItem.quantity,
          unit_price: orderItem.unit_price,
          subtotal: orderItem.subtotal,
          currency: orderItem.currency,
          delivered: orderItem.delivered,
          refunded: orderItem.refunded,
          created_at: toISOStringSafe(orderItem.created_at),
          updated_at: toISOStringSafe(orderItem.updated_at),
        }
      : (null as never),
    shippingPartner: shippingPartner
      ? {
          id: shippingPartner.id,
          partner_name: shippingPartner.partner_name,
          partner_code: shippingPartner.partner_code,
          status: shippingPartner.status,
          description: shippingPartner.description,
          created_at: toISOStringSafe(shippingPartner.created_at),
          updated_at: toISOStringSafe(shippingPartner.updated_at),
          deleted_at: shippingPartner.deleted_at
            ? toISOStringSafe(shippingPartner.deleted_at)
            : undefined,
        }
      : (null as never),
    carrier_tracking_code: updated.carrier_tracking_code ?? undefined,
    status: typia.assert<IShoppingMallShipment["status"]>(updated.status),
    manifest_url: updated.manifest_url ?? undefined,
    provider_response_code: updated.provider_response_code ?? undefined,
    createdByAdmin: admin
      ? { id: admin.id, name: admin.name, email: admin.email }
      : undefined,
    createdBySeller: seller
      ? { id: seller.id, business_name: seller.business_name }
      : undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    delivery_at:
      updated.delivery_at != null
        ? toISOStringSafe(updated.delivery_at)
        : undefined,
    cancelled_at:
      updated.cancelled_at != null
        ? toISOStringSafe(updated.cancelled_at)
        : undefined,
  };
}

