  const customer = await MyGlobal.prisma.shopping_mall_customers.findUnique({
    where: { id: updated.shopping_mall_customer_id },
    select: { id: true, name: true },
  });
  if (!customer) {
    throw new HttpException("Customer for cart not found", 500);
  }

  return {
    id: updated.id,
