import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function putShoppingMallSellerShipmentsShipmentId(props: {
  seller: SellerPayload;
  shipmentId: string & tags.Format<"uuid">;
  body: IShoppingMallShipment.IUpdate;
}): Promise<IShoppingMallShipment> {
  const shipment = await MyGlobal.prisma.shopping_mall_shipments.findUnique({
    where: { id: props.shipmentId },
  });
  if (!shipment) throw new HttpException("Shipment not found", 404);
  if (shipment.created_by_seller_id !== props.seller.id)
    throw new HttpException(
      "You are not authorized to update this shipment",
      403,
    );
  const allowedTransitions: Record<string, string[]> = {
    pending: ["ready", "cancelled"],
    ready: ["picked_up", "cancelled"],
    picked_up: ["in_transit", "cancelled"],
    in_transit: ["delivered", "cancelled", "returned"],
    delivered: ["returned"],
    cancelled: [],
    returned: [],
  };
  const currentStatus = shipment.status;
  const nextStatus = props.body.status ?? currentStatus;
  if (nextStatus !== currentStatus) {
    const validNext = allowedTransitions[currentStatus];
    if (!validNext.includes(nextStatus)) {
      throw new HttpException(
        `Invalid status transition from '${currentStatus}' to '${nextStatus}'`,
        400,
      );
    }
  }
  if (nextStatus === "delivered" && !props.body.delivery_at)
    throw new HttpException(
      "delivery_at timestamp must be set for delivered status",
      400,
    );
  if (nextStatus === "cancelled" && !props.body.cancelled_at)
    throw new HttpException(
      "cancelled_at timestamp must be set for cancelled status",
      400,
    );
  if (props.body.updated_by_admin_id)
    throw new HttpException("Seller cannot attribute update to admin", 400);
  const updated = await MyGlobal.prisma.shopping_mall_shipments.update({
    where: { id: props.shipmentId },
    data: {
      carrier_tracking_code: Object.prototype.hasOwnProperty.call(
        props.body,
        "carrier_tracking_code",
      )
        ? props.body.carrier_tracking_code
        : shipment.carrier_tracking_code,
      status: nextStatus,
      manifest_url: Object.prototype.hasOwnProperty.call(
        props.body,
        "manifest_url",
      )
        ? props.body.manifest_url
        : shipment.manifest_url,
      provider_response_code: Object.prototype.hasOwnProperty.call(
        props.body,
        "provider_response_code",
      )
        ? props.body.provider_response_code
        : shipment.provider_response_code,
      delivery_at:
        nextStatus === "delivered"
          ? props.body.delivery_at
          : shipment.delivery_at,
      cancelled_at:
        nextStatus === "cancelled"
          ? props.body.cancelled_at
          : shipment.cancelled_at,
      updated_at: (() => {
        const now = new Date();
        return toISOStringSafe(now);
      })(),
    },
  });
  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: { id: updated.order_id },
    select: {
      id: true,
      order_number: true,
      status: true,
      total_amount: true,
      currency: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });
  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findUnique({
    where: { id: updated.order_item_id },
    select: {
      id: true,
      shopping_mall_order_id: true,
      quantity: true,
      unit_price: true,
      subtotal: true,
      currency: true,
      delivered: true,
      refunded: true,
      created_at: true,
      updated_at: true,
    },
  });
  let skuSummary = undefined;
  if (orderItem) {
    skuSummary = await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
      where: { id: (orderItem as any).shopping_mall_product_sku_id },
      select: { id: true }, // removed in_stock field
    });
  }
  const shippingPartner = updated.shipping_partner_id
    ? await MyGlobal.prisma.shopping_mall_shipping_partners.findUnique({
        where: { id: updated.shipping_partner_id },
        select: {
          id: true,
          partner_name: true,
          partner_code: true,
          status: true,
          description: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
        },
      })
    : undefined;
  const sellerSummary = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: props.seller.id },
    select: { id: true, business_name: true },
  });
  let adminSummary = undefined;
  if (updated.created_by_admin_id) {
    adminSummary = await MyGlobal.prisma.shopping_mall_admins.findUnique({
      where: { id: updated.created_by_admin_id },
      select: { id: true, name: true, email: true },
    });
  }
  function dateToStringOrUndefined(
    x: Date | string | null | undefined,
  ): (string & tags.Format<"date-time">) | undefined {
    if (x == null) return undefined;
    return typeof x === "string"
      ? (x as string & tags.Format<"date-time">)
      : (toISOStringSafe(x) as string & tags.Format<"date-time">);
  }
  return {
    id: updated.id,
    order: order
      ? {
          id: order.id,
          order_number: order.order_number,
          status: order.status,
          total_amount: order.total_amount,
          currency: order.currency,
          created_at: dateToStringOrUndefined(order.created_at)!,
          updated_at: dateToStringOrUndefined(order.updated_at)!,
          deleted_at: dateToStringOrUndefined(order.deleted_at),
        }
      : ({} as any), // force as ISummary
    orderItem:
      orderItem && skuSummary
        ? {
            id: orderItem.id,
            shopping_mall_order_id: orderItem.shopping_mall_order_id,
            sku: skuSummary,
            quantity: orderItem.quantity,
            unit_price: orderItem.unit_price,
            subtotal: orderItem.subtotal,
            currency: orderItem.currency,
            delivered: orderItem.delivered,
            refunded: orderItem.refunded,
            created_at: dateToStringOrUndefined(orderItem.created_at)!,
            updated_at: dateToStringOrUndefined(orderItem.updated_at)!,
          }
        : ({} as any),
    shippingPartner: shippingPartner
      ? {
          id: shippingPartner.id,
          partner_name: shippingPartner.partner_name,
          partner_code: shippingPartner.partner_code,
          status: shippingPartner.status,
          description: shippingPartner.description,
          created_at: dateToStringOrUndefined(shippingPartner.created_at)!,
          updated_at: dateToStringOrUndefined(shippingPartner.updated_at)!,
          deleted_at: dateToStringOrUndefined(shippingPartner.deleted_at),
        }
      : ({} as any),
    carrier_tracking_code:
      typeof updated.carrier_tracking_code === "string"
        ? updated.carrier_tracking_code
        : updated.carrier_tracking_code == null
          ? undefined
          : String(updated.carrier_tracking_code),
    status: updated.status as IShoppingMallShipment["status"],
    manifest_url:
      typeof updated.manifest_url === "string"
        ? updated.manifest_url
        : updated.manifest_url == null
          ? undefined
          : String(updated.manifest_url),
    provider_response_code:
      typeof updated.provider_response_code === "string"
        ? updated.provider_response_code
        : updated.provider_response_code == null
          ? undefined
          : String(updated.provider_response_code),
    createdByAdmin: adminSummary
      ? {
          id: adminSummary.id,
          name: adminSummary.name,
          email: adminSummary.email,
        }
      : undefined,
    createdBySeller: sellerSummary
      ? { id: sellerSummary.id, business_name: sellerSummary.business_name }
      : undefined,
    created_at: dateToStringOrUndefined(updated.created_at)!,
    updated_at: dateToStringOrUndefined(updated.updated_at)!,
    delivery_at: dateToStringOrUndefined(updated.delivery_at),
    cancelled_at: dateToStringOrUndefined(updated.cancelled_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProductRating } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductRating";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";
import { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallProductsCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductsCategory";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerProductRatings(props: {
  customer: CustomerPayload;
  body: IShoppingMallProductRating.ICreate;
}): Promise<IShoppingMallProductRating> {
  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findUnique({
    where: { id: props.body.shopping_mall_order_item_id },
  });
  if (!orderItem) {
    throw new HttpException("Order item not found.", 404);
  }
  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: { id: props.body.shopping_mall_order_id },
  });
  if (!order || order.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException("Order not found or not owned by customer.", 404);
  }
  if (orderItem.shopping_mall_order_id !== order.id) {
    throw new HttpException(
      "Order item is not part of the specified order.",
      409,
    );
  }
  if (
    orderItem.shopping_mall_product_sku_id !==
    props.body.shopping_mall_product_sku_id
  ) {
    throw new HttpException(
      "Order item does not reference the given SKU.",
      409,
    );
  }
  const existing =
    await MyGlobal.prisma.shopping_mall_product_ratings.findFirst({
      where: {
        shopping_mall_customer_id: props.customer.id,
        shopping_mall_product_sku_id: props.body.shopping_mall_product_sku_id,
        shopping_mall_order_item_id: props.body.shopping_mall_order_item_id,
      },
    });
  if (existing) {
    throw new HttpException("You have already rated this order item.", 409);
  }
  const productSku =
    await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
      where: { id: props.body.shopping_mall_product_sku_id },
    });
  if (!productSku) throw new HttpException("SKU not found.", 404);
  const product = await MyGlobal.prisma.shopping_mall_products.findUnique({
    where: { id: productSku.shopping_mall_product_id },
  });
  if (!product) throw new HttpException("Product not found.", 404);
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_product_ratings.create({
    data: {
      id: v4(),
      shopping_mall_customer_id: props.customer.id,
      shopping_mall_customer_session_id: props.customer.session_id,
      shopping_mall_product_id: product.id,
      shopping_mall_product_sku_id: props.body.shopping_mall_product_sku_id,
      shopping_mall_order_id: props.body.shopping_mall_order_id,
      shopping_mall_order_item_id: props.body.shopping_mall_order_item_id,
      value: props.body.value,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });
  const customer = await MyGlobal.prisma.shopping_mall_customers.findUnique({
    where: { id: props.customer.id },
  });
  const session =
    await MyGlobal.prisma.shopping_mall_customer_sessions.findUnique({
      where: { id: props.customer.session_id },
    });
  return {
    id: created.id,
    customer:
      customer !== null
        ? { id: customer.id, name: customer.name }
        : { id: "", name: "" },
    session:
      session !== null && session !== undefined
        ? {
            id: session.id,
            created_at: toISOStringSafe(session.created_at),
            expired_at: toISOStringSafe(
              session.expired_at ?? session.created_at ?? new Date(),
            ), // always provide a string & Format<"date-time">
            last_active_at: toISOStringSafe(session.created_at),
            ip: session.ip,
            href: session.href,
            referrer: session.referrer,
            user_agent: "",
          }
        : {
            id: "",
            created_at: toISOStringSafe(new Date()),
            expired_at: toISOStringSafe(new Date()),
            last_active_at: toISOStringSafe(new Date()),
            ip: "",
            href: "",
            referrer: "",
            user_agent: "",
          },
    product: {
      id: product.id,
      title: product.title,
      default_price: product.default_price,
      business_status: product.business_status,
      seller: { id: product.shopping_mall_seller_id, business_name: "" },
      categories: [],
      created_at: toISOStringSafe(product.created_at),
    },
    productSku: {
      id: productSku.id,
      code: productSku.sku_code,
      product_title: product.title,
      option_summary: "",
      in_stock: productSku.stock > 0 && !productSku.deleted_at,
    },
    order: {
      id: order.id,
      order_number: order.order_number,
      status: order.status,
      total_amount: order.total_amount,
      currency: order.currency,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      deleted_at: order.deleted_at
        ? toISOStringSafe(order.deleted_at)
        : undefined,
    },
    order_item_id: orderItem.id,
    shopping_mall_customer_id: created.shopping_mall_customer_id,
    shopping_mall_customer_session_id:
      created.shopping_mall_customer_session_id,
    shopping_mall_product_id: created.shopping_mall_product_id,
    shopping_mall_product_sku_id: created.shopping_mall_product_sku_id,
    shopping_mall_order_id: created.shopping_mall_order_id,
    shopping_mall_order_item_id: created.shopping_mall_order_item_id,
    value: created.value,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at:
      created.deleted_at === null
        ? undefined
        : toISOStringSafe(created.deleted_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallReturnRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnRequest";
import { IPageIShoppingMallReturnRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallReturnRequest";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminReturnRequests(props: {
  admin: AdminPayload;
  body: IShoppingMallReturnRequest.IRequest;
}): Promise<IPageIShoppingMallReturnRequest.ISummary> {
  const {
    status,
    order_id,
    order_item_id,
    requested_by_customer_id,
    requested_by_seller_id,
    scheduled_pickup_from,
    scheduled_pickup_to,
    created_from,
    created_to,
    reason_q,
    page,
    limit,
    sort_by,
    sort_direction,
  } = props.body;
  const pageNumber = page !== undefined ? (page satisfies number as number) : 1;
  const limitNumber =
    limit !== undefined ? (limit satisfies number as number) : 20;
  const offset = (pageNumber - 1) * limitNumber;
  const where: Prisma.shopping_mall_return_requestsWhereInput = {
    deleted_at: null,
    ...(status !== undefined && { status }),
    ...(order_id !== undefined && { order_id }),
    ...(order_item_id !== undefined && { order_item_id }),
    ...(requested_by_customer_id !== undefined && { requested_by_customer_id }),
    ...(requested_by_seller_id !== undefined && { requested_by_seller_id }),
    ...(scheduled_pickup_from !== undefined || scheduled_pickup_to !== undefined
      ? {
          scheduled_pickup_at: {
            ...(scheduled_pickup_from !== undefined && {
              gte:
                scheduled_pickup_from !== null
                  ? toISOStringSafe(scheduled_pickup_from)
                  : undefined,
            }),
            ...(scheduled_pickup_to !== undefined && {
              lte:
                scheduled_pickup_to !== null
                  ? toISOStringSafe(scheduled_pickup_to)
                  : undefined,
            }),
          },
        }
      : {}),
    ...(created_from !== undefined || created_to !== undefined
      ? {
          created_at: {
            ...(created_from !== undefined && {
              gte:
                created_from !== null
                  ? toISOStringSafe(created_from)
                  : undefined,
            }),
            ...(created_to !== undefined && {
              lte:
                created_to !== null ? toISOStringSafe(created_to) : undefined,
            }),
          },
        }
      : {}),
    ...(reason_q !== undefined && reason_q.trim() !== ""
      ? { reason: { contains: reason_q, mode: "insensitive" } }
      : {}),
  };
  const allowedSortFields = [
    "created_at",
    "scheduled_pickup_at",
    "status",
    "id",
  ];
  const sortField =
    sort_by && allowedSortFields.includes(sort_by) ? sort_by : "created_at";
  const sortDirection =
    sort_direction === "asc" || sort_direction === "desc"
      ? sort_direction
      : "desc";
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_return_requests.findMany({
      where,
      skip: offset,
      take: limitNumber,
      orderBy: { [sortField]: sortDirection },
      include: {
        order: true,
        orderItem: true,
        requestedByCustomer: true,
        requestedBySeller: true,
        shippingPartner: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_return_requests.count({ where }),
  ]);

  const data = rows.map((row): IShoppingMallReturnRequest.ISummary => {
    const orderObj: IShoppingMallOrder.ISummary = row.order
      ? {
          id: row.order.id,
          order_number: row.order.order_number,
          status: row.order.status,
          total_amount: row.order.total_amount,
          currency: row.order.currency,
          created_at: toISOStringSafe(row.order.created_at),
          updated_at: toISOStringSafe(row.order.updated_at),
          deleted_at:
            row.order.deleted_at !== null && row.order.deleted_at !== undefined
              ? toISOStringSafe(row.order.deleted_at)
              : undefined,
        }
      : typia.random<IShoppingMallOrder.ISummary>();
    const orderItemObj: IShoppingMallOrderItem.ISummary = row.orderItem
      ? {
          id: row.orderItem.id,
          shopping_mall_order_id: row.orderItem.shopping_mall_order_id,
          sku: typia.random<IShoppingMallProductSku.ISummary>(), // Not joined, must stub
          quantity: row.orderItem.quantity,
          unit_price: row.orderItem.unit_price,
          subtotal: row.orderItem.subtotal,
          currency: row.orderItem.currency,
          delivered: row.orderItem.delivered,
          refunded: row.orderItem.refunded,
          created_at: toISOStringSafe(row.orderItem.created_at),
          updated_at: toISOStringSafe(row.orderItem.updated_at),
        }
      : typia.random<IShoppingMallOrderItem.ISummary>();
    return {
      id: row.id,
      order: orderObj,
      orderItem: orderItemObj,
      requestedByCustomer: row.requestedByCustomer
        ? {
            id: row.requestedByCustomer.id,
            name: row.requestedByCustomer.name,
          }
        : undefined,
      requestedBySeller: row.requestedBySeller
        ? {
            id: row.requestedBySeller.id,
            business_name: row.requestedBySeller.business_name,
          }
        : undefined,
      shippingPartner: row.shippingPartner
        ? {
            id: row.shippingPartner.id,
            partner_name: row.shippingPartner.partner_name,
            partner_code: row.shippingPartner.partner_code,
            status: row.shippingPartner.status,
            description: row.shippingPartner.description,
            created_at: toISOStringSafe(row.shippingPartner.created_at),
            updated_at: toISOStringSafe(row.shippingPartner.updated_at),
            deleted_at:
              row.shippingPartner.deleted_at !== null &&
              row.shippingPartner.deleted_at !== undefined
                ? toISOStringSafe(row.shippingPartner.deleted_at)
                : undefined,
          }
        : undefined,
      reason: row.reason,
      status: row.status,
      pickup_address: row.pickup_address ?? undefined,
      scheduled_pickup_at:
        row.scheduled_pickup_at !== null &&
        row.scheduled_pickup_at !== undefined
          ? toISOStringSafe(row.scheduled_pickup_at)
          : undefined,
      provider_tracking_code: row.provider_tracking_code ?? undefined,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
      completed_at:
        row.completed_at !== null && row.completed_at !== undefined
          ? toISOStringSafe(row.completed_at)
          : undefined,
      cancelled_at:
        row.cancelled_at !== null && row.cancelled_at !== undefined
          ? toISOStringSafe(row.cancelled_at)
          : undefined,
    };
  });

  const response: IPageIShoppingMallReturnRequest.ISummary = {
    pagination: {
      current: pageNumber as number & tags.Type<"int32"> & tags.Minimum<0>,
      limit: limitNumber as number & tags.Type<"int32"> & tags.Minimum<0>,
      records: total as number & tags.Type<"int32"> & tags.Minimum<0>,
      pages: Math.ceil(total / limitNumber) as number &
        tags.Type<"int32"> &
        tags.Minimum<0>,
    },
    data,
  };
  return response;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallDispute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallDispute";
import { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingMallAdminDisputes(props: {
  admin: AdminPayload;
  body: IShoppingMallDispute.ICreate;
}): Promise<IShoppingMallDispute> {
  const customer = await MyGlobal.prisma.shopping_mall_customers.findUnique({
    where: { id: props.body.shopping_mall_customer_id },
    select: { id: true, name: true },
  });
  if (!customer) throw new HttpException("Customer not found", 404);

  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: { id: props.body.shopping_mall_seller_id },
    select: { id: true, business_name: true },
  });
  if (!seller) throw new HttpException("Seller not found", 404);

  let adminSummary: IShoppingMallAdmin.ISummary | null = null;
  if (props.body.shopping_mall_admin_id != null) {
    const admin = await MyGlobal.prisma.shopping_mall_admins.findUnique({
      where: { id: props.body.shopping_mall_admin_id },
      select: { id: true, name: true, email: true },
    });
    if (!admin) throw new HttpException("Admin not found", 404);
    adminSummary = { id: admin.id, name: admin.name, email: admin.email };
  }

  let refundRequestSummary: IShoppingMallRefundRequest.ISummary | null = null;
  if (props.body.shopping_mall_refund_request_id != null) {
    const refundRequest =
      await MyGlobal.prisma.shopping_mall_refund_requests.findUnique({
        where: { id: props.body.shopping_mall_refund_request_id },
        select: {
          id: true,
          status: true,
          reason: true,
          requested_amount: true,
          approved_amount: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
          shopping_mall_customer_id: true,
          shopping_mall_seller_id: true,
          shopping_mall_order_id: true,
          order: {
            select: {
              id: true,
              order_number: true,
              status: true,
              total_amount: true,
              currency: true,
              created_at: true,
              updated_at: true,
              deleted_at: true,
            },
          },
          customer: { select: { id: true, name: true } },
          seller: { select: { id: true, business_name: true } },
        },
      });
    if (!refundRequest)
      throw new HttpException("Refund request not found", 404);
    refundRequestSummary = {
      id: refundRequest.id,
      order: {
        id: refundRequest.order.id,
        order_number: refundRequest.order.order_number,
        status: refundRequest.order.status,
        total_amount: refundRequest.order.total_amount,
        currency: refundRequest.order.currency,
        created_at: toISOStringSafe(refundRequest.order.created_at),
        updated_at: toISOStringSafe(refundRequest.order.updated_at),
        deleted_at:
          refundRequest.order.deleted_at != null
            ? toISOStringSafe(refundRequest.order.deleted_at)
            : null,
      },
      customer: {
        id: refundRequest.customer.id,
        name: refundRequest.customer.name,
      },
      seller: {
        id: refundRequest.seller.id,
        business_name: refundRequest.seller.business_name,
      },
      status: refundRequest.status,
      reason: refundRequest.reason,
      requested_amount: refundRequest.requested_amount,
      approved_amount: refundRequest.approved_amount ?? null,
      created_at: toISOStringSafe(refundRequest.created_at),
      updated_at: toISOStringSafe(refundRequest.updated_at),
      deleted_at:
        refundRequest.deleted_at != null
          ? toISOStringSafe(refundRequest.deleted_at)
          : null,
    };
  }

  const now = toISOStringSafe(new Date());
  const disputeCreate = await MyGlobal.prisma.shopping_mall_disputes.create({
    data: {
      id: v4(),
      shopping_mall_refund_request_id:
        props.body.shopping_mall_refund_request_id ?? null,
      shopping_mall_customer_id: props.body.shopping_mall_customer_id,
      shopping_mall_seller_id: props.body.shopping_mall_seller_id,
      shopping_mall_admin_id: props.body.shopping_mall_admin_id ?? null,
      status: props.body.status,
      subject: props.body.subject,
      root_cause: props.body.root_cause,
      resolution_note: props.body.resolution_note ?? null,
      created_at: now,
      updated_at: now,
    },
  });

  const result: IShoppingMallDispute = {
    id: disputeCreate.id,
    refund_request: refundRequestSummary ?? undefined,
    customer: { id: customer.id, name: customer.name },
    seller: { id: seller.id, business_name: seller.business_name },
    admin: adminSummary ?? undefined,
    status: disputeCreate.status,
    subject: disputeCreate.subject,
    root_cause: disputeCreate.root_cause,
    resolution_note: disputeCreate.resolution_note ?? undefined,
    created_at: toISOStringSafe(disputeCreate.created_at),
    updated_at: toISOStringSafe(disputeCreate.updated_at),
    deleted_at:
      disputeCreate.deleted_at != null
        ? toISOStringSafe(disputeCreate.deleted_at)
        : undefined,
  };
  return result;
}

