import { IShoppingMallProductRating } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductRating";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postShoppingMallSellerReviewsReviewIdResponses(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IShoppingMallReviewResponse.ICreate;
}): Promise<IShoppingMallReviewResponse> {
  // Step 1: Fetch the target review (must exist & not withdrawn/deleted)
  const review = await MyGlobal.prisma.shopping_mall_reviews.findFirst({
    where: {
      id: props.reviewId,
      withdrawn_at: null,
      deleted_at: null,
    },
  });
  if (!review) {
    throw new HttpException(
      "Review not found or already withdrawn/deleted",
      404,
    );
  }

  // Step 2: Check reviewer ownership
  const product = await MyGlobal.prisma.shopping_mall_products.findFirst({
    where: {
      id: review.shopping_mall_product_id,
      deleted_at: null,
    },
  });
  if (!product) {
    throw new HttpException("Associated product not found or deleted", 404);
  }
  if (product.shopping_mall_seller_id !== props.seller.id) {
    throw new HttpException(
      "You are not authorized to respond to this review",
      403,
    );
  }

  // Step 3: Enforce single response per review
  const alreadyResponded =
    await MyGlobal.prisma.shopping_mall_review_responses.findFirst({
      where: {
        shopping_mall_review_id: review.id,
        deleted_at: null,
      },
    });
  if (alreadyResponded) {
    throw new HttpException("A response for this review already exists", 409);
  }

  // Step 4: Create seller response
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_review_responses.create({
    data: {
      id: v4(),
      shopping_mall_review_id: review.id,
      shopping_mall_seller_id: props.seller.id,
      shopping_mall_seller_session_id: props.seller.session_id,
      body: props.body.body,
      withdrawn_at: null,
      moderation_status: props.body.moderation_status,
      moderation_reason:
        typeof props.body.moderation_reason === "string"
          ? props.body.moderation_reason
          : null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // Step 5: Hydrate seller/summary objects (DTO contract)
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findFirst({
    where: {
      id: props.seller.id,
    },
  });
  if (!seller) {
    throw new HttpException("Seller account not found", 404);
  }

  return {
    id: created.id,
    body: created.body,
    withdrawn_at: null,
    moderation_status: created.moderation_status,
    moderation_reason: created.moderation_reason,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: null,
    review: {
      id: review.id,
      title: review.title,
      is_draft: review.is_draft,
      moderation_status: review.moderation_status,
      created_at: toISOStringSafe(review.created_at),
      updated_at: toISOStringSafe(review.updated_at),
      customer: {
        id: review.shopping_mall_customer_id,
        name: "",
      },
      product: {
        id: review.shopping_mall_product_id,
        title: "",
        default_price: 0,
        business_status: "",
        seller: {
          id: product.shopping_mall_seller_id,
          business_name: seller.business_name,
        },
        categories: [],
        created_at: toISOStringSafe(product.created_at),
      },
      productSku: {
        id: review.shopping_mall_product_sku_id,
        code: "",
        product_title: "",
        option_summary: "",
        in_stock: false,
      },
      productRating: {
        id: review.shopping_mall_product_rating_id,
        value: 0,
        created_at: now,
        updated_at: now,
        deleted_at: null,
        customer: {
          id: review.shopping_mall_customer_id,
          name: "",
        },
        product: {
          id: review.shopping_mall_product_id,
          title: "",
          default_price: 0,
          business_status: "",
          seller: {
            id: product.shopping_mall_seller_id,
            business_name: seller.business_name,
          },
          categories: [],
          created_at: toISOStringSafe(product.created_at),
        },
        productSku: {
          id: review.shopping_mall_product_sku_id,
          code: "",
          product_title: "",
          option_summary: "",
          in_stock: false,
        },
      },
      orderItem: {
        id: review.shopping_mall_order_item_id,
      },
    },
    seller: {
      id: seller.id,
      business_name: seller.business_name,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthSellerLogin(props: {
  body: IShoppingMallSeller.ILogin;
}): Promise<IShoppingMallSeller.IAuthorized> {
  const seller = await MyGlobal.prisma.shopping_mall_sellers.findFirst({
    where: { email: props.body.email },
  });
  if (!seller) {
    throw new HttpException("Invalid credentials", 401);
  }
  if (!seller.is_email_verified) {
    throw new HttpException("Email verification required", 403);
  }
  if (seller.status !== "approved") {
    throw new HttpException("Account not permitted to login", 403);
  }
  const passwordValid = await PasswordUtil.verify(
    props.body.password,
    seller.password_hash,
  );
  if (!passwordValid) {
    throw new HttpException("Invalid credentials", 401);
  }
  const now = toISOStringSafe(new Date());
  const access_expiry = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refresh_expiry = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const session_id = v4();
  const session_create_data: any = {
    id: session_id,
    shopping_mall_seller_id: seller.id,
    href: props.body.href,
    referrer: props.body.referrer,
    created_at: now,
    expired_at: access_expiry,
  };
  if (typeof props.body.ip === "string") {
    session_create_data.ip = props.body.ip satisfies string as string;
  }
  const session = await MyGlobal.prisma.shopping_mall_seller_sessions.create({
    data: session_create_data,
  });
  const token = {
    access: jwt.sign(
      {
        type: "seller",
        id: seller.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "seller",
        id: seller.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: access_expiry,
    refreshable_until: refresh_expiry,
  };
  return {
    id: seller.id,
    email: seller.email,
    business_name: seller.business_name,
    registration_number: seller.registration_number,
    business_phone: seller.business_phone,
    is_email_verified: seller.is_email_verified,
    status: seller.status,
    created_at: toISOStringSafe(seller.created_at),
    updated_at: toISOStringSafe(seller.updated_at),
    token,
    seller: { id: seller.id, business_name: seller.business_name },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingMallAdminShipments(props: {
  admin: AdminPayload;
  body: IShoppingMallShipment.ICreate;
}): Promise<IShoppingMallShipment> {
  const { body, admin } = props;

  // 1. Validate referenced entities exist
  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: { id: body.order_id },
  });
  if (!order) {
    throw new HttpException("Referenced order does not exist.", 404);
  }

  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findUnique({
    where: { id: body.order_item_id },
  });
  if (!orderItem) {
    throw new HttpException("Referenced order item does not exist.", 404);
  }

  const shippingPartner =
    await MyGlobal.prisma.shopping_mall_shipping_partners.findUnique({
      where: {
        id: body.shipping_partner_id,
        status: "active",
        deleted_at: null,
      },
    });
  if (!shippingPartner) {
    throw new HttpException(
      "Referenced shipping partner does not exist or is not active.",
      404,
    );
  }

  // 2. Enforce actor attribution rules (admin only for this endpoint)
  if (body.created_by_admin_id !== admin.id) {
    throw new HttpException(
      "created_by_admin_id must match current admin.",
      400,
    );
  }
  if (body.created_by_seller_id) {
    throw new HttpException(
      "created_by_seller_id must be null for admin-attributed shipment.",
      400,
    );
  }

  // 3. Generate new shipment ID and timestamps
  const id = v4();
  const now = toISOStringSafe(new Date());

  // 4. Insert the shipment record
  const created = await MyGlobal.prisma.shopping_mall_shipments.create({
    data: {
      id,
      order_id: body.order_id,
      order_item_id: body.order_item_id,
      shipping_partner_id: body.shipping_partner_id,
      carrier_tracking_code: body.carrier_tracking_code ?? null,
      status: body.status,
      manifest_url: body.manifest_url ?? null,
      provider_response_code: body.provider_response_code ?? null,
      created_by_admin_id: body.created_by_admin_id ?? admin.id,
      created_by_seller_id: null,
      created_at: now,
      updated_at: now,
      delivery_at: body.status === "delivered" ? now : null,
      cancelled_at: body.status === "cancelled" ? now : null,
    },
  });

  // 5. Compose summary references for response DTO
  const orderSummary = {
    id: order.id,
    order_number: order.order_number,
    status: order.status,
    total_amount: order.total_amount,
    currency: order.currency,
    created_at: toISOStringSafe(order.created_at),
    updated_at: toISOStringSafe(order.updated_at),
    deleted_at: order.deleted_at
      ? toISOStringSafe(order.deleted_at)
      : undefined,
  };

  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findUnique({
    where: { id: orderItem.shopping_mall_product_sku_id },
  });
  const skuSummary = sku
    ? {
        id: sku.id satisfies string as string,
        code: sku.sku_code ?? "",
        product_title: "", // Not in schema
        option_summary: "", // Not in schema
        in_stock: false, // Not in schema
      }
    : {
        id: "",
        code: "",
        product_title: "",
        option_summary: "",
        in_stock: false,
      };

  const orderItemSummary = {
    id: orderItem.id,
    shopping_mall_order_id: orderItem.shopping_mall_order_id,
    sku: skuSummary,
    quantity: orderItem.quantity,
    unit_price: orderItem.unit_price,
    subtotal: orderItem.subtotal,
    currency: orderItem.currency,
    delivered: orderItem.delivered,
    refunded: orderItem.refunded,
    created_at: toISOStringSafe(orderItem.created_at),
    updated_at: toISOStringSafe(orderItem.updated_at),
  };

  const shippingPartnerSummary = {
    id: shippingPartner.id,
    partner_name: shippingPartner.partner_name,
    partner_code: shippingPartner.partner_code,
    status: shippingPartner.status,
    description: shippingPartner.description,
    created_at: toISOStringSafe(shippingPartner.created_at),
    updated_at: toISOStringSafe(shippingPartner.updated_at),
    deleted_at: shippingPartner.deleted_at
      ? toISOStringSafe(shippingPartner.deleted_at)
      : undefined,
  };

  const adminSummary = {
    id: admin.id,
    name: "",
    email: "",
  };

  return {
    id,
    order: orderSummary,
    orderItem: orderItemSummary,
    shippingPartner: shippingPartnerSummary,
    carrier_tracking_code: created.carrier_tracking_code ?? undefined,
    status: typia.assert<IShoppingMallShipment["status"]>(created.status),
    manifest_url: created.manifest_url ?? undefined,
    provider_response_code: created.provider_response_code ?? undefined,
    createdByAdmin: adminSummary,
    createdBySeller: null,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    delivery_at:
      created.delivery_at != null
        ? toISOStringSafe(created.delivery_at)
        : undefined,
    cancelled_at:
      created.cancelled_at != null
        ? toISOStringSafe(created.cancelled_at)
        : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallPaymentRefund } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentRefund";
import { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingMallAdminPaymentsPaymentIdRefunds(props: {
  admin: AdminPayload;
  paymentId: string & tags.Format<"uuid">;
  body: IShoppingMallPaymentRefund.ICreate;
}): Promise<IShoppingMallPaymentRefund> {
  const now = toISOStringSafe(new Date());

  // 1. Lookup payment
  const payment = await MyGlobal.prisma.shopping_mall_payments.findFirst({
    where: {
      id: props.paymentId,
      deleted_at: null,
    },
  });
  if (!payment) throw new HttpException("Payment record not found", 404);
  if (
    payment.status !== "initiated" &&
    payment.status !== "pending" &&
    payment.status !== "completed"
  )
    throw new HttpException(
      "This payment cannot be refunded in its current status.",
      400,
    );

  // 2. Validate refund amount business rule
  if (typeof props.body.amount !== "number" || props.body.amount <= 0)
    throw new HttpException("Refund amount must be positive.", 400);
  if (props.body.amount > payment.amount)
    throw new HttpException("Refund amount exceeds payment total.", 400);
  // 3. Currency match
  if (props.body.currency !== payment.currency)
    throw new HttpException(
      "Refund currency must match payment currency.",
      400,
    );

  // 4. Check for concurrent/conflicting refunds
  const existingRefund =
    await MyGlobal.prisma.shopping_mall_payment_refunds.findFirst({
      where: {
        payment_id: props.paymentId,
        status: {
          in: ["requested", "pending", "processing", "completed"],
        },
        deleted_at: null,
      },
    });
  if (existingRefund) {
    throw new HttpException(
      "A refund operation is already in progress or completed for this payment.",
      409,
    );
  }

  // 5. Insert refund
  const created = await MyGlobal.prisma.shopping_mall_payment_refunds.create({
    data: {
      id: v4(),
      payment_id: props.paymentId,
      processed_by_admin_id: props.admin.id,
      amount: props.body.amount,
      currency: props.body.currency,
      reason: props.body.reason,
      status: props.body.status,
      external_refund_id: props.body.external_refund_id ?? "",
      requested_at: now,
      processed_at: null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // 6. Retrieve summary data for output
  const [paymentSummary, adminSummary] = await Promise.all([
    MyGlobal.prisma.shopping_mall_payments.findUnique({
      where: { id: created.payment_id },
      select: {
        id: true,
        method_type: true,
        amount: true,
        currency: true,
        status: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_admins.findUnique({
      where: { id: created.processed_by_admin_id! },
      select: {
        id: true,
        name: true,
        email: true,
      },
    }),
  ]);
  if (!paymentSummary)
    throw new HttpException("Summary payment record not found", 500);

  return {
    id: created.id,
    payment: paymentSummary && {
      id: paymentSummary.id,
      method: paymentSummary.method_type,
      amount: paymentSummary.amount,
      currency: paymentSummary.currency,
      status: paymentSummary.status,
      created_at: toISOStringSafe(paymentSummary.created_at),
    },
    processed_by_admin: adminSummary && {
      id: adminSummary.id,
      name: adminSummary.name,
      email: adminSummary.email,
    },
    amount: created.amount,
    currency: created.currency,
    reason: created.reason,
    status: created.status,
    external_refund_id: created.external_refund_id,
    requested_at: toISOStringSafe(created.requested_at),
    processed_at: created.processed_at
      ? toISOStringSafe(created.processed_at)
      : undefined,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at
      ? toISOStringSafe(created.deleted_at)
      : undefined,
  };
}

