export async function postShoppingMallReviews(props: {
  body: IShoppingMallReview.ICreate;
}): Promise<IShoppingMallReview> {
  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findUnique({
    where: { id: props.body.shopping_mall_order_item_id, deleted_at: null },
  });
  if (
    !orderItem ||
    orderItem.shopping_mall_product_id !==
      props.body.shopping_mall_product_id ||
    orderItem.shopping_mall_product_sku_id !==
      props.body.shopping_mall_product_sku_id ||
    orderItem.shopping_mall_order_id !== props.body.shopping_mall_order_id
  ) {
    throw new HttpException(
      "Purchase verification failed: The product SKU/order combination does not match a valid order item.",
      400,
    );
  }

  const existingReview = await MyGlobal.prisma.shopping_mall_reviews.findUnique(
    {
      where: {
        shopping_mall_order_item_id: props.body.shopping_mall_order_item_id,
      },
    },
  );
  if (existingReview) {
    throw new HttpException(
      "Duplicate review is not permitted: This order item was already reviewed.",
      409,
    );
  }

  // Fetch the related order to determine customer (for review ownership)
  const order = await MyGlobal.prisma.shopping_mall_orders.findUniqueOrThrow({
    where: { id: props.body.shopping_mall_order_id },
  });

  const now = toISOStringSafe(new Date());
  const reviewId = v4();
  const created = await MyGlobal.prisma.shopping_mall_reviews.create({
    data: {
      id: reviewId,
      title: props.body.title,
      body: props.body.body,
      is_draft: props.body.is_draft,
      moderation_status: props.body.moderation_status,
      withdrawn_at: props.body.withdrawn_at ?? null,
      shopping_mall_customer_id: order.shopping_mall_customer_id,
      shopping_mall_customer_session_id:
        (props.body as any).shopping_mall_customer_session_id !== undefined
          ? (props.body as any).shopping_mall_customer_session_id
          : undefined,
      shopping_mall_product_id: props.body.shopping_mall_product_id,
      shopping_mall_product_sku_id: props.body.shopping_mall_product_sku_id,
      shopping_mall_order_id: props.body.shopping_mall_order_id,
      shopping_mall_order_item_id: props.body.shopping_mall_order_item_id,
      shopping_mall_product_rating_id:
        props.body.shopping_mall_product_rating_id,
      moderation_reason: null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  const [customer, product, sku, rating, customerSession] = await Promise.all([
    MyGlobal.prisma.shopping_mall_customers.findUniqueOrThrow({
      where: { id: created.shopping_mall_customer_id },
    }),
    MyGlobal.prisma.shopping_mall_products.findUniqueOrThrow({
      where: { id: created.shopping_mall_product_id },
    }),
    MyGlobal.prisma.shopping_mall_product_skus.findUniqueOrThrow({
      where: { id: created.shopping_mall_product_sku_id },
    }),
    MyGlobal.prisma.shopping_mall_product_ratings.findUniqueOrThrow({
      where: { id: created.shopping_mall_product_rating_id },
    }),
    created.shopping_mall_customer_session_id
      ? MyGlobal.prisma.shopping_mall_customer_sessions.findUniqueOrThrow({
          where: { id: created.shopping_mall_customer_session_id },
        })
      : Promise.resolve(null),
  ]);

  // (Order is already loaded above; fetch orderItem summary fields)
  const orderItemSummary = {
    id: orderItem.id,
    shopping_mall_order_id: orderItem.shopping_mall_order_id,
    sku: {
      id: sku.id,
      code: sku.sku_code,
      product_title: product.title,
      option_summary: sku.sku_code,
      in_stock:
        sku.status === "active" && sku.deleted_at === null && sku.stock > 0,
    },
    quantity: orderItem.quantity,
    unit_price: orderItem.unit_price,
    subtotal: orderItem.subtotal,
    currency: orderItem.currency,
    delivered: orderItem.delivered,
    refunded: orderItem.refunded,
    created_at: toISOStringSafe(orderItem.created_at),
    updated_at: toISOStringSafe(orderItem.updated_at),
  };

  return {
    id: created.id,
    title: created.title,
    body: created.body,
    is_draft: created.is_draft,
    withdrawn_at:
      created.withdrawn_at !== undefined && created.withdrawn_at !== null
        ? toISOStringSafe(created.withdrawn_at)
        : null,
    moderation_status: created.moderation_status,
    moderation_reason: created.moderation_reason ?? null,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at:
      created.deleted_at !== undefined && created.deleted_at !== null
        ? toISOStringSafe(created.deleted_at)
        : null,
    customer: { id: customer.id, name: customer.name },
    customerSession: customerSession
      ? {
          id: customerSession.id,
          created_at: toISOStringSafe(customerSession.created_at),
          expired_at:
            customerSession.expired_at !== undefined &&
            customerSession.expired_at !== null
              ? toISOStringSafe(customerSession.expired_at)
              : toISOStringSafe(customerSession.created_at),
          last_active_at: toISOStringSafe(
            (customerSession as any).updated_at !== undefined &&
              (customerSession as any).updated_at !== null
              ? (customerSession as any).updated_at
              : customerSession.created_at,
          ),
          ip: customerSession.ip,
          href: customerSession.href,
          referrer: customerSession.referrer,
          user_agent: "",
        }
      : {
          id: "",
          created_at: now,
          expired_at: now,
          last_active_at: now,
          ip: "",
          href: "",
          referrer: "",
          user_agent: "",
        },
    product: {
      id: product.id,
      title: product.title,
      default_price: product.default_price,
      business_status: product.business_status,
      seller: { id: product.shopping_mall_seller_id, business_name: "" },
      categories: [],
      created_at: toISOStringSafe(product.created_at),
    },
    productSku: {
      id: sku.id,
      code: sku.sku_code,
      product_title: product.title,
      option_summary: sku.sku_code,
      in_stock:
        sku.status === "active" && sku.deleted_at === null && sku.stock > 0,
    },
    order: {
      id: order.id,
      order_number: order.order_number,
      status: order.status,
      total_amount: order.total_amount,
      currency: order.currency,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      deleted_at:
        order.deleted_at !== undefined && order.deleted_at !== null
          ? toISOStringSafe(order.deleted_at)
          : null,
    },
    orderItem: orderItemSummary,
    rating: {
      id: rating.id,
      value: rating.value,
      created_at: toISOStringSafe(rating.created_at),
      updated_at: toISOStringSafe(rating.updated_at),
      deleted_at:
        rating.deleted_at !== undefined && rating.deleted_at !== null
          ? toISOStringSafe(rating.deleted_at)
          : null,
      customer: { id: customer.id, name: customer.name },
      product: {
        id: product.id,
        title: product.title,
        default_price: product.default_price,
        business_status: product.business_status,
        seller: { id: product.shopping_mall_seller_id, business_name: "" },
        categories: [],
        created_at: toISOStringSafe(product.created_at),
      },
      productSku: {
        id: sku.id,
        code: sku.sku_code,
        product_title: product.title,
        option_summary: sku.sku_code,
        in_stock:
          sku.status === "active" && sku.deleted_at === null && sku.stock > 0,
      },
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthCustomerLogin(props: {
  body: IShoppingMallCustomer.ILogin;
}): Promise<IShoppingMallCustomer.IAuthorized> {
  const input = props.body;
  const customer = await MyGlobal.prisma.shopping_mall_customers.findFirst({
    where: { email: input.email },
  });
  if (!customer) {
    throw new HttpException("Invalid credentials", 401);
  }
  const verified = await PasswordUtil.verify(
    input.password,
    customer.password_hash,
  );
  if (!verified) {
    throw new HttpException("Invalid credentials", 401);
  }
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
  // Only include 'ip' if present and not null/undefined
  const sessionData: any = {
    id: v4() as string & tags.Format<"uuid">,
    shopping_mall_customer_id: customer.id,
    href: input.href,
    referrer: input.referrer,
    created_at: toISOStringSafe(now),
    expired_at: toISOStringSafe(accessExpires),
  };
  if (input.ip !== null && input.ip !== undefined) {
    sessionData.ip = input.ip satisfies string as string;
  }
  const session = await MyGlobal.prisma.shopping_mall_customer_sessions.create({
    data: sessionData,
  });
  const access = jwt.sign(
    {
      type: "customer",
      id: customer.id,
      session_id: session.id,
      created_at: toISOStringSafe(now),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const refresh = jwt.sign(
    {
      type: "customer",
      id: customer.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(now),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );
  return {
    id: customer.id,
    email: customer.email,
    name: customer.name,
    phone: customer.phone,
    is_email_verified: customer.is_email_verified,
    created_at: toISOStringSafe(customer.created_at),
    updated_at: toISOStringSafe(customer.updated_at),
    token: {
      access,
      refresh,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallDispute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallDispute";
import { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminDisputesDisputeId(props: {
  admin: AdminPayload;
  disputeId: string & tags.Format<"uuid">;
  body: IShoppingMallDispute.IUpdate;
}): Promise<IShoppingMallDispute> {
  const dispute = await MyGlobal.prisma.shopping_mall_disputes.findUnique({
    where: { id: props.disputeId },
  });
  if (dispute === null) {
    throw new HttpException("Dispute not found", 404);
  }
  if (
    dispute.shopping_mall_admin_id !== null &&
    dispute.shopping_mall_admin_id !== props.admin.id
  ) {
    throw new HttpException(
      "Forbidden: Only the assigned admin can update this dispute",
      403,
    );
  }
  // Validate admin if assignment changes or explicit assignment requested
  if (
    props.body.shopping_mall_admin_id !== undefined &&
    props.body.shopping_mall_admin_id !== null &&
    props.body.shopping_mall_admin_id !== props.admin.id
  ) {
    const targetAdmin = await MyGlobal.prisma.shopping_mall_admins.findUnique({
      where: { id: props.body.shopping_mall_admin_id },
    });
    if (
      targetAdmin === null ||
      targetAdmin.status !== "active" ||
      !targetAdmin.is_email_verified
    ) {
      throw new HttpException(
        "Target admin assignment invalid or not active",
        400,
      );
    }
  }
  if (
    props.body.shopping_mall_refund_request_id !== undefined &&
    props.body.shopping_mall_refund_request_id !== null
  ) {
    const refundCheck =
      await MyGlobal.prisma.shopping_mall_refund_requests.findUnique({
        where: { id: props.body.shopping_mall_refund_request_id },
      });
    if (refundCheck === null || refundCheck.deleted_at !== null) {
      throw new HttpException(
        "Referenced refund request not found or deleted",
        400,
      );
    }
  }
  if (
    props.body.shopping_mall_customer_id !== undefined &&
    props.body.shopping_mall_customer_id !== null
  ) {
    const customerCheck =
      await MyGlobal.prisma.shopping_mall_customers.findUnique({
        where: { id: props.body.shopping_mall_customer_id },
      });
    if (customerCheck === null) {
      throw new HttpException("Referenced customer not found", 400);
    }
  }
  if (
    props.body.shopping_mall_seller_id !== undefined &&
    props.body.shopping_mall_seller_id !== null
  ) {
    const sellerCheck = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
      where: { id: props.body.shopping_mall_seller_id },
    });
    if (sellerCheck === null) {
      throw new HttpException("Referenced seller not found", 400);
    }
  }
  const updated = await MyGlobal.prisma.shopping_mall_disputes.update({
    where: { id: props.disputeId },
    data: {
      shopping_mall_refund_request_id:
        props.body.shopping_mall_refund_request_id !== undefined
          ? props.body.shopping_mall_refund_request_id
          : dispute.shopping_mall_refund_request_id,
      shopping_mall_customer_id:
        props.body.shopping_mall_customer_id !== undefined
          ? props.body.shopping_mall_customer_id
          : dispute.shopping_mall_customer_id,
      shopping_mall_seller_id:
        props.body.shopping_mall_seller_id !== undefined
          ? props.body.shopping_mall_seller_id
          : dispute.shopping_mall_seller_id,
      shopping_mall_admin_id:
        props.body.shopping_mall_admin_id !== undefined
          ? props.body.shopping_mall_admin_id
          : dispute.shopping_mall_admin_id,
      status:
        props.body.status !== undefined ? props.body.status : dispute.status,
      subject:
        props.body.subject !== undefined ? props.body.subject : dispute.subject,
      root_cause:
        props.body.root_cause !== undefined
          ? props.body.root_cause
          : dispute.root_cause,
      resolution_note:
        props.body.resolution_note !== undefined
          ? props.body.resolution_note
          : dispute.resolution_note,
      updated_at: toISOStringSafe(new Date()),
    },
  });
  // Fetch top entities
  const [customer, seller, admin, refund] = await Promise.all([
    MyGlobal.prisma.shopping_mall_customers.findUnique({
      where: { id: updated.shopping_mall_customer_id },
    }),
    MyGlobal.prisma.shopping_mall_sellers.findUnique({
      where: { id: updated.shopping_mall_seller_id },
    }),
    updated.shopping_mall_admin_id
      ? MyGlobal.prisma.shopping_mall_admins.findUnique({
          where: { id: updated.shopping_mall_admin_id },
        })
      : Promise.resolve(undefined),
    updated.shopping_mall_refund_request_id
      ? MyGlobal.prisma.shopping_mall_refund_requests.findUnique({
          where: { id: updated.shopping_mall_refund_request_id },
        })
      : Promise.resolve(undefined),
  ]);
  // For refund (ISummary), its nested 'order', 'customer', 'seller' must be present if refund exists
  let refundRequest: IShoppingMallRefundRequest.ISummary | null | undefined =
    null;
  if (refund !== undefined && refund !== null) {
    // Fetch nested references
    const [orderData, refundCustomerData, refundSellerData] = await Promise.all(
      [
        refund.shopping_mall_order_id
          ? MyGlobal.prisma.shopping_mall_orders.findUnique({
              where: { id: refund.shopping_mall_order_id },
            })
          : Promise.resolve(null),
        refund.shopping_mall_customer_id
          ? MyGlobal.prisma.shopping_mall_customers.findUnique({
              where: { id: refund.shopping_mall_customer_id },
            })
          : Promise.resolve(null),
        refund.shopping_mall_seller_id
          ? MyGlobal.prisma.shopping_mall_sellers.findUnique({
              where: { id: refund.shopping_mall_seller_id },
            })
          : Promise.resolve(null),
      ],
    );
    if (orderData && refundCustomerData && refundSellerData) {
      refundRequest = {
        id: refund.id,
        order: {
          id: orderData.id,
          order_number: orderData.order_number,
          status: orderData.status,
          total_amount: orderData.total_amount,
          currency: orderData.currency,
          created_at: toISOStringSafe(orderData.created_at),
          updated_at: toISOStringSafe(orderData.updated_at),
          deleted_at:
            orderData.deleted_at === null
              ? null
              : toISOStringSafe(orderData.deleted_at),
        },
        customer: {
          id: refundCustomerData.id,
          name: refundCustomerData.name,
        },
        seller: {
          id: refundSellerData.id,
          business_name: refundSellerData.business_name,
        },
        status: refund.status,
        reason: refund.reason,
        requested_amount: refund.requested_amount,
        approved_amount: refund.approved_amount ?? null,
        created_at: toISOStringSafe(refund.created_at),
        updated_at: toISOStringSafe(refund.updated_at),
        deleted_at:
          refund.deleted_at === null
            ? null
            : toISOStringSafe(refund.deleted_at),
      };
    } else {
      refundRequest = null;
    }
  } else {
    refundRequest = undefined;
  }
  // Respond as per DTO contract
  return {
    id: updated.id,
    refund_request: refundRequest,
    customer:
      customer !== undefined && customer !== null
        ? { id: customer.id, name: customer.name }
        : { id: updated.shopping_mall_customer_id, name: "Deleted customer" },
    seller:
      seller !== undefined && seller !== null
        ? { id: seller.id, business_name: seller.business_name }
        : {
            id: updated.shopping_mall_seller_id,
            business_name: "Deleted seller",
          },
    admin:
      admin !== undefined && admin !== null
        ? { id: admin.id, name: admin.name, email: admin.email }
        : undefined,
    status: updated.status,
    subject: updated.subject,
    root_cause: updated.root_cause,
    resolution_note: updated.resolution_note ?? undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at:
      updated.deleted_at === null ? null : toISOStringSafe(updated.deleted_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallReturnRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnRequest";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function putShoppingMallCustomerReturnRequestsReturnRequestId(props: {
  customer: CustomerPayload;
  returnRequestId: string & tags.Format<"uuid">;
  body: IShoppingMallReturnRequest.IUpdate;
}): Promise<IShoppingMallReturnRequest> {
  const record = await MyGlobal.prisma.shopping_mall_return_requests.findFirst({
    where: {
      id: props.returnRequestId,
      deleted_at: null,
    },
  });
  if (!record) {
    throw new HttpException("Return request not found", 404);
  }
  if (record.requested_by_customer_id !== props.customer.id) {
    throw new HttpException(
      "You are not authorized to update this request.",
      403,
    );
  }

  const immutableStatuses = ["completed", "cancelled"];
  if (immutableStatuses.includes(record.status)) {
    if (
      typeof props.body.status === "string" &&
      props.body.status !== record.status
    ) {
      throw new HttpException(
        `Cannot change status after request is completed or cancelled`,
        400,
      );
    }
  }

  const allowedStatuses = [
    "pending",
    "approved",
    "scheduled",
    "picked_up",
    "delivered",
    "completed",
    "rejected",
    "cancelled",
  ];
  if (
    props.body.status !== undefined &&
    !allowedStatuses.includes(props.body.status)
  ) {
    throw new HttpException(`Invalid status value: ${props.body.status}`, 400);
  }

  const updateData: Record<string, unknown> = {
    updated_at: toISOStringSafe(new Date()),
  };
  if (props.body.reason !== undefined) updateData.reason = props.body.reason;
  if (props.body.status !== undefined) updateData.status = props.body.status;
  if ("pickup_address" in props.body)
    updateData.pickup_address = props.body.pickup_address ?? null;
  if ("scheduled_pickup_at" in props.body)
    updateData.scheduled_pickup_at = props.body.scheduled_pickup_at ?? null;
  if ("provider_tracking_code" in props.body)
    updateData.provider_tracking_code =
      props.body.provider_tracking_code ?? null;
  if ("shipping_partner_id" in props.body)
    updateData.shipping_partner_id = props.body.shipping_partner_id ?? null;

  if (props.body.status === "completed") {
    updateData.completed_at = toISOStringSafe(new Date());
  }
  if (props.body.status === "cancelled") {
    updateData.cancelled_at = toISOStringSafe(new Date());
  }

  const updated = await MyGlobal.prisma.shopping_mall_return_requests.update({
    where: { id: props.returnRequestId },
    data: updateData,
  });

  const [
    order,
    orderItem,
    requestedByCustomer,
    requestedBySeller,
    shippingPartner,
  ] = await Promise.all([
    MyGlobal.prisma.shopping_mall_orders.findUnique({
      where: { id: updated.order_id },
    }),
    MyGlobal.prisma.shopping_mall_order_items.findUnique({
      where: { id: updated.order_item_id },
    }),
    updated.requested_by_customer_id
      ? MyGlobal.prisma.shopping_mall_customers.findUnique({
          where: { id: updated.requested_by_customer_id },
        })
      : Promise.resolve(undefined),
    updated.requested_by_seller_id
      ? MyGlobal.prisma.shopping_mall_sellers.findUnique({
          where: { id: updated.requested_by_seller_id },
        })
      : Promise.resolve(undefined),
    updated.shipping_partner_id
      ? MyGlobal.prisma.shopping_mall_shipping_partners.findUnique({
          where: { id: updated.shipping_partner_id },
        })
      : Promise.resolve(undefined),
  ]);

  if (!order)
    throw new HttpException("Corrupted: Related order not found.", 500);
  if (!orderItem)
    throw new HttpException("Corrupted: Related order item not found.", 500);

  return {
    id: updated.id,
    order: {
      id: order.id,
      order_number: order.order_number,
      status: order.status,
      total_amount: order.total_amount,
      currency: order.currency,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      deleted_at:
        order.deleted_at !== null && order.deleted_at !== undefined
          ? toISOStringSafe(order.deleted_at)
          : undefined,
    },
    orderItem: {
      id: orderItem.id,
      shopping_mall_order_id: orderItem.shopping_mall_order_id,
      sku: {
        id: orderItem.shopping_mall_product_sku_id,
        code: "",
        product_title: "",
        option_summary: "",
        in_stock: true,
      },
      quantity: orderItem.quantity,
      unit_price: orderItem.unit_price,
      subtotal: orderItem.subtotal,
      currency: orderItem.currency,
      delivered: orderItem.delivered,
      refunded: orderItem.refunded,
      created_at: toISOStringSafe(orderItem.created_at),
      updated_at: toISOStringSafe(orderItem.updated_at),
    },
    requestedByCustomer: requestedByCustomer
      ? {
          id: requestedByCustomer.id,
          name: requestedByCustomer.name,
        }
      : undefined,
    requestedBySeller: requestedBySeller
      ? {
          id: requestedBySeller.id,
          business_name: requestedBySeller.business_name,
        }
      : undefined,
    shippingPartner: shippingPartner
      ? {
          id: shippingPartner.id,
          partner_name: shippingPartner.partner_name,
          partner_code: shippingPartner.partner_code,
          status: shippingPartner.status,
          description: shippingPartner.description,
          created_at: toISOStringSafe(shippingPartner.created_at),
          updated_at: toISOStringSafe(shippingPartner.updated_at),
          deleted_at:
            shippingPartner.deleted_at !== null &&
            shippingPartner.deleted_at !== undefined
              ? toISOStringSafe(shippingPartner.deleted_at)
              : undefined,
        }
      : undefined,
    reason: updated.reason,
    status: updated.status,
    pickup_address: updated.pickup_address ?? undefined,
    scheduled_pickup_at: updated.scheduled_pickup_at
      ? toISOStringSafe(updated.scheduled_pickup_at)
      : undefined,
    provider_tracking_code: updated.provider_tracking_code ?? undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    completed_at: updated.completed_at
      ? toISOStringSafe(updated.completed_at)
      : undefined,
    cancelled_at: updated.cancelled_at
      ? toISOStringSafe(updated.cancelled_at)
      : undefined,
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminLogin(props: {
  body: IShoppingMallAdmin.ILogin;
}): Promise<IShoppingMallAdmin.IAuthorized> {
  const admin = await MyGlobal.prisma.shopping_mall_admins.findFirst({
    where: { email: props.body.email },
  });
  if (!admin) {
    throw new HttpException("Invalid credentials", 401);
  }
  const isValid = await PasswordUtil.verify(
    props.body.password,
    admin.password_hash,
  );
  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
  const sessionId = v4();
  const token = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: sessionId,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };
  return {
    id: admin.id,
    email: admin.email,
    name: admin.name,
    is_email_verified: admin.is_email_verified,
    status: admin.status,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    token,
  };
}

