import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderShipment";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallShippingPartner } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShippingPartner";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminOrdersOrderNumberShipmentsShipmentId(props: {
  admin: AdminPayload;
  orderNumber: string;
  shipmentId: string & tags.Format<"uuid">;
  body: IShoppingMallOrderShipment.IUpdate;
}): Promise<IShoppingMallOrderShipment> {
  // 1. Resolve order and shipment existence, join by orderNumber/PK
  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: {
      order_number: props.orderNumber,
      deleted_at: null,
    },
  });
  if (!order) {
    throw new HttpException("Order not found", 404);
  }
  const shipment =
    await MyGlobal.prisma.shopping_mall_order_shipments.findUnique({
      where: {
        id: props.shipmentId,
        shopping_mall_order_id: order.id,
        deleted_at: null,
      },
    });
  if (!shipment) {
    throw new HttpException("Shipment not found", 404);
  }

  // 2. Build update data (only modifiable fields)
  const updateData: Record<string, unknown> = {};
  if (typeof props.body.shopping_mall_shipping_partner_id === "string") {
    updateData.shopping_mall_shipping_partner_id =
      props.body.shopping_mall_shipping_partner_id;
  }
  if (typeof props.body.tracking_number === "string") {
    if (props.body.tracking_number !== shipment.tracking_number) {
      // Ensure uniqueness, only if new value provided
      const dupe =
        await MyGlobal.prisma.shopping_mall_order_shipments.findUnique({
          where: { tracking_number: props.body.tracking_number },
        });
      if (dupe && dupe.id !== shipment.id) {
        throw new HttpException("Tracking number already assigned", 409);
      }
    }
    updateData.tracking_number = props.body.tracking_number;
  }
  if (typeof props.body.status === "string") {
    updateData.status = props.body.status;
  }
  if ("ship_date" in props.body) {
    updateData.ship_date =
      props.body.ship_date === undefined ? null : props.body.ship_date;
  }
  if ("expected_delivery_date" in props.body) {
    updateData.expected_delivery_date =
      props.body.expected_delivery_date === undefined
        ? null
        : props.body.expected_delivery_date;
  }
  if ("delivered_at" in props.body) {
    updateData.delivered_at =
      props.body.delivered_at === undefined ? null : props.body.delivered_at;
  }
  updateData.updated_at = toISOStringSafe(new Date());

  // 3. Update shipment
  const updated = await MyGlobal.prisma.shopping_mall_order_shipments.update({
    where: { id: props.shipmentId },
    data: updateData,
  });

  // 4. Fetch relations for API response (order summary, shipping partner summary)
  const orderSummary = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: { id: updated.shopping_mall_order_id },
  });
  const partnerSummary =
    await MyGlobal.prisma.shopping_mall_shipping_partners.findUnique({
      where: { id: updated.shopping_mall_shipping_partner_id },
    });
  if (!orderSummary || !partnerSummary) {
    throw new HttpException("Related records not found", 500);
  }

  return {
    id: updated.id,
    order: {
      id: orderSummary.id,
      order_number: orderSummary.order_number,
      status: orderSummary.status,
      total_amount: orderSummary.total_amount,
      currency: orderSummary.currency,
      created_at: toISOStringSafe(orderSummary.created_at),
      updated_at: toISOStringSafe(orderSummary.updated_at),
      deleted_at: orderSummary.deleted_at
        ? toISOStringSafe(orderSummary.deleted_at)
        : undefined,
    },
    shippingPartner: {
      id: partnerSummary.id,
      partner_name: partnerSummary.partner_name,
      partner_code: partnerSummary.partner_code,
      status: partnerSummary.status,
      description: partnerSummary.description,
      created_at: toISOStringSafe(partnerSummary.created_at),
      updated_at: toISOStringSafe(partnerSummary.updated_at),
      deleted_at: partnerSummary.deleted_at
        ? toISOStringSafe(partnerSummary.deleted_at)
        : undefined,
    },
    tracking_number: updated.tracking_number,
    status: updated.status,
    ship_date: updated.ship_date
      ? toISOStringSafe(updated.ship_date)
      : updated.ship_date,
    expected_delivery_date: updated.expected_delivery_date
      ? toISOStringSafe(updated.expected_delivery_date)
      : updated.expected_delivery_date,
    delivered_at: updated.delivered_at
      ? toISOStringSafe(updated.delivered_at)
      : updated.delivered_at,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteShoppingMallAdminOrdersOrderNumberShipmentsShipmentId(props: {
  admin: AdminPayload;
  orderNumber: string;
  shipmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Find the order by orderNumber
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      order_number: props.orderNumber,
      deleted_at: null,
    },
  });
  if (!order) {
    throw new HttpException("Order not found.", 404);
  }

  // Find the shipment by shipmentId and match order
  const shipment =
    await MyGlobal.prisma.shopping_mall_order_shipments.findFirst({
      where: {
        id: props.shipmentId,
        shopping_mall_order_id: order.id,
        deleted_at: null,
      },
    });
  if (!shipment) {
    throw new HttpException("Shipment not found for this order.", 404);
  }

  // Business state checks - prevent deletion if status is delivered, returned, or not pending/cancellable
  if (shipment.status === "delivered" || shipment.status === "returned") {
    throw new HttpException(
      "Shipment cannot be deleted when status is delivered or returned.",
      409,
    );
  }

  // Prevent deletion if the order has payments in finalized state related to shipment
  const paymentCount = await MyGlobal.prisma.shopping_mall_payments.count({
    where: {
      // Could narrow further if shipment-level link exists; here, just block if order-level payments done
      status: {
        in: ["completed", "refunded", "failed"],
      },
      deleted_at: null,
      // Payment can't be directly linked to shipment, so block if completed payment for order exists
      // (Business logic may require finer mapping)
      // join to order via order.id if joined in actual DB, but not present in schema from what's loaded
    },
  });
  if (paymentCount > 0) {
    throw new HttpException(
      "Associated payments are finalized; cannot delete shipment.",
      409,
    );
  }

  // Prevent deletion if any refund events exist on this payment/order
  const refundCount = await MyGlobal.prisma.shopping_mall_payment_refunds.count(
    {
      where: {
        // We don't have direct shipment link; block if order's payments have refunds
        status: {
          in: ["completed"],
        },
        deleted_at: null,
      },
    },
  );
  if (refundCount > 0) {
    throw new HttpException(
      "Associated refunds for order are finalized; cannot delete shipment.",
      409,
    );
  }

  // Hard delete the shipment
  await MyGlobal.prisma.shopping_mall_order_shipments.delete({
    where: { id: props.shipmentId },
  });

  // Log the action in the audit logs
  await MyGlobal.prisma.shopping_mall_order_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_order_id: order.id,
      actor_admin_id: props.admin.id,
      action_type: "shipment_deleted",
      details_json: JSON.stringify({
        shipment_id: props.shipmentId,
        performed_by: "admin",
        admin_id: props.admin.id,
        rationale: "Shipment deleted via admin endpoint.",
      }),
      created_at: toISOStringSafe(new Date()),
    },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderStatusHistory";
import { IPageIShoppingMallOrderStatusHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrderStatusHistory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminOrdersOrderNumberStatusHistories(props: {
  admin: AdminPayload;
  orderNumber: string;
  body: IShoppingMallOrderStatusHistory.IRequest;
}): Promise<IPageIShoppingMallOrderStatusHistory> {
  // 1. Find the order by orderNumber
  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: { order_number: props.orderNumber, deleted_at: null },
  });
  if (!order) {
    throw new HttpException("Order not found", 404);
  }

  // 2. Prepare filters
  const {
    statuses,
    actor_type,
    actor_id,
    from_time,
    to_time,
    search,
    page,
    limit,
    sort_by,
    sort_order,
  } = props.body;
  const skip = ((page ?? 1) - 1) * (limit ?? 20);
  const take = limit ?? 20;
  const orderBy = ((): Record<string, unknown> => {
    if (sort_by === "status") {
      return { to_status: sort_order ?? "desc" };
    }
    return { created_at: sort_order ?? "desc" };
  })();

  // 3. Build history where clause
  const where: Record<string, unknown> = {
    shopping_mall_order_id: order.id,
    ...(statuses && statuses.length > 0 ? { to_status: { in: statuses } } : {}),
    ...(from_time ? { created_at: { gte: from_time } } : {}),
    ...(to_time
      ? {
          created_at: {
            ...(from_time ? { gte: from_time } : {}),
            lte: to_time,
          },
        }
      : {}),
    ...(search ? { comment: { contains: search } } : {}),
  };
  if (actor_type || actor_id) {
    if (actor_type === "admin")
      where.actor_admin_id = actor_id ?? { not: null };
    if (actor_type === "seller")
      where.actor_seller_id = actor_id ?? { not: null };
    if (actor_type === "customer")
      where.actor_customer_id = actor_id ?? { not: null };
    if (actor_type === "system")
      ((where.actor_admin_id = null),
        (where.actor_seller_id = null),
        (where.actor_customer_id = null));
  }

  // 4. Query status histories with pagination and actors joined
  const [total, rows] = await Promise.all([
    MyGlobal.prisma.shopping_mall_order_status_histories.count({ where }),
    MyGlobal.prisma.shopping_mall_order_status_histories.findMany({
      where,
      orderBy,
      skip,
      take,
      include: {
        adminActor: true,
        sellerActor: true,
        customerActor: true,
      },
    }),
  ]);

  // 5. Compose pagination object and data/transform
  const data = rows.map((h) => ({
    id: h.id,
    order: {
      id: order.id,
      order_number: order.order_number,
      status: order.status,
      total_amount: order.total_amount,
      currency: order.currency,
      created_at: toISOStringSafe(order.created_at),
      updated_at: toISOStringSafe(order.updated_at),
      deleted_at: order.deleted_at ? toISOStringSafe(order.deleted_at) : null,
    },
    from_status: h.from_status,
    to_status: h.to_status,
    comment: h.comment ?? undefined,
    created_at: toISOStringSafe(h.created_at),
    admin: h.adminActor
      ? {
          id: h.adminActor.id,
