import { IShoppingMallDisputeMessage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallDisputeMessage";
import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminDisputesDisputeIdMessagesDisputeMessageId(props: {
  admin: AdminPayload;
  disputeId: string & tags.Format<"uuid">;
  disputeMessageId: string & tags.Format<"uuid">;
  body: IShoppingMallDisputeMessage.IUpdate;
}): Promise<IShoppingMallDisputeMessage> {
  // Find message matching both dispute and message IDs, not soft-deleted
  const message =
    await MyGlobal.prisma.shopping_mall_dispute_messages.findFirst({
      where: {
        id: props.disputeMessageId,
        shopping_mall_dispute_id: props.disputeId,
        deleted_at: null,
      },
    });
  if (!message) {
    throw new HttpException(
      "Dispute message not found or already deleted.",
      404,
    );
  }

  // (Admins can always edit dispute messages - further business restrictions would go here if needed)

  // Update allowed fields
  const updated = await MyGlobal.prisma.shopping_mall_dispute_messages.update({
    where: { id: props.disputeMessageId },
    data: {
      ...(props.body.content !== undefined && { content: props.body.content }),
      ...(props.body.role !== undefined && { role: props.body.role }),
    },
  });

  // Gather actor summaries (admin, seller, customer for sender & receiver)
  // All summary fields only if IDs present; null/undefined if not set
  // Prisma: must fetch actor data for summaries, but DO NOT do N+1
  const [
    senderAdmin,
    senderSeller,
    senderCustomer,
    receiverAdmin,
    receiverSeller,
    receiverCustomer,
  ] = await Promise.all([
    updated.shopping_mall_sender_admin_id
      ? MyGlobal.prisma.shopping_mall_admins.findUnique({
          where: { id: updated.shopping_mall_sender_admin_id },
        })
      : Promise.resolve(undefined),
    updated.shopping_mall_sender_seller_id
      ? MyGlobal.prisma.shopping_mall_sellers.findUnique({
          where: { id: updated.shopping_mall_sender_seller_id },
        })
      : Promise.resolve(undefined),
    updated.shopping_mall_sender_customer_id
      ? MyGlobal.prisma.shopping_mall_customers.findUnique({
          where: { id: updated.shopping_mall_sender_customer_id },
        })
      : Promise.resolve(undefined),
    updated.shopping_mall_receiver_admin_id
      ? MyGlobal.prisma.shopping_mall_admins.findUnique({
          where: { id: updated.shopping_mall_receiver_admin_id },
        })
      : Promise.resolve(undefined),
    updated.shopping_mall_receiver_seller_id
      ? MyGlobal.prisma.shopping_mall_sellers.findUnique({
          where: { id: updated.shopping_mall_receiver_seller_id },
        })
      : Promise.resolve(undefined),
    updated.shopping_mall_receiver_customer_id
      ? MyGlobal.prisma.shopping_mall_customers.findUnique({
          where: { id: updated.shopping_mall_receiver_customer_id },
        })
      : Promise.resolve(undefined),
  ]);

  return {
    id: updated.id,
    shopping_mall_dispute_id: updated.shopping_mall_dispute_id,
    sender_admin: senderAdmin
      ? {
          id: senderAdmin.id,
          name: senderAdmin.name,
          email: senderAdmin.email,
        }
      : undefined,
    sender_seller: senderSeller
      ? {
          id: senderSeller.id,
          business_name: senderSeller.business_name,
        }
      : undefined,
    sender_customer: senderCustomer
      ? {
          id: senderCustomer.id,
          name: senderCustomer.name,
        }
      : undefined,
    receiver_admin: receiverAdmin
      ? {
          id: receiverAdmin.id,
          name: receiverAdmin.name,
          email: receiverAdmin.email,
        }
      : undefined,
    receiver_seller: receiverSeller
      ? {
          id: receiverSeller.id,
          business_name: receiverSeller.business_name,
        }
      : undefined,
    receiver_customer: receiverCustomer
      ? {
          id: receiverCustomer.id,
          name: receiverCustomer.name,
        }
      : undefined,
    role: updated.role,
    content: updated.content,
    created_at: toISOStringSafe(updated.created_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteShoppingMallAdminShipmentsShipmentId(props: {
  admin: AdminPayload;
  shipmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  // 1. Find the shipment (must exist)
  const shipment = await MyGlobal.prisma.shopping_mall_shipments.findUnique({
    where: { id: props.shipmentId },
  });
  if (!shipment) {
    throw new HttpException("Shipment not found", 404);
  }

  // 2. Validate shipment status (must not be in transit, delivered, cancelled, or returned)
  const NON_DELETABLE_STATUSES = [
    "in_transit",
    "delivered",
    "cancelled",
    "returned",
  ];
  if (NON_DELETABLE_STATUSES.includes(shipment.status)) {
    throw new HttpException(
      `Cannot delete shipment in status '${shipment.status}'. Only shipments in cancellable statuses may be deleted.`,
      409,
    );
  }

  // 3. Check for tracking histories
  const trackingCount =
    await MyGlobal.prisma.shopping_mall_shipment_tracking_histories.count({
      where: { shipment_id: props.shipmentId },
    });
  if (trackingCount > 0) {
    throw new HttpException(
      "Cannot delete shipment: It has tracking history records.",
      409,
    );
  }

  // 4. Do hard delete
  await MyGlobal.prisma.shopping_mall_shipments.delete({
    where: { id: props.shipmentId },
  });
  // No return value: void
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function deleteShoppingMallSellerShipmentsShipmentId(props: {
  seller: SellerPayload;
  shipmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Look up the shipment by ID
  const shipment = await MyGlobal.prisma.shopping_mall_shipments.findUnique({
    where: { id: props.shipmentId },
  });
  if (!shipment) {
    throw new HttpException("Shipment not found", 404);
  }
  // Validate owner (created_by_seller_id matches actor)
  if (shipment.created_by_seller_id !== props.seller.id) {
    throw new HttpException(
      "You are not authorized to delete this shipment.",
      403,
    );
  }
  // Validate status (only allow if NOT delivered/in_transit/cancelled/returned)
  const forbiddenStatuses = [
    "in_transit",
    "delivered",
    "cancelled",
    "returned",
  ];
  if (forbiddenStatuses.includes(shipment.status)) {
    throw new HttpException(
      "Cannot delete shipment: status does not allow deletion.",
      400,
    );
  }
  // Validate: no tracking histories exist for this shipment
  const trackingExists =
    await MyGlobal.prisma.shopping_mall_shipment_tracking_histories.findFirst({
      where: { shipment_id: props.shipmentId },
    });
  if (trackingExists) {
    throw new HttpException(
      "Cannot delete shipment: tracking histories exist for this shipment.",
      400,
    );
  }
  // Delete the shipment
  await MyGlobal.prisma.shopping_mall_shipments.delete({
    where: { id: props.shipmentId },
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallShipmentTrackingHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipmentTrackingHistory";
import { IPageIShoppingMallShipmentTrackingHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallShipmentTrackingHistory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingMallSellerShipmentsShipmentIdTrackingHistories(props: {
  seller: SellerPayload;
  shipmentId: string & tags.Format<"uuid">;
  body: IShoppingMallShipmentTrackingHistory.IRequest;
}): Promise<IPageIShoppingMallShipmentTrackingHistory> {
  // 1. Authorization: seller must be creator or assignee
  const shipment = await MyGlobal.prisma.shopping_mall_shipments.findUnique({
    where: { id: props.shipmentId },
    select: { created_by_seller_id: true },
  });
  if (!shipment || shipment.created_by_seller_id !== props.seller.id) {
    throw new HttpException(
      "You do not have access to this shipment or it does not exist.",
      403,
    );
  }
  // 2. Dynamic filters
  const {
    status,
    event_code,
    search,
    from_event_time,
    to_event_time,
    page,
    limit,
  } = props.body;

  const filters: Record<string, any> = { shipment_id: props.shipmentId };
  if (status) filters.status = status;
  if (event_code) filters.event_code = event_code;
  if (from_event_time || to_event_time) {
    filters.event_time = {};
    if (from_event_time) filters.event_time.gte = from_event_time;
    if (to_event_time) filters.event_time.lte = to_event_time;
  }
  // 3. Text search
  let orSearch: any[] | undefined;
  if (search) {
    orSearch = [
      { tracking_message: { contains: search } },
      { location: { contains: search } },
      { event_code: { contains: search } },
    ];
  }
  // 4. Pagination
  const skip = (page - 1) * limit;
  const take = limit;
  const where = orSearch ? { ...filters, OR: orSearch } : filters;

  // Query + count
  const [records, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_shipment_tracking_histories.findMany({
      where,
      skip,
      take,
      orderBy: [{ event_time: "asc" }, { created_at: "asc" }],
    }),
    MyGlobal.prisma.shopping_mall_shipment_tracking_histories.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: records.map((event) => ({
      id: event.id,
      shipment_id: event.shipment_id,
      event_time: toISOStringSafe(event.event_time),
      location: event.location === null ? null : event.location,
      latitude: event.latitude === null ? null : event.latitude,
      longitude: event.longitude === null ? null : event.longitude,
      event_code: event.event_code === null ? null : event.event_code,
      status: event.status,
      tracking_message: event.tracking_message,
      created_at: toISOStringSafe(event.created_at),
    })),
  };
}

